    $p = New-TestProfile $Name
    $roots = @(1..$Count | ForEach-Object { New-TestRoot -ProfileInfo $p })
    [pscustomobject]@{ Profile = $p; Roots = $roots; Entries = @($roots | ForEach-Object { [pscustomobject]@{ Source = 't'; Path = $_; Fingerprint = $null } }) }
