        Assert-Eq @($i.Partitions).Count 0 'sem particoes'
        Assert-Eq $i.ProfileBaseStatus[$p.Sid + '|' + $p.ProfilePath][0].Status 'NOT_FOUND' 'base inexistente'
        Assert-Eq $i.Snapshot.Total 0 'processos vazios'
