    Test-Case 'Reparse points' 'Junction dentro da root: contada, nao atravessada, bloqueia; deleter aborta sem excluir' {
        $p = New-TestProfile 'jinside'
        $r = New-TestRoot -ProfileInfo $p
        $target = Join-Path $sandbox 'alvo-jinside'; [void][IO.Directory]::CreateDirectory($target); [IO.File]::WriteAllText((Join-Path $target 'canario.txt'), 'vivo')
        New-Junction -Link (Join-Path $r 'sub\link') -Target $target
        $i = Inv -Profiles @($p)
        $x = Find-Part $i $r
        Assert-Eq $x.ReparsePoints 1 'contada'
        Assert-Eq $x.Files 2 'alvo nao contado'
        Assert-True ($x.Flags -contains 'REPARSE_POINT') 'flag'
        Assert-Eq (Test-AtmCandidate -Partition $x -Inventory $i).Category 'BLOCKED' 'bloqueado'
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r)
        Assert-True (-not $d.Attempted) 'nada tentado'
        Assert-True ([IO.File]::Exists((Join-Path $r 'a.txt'))) 'root intacta'
        Assert-True ([IO.File]::Exists((Join-Path $target 'canario.txt'))) 'alvo intacto'
        $pr = [AgentTempManager.AtmLockProbe]::ProbeTree($r, 5)
        Assert-True (-not $pr.Ok -and $pr.ReparsePoints -eq 1) 'sondagem recusa'
    }
    Test-Case 'Reparse points' 'Reparse point em ancestral (TEMP e junction): base nao auditada' {
        $p = New-TestProfile 'janc'
        $realTemp = Join-Path $sandbox 'temp-real-janc'
        [void][IO.Directory]::CreateDirectory((Join-Path $realTemp ('claude\C--x\' + [guid]::NewGuid())))
        $temp = $p.TempCandidates[0].TempPath
        [IO.Directory]::Delete((Join-Path $temp 'claude')); [IO.Directory]::Delete($temp)
        New-Junction -Link $temp -Target $realTemp
        $i = Inv -Profiles @($p)
        Assert-Eq @($i.Bases)[0].Status 'REPARSE_IN_PATH' 'status'
        Assert-Eq @($i.Partitions).Count 0 'nada inventariado'
        Assert-Eq (Test-AtmPathChain (Join-Path $temp 'claude')).Status 'REPARSE_IN_PATH' 'cadeia'
    }
    Test-Case 'Reparse points' 'Symlink de diretorio (se permitido) tambem e bloqueado' {
        $p = New-TestProfile 'symlink'
        $r = New-TestRoot -ProfileInfo $p
        $target = Join-Path $sandbox 'alvo-sym'; [void][IO.Directory]::CreateDirectory($target)
        # No symlink privilege: the case is reported as NAO_TESTADO below.
        try { $null = cmd /c mklink /D "`"$(Join-Path $r 'sym')`"" "`"$target`"" 2>&1 } catch { $null = $_ }
        if (-not [IO.Directory]::Exists((Join-Path $r 'sym'))) { $script:caseSkipped = $true; $script:caseNote = 'symlink exige privilegio (SeCreateSymbolicLink) ou modo desenvolvedor; reparse coberto por junctions'; return }
        $cleanupActions.Add([scriptblock]::Create("try { [IO.Directory]::Delete('$(Join-Path $r 'sym')', `$false) } catch { }"))
        Assert-True ((Find-Part (Inv -Profiles @($p)) $r).Flags -contains 'REPARSE_POINT') 'flag'
    }

    # ------------------------------------------------------------------ locks / in use
    Test-Case 'Arquivos em uso' 'Arquivo aberto (FileShare.None e ReadWrite|Delete) -> EM_USO, preservado' {
        $p = New-TestProfile 'locked'
        $r = New-TestRoot -ProfileInfo $p
        $i = Inv -Profiles @($p)
        foreach ($share in @([IO.FileShare]::None, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))) {
            $fs = [IO.File]::Open((Join-Path $r 'a.txt'), 'Open', 'Read', $share)
            try {
                $g = Test-AtmCandidate -Partition (Find-Part $i $r) -Inventory $i
                Assert-Eq $g.Category 'BLOCKED' "bloqueado ($share)"
                Assert-True (($g.Reasons -join ' ') -match 'EM_USO') "motivo ($share): $($g.Reasons -join ';')"
                $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p))
                Assert-Eq $c.Aborted 'NENHUM_CAMINHO_ELEGIVEL' 'clean recusa'
            } finally { $fs.Dispose() }
        }
        Assert-True ([IO.File]::Exists((Join-Path $r 'a.txt'))) 'preservado'
    }
    Test-Case 'Arquivos em uso' 'Processo com diretorio corrente dentro da root -> EM_USO' {
        $p = New-TestProfile 'cwd'
        $r = New-TestRoot -ProfileInfo $p
        $sp = Start-AtmTestHelperProcess -File "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Arguments '-NoProfile -Command Start-Sleep 60' -WorkingDirectory (Join-Path $r 'sub')
        $cleanupActions.Add({ Stop-AtmTestHelperProcess -Process $sp }.GetNewClosure())
        Start-Sleep -Milliseconds 1500
        $pr = [AgentTempManager.AtmLockProbe]::ProbeTree($r, 5)
        Stop-AtmTestHelperProcess -Process $sp
        Assert-True ($pr.InUse -ge 1) "diretorio em uso detectado ($($pr.Samples -join ';'))"
    }

    # ------------------------------------------------------------------ allowlist / traversal
    Test-Case 'Path traversal' 'Entradas maliciosas ou nao canonicas sao rejeitadas' {
        $p = New-TestProfile 'trav'
        $r = New-TestRoot -ProfileInfo $p
        $b = Get-Base $p
        $bad = @{
            "$b\C--work-proj\..\C--work-proj\$(Split-Path $r -Leaf)" = 'PATH_TRAVERSAL'
            'relativo\x'                       = 'NOT_ABSOLUTE_LOCAL_PATH'
            '\\servidor\share\x'               = 'NOT_ABSOLUTE_LOCAL_PATH'
            "\\?\$r"                           = 'NOT_ABSOLUTE_LOCAL_PATH'
            "$b\*"                             = 'WILDCARD_OR_INVALID_CHARS'
            "$r`:stream"                       = 'ALTERNATE_DATA_STREAM'
            "$r\"                              = 'TRAILING_SEPARATOR'
            "$r."                              = 'TRAILING_DOT_OR_SPACE'
            'C:\Users\EXAMPL~1\x'              = 'SHORT_NAME_NOT_ALLOWED'
            " $r"                              = 'LEADING_OR_TRAILING_WHITESPACE'
            ($r -replace '\\', '\\')           = 'EMPTY_SEGMENT'
        }
        foreach ($k in $bad.Keys) { Assert-Eq (Test-AtmAllowListPathSyntax $k) $bad[$k] "entrada '$k'" }
        Assert-Eq (Test-AtmAllowListPathSyntax $r) $null 'caminho valido aceito'
    }
    Test-Case 'Path traversal' 'Perfil, TEMP, base, projeto e raiz do disco nunca sao aceitos' {
        $p = New-TestProfile 'roots'
        $r = New-TestRoot -ProfileInfo $p
        $b = Get-Base $p
        $targets = @($p.ProfilePath, $p.TempCandidates[0].TempPath, $b, [IO.Path]::GetDirectoryName($r), 'C:\', $sandbox)
        $entries = @($targets | ForEach-Object { [pscustomobject]@{ Source = 't'; Path = $_; Fingerprint = $null } })
        $c = Invoke-AtmClean -Entries $entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $c.Aborted 'NENHUM_CAMINHO_ELEGIVEL' 'tudo recusado'
        Assert-Eq @($c.Rejected).Count $targets.Count 'todos recusados'
        Assert-True ([IO.Directory]::Exists($r)) 'preservado'
    }
    Test-Case 'Allowlist' 'Leitura de allowlist UTF-8 com comentarios, fingerprint e Unicode' {
        $f = Join-Path $sandbox 'allow.txt'
        $u = "C:\x\" + $uni
        [IO.File]::WriteAllText($f, "# comentario`r`n`r`n$u|ABCDEF`r`nC:\y\z`r`n", (New-Object Text.UTF8Encoding($true)))
        $e = @(Read-AtmAllowList -File $f -Paths @('C:\w'))
        Assert-Eq $e.Count 3 'entradas'
        Assert-Eq $e[0].Path $u 'unicode preservado'
        Assert-Eq $e[0].Fingerprint 'ABCDEF' 'fingerprint'
        Assert-Eq $e[2].Source '-Path' 'origem'
    }

    # ------------------------------------------------------------------ clean flow
    Test-Case 'Clean' 'Sem confirmacao ou confirmacao divergente: nada e apagado' {
        $p = New-TestProfile 'noconfirm'
        $r = New-TestRoot -ProfileInfo $p
        $e = @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null })
        # AUT-2: the declarations are answered with the phrase shown; only the final confirmation is wrong or missing.
        foreach ($wrong in @({ param($x) $null }, { param($x) '' }, { param($x) $x.ToLowerInvariant() }, { param($x) "$x " }, { param($x) 'sim' })) {
            $reader = { param($x, $k) if ($k -ceq 'confirm') { & $wrong $x } else { $x } }.GetNewClosure()
            $c = Invoke-AtmClean -Entries $e -PlanPresenter $presenter -ConfirmationReader $reader -InventoryArgs (Get-InvArgs -Profiles @($p)) -LogWriter (New-TestCleanLogWriter)
            Assert-Eq $c.Aborted 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' 'abortado'
            Assert-Eq @($c.Deleted).Count 0 'nada excluido'
        }
        $c = Invoke-AtmClean -Entries $e -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $c.Aborted 'SEM_APRESENTACAO_OU_CONFIRMACAO' 'sem leitor/apresentador'
        $c = Invoke-AtmClean -Entries $e -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $c.Aborted 'SEM_APRESENTACAO_OU_CONFIRMACAO' 'sem apresentador do plano'
        Assert-True ([IO.Directory]::Exists($r)) 'preservado'
    }
    Test-Case 'Clean' 'Allowlist vazia e caminho fora da allowlist preservado' {
        $c = Invoke-AtmClean -Entries @() -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct}
        Assert-Eq $c.Aborted 'ALLOWLIST_VAZIA' 'vazia'
        $p = New-TestProfile 'outside'
        $r1 = New-TestRoot -ProfileInfo $p; $r2 = New-TestRoot -ProfileInfo $p
        $before = Get-StableTreeListing $r2
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r1; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p)) -LogWriter (New-TestCleanLogWriter)
        Assert-Eq @($c.Deleted | Where-Object { $_.Completed -and $_.Verified }).Count 1 'somente r1'
        Assert-True (-not [IO.Directory]::Exists($r1)) 'r1 excluido'
        Assert-Eq (Get-TreeListing $r2) $before 'r2 (fora da allowlist) intacto'
        Assert-True ([IO.Directory]::Exists([IO.Path]::GetDirectoryName($r1))) 'diretorio do projeto preservado'
        Assert-True ($null -ne $c.PostInventory) 'auditoria posterior executada'
    }
    Test-Case 'Clean' 'Alteracao entre preview e clean (fingerprint) -> recusado' {
        $p = New-TestProfile 'changed'
        $r = New-TestRoot -ProfileInfo $p
        $fp = (Find-Part (Inv -Profiles @($p)) $r).Fingerprint
        [IO.File]::WriteAllBytes((Join-Path $r 'novo.bin'), (New-Object byte[] 3))
        [IO.File]::SetLastWriteTimeUtc((Join-Path $r 'novo.bin'), [datetime]::UtcNow.AddDays(-5))
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $fp }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $c.Aborted 'NENHUM_CAMINHO_ELEGIVEL' 'recusado'
        Assert-True ((@($c.Rejected)[0].Reasons -join ' ') -match 'ALTERADO_DESDE_O_PREVIEW') 'motivo'
        Assert-True ([IO.Directory]::Exists($r)) 'preservado'
    }
    Test-Case 'Clean' 'Alteracao apos a confirmacao (antes da exclusao) -> preservado na revalidacao' {
        $p = New-TestProfile 'toctou'
        $r = New-TestRoot -ProfileInfo $p
        $hook = { param($part) [IO.File]::WriteAllBytes((Join-Path $part.Path 'apareceu.bin'), (New-Object byte[] 9)) }
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p)) -BeforeDeleteHook $hook -LogWriter (New-TestCleanLogWriter)
        Assert-Eq @($c.Deleted).Count 0 'nada excluido'
        Assert-Eq @($c.Skipped).Count 1 'preservado'
        Assert-True ([IO.File]::Exists((Join-Path $r 'apareceu.bin'))) 'arquivo novo intacto'
    }
    Test-Case 'Clean' 'Root removida entre preview e clean / durante a revalidacao' {
        $p = New-TestProfile 'vanish'
        $r = New-TestRoot -ProfileInfo $p
        $hook = { param($part) [AgentTempManager.AtmDeleter]::DeleteTree($part.Path) | Out-Null }
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p)) -BeforeDeleteHook $hook -LogWriter (New-TestCleanLogWriter)
        Assert-Eq @($c.Skipped).Count 1 'tratado como desaparecido'
        $c2 = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $c2.Aborted 'NENHUM_CAMINHO_ELEGIVEL' 'inexistente recusado'
        $s = [AgentTempManager.AtmScanner]::ScanTree($r, 3, 4096)
        Assert-True (-not $s.Exists) 'scanner tolera remocao'
    }
    Test-Case 'Clean' 'Caixa divergente e duplicados na allowlist sao recusados' {
        $p = New-TestProfile 'case'
        $r = New-TestRoot -ProfileInfo $p
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r.ToUpperInvariant().Replace('C:\', 'C:\'); Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $c.Aborted 'NENHUM_CAMINHO_ELEGIVEL' 'caixa'
        $c2 = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 'a'; Path = $r; Fingerprint = $null }, [pscustomobject]@{ Source = 'b'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader { param($x) 'nao' } -InventoryArgs (Get-InvArgs -Profiles @($p)) -LogWriter (New-TestCleanLogWriter)
        Assert-True (@($c2.Rejected | Where-Object { $_.Reasons -contains 'DUPLICADO_NA_ALLOWLIST' }).Count -eq 1) 'duplicado'
        Assert-True ([IO.Directory]::Exists($r)) 'preservado'
    }
    Test-Case 'Clean' 'Classes ACTIVE/RECENT/UNKNOWN nunca entram no plano' {
        $p = New-TestProfile 'classes'
        $ra = New-TestRoot -ProfileInfo $p; $rr = New-TestRoot -ProfileInfo $p; $ru = New-TestRoot -ProfileInfo $p
        [IO.File]::SetLastWriteTimeUtc((Join-Path $rr 'a.txt'), $nowFuture.AddHours(-3))
        $procs = New-Procs -Extra @(
            [pscustomobject]@{ ProcessId = 801; Name = 'n.exe'; ParentProcessId = 1; CommandLine = "n $ra"; CreationDate = (Get-Date) },
            [pscustomobject]@{ ProcessId = 802; Name = 'n.exe'; ParentProcessId = 1; CommandLine = "n $([IO.Path]::GetDirectoryName($ru))"; CreationDate = (Get-Date) })
        $e = @($ra, $rr, $ru | ForEach-Object { [pscustomobject]@{ Source = 't'; Path = $_; Fingerprint = $null } })
        $c = Invoke-AtmClean -Entries $e -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs)
        Assert-Eq $c.Aborted 'NENHUM_CAMINHO_ELEGIVEL' 'nenhum elegivel'
        Assert-True ([IO.Directory]::Exists($ra) -and [IO.Directory]::Exists($rr) -and [IO.Directory]::Exists($ru)) 'todos preservados'
    }

    # ------------------------------------------------------------------ clean log (T1, F-04)
    # Every case below passes the stand-in deleter (it deletes nothing) and the stand-in presence check; the roots of
    # each fixture are asserted intact at the end.
    Test-Case 'Clean log (T1)' 'Sequencia: run-start, plano, confirmacao, intent gravado antes de cada chamada ao deleter simulado, result e run-end; runId, recSeq e opId coerentes; nada apagado' {
        $f = New-TestT1Fixture 't1seq' 3
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($null -eq $c.Aborted -and $null -eq $c.StoppedBy -and @($c.LogErrors).Count -eq 0) "sem parada ($($c.Aborted) $($c.StoppedBy))"
        Assert-Eq $d.Calls.Count 3 'tres chamadas ao deleter simulado'
        $recs = Get-TestCleanLogRecords $w
        Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,plan,plan,declaration,declaration,declaration,confirmation,plan-check,intent,result,intent,result,intent,result,run-end' 'ordem dos registros'
        Assert-Eq (@($recs | ForEach-Object { $_.recSeq }) -join ',') ((1..16) -join ',') 'recSeq continuo'
        Assert-Eq @($recs | Where-Object { $_.runId -cne $c.RunId -or $_.schema -cne 'atm.cleanlog/1' }).Count 0 'runId e schema em todos os registros'
        foreach ($call in $d.Calls) { Assert-True ($call.LastType -ceq 'intent' -and [string]::Equals($call.LastPath, $call.Path, [StringComparison]::OrdinalIgnoreCase)) "intent da propria raiz gravado antes da chamada ($($call.LastType))" }
        Assert-Eq (@($c.Deleted | ForEach-Object { $_.OpId }) -join ',') (@(1..3 | ForEach-Object { '{0}:{1}' -f $c.RunId, $_ }) -join ',') 'opId runId:seq'
        Assert-Eq (@($recs | Where-Object { $_.type -ceq 'intent' } | ForEach-Object { $_.opId }) -join ',') (@($recs | Where-Object { $_.type -ceq 'result' } | ForEach-Object { $_.opId }) -join ',') 'cada intent tem o result da mesma operacao'
        Assert-Eq @($c.Deleted | Where-Object { $_.Outcome -cne 'COMPLETE' -or $_.VerifiedState -cne 'GONE' }).Count 0 'desfechos COMPLETE com ausencia confirmada'
        Assert-True (@($recs | Where-Object { $_.type -ceq 'confirmation' })[0].accepted -eq $true) 'confirmacao aceita registrada'
        Assert-True ($w.Closed -eq 1 -and $w.Disposed -ge 1) 'log fechado e liberado'
        Assert-True ($null -ne $c.PostInventory) 'auditoria posterior'
        Assert-True (Test-TestT1RootsIntact $f) 'deleter simulado: nada apagado'
    }
    Test-Case 'Clean log (T1)' 'Recusa, exclusao parcial, excecao (desfecho desconhecido), verificacao inconclusiva e raiz ainda presente: registrados, e a execucao para antes da proxima raiz' {
        $cases = @(
            @{ Kind = 'REFUSED'; Presence = $true; Outcome = 'REFUSED'; Vs = 'PRESENT' },
            @{ Kind = 'PARTIAL'; Presence = $true; Outcome = 'PARTIAL'; Vs = 'PRESENT' },
            @{ Kind = 'THROW'; Presence = $false; Outcome = 'EXCEPTION'; Vs = 'UNKNOWN' },
            @{ Kind = 'COMPLETE'; Presence = $null; Outcome = 'VERIFICATION_FAILED'; Vs = 'UNKNOWN' },
            @{ Kind = 'COMPLETE'; Presence = $true; Outcome = 'VERIFICATION_FAILED'; Vs = 'PRESENT' })
        $n = 0
        foreach ($k in $cases) {
            $n++
            $f = New-TestT1Fixture ('t1out' + $n) 2
            $w = New-TestCleanLogWriter
            $d = New-TestCleanDeleter -Writer $w -Results @($k.Kind) -Presence $k.Presence
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            $tag = "$($k.Kind)/$($k.Presence)"
            Assert-Eq $d.Calls.Count 1 "$($tag): nenhuma chamada depois do primeiro desfecho"
            Assert-True ($null -eq $c.Aborted -and $c.StoppedBy -ceq ('STOPPED_AFTER_' + $k.Outcome)) "$($tag): parada ($($c.Aborted) $($c.StoppedBy))"
            $row = @($c.Deleted)
            Assert-True ($row.Count -eq 1 -and $row[0].Outcome -ceq $k.Outcome -and $row[0].VerifiedState -ceq $k.Vs) "$($tag): desfecho $($row[0].Outcome)/$($row[0].VerifiedState)"
            $recs = Get-TestCleanLogRecords $w
            Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,plan,declaration,declaration,confirmation,plan-check,intent,result,run-end' "$($tag): registros"
            $res = @($recs | Where-Object { $_.type -ceq 'result' })[0]
            Assert-True ($res.outcome -ceq $k.Outcome -and $res.opId -ceq $row[0].OpId) "$($tag): result registrado"
            Assert-Eq @($recs | Where-Object { $_.type -ceq 'run-end' })[0].stoppedBy ('STOPPED_AFTER_' + $k.Outcome) "$($tag): run-end com o motivo"
            if ($k.Kind -ceq 'THROW') {
                Assert-True ($row[0].ExceptionType -ceq 'IOException' -and $null -eq $row[0].Attempted -and $null -eq $row[0].FilesDeleted) 'excecao: resultado desconhecido, nunca presumido'
                Assert-True ([string]$res.verifiedGone -ceq 'UNKNOWN' -and $res.exceptionType -ceq 'IOException') 'excecao: log diz UNKNOWN'
            }
            Assert-True ($null -ne $c.PostInventory) "$($tag): auditoria posterior"
            Assert-True (Test-TestT1RootsIntact $f) "$($tag): nada apagado"
        }
    }
    Test-Case 'Clean log (T1)' 'Falha do log: run-start, plano ou confirmacao -> nenhuma chamada ao deleter; intent -> raiz nunca iniciada; result -> nenhuma nova chamada, opId e resultado conhecido mantidos; run-end e fechamento nao mascaram o erro principal' {
        $go = {
            param($Writer, [object[]]$Results = @(), $Presence = $false)
            $f = New-TestT1Fixture ('t1lf' + [guid]::NewGuid().ToString('N').Substring(0, 6)) 2
            $seen = @{ Reader = 0 }
            $reader = { param($x) $seen.Reader++; $x }.GetNewClosure()
            $d = New-TestCleanDeleter -Writer $Writer -Results $Results -Presence $Presence
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $Writer -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
            [pscustomobject]@{ C = $c; Calls = $d.Calls.Count; Reader = $seen.Reader; Types = (@(Get-TestCleanLogRecords $Writer | ForEach-Object { $_.type }) -join ','); Stages = (@($c.LogErrors | ForEach-Object { $_.Stage }) -join ',') }
        }
        foreach ($t in @('run-start', 'plan')) {
            $w = New-TestCleanLogWriter -FailOn $t
            $o = & $go $w
            Assert-True ($o.C.Aborted -ceq 'LOG_WRITE_FAILED' -and $o.Calls -eq 0 -and $o.Reader -eq 0 -and $o.Stages -ceq $t) "$($t): abortado antes da confirmacao ($($o.C.Aborted), leitor $($o.Reader), estagios $($o.Stages))"
            Assert-True ($w.Disposed -ge 1) "$($t): liberado"
        }
        $o = & $go (New-TestCleanLogWriter -FailOn 'confirmation')
        Assert-True ($o.C.Aborted -ceq 'LOG_WRITE_FAILED' -and $o.Calls -eq 0 -and $o.Reader -eq 5 -and $o.Stages -ceq 'confirmation' -and -not $o.C.Confirmed) "confirmacao nao registrada: nada iniciado ($($o.C.Aborted))"
        $o = & $go (New-TestCleanLogWriter -FailOn 'intent')
        Assert-True ($o.C.Aborted -ceq 'LOG_INTENT_FAILED' -and $o.Calls -eq 0 -and @($o.C.LogErrors)[0].OpId -ceq ('{0}:1' -f $o.C.RunId)) "intent da primeira raiz: deleter nunca chamado ($($o.C.Aborted))"
        $o = & $go (New-TestCleanLogWriter -FailOn 'intent' -FailAt 2)
        Assert-True ($o.C.StoppedBy -ceq 'LOG_INTENT_FAILED' -and $null -eq $o.C.Aborted -and $o.Calls -eq 1 -and @($o.C.Deleted).Count -eq 1) "intent da segunda raiz: parada depois da primeira ($($o.C.StoppedBy), $($o.Calls))"
        $w = New-TestCleanLogWriter -FailOn 'result'
        $o = & $go $w
        $e = @($o.C.LogErrors)[0]
        Assert-True ($o.C.StoppedBy -ceq 'LOG_RESULT_FAILED' -and $o.Calls -eq 1 -and $e.Stage -ceq 'result' -and $e.OpId -ceq @($o.C.Deleted)[0].OpId -and @($o.C.Deleted)[0].Outcome -ceq 'COMPLETE') "result: nenhuma nova chamada, opId e resultado conhecido ($($o.C.StoppedBy) $($e.OpId))"
        Assert-True (-not $o.Types.Contains('run-end') -and $w.Closed -eq 1) 'depois da falha nada mais e escrito (sem run-end); fechado'
        $txt = (@(Show-AtmCleanResult -Result $o.C 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.stopped' 'LOG_RESULT_FAILED')) -and $txt.Contains((Get-AtmText 'clean.logError' 'result' $e.OpId $e.Code))) 'console: parada e falha do log com o opId'
        $o = & $go (New-TestCleanLogWriter -FailOn 'run-end')
        Assert-True ($o.C.StoppedBy -ceq 'LOG_END_FAILED' -and $o.Calls -eq 2 -and $o.Stages -ceq 'run-end') "run-end: execucao nunca apresentada como completa ($($o.C.StoppedBy))"
        $o = & $go (New-TestCleanLogWriter -CloseCode 'LOG_CLOSE_FAILED_WIN32_6')
        Assert-True ($o.C.StoppedBy -ceq 'LOG_CLOSE_FAILED' -and $o.Stages -ceq 'close' -and $o.Types.EndsWith('run-end')) "fechamento: execucao nunca apresentada como completa ($($o.C.StoppedBy))"
        $o = & $go (New-TestCleanLogWriter -FailOn 'result' -CloseCode 'LOG_CLOSE_FAILED_WIN32_6')
        Assert-True ($o.C.StoppedBy -ceq 'LOG_RESULT_FAILED' -and $o.Stages -ceq 'result,close') "erro principal mantido ($($o.C.StoppedBy); $($o.Stages))"
        $o = & $go (New-TestCleanLogWriter -CloseCode 'LOG_CLOSE_FAILED_WIN32_6') @('REFUSED') $true
        Assert-True ($o.C.StoppedBy -ceq 'STOPPED_AFTER_REFUSED' -and $o.Stages -ceq 'close') "recusa mantida como motivo ($($o.C.StoppedBy); $($o.Stages))"
    }
    Test-Case 'Clean log (T1)' 'Confirmacao rejeitada: registrada, deleter nunca chamado, log encerrado; sem -LogFile com a trava aberta: LOG_REQUIRED antes de qualquer confirmacao' {
        $f = New-TestT1Fixture 't1rej' 1
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader { param($x) 'nao' } -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($c.Aborted -ceq 'DECLARATION_DECLINED' -and $c.RefusedAt.Step -ceq 'task' -and $d.Calls.Count -eq 0 -and -not $c.Confirmed) "rejeitada ($($c.Aborted))"
        $recs = Get-TestCleanLogRecords $w
        Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,confirmation,run-end' 'registros'
        Assert-True (@($recs | Where-Object { $_.type -ceq 'confirmation' })[0].accepted -eq $false) 'rejeicao registrada'
        Assert-True ($w.Closed -eq 1 -and $null -eq $c.PostInventory) 'log encerrado; sem auditoria posterior (nada iniciado)'
        $seen = @{ Reader = 0 }
        $d2 = New-TestCleanDeleter
        $c2 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ({ param($x) $seen.Reader++; $x }.GetNewClosure()) -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present
        Assert-True ($c2.Aborted -ceq 'LOG_REQUIRED' -and $seen.Reader -eq 0 -and $d2.Calls.Count -eq 0 -and $null -eq $c2.RunId) "LOG_REQUIRED ($($c2.Aborted))"
        $txt = (@(Show-AtmCleanResult -Result $c2 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.logRequired')) -and $txt.Contains((Get-AtmText 'clean.nothing'))) 'console explica a exigencia'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean log (T1)' 'CREATED_* (resultado simulado do escritor): arquivo criado e recusado depois - resultado e console dizem que foi criado, o arquivo fica intacto, nenhuma confirmacao nem chamada ao deleter' {
        # Simulated: Open-AtmCleanLog is replaced in this scope only by a stand-in that reports a refusal after the creation
        # (no real failure is provoked); the file it "created" is a sandbox fixture written here, checked intact at the end.
        $f = New-TestT1Fixture 't1created' 1
        $path = Join-Path $sandbox 't1-created-refused.jsonl'
        [IO.File]::WriteAllText($path, '')
        $seen = @{ Reader = 0 }
        $d = New-TestCleanDeleter
        $c = & {
            Set-Item -LiteralPath 'function:local:Open-AtmCleanLog' -Value { param([string]$Path, $Inventory, [string]$ProcessUserSid) [pscustomobject]@{ Log = $null; Code = 'LOG_CREATE_CREATED_LINK_COUNT'; Created = $true } }
            Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ({ param($x) $seen.Reader++; $x }.GetNewClosure()) -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogFile $path -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        }
        Assert-True ($c.Aborted -ceq 'LOG_OPEN_FAILED' -and $c.LogCreated -and $c.LogFile -ceq $path) "recusa depois da criacao ($($c.Aborted), criado=$($c.LogCreated))"
        Assert-True (@($c.LogErrors)[0].Stage -ceq 'open' -and @($c.LogErrors)[0].Code -ceq 'LOG_CREATE_CREATED_LINK_COUNT') 'codigo CREATED_ propagado'
        Assert-True ($seen.Reader -eq 0 -and $d.Calls.Count -eq 0 -and -not $c.Confirmed -and @($c.Deleted).Count -eq 0) 'nenhuma confirmacao nem exclusao iniciada'
        $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.logKept' $path)) -and $txt.Contains('LOG_CREATE_CREATED_LINK_COUNT')) 'console: o arquivo foi criado e e mantido'
        Assert-True ([IO.File]::Exists($path)) 'arquivo preservado'
        Assert-Eq ${function:Open-AtmCleanLog}.ToString().Contains('AtmCleanLog]::Pin') $true 'o substituto nao vaza para o resto da suite'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean log (T1)' 'Revalidacao recusada: registro skip com opId, caminho e motivos; nenhum intent nem chamada ao deleter para essa raiz; a execucao para (AUT-2: REVALIDATION_REFUSED)' {
        $f = New-TestT1Fixture 't1skip' 1
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $hook = { param($part) [IO.File]::WriteAllBytes((Join-Path $part.Path 'apareceu.bin'), (New-Object byte[] 9)) }
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -BeforeDeleteHook $hook -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        $recs = Get-TestCleanLogRecords $w
        Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,declaration,confirmation,plan-check,skip,run-end' 'registros'
        $sk = @($recs | Where-Object { $_.type -ceq 'skip' })[0]
        Assert-True ($sk.opId -ceq ('{0}:1' -f $c.RunId) -and [string]::Equals($sk.path, $f.Roots[0], [StringComparison]::OrdinalIgnoreCase) -and ((@($sk.reasons) -join ' ') -match 'ALTERADO_APOS_CONFIRMACAO')) "skip identificado ($(@($sk.reasons) -join ';'))"
        Assert-True ($d.Calls.Count -eq 0 -and @($c.Deleted).Count -eq 0 -and @($c.Skipped).Count -eq 1 -and $c.Aborted -ceq 'REVALIDATION_REFUSED' -and $null -eq $c.StoppedBy) "nenhuma chamada; parada sem exclusao anterior = Aborted ($($c.Aborted) $($c.StoppedBy))"
        $end = @($recs | Where-Object { $_.type -ceq 'run-end' })[0]
        Assert-True ($end.skipped -eq 1 -and $end.stoppedBy -ceq 'REVALIDATION_REFUSED' -and $end.stoppedAtOpId -ceq ('{0}:1' -f $c.RunId)) 'run-end com a raiz que parou a execucao'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean log (T1)' 'Trava fechada: fluxo de plano inalterado - sem LOG_REQUIRED, log nunca criado nem aberto (caminho novo ou existente), escritor e deleter simulados nunca chamados' {
        $f = New-TestT1Fixture 't1gate' 1
        $new = Join-Path $sandbox 't1-gate-novo.jsonl'
        $old = Join-Path $sandbox 't1-gate-existente.jsonl'; [IO.File]::WriteAllText($old, 'x')
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $ia = Get-InvArgs -Profiles @($f.Profile)
        $script:AtmRealDeletionEnabled = $false
        try {
            $all = @(
                (Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs $ia),
                (Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs $ia -LogFile $new),
                (Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs $ia -LogFile $old),
                (Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs $ia -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present))
        } finally { $script:AtmRealDeletionEnabled = $true }
        foreach ($c in $all) {
            Assert-Eq $c.Aborted 'EXCLUSAO_REAL_DESABILITADA_V0_1' 'abortado pela trava'
            Assert-True ($null -eq $c.RunId -and $null -eq $c.LogFile -and -not $c.LogCreated -and @($c.LogErrors).Count -eq 0 -and @($c.Verified).Count -eq 1) 'plano validado, nenhum log'
        }
        Assert-True (-not (Test-Path -LiteralPath $new)) 'caminho novo nao criado'
        Assert-Eq ([IO.File]::ReadAllText($old)) 'x' 'arquivo existente intacto'
        Assert-True ($w.Lines.Count -eq 0 -and $w.Closed -eq 0 -and $w.Disposed -eq 0 -and $d.Calls.Count -eq 0) 'escritor e deleter simulados nunca chamados'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean log (T1)' 'Escritor real (sandbox): arquivo novo, JSON Lines UTF-8 sem BOM e LF, DACL protegida; enquanto aberto, leitura permitida e outro escritor ou renomeacao recusados; mesmo nome, nome existente e pasta recusados sem alterar nada; registro grande ou com quebra de linha para o log; handle liberado' {
        $dir = New-TestCleanLogDir 'writer'
        if (-not $dir) { return }
        $inv = Inv -Profiles @((New-TestProfile 't1writer'))
        $path = Join-Path $dir 'run.jsonl'
        $o = Open-AtmCleanLog -Path $path -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($null -ne $o.Log -and $o.Created -and $null -eq $o.Code) "aberto ($($o.Code))"
        $log = $o.Log
        try {
            $st = @{ RunId = 'r-t1'; RecSeq = 0 }
            Assert-Eq (Write-AtmCleanLogRecord -Log $log -State $st -Type 'run-start' -Fields ([ordered]@{ user = $uni })) $null 'registro 1'
            Assert-Eq (Write-AtmCleanLogRecord -Log $log -State $st -Type 'plan' -Fields ([ordered]@{ path = "C:\x\$uni" })) $null 'registro 2'
            $other = 'ABERTO'; try { $fs = [IO.File]::Open($path, 'Open', 'Write', 'ReadWrite'); $fs.Dispose() } catch { $other = 'RECUSADO' }
            Assert-Eq $other 'RECUSADO' 'outro escritor enquanto aberto'
            $mv = 'MOVIDO'; try { [IO.File]::Move($path, (Join-Path $dir 'movido.jsonl')) } catch { $mv = 'RECUSADO' }
            Assert-Eq $mv 'RECUSADO' 'renomear enquanto aberto'
            $fs = [IO.File]::Open($path, 'Open', 'Read', 'ReadWrite'); try { $len = $fs.Length } finally { $fs.Dispose() }
            Assert-True ($len -gt 0) 'leitura permitida; registros ja gravados'
            $o2 = Open-AtmCleanLog -Path $path -Inventory $inv -ProcessUserSid $me.Sid
            Assert-True ($null -eq $o2.Log -and $o2.Code -ceq 'LOG_CREATE_EXISTS' -and -not $o2.Created) "segundo log no mesmo nome recusado ($($o2.Code))"
            Assert-Eq ($log.AppendLine(('x' * 70000))) 'LOG_RECORD_TOO_LARGE' 'registro acima do limite'
            Assert-Eq ($log.AppendLine('{"n":3}')) 'LOG_STOPPED' 'nada e escrito depois da primeira falha'
            Assert-Eq ($log.Close()) $null 'fechamento'
        } finally { $log.Dispose() }
        $fs = [IO.File]::Open($path, 'Open', 'Read', 'None'); $fs.Dispose()
        $rd = Read-TestCleanLogFile $path
        Assert-True (-not $rd.Bom -and -not $rd.Cr -and $rd.EndsLf) 'UTF-8 sem BOM, LF'
        Assert-Eq @($rd.Records).Count 2 'somente os registros aceitos'
        Assert-True ($rd.Records[0].user -ceq $uni -and $rd.Records[1].recSeq -eq 2 -and $rd.Records[1].runId -ceq 'r-t1') 'conteudo e Unicode preservados'
        Assert-True ((Get-Acl -LiteralPath $path).AreAccessRulesProtected) 'DACL protegida'
        $nl = Open-AtmCleanLog -Path (Join-Path $dir 'nl.jsonl') -Inventory $inv -ProcessUserSid $me.Sid
        try { Assert-Eq ($nl.Log.AppendLine("a`nb")) 'LOG_RECORD_INVALID' 'quebra de linha recusada' } finally { $nl.Log.Dispose() }
        Assert-Eq ([IO.File]::ReadAllBytes((Join-Path $dir 'nl.jsonl'))).Length 0 'nada gravado (arquivo criado e mantido)'
        # The 64 KiB limit counts UTF-8 bytes (with the LF), not characters: 21845 CJK characters are 65535 bytes + LF.
        $mb = Open-AtmCleanLog -Path (Join-Path $dir 'bytes.jsonl') -Inventory $inv -ProcessUserSid $me.Sid
        try {
            $cjk = [string][char]0x65E5
            Assert-Eq ($mb.Log.AppendLine(($cjk * 21845))) $null '65536 bytes UTF-8 (limite exato) aceitos'
            Assert-Eq ($mb.Log.AppendLine(($cjk * 21846))) 'LOG_RECORD_TOO_LARGE' '21846 caracteres = 65539 bytes: recusado (bem abaixo de 65536 caracteres)'
        } finally { $mb.Log.Dispose() }
        Assert-Eq ([IO.File]::ReadAllBytes((Join-Path $dir 'bytes.jsonl'))).Length 65536 'so o registro dentro do limite foi gravado'
        $sg = Open-AtmCleanLog -Path (Join-Path $dir 'surrogate.jsonl') -Inventory $inv -ProcessUserSid $me.Sid
        try { Assert-Eq ($sg.Log.AppendLine(('a' + [char]0xD800 + 'b'))) 'LOG_RECORD_INVALID' 'UTF-16 invalido (surrogate isolado) recusado, nunca substituido' } finally { $sg.Log.Dispose() }
        Assert-Eq ([IO.File]::ReadAllBytes((Join-Path $dir 'surrogate.jsonl'))).Length 0 'nada gravado'
        $ex = Join-Path $dir 'existente.jsonl'; [IO.File]::WriteAllText($ex, 'antes')
        $o3 = Open-AtmCleanLog -Path $ex -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($null -eq $o3.Log -and $o3.Code -ceq 'LOG_CREATE_EXISTS' -and -not $o3.Created -and [IO.File]::ReadAllText($ex) -ceq 'antes') "existente recusado e intacto ($($o3.Code))"
        $dn = Join-Path $dir 'pasta.jsonl'; [void][IO.Directory]::CreateDirectory($dn)
        $o4 = Open-AtmCleanLog -Path $dn -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($null -eq $o4.Log -and $o4.Code -ceq 'LOG_CREATE_EXISTS') "pasta com o nome recusada ($($o4.Code))"
    }
    Test-Case 'Clean log (T1)' 'Destino do log: dentro de uma base auditada, nao canonico ou pasta inexistente recusados; pasta em que outra conta pode criar arquivos recusada sem alterar a ACL e sem criar arquivo' {
        $dir = New-TestCleanLogDir 'dest'
        if (-not $dir) { return }
        $p = New-TestProfile 't1dest'; $null = New-TestRoot -ProfileInfo $p
        $inv = Inv -Profiles @($p)
        $inBase = Join-Path (Get-Base $p) 'log.jsonl'
        $o = Open-AtmCleanLog -Path $inBase -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($o.Code -ceq 'LOG_DESTINATION_NOT_ALLOWED' -and -not $o.Created -and -not (Test-Path -LiteralPath $inBase)) "dentro da base ($($o.Code))"
        $o = Open-AtmCleanLog -Path ((Get-Base $p) + '\..\log.jsonl') -Inventory $inv -ProcessUserSid $me.Sid
        Assert-Eq $o.Code 'LOG_DESTINATION_NOT_ALLOWED' 'nao canonico'
        $inRoot = Join-Path (@($inv.Partitions | Where-Object { $_.Kind -eq 'SessionRoot' })[0].Path) 'log.jsonl'
        $o = Open-AtmCleanLog -Path $inRoot -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($o.Code -ceq 'LOG_DESTINATION_NOT_ALLOWED' -and -not $o.Created -and -not (Test-Path -LiteralPath $inRoot)) "dentro de uma raiz ($($o.Code))"
        $o = Open-AtmCleanLog -Path (Join-Path $dir 'nao-existe\x.jsonl') -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($o.Code -like 'LOG_PIN_*' -and -not $o.Created) "pasta inexistente ($($o.Code))"
        $open = Join-Path $dir 'aberta'; [void][IO.Directory]::CreateDirectory($open)
        $acl = Get-Acl -LiteralPath $open
        $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier('S-1-1-0')), 'CreateFiles', 'Allow')))
        Set-Acl -LiteralPath $open -AclObject $acl
        $before = (Get-Acl -LiteralPath $open).Sddl
        $o = Open-AtmCleanLog -Path (Join-Path $open 'x.jsonl') -Inventory $inv -ProcessUserSid $me.Sid
        Assert-True ($o.Code -ceq 'LOG_PIN_PARENT_THIRD_PARTY_WRITE' -and -not $o.Created) "pasta com escrita de terceiros ($($o.Code))"
        Assert-Eq (Get-Acl -LiteralPath $open).Sddl $before 'ACL inalterada'
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $open 'x.jsonl'))) 'nenhum arquivo criado'
    }
    Test-Case 'Clean log (T1)' 'Fluxo com -LogFile real (sandbox) e deleter simulado: intent lido do proprio arquivo antes de cada chamada, registros completos, handle liberado; arquivo existente -> LOG_OPEN_FAILED sem confirmacao nem chamada, arquivo intacto' {
        $dir = New-TestCleanLogDir 'flow'
        if (-not $dir) { return }
        $f = New-TestT1Fixture 't1flow' 2
        $path = Join-Path $dir 'clean.jsonl'
        $d = New-TestCleanDeleter -LogPath $path
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogFile $path -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($null -eq $c.Aborted -and $null -eq $c.StoppedBy -and $c.LogFile -ceq $path -and $c.LogCreated) "execucao ($($c.Aborted) $($c.StoppedBy) $(@($c.LogErrors | ForEach-Object { $_.Code }) -join ','))"
        Assert-Eq $d.Calls.Count 2 'duas chamadas'
        foreach ($call in $d.Calls) { Assert-True ($call.LastType -ceq 'intent' -and [string]::Equals($call.LastPath, $call.Path, [StringComparison]::OrdinalIgnoreCase)) "intent no arquivo antes da chamada ($($call.LastType))" }
        $fs = [IO.File]::Open($path, 'Open', 'Read', 'None'); $fs.Dispose()
        $rd = Read-TestCleanLogFile $path
        Assert-Eq (@($rd.Records | ForEach-Object { $_.type }) -join ',') 'run-start,plan,plan,declaration,declaration,confirmation,plan-check,intent,result,intent,result,run-end' 'registros no arquivo'
        Assert-Eq @($rd.Records | Where-Object { $_.runId -cne $c.RunId }).Count 0 'runId'
        $bytes = [IO.File]::ReadAllBytes($path)
        $seen = @{ Reader = 0 }
        $d2 = New-TestCleanDeleter
        $c2 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ({ param($x) $seen.Reader++; $x }.GetNewClosure()) -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogFile $path -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present
        Assert-True ($c2.Aborted -ceq 'LOG_OPEN_FAILED' -and @($c2.LogErrors)[0].Code -ceq 'LOG_CREATE_EXISTS' -and -not $c2.LogCreated -and $seen.Reader -eq 0 -and $d2.Calls.Count -eq 0) "existente ($($c2.Aborted) $(@($c2.LogErrors)[0].Code))"
        Assert-Eq ([Convert]::ToBase64String([IO.File]::ReadAllBytes($path))) ([Convert]::ToBase64String($bytes)) 'arquivo existente intacto'
        # A log inside a root this run would delete is outside the destination policy (every root is inside a base).
        $inRoot = Join-Path $f.Roots[0] 'clean.jsonl'
        $d3 = New-TestCleanDeleter
        $seen.Reader = 0
        $c3 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ({ param($x) $seen.Reader++; $x }.GetNewClosure()) -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogFile $inRoot -DeleteTreeImpl $d3.Delete -PathPresenceImpl $d3.Present
        Assert-True ($c3.Aborted -ceq 'LOG_OPEN_FAILED' -and @($c3.LogErrors)[0].Code -ceq 'LOG_DESTINATION_NOT_ALLOWED' -and $seen.Reader -eq 0 -and $d3.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $inRoot)) "log dentro da raiz a excluir recusado ($($c3.Aborted) $(@($c3.LogErrors)[0].Code))"
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean log (T1)' 'Interrupcao entre intent e result: processo filho que sai sozinho dentro do deleter simulado (sem encerramento forcado) deixa intent sem result - desfecho desconhecido; raiz intacta' {
        $dir = New-TestCleanLogDir 'interrupt'
        if (-not $dir) { return }
        $f = New-TestT1Fixture 't1intr' 1
        $path = Join-Path $dir 'intr.jsonl'
        $child = Join-Path $sandbox 't1-interrupt-child.ps1'
        [IO.File]::WriteAllText($child, @'
param([string]$Src, [string]$ProfileRoot, [string]$Temp, [string]$Sid, [string]$Name, [string]$IsAdmin, [string]$Root, [string]$LogFile, [string]$NowTicks, [string]$LockName)
# A fresh process: the product files as shipped, the deletion gate opened in THIS process only (as the suite does), and a
# stand-in deleter that deletes nothing and ends the process itself (Environment.Exit) after the intent was written.
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0
. (Join-Path $Src 'lib\Engine.Audit.ps1')
Initialize-AtmNative -LibDir (Join-Path $Src 'lib')
foreach ($f in @(Get-ChildItem -LiteralPath (Join-Path $Src 'providers') -Filter '*.ps1' -File | Sort-Object Name)) { . $f.FullName }
. (Join-Path $Src 'lib\Engine.Clean.ps1')
. (Join-Path $Src 'lib\Engine.Diagnose.ps1')
$script:AtmRealDeletionEnabled = $true
# B8: a test lock name of its own (this child ends inside the run, so it abandons that mutex), never the product name.
$script:AtmCleanLockName = $LockName
# B2-1: as the suite, no query of this runner's services or Hyper-V.
$script:AtmRuntimeEvidenceSources = @{ ServiceSource = { param($Names) @() }; VirtualizationSource = { param($Op) @() } }
# AUT-2: as the suite, the console observation replaced (this child has no console).
$script:AtmCleanConsoleSource = { $true }
$prof =[pscustomobject]@{ Sid = $Sid; UserName = 'TEST\t1intr'; ProfilePath = $ProfileRoot; Loaded = $true; Special = $false; Origin = 'Test'; EnvStatus = 'OK'
    TempCandidates = @([pscustomobject]@{ TempPath = $Temp; Source = 'test' }); EnvValues = @{}; EnvKnown = $true; Notes = @() }
$ia = @{ ProfilesOverride = @($prof); ProcessesOverride = @([pscustomobject]@{ ProcessId = 1; Name = 'idle.exe'; ParentProcessId = 0; CommandLine = 'idle.exe'; CreationDate = (Get-Date).AddHours(-1) })
    IdentityOverride = [pscustomobject]@{ Sid = $Sid; Name = $Name; IsAdmin = ($IsAdmin -ceq 'True') }; NowUtc = (New-Object DateTime ([long]$NowTicks), ([DateTimeKind]::Utc)); NoProgress = $true; ConfigDir = (Join-Path $Src 'config') }
$c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $Root; Fingerprint = $null }) -PlanPresenter { param($v, $r, $i) } -ConfirmationReader { param($x) $x } -InventoryArgs $ia -LogFile $LogFile -DeleteTreeImpl { param($Part) [Environment]::Exit(7) } -PathPresenceImpl { param($P) $false }
[Console]::Out.WriteLine('NOT_EXITED ' + $c.Aborted + ' ' + $c.StoppedBy)
exit 0
'@, (New-Object Text.UTF8Encoding $true))
        $shell = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $tp = $f.Profile.TempCandidates[0].TempPath
        $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$child`" -Src `"$srcDir`" -ProfileRoot `"$($f.Profile.ProfilePath)`" -Temp `"$tp`" -Sid `"$($testIdentity.Sid)`" -Name `"$($testIdentity.Name)`" -IsAdmin `"$($testIdentity.IsAdmin)`" -Root `"$($f.Roots[0])`" -LogFile `"$path`" -NowTicks `"$($nowFuture.Ticks)`" -LockName `"$(New-TestLockName)`"") -TimeoutSec 300
        Assert-True ($r.Exit -eq 7 -and -not $r.TimedOut) "o filho saiu sozinho dentro do deleter simulado (saida $($r.Exit) $($r.Text))"
        $rd = Read-TestCleanLogFile $path
        $types = @($rd.Records | ForEach-Object { $_.type })
        Assert-Eq ($types -join ',') 'run-start,plan,declaration,confirmation,plan-check,intent' 'o log termina no intent: sem result e sem run-end'
        Assert-True (-not $rd.Bom -and $rd.EndsLf) 'registros completos ate o intent'
        Assert-True (Test-TestT1RootsIntact $f) 'raiz intacta (o deleter simulado nada apagou)'
        $script:caseNote = 'intent sem result = desfecho desconhecido; queda de energia e falha real de flush nao reproduzidas'
    }
    Test-Case 'Clean log (T1)' 'Estatico: seams de teste nunca usados fora do motor; intent antes do unico ponto de exclusao; LOG_REQUIRED depois da trava; acesso do escritor so de acrescimo e criacao de arquivo novo; CLI nao trata parada como sucesso' {
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Clean.ps1' })) {
            $txt = [IO.File]::ReadAllText($fi.FullName)
            foreach ($seam in @('DeleteTreeImpl', 'PathPresenceImpl', 'LogWriter')) { Assert-True (-not $txt.Contains($seam)) "$($fi.Name) usa o seam $seam" }
        }
        $iGate = $clean.IndexOf("'EXCLUSAO_REAL_DESABILITADA_V0_1'"); $iReq = $clean.IndexOf("'LOG_REQUIRED'"); $iIntent = $clean.IndexOf("-Type 'intent'"); $iDel = $clean.IndexOf('AtmDeleter]::DeleteTree')
        Assert-True ($iGate -gt 0 -and $iReq -gt $iGate -and $iIntent -gt $iReq -and $iDel -gt $iIntent) "ordem no motor: trava $iGate < LOG_REQUIRED $iReq < intent $iIntent < exclusao $iDel"
        $ncs = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Native.cs'))
        $cls = $ncs.Substring($ncs.IndexOf('public sealed class AtmCleanLog'))
        $cls = $cls.Substring(0, $cls.IndexOf('public static class AtmPathCheck'))
        Assert-True ($cls.Contains('FILE_APPEND_DATA | FILE_READ_ATTRIBUTES | READ_CONTROL | SYNCHRONIZE, ref oa') -and $cls.Contains('FILE_SHARE_READ, FILE_CREATE,') -and $cls.Contains('OBJ_DONT_REPARSE') -and $cls.Contains('FILE_OPEN_REPARSE_POINT | FILE_WRITE_THROUGH') -and $cls.Contains('FlushFileBuffers(file)')) 'escritor: acrescimo, arquivo novo, sem reparse, write-through e flush'
        foreach ($pat in @('DeleteFile', 'DeleteTree', 'DELETE_ON_CLOSE', 'FileDispositionInformation', 'SetFileInformationByHandle', 'SetSecurityInfo', 'SetNamedSecurityInfo')) { Assert-True (-not $cls.Contains($pat)) "escritor nunca remove arquivo nem altera ACL ($pat)" }
        Assert-True ($cls.Contains('if (written != (uint)body.Length) return Stop("LOG_WRITE_INCOMPLETE")') -and $cls.Contains('new UTF8Encoding(false, true).GetBytes(line + "\n")') -and $cls.Contains('if (body.Length > MaxRecordBytes)')) 'escrita parcial detectada; limite contado nos bytes UTF-8 da linha com o LF'
        Assert-True ([IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1')).Contains('exit $(if ($res.Aborted -or $res.StoppedBy) { 3 } else { 0 })')) 'CLI: parada depois de uma exclusao sai com 3'
    }

    # ------------------------------------------------------------------ clean lock (B8)
    # Test lock names only (Global\AgentTempManager.Test.<hex>; the suite's own name, or a new one per case); the stand-in
    # deleter everywhere; child processes always end by themselves. Same identity only: other users, sessions and
    # elevation levels are operator-only (last case, NAO_TESTADO).
    Test-Case 'Clean lock (B8)' 'Segunda execucao recusada antes do inventario e de qualquer log enquanto outro processo (mesma identidade) mantem o lock; execucao seguinte permitida depois da liberacao' {
        $n = New-TestLockName
        $f = New-TestT1Fixture 'b8busy' 1
        $prev = $script:AtmCleanLockName
        $script:AtmCleanLockName = $n
        try {
            $h = Start-TestLockHolder -Name $n -Mode release
            Assert-Eq $h.Status 'ACQUIRED' 'o processo filho criou e adquiriu o lock de teste'
            $k = New-TestCleanCounter
            $w = New-TestCleanLogWriter
            $d = New-TestCleanDeleter -Writer $w
            $logPath = Join-Path $sandbox 'b8-busy-nao-criado.jsonl'
            $c = & {
                Set-Item -LiteralPath 'function:local:Invoke-AtmInventory' -Value $k.Inventory
                Invoke-AtmClean -Entries $f.Entries -PlanPresenter $k.Presenter -ConfirmationReader $k.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogFile $logPath -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            }
            Assert-True ($c.Aborted -ceq 'CLEAN_LOCK_BUSY' -and $null -eq $c.RunId) "recusado ($($c.Aborted))"
            Assert-True ($k.Inv -eq 0 -and $k.Pres -eq 0 -and $k.Read -eq 0 -and $d.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $logPath)) "nada iniciado: inventario $($k.Inv), plano $($k.Pres), confirmacao $($k.Read), deleter $($d.Calls.Count), log"
            Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) 'nada mantido neste processo'
            $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
            Assert-True ($txt.Contains((Get-AtmText 'clean.lockUnavailable' 'CLEAN_LOCK_BUSY')) -and $txt.Contains((Get-AtmText 'clean.nothing'))) 'mensagem de lock indisponivel'
            $end = Stop-TestLockHolderByGo $h
            Assert-True ($end.Exited -and $end.Exit -eq 0) "o filho liberou e terminou sozinho (saida $($end.Exit))"
            $w2 = New-TestCleanLogWriter
            $d2 = New-TestCleanDeleter -Writer $w2
            $c2 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w2 -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present
            Assert-True ($null -eq $c2.Aborted -and $null -eq $c2.StoppedBy -and $d2.Calls.Count -eq 1 -and $null -eq $c2.LockReleaseError) "execucao seguinte completa ($($c2.Aborted) $($c2.StoppedBy))"
            Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) 'liberado ao final'
        } finally { $script:AtmCleanLockName = $prev }
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean lock (B8)' 'Liberacao em todos os caminhos: confirmacao rejeitada, falhas do log, desfechos do deleter simulado e excecao inesperada; confirmado por outro processo ao final' {
        $n = New-TestLockName
        $prev = $script:AtmCleanLockName
        $script:AtmCleanLockName = $n
        try {
            $runs = @(
                @{ Tag = 'rejeitada'; Reader = { param($x) 'nao' }; Writer = (New-TestCleanLogWriter); Results = @(); Presence = $false; Want = 'DECLARATION_DECLINED' },
                @{ Tag = 'run-start'; Reader = ${function:Confirm-Correct}; Writer = (New-TestCleanLogWriter -FailOn 'run-start'); Results = @(); Presence = $false; Want = 'LOG_WRITE_FAILED' },
                @{ Tag = 'intent'; Reader = ${function:Confirm-Correct}; Writer = (New-TestCleanLogWriter -FailOn 'intent'); Results = @(); Presence = $false; Want = 'LOG_INTENT_FAILED' },
                @{ Tag = 'excecao do deleter'; Reader = ${function:Confirm-Correct}; Writer = (New-TestCleanLogWriter); Results = @('THROW'); Presence = $false; Want = 'STOPPED_AFTER_EXCEPTION' },
                @{ Tag = 'recusa'; Reader = ${function:Confirm-Correct}; Writer = (New-TestCleanLogWriter); Results = @('REFUSED'); Presence = $true; Want = 'STOPPED_AFTER_REFUSED' },
                @{ Tag = 'fechamento'; Reader = ${function:Confirm-Correct}; Writer = (New-TestCleanLogWriter -CloseCode 'LOG_CLOSE_FAILED_WIN32_6'); Results = @(); Presence = $false; Want = 'LOG_CLOSE_FAILED' })
            foreach ($run in $runs) {
                $f = New-TestT1Fixture ('b8rel' + [guid]::NewGuid().ToString('N').Substring(0, 6)) 1
                $d = New-TestCleanDeleter -Writer $run.Writer -Results $run.Results -Presence $run.Presence
                $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $run.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $run.Writer -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
                $code = $(if ($c.Aborted) { $c.Aborted } else { $c.StoppedBy })
                Assert-True ($code -ceq $run.Want -and $null -eq $c.LockReleaseError) "$($run.Tag): $code"
                Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) "$($run.Tag): lock liberado"
                Assert-True (Test-TestT1RootsIntact $f) "$($run.Tag): nada apagado"
            }
            # An unexpected exception after the acquisition (the presenter throws): the lock is still released.
            $f = New-TestT1Fixture 'b8throw' 1
            $d = New-TestCleanDeleter
            $threw = $false
            try { $null = Invoke-AtmClean -Entries $f.Entries -PlanPresenter { param($v, $r, $i) throw 'PRESENTER_FAILED' } -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present } catch { $threw = $true }
            Assert-True ($threw -and $d.Calls.Count -eq 0 -and -not [AgentTempManager.AtmCleanLock]::IsHeld) 'excecao inesperada: propagada, lock liberado'
            # Another process confirms the kernel ownership was released (not only this process's reservation).
            $h = Start-TestLockHolder -Name $n -Mode release -GoNow
            $end = Stop-TestLockHolderByGo $h
            Assert-True ($h.Status -ceq 'ACQUIRED' -and $end.Exited -and $end.Exit -eq 0) "outro processo adquire em seguida ($($h.Status), saida $($end.Exit))"
        } finally { $script:AtmCleanLockName = $prev }
    }
    Test-Case 'Clean lock (B8)' 'Aninhamento na mesma thread recusado (CLEAN_LOCK_NESTED) sem liberar o lock da execucao externa' {
        # The presenter runs inside the engine and reaches these variables (and the suite's functions) by dynamic scope;
        # the b8* names avoid the engine's own variable names.
        $b8Fix = New-TestT1Fixture 'b8nest' 1
        $b8Inner = @{ Result = $null; HeldAfter = $null; Pres = $null }
        $b8Del = New-TestCleanDeleter
        $nestedPresenter = {
            param($v, $r, $i)
            $b8k = New-TestCleanCounter
            $b8Inner.Result = Invoke-AtmClean -Entries $b8Fix.Entries -PlanPresenter $b8k.Presenter -ConfirmationReader $b8k.Reader -InventoryArgs (Get-InvArgs -Profiles @($b8Fix.Profile)) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $b8Del.Delete -PathPresenceImpl $b8Del.Present
            $b8Inner.Pres = $b8k.Pres
            $b8Inner.HeldAfter = [AgentTempManager.AtmCleanLock]::IsHeld
        }
        $c = Invoke-AtmClean -Entries $b8Fix.Entries -PlanPresenter $nestedPresenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($b8Fix.Profile)) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $b8Del.Delete -PathPresenceImpl $b8Del.Present
        Assert-True ($null -ne $b8Inner.Result -and $b8Inner.Result.Aborted -ceq 'CLEAN_LOCK_NESTED' -and $b8Inner.Pres -eq 0) "interna recusada ($(if ($b8Inner.Result) { $b8Inner.Result.Aborted }))"
        Assert-True ($b8Inner.HeldAfter -eq $true) 'o lock externo continua mantido depois da recusa interna'
        Assert-True ($null -eq $c.Aborted -and $null -eq $c.StoppedBy -and $b8Del.Calls.Count -eq 1 -and $null -eq $c.LockReleaseError) "externa completa ($($c.Aborted) $($c.StoppedBy))"
        Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) 'liberado ao final'
        Assert-True (Test-TestT1RootsIntact $b8Fix) 'nada apagado'
    }
    Test-Case 'Clean lock (B8)' 'Abandono por saida voluntaria de processo filho: CLEAN_LOCK_ABANDONED sem inventario, plano, log nem deleter, posse liberada; nova tentativa comeca do zero' {
        Initialize-AtmTestMutex
        $n = New-TestLockName
        $f = New-TestT1Fixture 'b8aband' 1
        $prev = $script:AtmCleanLockName
        $script:AtmCleanLockName = $n
        $obs = $null
        try {
            $h = Start-TestLockHolder -Name $n -Mode abandon
            Assert-Eq $h.Status 'ACQUIRED' 'o filho adquiriu'
            # An observer handle (not an owner) keeps the object alive after the child ends, so its abandoned state remains.
            $obs = [AtmTestMutex]::OpenSync($n)
            Assert-True (-not $obs.IsInvalid) 'handle observador aberto'
            $end = Stop-TestLockHolderByGo $h
            Assert-True ($end.Exited -and $end.Exit -eq 0) "o filho terminou sozinho sem liberar (saida $($end.Exit))"
            $k = New-TestCleanCounter
            $w = New-TestCleanLogWriter
            $d = New-TestCleanDeleter -Writer $w
            $c = & {
                Set-Item -LiteralPath 'function:local:Invoke-AtmInventory' -Value $k.Inventory
                Invoke-AtmClean -Entries $f.Entries -PlanPresenter $k.Presenter -ConfirmationReader $k.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            }
            Assert-True ($c.Aborted -ceq 'CLEAN_LOCK_ABANDONED' -and $null -eq $c.LockReleaseError -and $null -eq $c.RunId) "abandono ($($c.Aborted) [$($c.LockReleaseError)])"
            Assert-True ($k.Inv -eq 0 -and $k.Pres -eq 0 -and $k.Read -eq 0 -and $d.Calls.Count -eq 0 -and $w.Lines.Count -eq 0) 'nada iniciado'
            Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) 'posse recebida liberada'
            $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
            Assert-True ($txt.Contains((Get-AtmText 'clean.lockAbandoned'))) 'mensagem de abandono'
            $w2 = New-TestCleanLogWriter
            $d2 = New-TestCleanDeleter -Writer $w2
            $c2 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w2 -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present
            Assert-True ($null -eq $c2.Aborted -and $null -eq $c2.StoppedBy -and $d2.Calls.Count -eq 1 -and @(Get-TestCleanLogRecords $w2)[0].type -ceq 'run-start') "nova tentativa do zero ($($c2.Aborted) $($c2.StoppedBy))"
        } finally {
            if ($null -ne $obs) { $obs.Dispose() }
            $script:AtmCleanLockName = $prev
        }
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
        # Without an observer handle the object is destroyed with the child's last handle: the next acquisition creates a
        # new mutex and sees no abandonment (the signal is opportunistic, never a persistent record).
        $n2 = New-TestLockName
        $h2 = Start-TestLockHolder -Name $n2 -Mode abandon
        $end2 = Stop-TestLockHolderByGo $h2
        $l2 = [AgentTempManager.AtmCleanLock]::TryAcquire($n2)
        try { Assert-True ($h2.Status -ceq 'ACQUIRED' -and $end2.Exited -and $end2.Exit -eq 0 -and $l2.Status -ceq 'ACQUIRED' -and $l2.Created) "sem observador: objeto novo, nenhum sinal de abandono ($($l2.Status), criado=$($l2.Created))" }
        finally { $null = $l2.Release() }
        $script:caseNote = 'abandono detectado so enquanto um handle observador mantem o objeto; sem ele, objeto novo e nenhum sinal'
    }
    Test-Case 'Clean lock (B8)' 'Liberacao impossivel (chamada por outra thread, processo filho): codigo LOCK_RELEASE_WRONG_THREAD, reserva mantida (nova aquisicao no mesmo processo recusada como NESTED), handle fechado' {
        # In a child process only: the reservation it keeps on purpose would refuse every later clean of the suite.
        $n = New-TestLockName
        $child = Join-Path $sandbox 'lock-wrongthread.ps1'
        $out = Join-Path $sandbox 'lock-wrongthread.txt'
        [IO.File]::WriteAllText($child, @'
param([string]$Src, [string]$Name, [string]$Out)
$ErrorActionPreference = 'Stop'
. (Join-Path $Src 'lib\Engine.Audit.ps1')
Initialize-AtmNative -LibDir (Join-Path $Src 'lib')
$l = [AgentTempManager.AtmCleanLock]::TryAcquire($Name)
# Release() called from the thread of another runspace: not the owner thread.
$ps = [powershell]::Create()
$null = $ps.AddScript({ param($x) $x.Release() }).AddArgument($l)
$rc = @($ps.Invoke())[0]
$ps.Dispose()
$held = [AgentTempManager.AtmCleanLock]::IsHeld
$again = [AgentTempManager.AtmCleanLock]::TryAcquire($Name)
[IO.File]::WriteAllText($Out, ('{0}|{1}|{2}|{3}' -f $l.Status, $rc, $held, $again.Status))
exit 0
'@, (New-Object Text.UTF8Encoding $true))
        $shell = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$child`" -Src `"$srcDir`" -Name `"$n`" -Out `"$out`"") -TimeoutSec 300
        Assert-True ($r.Exit -eq 0 -and (Test-Path -LiteralPath $out)) "processo filho ($($r.Exit) $($r.Text))"
        Assert-Eq ([IO.File]::ReadAllText($out)) 'ACQUIRED|LOCK_RELEASE_WRONG_THREAD|True|NESTED' 'falha de liberacao: reserva mantida (fail closed)'
        # The child ended by itself; its handle closed with it, so the object is gone and a new acquisition here works.
        $l = [AgentTempManager.AtmCleanLock]::TryAcquire($n)
        try { Assert-True ($l.Status -ceq 'ACQUIRED') "depois do fim do filho ($($l.Status))" } finally { $null = $l.Release() }
    }
    Test-Case 'Clean lock (B8)' 'Objeto preexistente incompativel (mutex com seguranca padrao, evento com o nome) e nome fora do padrao: recusados antes do inventario, sem alterar o objeto' {
        Initialize-AtmTestMutex
        $f = New-TestT1Fixture 'b8compat' 1
        $prev = $script:AtmCleanLockName
        try {
            foreach ($kind in @('mutex', 'event', 'name')) {
                $n = $(if ($kind -ceq 'name') { 'Local\AgentTempManager.Clean' } else { New-TestLockName })
                $obj = $(if ($kind -ceq 'mutex') { [AtmTestMutex]::CreateDefault($n) } elseif ($kind -ceq 'event') { [AtmTestMutex]::CreateNamedEvent($n) } else { $null })
                try {
                    $before = $(if ($kind -ceq 'mutex') { [AtmTestMutex]::GetSddl($n) } else { $null })
                    $script:AtmCleanLockName = $n
                    $k = New-TestCleanCounter
                    $d = New-TestCleanDeleter
                    $c = & {
                        Set-Item -LiteralPath 'function:local:Invoke-AtmInventory' -Value $k.Inventory
                        Invoke-AtmClean -Entries $f.Entries -PlanPresenter $k.Presenter -ConfirmationReader $k.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
                    }
                    $want = @{ mutex = 'CLEAN_LOCK_POLICY_'; event = 'CLEAN_LOCK_TYPE_MISMATCH'; name = 'CLEAN_LOCK_NAME_INVALID' }[$kind]
                    Assert-True ([string]$c.Aborted -clike "$want*" -and $k.Inv -eq 0 -and $k.Pres -eq 0 -and $d.Calls.Count -eq 0) "$($kind): $($c.Aborted)"
                    Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) "$($kind): nada mantido"
                    if ($kind -ceq 'mutex') { Assert-Eq ([AtmTestMutex]::GetSddl($n)) $before 'seguranca do objeto preexistente inalterada' }
                } finally { if ($null -ne $obj) { $obj.Dispose() } }
            }
        } finally { $script:AtmCleanLockName = $prev }
        foreach ($bad in @('Global\AgentTempManager.Clean2', 'Global\AgentTempManager.Test.XYZ', ('Global\AgentTempManager.Test.' + [guid]::NewGuid().ToString('N').ToUpperInvariant()), 'Local\AgentTempManager.Clean', 'AgentTempManager.Clean', '')) {
            Assert-True (-not [AgentTempManager.AtmCleanLock]::ValidName($bad)) "nome recusado: [$bad]"
        }
        Assert-True ([AgentTempManager.AtmCleanLock]::ValidName('Global\AgentTempManager.Clean') -and [AgentTempManager.AtmCleanLock]::ValidName($script:AtmCleanLockName)) 'nome de produto e nome de teste da suite aceitos'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean lock (B8)' 'F-E: processo novo, biblioteca nativa ainda nao carregada - depois da trava, clean sem -LogFile termina em LOG_REQUIRED (nunca tipo ausente), lock liberado, nenhum log; com a trava fechada, so o plano, sem lock nem pergunta' {
        $f = New-TestT1Fixture 'fixfe' 1
        $child = Join-Path $sandbox 'fixfe-child.ps1'
        [IO.File]::WriteAllText($child, @'
param([string]$Src, [string]$ProfileRoot, [string]$Temp, [string]$Sid, [string]$Name, [string]$IsAdmin, [string]$Root, [string]$NowTicks, [string]$LockName, [string]$Gate, [string]$Out)
# A fresh process: the product files as shipped and NO explicit load of the native library (as the CLI with no -LogFile:
# nothing inventories before the engine). The deletion gate is opened in THIS process only when -Gate open; the deleter
# is a stand-in that deletes nothing.
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0
. (Join-Path $Src 'lib\Engine.Audit.ps1')
foreach ($f in @(Get-ChildItem -LiteralPath (Join-Path $Src 'providers') -Filter '*.ps1' -File | Sort-Object Name)) { . $f.FullName }
. (Join-Path $Src 'lib\Engine.Clean.ps1')
. (Join-Path $Src 'lib\Engine.Diagnose.ps1')
$loadedBefore = [bool]('AgentTempManager.AtmScanner' -as [type])
$script:AtmRealDeletionEnabled = ($Gate -ceq 'open')
$script:AtmCleanLockName = $LockName
$script:AtmRuntimeEvidenceSources = @{ ServiceSource = { param($Names) @() }; VirtualizationSource = { param($Op) @() } }
$script:AtmCleanConsoleSource = { $true }
$prof = [pscustomobject]@{ Sid = $Sid; UserName = 'TEST\fixfe'; ProfilePath = $ProfileRoot; Loaded = $true; Special = $false; Origin = 'Test'; EnvStatus = 'OK'
    TempCandidates = @([pscustomobject]@{ TempPath = $Temp; Source = 'test' }); EnvValues = @{}; EnvKnown = $true; Notes = @() }
$ia = @{ ProfilesOverride = @($prof); ProcessesOverride = @([pscustomobject]@{ ProcessId = 1; Name = 'idle.exe'; ParentProcessId = 0; CommandLine = 'idle.exe'; CreationDate = (Get-Date).AddHours(-1) })
    IdentityOverride = [pscustomobject]@{ Sid = $Sid; Name = $Name; IsAdmin = ($IsAdmin -ceq 'True') }; NowUtc = (New-Object DateTime ([long]$NowTicks), ([DateTimeKind]::Utc)); NoProgress = $true; ConfigDir = (Join-Path $Src 'config') }
$calls = @{ Reader = 0; Deleter = 0 }
$err = 'NONE'
try {
    $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $Root; Fingerprint = $null }) -PlanPresenter { param($v, $r, $i) } -ConfirmationReader ({ param($x) $calls.Reader++; $x }.GetNewClosure()) -InventoryArgs $ia -DeleteTreeImpl ({ param($Part) $calls.Deleter++ }.GetNewClosure()) -PathPresenceImpl { param($P) $true }
    $res = '{0}|{1}|{2}' -f $c.Aborted, $c.StoppedBy, [bool]$c.LogCreated
} catch { $err = $_.Exception.GetBaseException().GetType().Name + ': ' + $_.Exception.GetBaseException().Message; $res = '||' }
# The lock is free again (with the gate closed it was never taken): a new acquisition of the same name succeeds.
$again = 'NOT_LOADED'
if ('AgentTempManager.AtmCleanLock' -as [type]) { $l = [AgentTempManager.AtmCleanLock]::TryAcquire($LockName); $again = [string]$l.Status; if ($l.Acquired) { $null = $l.Release() }; $l.Dispose() }
[IO.File]::WriteAllText($Out, ('{0}|{1}|{2}|{3}|{4}|{5}' -f $loadedBefore, $res, $calls.Reader, $calls.Deleter, $again, $err))
exit 0
'@, (New-Object Text.UTF8Encoding $true))
        $shell = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $tp = $f.Profile.TempCandidates[0].TempPath
        $got = @{}
        foreach ($gate in @('open', 'closed')) {
            $out = Join-Path $sandbox "fixfe-$gate.txt"
            $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$child`" -Src `"$srcDir`" -ProfileRoot `"$($f.Profile.ProfilePath)`" -Temp `"$tp`" -Sid `"$($testIdentity.Sid)`" -Name `"$($testIdentity.Name)`" -IsAdmin `"$($testIdentity.IsAdmin)`" -Root `"$($f.Roots[0])`" -NowTicks `"$($nowFuture.Ticks)`" -LockName `"$(New-TestLockName)`" -Gate $gate -Out `"$out`"") -TimeoutSec 300
            Assert-True ($r.Exit -eq 0 -and -not $r.TimedOut -and (Test-Path -LiteralPath $out)) "filho ($gate) terminou ($($r.Exit) $($r.Text))"
            $got[$gate] = @([IO.File]::ReadAllText($out) -split '\|')
        }
        # loadedBefore|Aborted|StoppedBy|LogCreated|reader|deleter|lock again|error
        $o = $got['open']
        Assert-True ($o[0] -ceq 'False') 'biblioteca nativa nao carregada antes do clean (condicao do defeito reproduzida)'
        Assert-True ($o[7] -ceq 'NONE') "trava aberta: nenhuma excecao (era 'tipo ausente'): $($o[7])"
        Assert-True ($o[1] -ceq 'LOG_REQUIRED' -and $o[2] -eq '' -and $o[3] -ceq 'False') "trava aberta: recusa LOG_REQUIRED, sem log ($($o[1]) $($o[2]) $($o[3]))"
        Assert-True ($o[4] -ceq '0' -and $o[5] -ceq '0') "trava aberta: nenhuma pergunta nem chamada ao deleter (leitor $($o[4]), deleter $($o[5]))"
        Assert-True ($o[6] -ceq 'ACQUIRED') "trava aberta: lock liberado ao final ($($o[6]))"
        $c2 = $got['closed']
        Assert-True ($c2[7] -ceq 'NONE' -and $c2[1] -ceq 'EXCLUSAO_REAL_DESABILITADA_V0_1' -and $c2[3] -ceq 'False' -and $c2[4] -ceq '0' -and $c2[5] -ceq '0') "trava fechada: so o plano, sem log, pergunta ou deleter ($($c2[1]) $($c2[7]))"
        Assert-True ($c2[6] -ceq 'ACQUIRED') "trava fechada: o lock nunca foi tomado ($($c2[6]))"
        Assert-True (Test-TestT1RootsIntact $f) 'raiz intacta'
    }
    Test-Case 'Clean lock (B8)' 'Trava fechada: nenhuma aquisicao (um nome invalido nao e nem consultado) e fluxo de plano inalterado' {
        $f = New-TestT1Fixture 'b8gate' 1
        $seen = @{ HeldInPlan = $null }
        $prev = $script:AtmCleanLockName
        $script:AtmCleanLockName = 'Local\nao-consultado'
        $script:AtmRealDeletionEnabled = $false
        try {
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter ({ param($v, $r, $i) $seen.HeldInPlan = [AgentTempManager.AtmCleanLock]::IsHeld }.GetNewClosure()) -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($f.Profile))
        } finally { $script:AtmRealDeletionEnabled = $true; $script:AtmCleanLockName = $prev }
        Assert-True ($c.Aborted -ceq 'EXCLUSAO_REAL_DESABILITADA_V0_1' -and @($c.Verified).Count -eq 1 -and $null -eq $c.LockReleaseError) "so o plano ($($c.Aborted))"
        Assert-True ($seen.HeldInPlan -eq $false) 'nenhum lock durante o plano'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Clean lock (B8)' 'Descritor do objeto criado: DACL protegida (SYSTEM, Administradores, Authenticated Users so SYNCHRONIZE e READ_CONTROL) e rotulo Medium, lidos pelo handle; liberacao dupla sem efeito' {
        Initialize-AtmTestMutex
        $n = New-TestLockName
        $l = [AgentTempManager.AtmCleanLock]::TryAcquire($n)
        try {
            Assert-True ($l.Acquired -and $l.Created -and $l.Status -ceq 'ACQUIRED') "criado e adquirido ($($l.Status))"
            $sddl = [AtmTestMutex]::GetSddl($n)
            Assert-True ($sddl -match '^D:P' -and $sddl.Contains('(A;;0x120000;;;AU)') -and $sddl -match '\(A;;0x1f0001;;;SY\)' -and $sddl -match '\(A;;0x1f0001;;;BA\)' -and $sddl -match 'S:[A-Z]*\(ML;;NW;;;ME\)$') "descritor: $sddl"
            Assert-Eq ([regex]::Matches($sddl, '\(A;').Count) 3 'exatamente tres entradas de permissao'
        } finally {
            Assert-Eq ($l.Release()) $null 'liberado'
            Assert-Eq ($l.Release()) $null 'segunda liberacao sem efeito'
            $l.Dispose()
        }
        Assert-True (-not [AgentTempManager.AtmCleanLock]::IsHeld) 'nada mantido'
    }
    Test-Case 'Clean lock (B8)' 'Estatico: nome fixo do produto em uma unica atribuicao; a suite nunca o usa; aquisicao so com a trava aberta e antes do nucleo; liberacao no finally; nucleo e nome so no motor; sem alterar seguranca de objeto nem encerrar processos' {
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-Eq $shippedCleanLockName 'Global\AgentTempManager.Clean' 'constante distribuida'
        Assert-Eq ([regex]::Matches($clean, '\$script:AtmCleanLockName\s*=').Count) 1 'uma unica atribuicao no motor'
        Assert-True ($script:AtmCleanLockName -cmatch '^Global\\AgentTempManager\.Test\.[0-9a-f]{32}$') 'a suite usa nome de teste proprio'
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Clean.ps1' -and $_.Name -ne 'Native.cs' })) {
            $txt = [IO.File]::ReadAllText($fi.FullName)
            foreach ($pat in @('AtmCleanLockName', 'Invoke-AtmCleanCore', 'AtmCleanLock]', 'RefusedBy')) { Assert-True (-not $txt.Contains($pat)) "$($fi.Name) usa $pat" }
        }
        $w = $clean.Substring($clean.IndexOf('function Invoke-AtmClean {'))
        $w = $w.Substring(0, $w.IndexOf('function Invoke-AtmCleanCore'))
        $iGate = $w.IndexOf('if (-not $script:AtmRealDeletionEnabled) { return (Invoke-AtmCleanCore @PSBoundParameters) }'); $iAcq = $w.IndexOf('[AgentTempManager.AtmCleanLock]::TryAcquire($script:AtmCleanLockName)')
        $iCore = $w.IndexOf('$res = Invoke-AtmCleanCore @PSBoundParameters'); $iFin = $w.IndexOf('} finally {'); $iRel = $w.IndexOf('$rc = $lock.Release()')
        Assert-True ($iGate -gt 0 -and $iAcq -gt $iGate -and $iCore -gt $iAcq -and $iFin -gt $iCore -and $iRel -gt $iFin) "ordem: trava $iGate, aquisicao $iAcq, nucleo $iCore, finally $iFin, liberacao $iRel"
        Assert-True (-not $w.Contains('Invoke-AtmInventory')) 'o wrapper nao inventaria antes do lock'
        # F-E: past the gate the verified native library is loaded by the product's own loader before the lock (it was
        # otherwise loaded only by the first inventory); with the gate closed this line is never reached.
        $iNat = $w.IndexOf('Initialize-AtmNative')
        Assert-True ($iNat -gt $iGate -and $iNat -lt $iAcq -and [regex]::Matches($w, 'Initialize-AtmNative').Count -eq 1 -and -not $w.Contains('Add-Type')) "carga nativa entre a trava ($iGate) e a aquisicao ($iAcq): $iNat, pelo carregador existente"
        $ncs = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Native.cs'))
        $cls = $ncs.Substring($ncs.IndexOf('public sealed class AtmCleanLock'))
        $cls = $cls.Substring(0, $cls.IndexOf('public static class AtmPathCheck'))
        foreach ($pat in @('SetSecurityInfo', 'SetKernelObjectSecurity', 'SetNamedSecurityInfo', 'TerminateProcess', 'OpenProcess', 'Local\\', 'Guid.NewGuid', 'Environment.UserName')) { Assert-True (-not $cls.Contains($pat)) "AtmCleanLock nao usa $pat" }
        Assert-True ($cls.Contains('WaitForSingleObject(l.handle, 0)') -and $cls.Contains('CreateMutexExW(ref sa, name, 0, SYNCHRONIZE | READ_CONTROL)')) 'sem espera; direitos minimos'
    }
    Test-Case 'Clean lock (B8)' 'Matriz entre usuarios, sessoes e niveis de elevacao (operator-only): NAO_TESTADO' {
        $script:caseSkipped = $true
        $script:caseNote = 'dois usuarios, sessoes console/RDP, processo elevado e nao elevado e pre-criacao por usuario comum dependem do operador; a suite cobre so processos da mesma identidade'
    }

    # ------------------------------------------------------------------ runtime evidence (B2-1)
    # Synthetic process rows (the same rows feed the V0.1 snapshot and the V0.2 collection), the suite's empty service and
    # virtualization sources unless a case sets its own, the stand-in deleter wherever clean runs.
    Test-Case 'Evidencia de execucao (B2-1)' 'Relacao direta: processo verificado com referencia direta -> BLOCKED com RUNTIME_USE_OBSERVED e proveniencia completa; motivos V0.1 primeiro e inalterados; classe inalterada; clean recusa sem chamar o deleter' {
        $p = New-TestProfile 'b2direct'
        $r = New-TestRoot -ProfileInfo $p
        $procs = New-Procs -Extra @((New-TestRuntimeProc 801 'node.exe' "node $r\x.js"))
        $inv = Inv -Profiles @($p) -Procs $procs
        $base = Test-AtmCandidate -Partition (Find-Part $inv $r) -Inventory $inv
        $row = Get-TestPreviewRow (Invoke-AtmPreview -Inventory $inv -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs)) $r
        $g = $row.Gate
        Assert-True ($g.Category -ceq 'BLOCKED' -and $row.Partition.Class -ceq 'ACTIVE_EVIDENCE') "categoria e classe ($($g.Category) $($row.Partition.Class))"
        Assert-Eq ((@($g.Reasons)[0..(@($base.Reasons).Count - 1)]) -join '|') (@($base.Reasons) -join '|') 'motivos anteriores primeiro e inalterados'
        $u = @($g.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_USE_OBSERVED' })
        Assert-Eq $u.Count 1 "um motivo de uso observado ($(Get-TestRuntimeCodes $g))"
        $x = $u[0]
        Assert-True ($x.Decision -ceq 'BLOCKED' -and $x.Nature -ceq 'DIRECT' -and $x.Relation -ceq 'REFERENCES_PATH' -and $x.Collector -ceq 'inventory' -and $x.Evidence -ceq 'PATH_REFERENCE_DIRECT' -and $x.Coverage -ceq 'COMPLETE' -and $null -ne $x.ObservedUtc -and [string]$x.Detail -match '801@') "proveniencia: $($x.Decision) $($x.Nature) $($x.Relation) $($x.Collector) $($x.Evidence) $($x.Coverage) $($x.Detail)"
        Assert-True (@($g.Reasons | Where-Object { $_ -like 'RUNTIME_USE_OBSERVED:*' }).Count -eq 1) 'motivo visivel no texto do preview'
        $d = New-TestCleanDeleter
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($c.Aborted -ceq 'NENHUM_CAMINHO_ELEGIVEL' -and $d.Calls.Count -eq 0 -and ((@($c.Rejected)[0].Reasons -join ' ') -match 'RUNTIME_USE_OBSERVED')) "clean: recusado com o motivo, deleter nunca chamado ($($c.Aborted))"
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Sessao da propria raiz: viva com identidade exata -> RUNTIME_SESSION_LIVE BLOCKED; sem hora registrada -> RUNTIME_SESSION_UNVERIFIED INVESTIGATE; PID reutilizado -> nenhum motivo e nenhuma promocao' {
        $t = ConvertTo-TestMicroUtc ((Get-Date).AddMinutes(-20))
        $cases = @(
            @{ Tag = 'viva'; Start = $t; Want = 'RUNTIME_SESSION_LIVE'; Cat = 'BLOCKED' },
            @{ Tag = 'sem hora'; Start = $null; Want = 'RUNTIME_SESSION_UNVERIFIED'; Cat = 'INVESTIGATE' },
            @{ Tag = 'pid reutilizado'; Start = $t.AddHours(-1); Want = ''; Cat = $null })
        foreach ($k in $cases) {
            $p = New-TestProfile ('b2sess' + [guid]::NewGuid().ToString('N').Substring(0, 6))
            $r = New-TestRoot -ProfileInfo $p
            $procs = New-Procs -Extra @((New-TestRuntimeProc 802 'claude.exe' 'claude' $t))
            Write-TestSessionFile -ProfileInfo $p -SessionId (Split-Path $r -Leaf) -ProcId 802 -ProcStartUtc $k.Start
            $inv = Inv -Profiles @($p) -Procs $procs
            $base = Test-AtmCandidate -Partition (Find-Part $inv $r) -Inventory $inv
            $g = (Get-TestPreviewRow (Invoke-AtmPreview -Inventory $inv -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs)) $r).Gate
            $codes = Get-TestRuntimeCodes $g
            Assert-Eq $codes $k.Want "$($k.Tag): motivos de execucao"
            $want = $(if ($k.Cat) { $k.Cat } else { $base.Category })
            Assert-Eq $g.Category $want "$($k.Tag): categoria (antes $($base.Category))"
            if ($k.Want) {
                $x = @($g.RuntimeReasons)[0]
                Assert-True ($x.Collector -ceq 'sessions-claude-code' -and $x.Nature -ceq $(if ($k.Cat -ceq 'BLOCKED') { 'DIRECT' } else { 'AMBIGUOUS' }) -and $null -ne $x.ObservedUtc -and $x.Coverage -like '*sessions-claude-code:*') "$($k.Tag): proveniencia ($($x.Collector) $($x.Nature) $($x.Coverage))"
            } else { Assert-Eq (@($g.Reasons) -join '|') (@($base.Reasons) -join '|') "$($k.Tag): motivos iguais aos anteriores" }
        }
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Ligacao ambigua ou derivada: referencia de processo sem identidade verificavel -> RUNTIME_ASSOCIATION_AMBIGUOUS; referencia a pasta acima da raiz -> RUNTIME_ANCESTOR_REFERENCE; ambas INVESTIGATE, nunca uso' {
        $p = New-TestProfile 'b2amb'
        $r1 = New-TestRoot -ProfileInfo $p -Slug 'C--amb-one'; $r2 = New-TestRoot -ProfileInfo $p -Slug 'C--amb-two'
        $procs = New-Procs -Extra @((New-TestRuntimeProc 803 'node.exe' "node $r1\y.js" $null), (New-TestRuntimeProc 804 'node.exe' "node $([IO.Path]::GetDirectoryName($r2))"))
        $inv = Inv -Profiles @($p) -Procs $procs
        $rows = Invoke-AtmPreview -Inventory $inv -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs)
        $g1 = (Get-TestPreviewRow $rows $r1).Gate; $g2 = (Get-TestPreviewRow $rows $r2).Gate
        $a = @($g1.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_ASSOCIATION_AMBIGUOUS' })
        Assert-True ($a.Count -eq 1 -and $a[0].Decision -ceq 'INVESTIGATE' -and $a[0].Nature -ceq 'AMBIGUOUS' -and @($g1.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_USE_OBSERVED' }).Count -eq 0) "identidade nao verificada: ambigua, nunca uso ($(Get-TestRuntimeCodes $g1))"
        $n = @($g2.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_ANCESTOR_REFERENCE' })
        Assert-True ($n.Count -eq 1 -and $n[0].Decision -ceq 'INVESTIGATE' -and $n[0].Nature -ceq 'DERIVED' -and $g2.Category -ceq 'INVESTIGATE') "ancestral: derivada, investigar ($(Get-TestRuntimeCodes $g2) $($g2.Category))"
        Assert-True ($g1.Category -ne 'ELIGIBLE') 'nenhuma das duas elegivel'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Servico e VM: processo de servico ou de VM com referencia direta a raiz -> uso observado com a proveniencia SERVICE ou VIRTUAL_MACHINE; servico ou VM sem relacao -> nenhum motivo por raiz (a raiz elegivel continua ELEGIVEL)' {
        $p = New-TestProfile 'b2svc'
        $rs = New-TestRoot -ProfileInfo $p -Slug 'C--svc-a'; $rv = New-TestRoot -ProfileInfo $p -Slug 'C--svc-b'; $rf = New-TestRoot -ProfileInfo $p -Slug 'C--svc-c'
        $procs = New-Procs -Extra @((New-TestRuntimeProc 805 'svc.exe' "svc.exe $rs\s.db"), (New-TestRuntimeProc 806 'vmwp.exe' "vmwp.exe $rv\v.vhdx"), (New-TestRuntimeProc 807 'other.exe' 'other.exe --idle'))
        $fakeSvc = [pscustomobject]@{ Id = 'fake-svc'; DisplayName = 'F'; ContractVersion = 2; Capabilities = @('runtime'); GetServiceHints = { @([pscustomobject]@{ Name = 'B2LinkedSvc' }, [pscustomobject]@{ Name = 'B2FreeSvc' }) } }
        $svcRows = @(
            [pscustomobject]@{ Name = 'B2LinkedSvc'; State = 'Running'; StartMode = 'Auto'; DelayedAutoStart = $false; StartName = 'LocalSystem'; ProcessId = 805; PathName = 'C:\Windows\System32\svc.exe' },
            [pscustomobject]@{ Name = 'B2FreeSvc'; State = 'Running'; StartMode = 'Auto'; DelayedAutoStart = $false; StartName = 'LocalSystem'; ProcessId = 807; PathName = 'C:\Windows\System32\other.exe' })
        $vm = [pscustomobject]@{ Name = '11111111-2222-3333-4444-555555555555'; Caption = 'Virtual Machine'; Description = 'Microsoft Virtual Computer System'; ElementName = 'b2-vm'; EnabledState = 2; ProcessID = 806 }
        $hostRow = [pscustomobject]@{ Name = 'B2-HOST'; Caption = 'Hosting Computer System'; Description = 'Microsoft Hosting Computer System'; ElementName = 'B2-HOST'; EnabledState = 2; ProcessID = $null }
        $vt = @{ Hypervisor = @([pscustomobject]@{ HypervisorPresent = $true }); NamespaceRoot = @([pscustomobject]@{ Name = 'virtualization' }); NamespaceV2 = @([pscustomobject]@{ Name = 'v2' }); Vmms = @([pscustomobject]@{ Name = 'vmms'; State = 'Running' }); Vms = @($hostRow, $vm) }
        $prev = $script:AtmRuntimeEvidenceSources
        $script:AtmRuntimeEvidenceSources = @{ Providers = @((Get-AtmProviders | Where-Object { $_.Id -ceq 'claude-code' }), $fakeSvc); ServiceSource = ({ param($Names) $svcRows }.GetNewClosure()); VirtualizationSource = ({ param($Op) @($vt[$Op]) }.GetNewClosure()) }
        try {
            $inv = Inv -Profiles @($p) -Procs $procs
            $rows = Invoke-AtmPreview -Inventory $inv -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs)
        } finally { $script:AtmRuntimeEvidenceSources = $prev }
        $us = @((Get-TestPreviewRow $rows $rs).Gate.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_USE_OBSERVED' })
        Assert-True ($us.Count -eq 1 -and [string]$us[0].Detail -match '805@\d+ \(SERVICE\)') "servico com referencia: uso observado com proveniencia ($(if ($us.Count) { $us[0].Detail }))"
        $uv = @((Get-TestPreviewRow $rows $rv).Gate.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_USE_OBSERVED' })
        Assert-True ($uv.Count -eq 1 -and [string]$uv[0].Detail -match '806@\d+ \(VIRTUAL_MACHINE\)') "VM com referencia: uso observado com proveniencia ($(if ($uv.Count) { $uv[0].Detail }))"
        $gf = (Get-TestPreviewRow $rows $rf).Gate
        $bf = Test-AtmCandidate -Partition (Find-Part $inv $rf) -Inventory $inv
        Assert-True (@($gf.RuntimeReasons).Count -eq 0 -and $gf.Category -ceq $bf.Category -and $bf.Category -ceq 'ELIGIBLE') "servico em execucao e VM sem relacao: nenhum motivo por raiz ($(Get-TestRuntimeCodes $gf); $($gf.Category))"
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Evidencia positiva com cobertura parcial: processo ilegivel (B1 intacto) e referencia direta de outro -> uso observado mantido; raiz sem referencia segue bloqueada pela cobertura de processos, sem motivo de execucao inventado' {
        $p = New-TestProfile 'b2partial'
        $r1 = New-TestRoot -ProfileInfo $p -Slug 'C--part-a'; $r2 = New-TestRoot -ProfileInfo $p -Slug 'C--part-b'
        $procs = New-Procs -Extra @((New-TestRuntimeProc 808 'secret.exe' $null), (New-TestRuntimeProc 809 'node.exe' "node $r1\z.js"))
        # An elevated identity: outside the B1 restricted exception, so B1 stays exactly as it was whatever runs the suite.
        $adm = [pscustomobject]@{ Sid = $testOwnerSid; Name = $me.Name; IsAdmin = $true }
        $inv = Inv -Profiles @($p) -Procs $procs -Identity $adm
        $rows = Invoke-AtmPreview -Inventory $inv -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs -Identity $adm)
        $g1 = (Get-TestPreviewRow $rows $r1).Gate; $g2 = (Get-TestPreviewRow $rows $r2).Gate
        Assert-True ($g1.Category -ceq 'BLOCKED' -and @($g1.RuntimeReasons | Where-Object { $_.Code -ceq 'RUNTIME_USE_OBSERVED' }).Count -eq 1) "uso observado com cobertura parcial ($(Get-TestRuntimeCodes $g1))"
        Assert-True ($g2.Category -ceq 'BLOCKED' -and ((@($g2.Reasons) -join ' ') -match 'COBERTURA_DE_PROCESSOS_INCOMPLETA') -and @($g2.RuntimeReasons).Count -eq 0) "B1 mantido; nenhum motivo de execucao inventado ($(Get-TestRuntimeCodes $g2))"
        $nt = @(@((Get-TestPreviewRow $rows $r2).Runtime.Notices) | Where-Object { $_.Kind -ceq 'NOT_ATTRIBUTABLE' -and $_.Collector -ceq 'processes' })
        Assert-Eq $nt.Count 1 'lacuna de processos como aviso da execucao, nao de uma raiz'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Ausencia de evidencia nunca promove: raiz sem evidencia (so lacunas estruturais) mantem exatamente categoria e motivos; nenhuma raiz antes BLOCKED ou INVESTIGATE vira ELEGIVEL; avisos estruturais uma vez' {
        $p = New-TestProfile 'b2none'
        $re = New-TestRoot -ProfileInfo $p -Slug 'C--none-a'; $rr = New-TestRoot -ProfileInfo $p -Slug 'C--none-b'; $ra = New-TestRoot -ProfileInfo $p -Slug 'C--none-c'
        [IO.File]::SetLastWriteTimeUtc((Join-Path $rr 'a.txt'), $nowFuture.AddHours(-3))
        $procs = New-Procs -Extra @((New-TestRuntimeProc 810 'node.exe' "node $([IO.Path]::GetDirectoryName($ra))"))
        $inv = Inv -Profiles @($p) -Procs $procs
        $rows = Invoke-AtmPreview -Inventory $inv -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs $procs)
        $rank = @{ 'ELIGIBLE' = 0; 'INVESTIGATE' = 1; 'BLOCKED' = 2 }
        foreach ($row in $rows) {
            $b = Test-AtmCandidate -Partition $row.Partition -Inventory $inv
            Assert-True ($rank[$row.Gate.Category] -ge $rank[$b.Category]) "nunca promove: $($row.Partition.Name) $($b.Category) -> $($row.Gate.Category)"
        }
        $ge = (Get-TestPreviewRow $rows $re).Gate; $be = Test-AtmCandidate -Partition (Find-Part $inv $re) -Inventory $inv
        Assert-True ($be.Category -ceq 'ELIGIBLE' -and $ge.Category -ceq 'ELIGIBLE' -and (@($ge.Reasons) -join '|') -ceq (@($be.Reasons) -join '|') -and @($ge.RuntimeReasons).Count -eq 0) "sem evidencia: categoria e motivos exatamente iguais ($($ge.Category))"
        $st = @(@((Get-TestPreviewRow $rows $re).Runtime.Notices) | Where-Object { $_.Kind -ceq 'STRUCTURAL' } | ForEach-Object { $_.Collector } | Sort-Object)
        Assert-Eq ($st -join ',') 'handles,process-cwd,worktree-discovery' 'lacunas estruturais como aviso da execucao'
        $txt = (@(Show-AtmPreview -Inventory $inv -Rows $rows 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'runtime.noEvidenceIsNotUnused')) -and ([regex]::Matches($txt, [regex]::Escape((Get-AtmText 'runtime.notice.STRUCTURAL' 'x').Split(':')[0])).Count -eq 1)) 'preview: aviso uma vez e frase de que ausencia nao e desuso'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Falha, TIMEOUT e NOT_OBSERVABLE: execucao que lanca -> RUNTIME_NOT_COLLECTED em toda raiz; prazo 0 -> RUNTIME_TIMEOUT (nunca uso); NOT_OBSERVABLE estrutural -> so aviso' {
        $p = New-TestProfile 'b2fail'
        $r = New-TestRoot -ProfileInfo $p
        $ia = Get-InvArgs -Profiles @($p)
        $inv = Inv -Profiles @($p)
        $rowsF = & {
            Set-Item -LiteralPath 'function:local:Invoke-AtmDiagnoseRun' -Value { throw (New-Object InvalidOperationException 'synthetic') }
            Invoke-AtmPreview -Inventory $inv -InventoryArgs $ia
        }
        $gF = (Get-TestPreviewRow $rowsF $r).Gate
        Assert-True ($gF.Category -ceq 'INVESTIGATE' -and (Get-TestRuntimeCodes $gF) -ceq 'RUNTIME_NOT_COLLECTED' -and @($gF.RuntimeReasons)[0].Evidence -ceq 'EXCEPTION_INVALIDOPERATIONEXCEPTION') "falha: investigar ($(Get-TestRuntimeCodes $gF) $($gF.Category))"
        $prev = $script:AtmRuntimeEvidenceSources
        $script:AtmRuntimeEvidenceSources = @{} + $prev; $script:AtmRuntimeEvidenceSources['DeadlineSeconds'] = 0
        try { $rowsT = Invoke-AtmPreview -Inventory $inv -InventoryArgs $ia } finally { $script:AtmRuntimeEvidenceSources = $prev }
        $gT = (Get-TestPreviewRow $rowsT $r).Gate
        $codesT = Get-TestRuntimeCodes $gT
        Assert-True ($gT.Category -ceq 'INVESTIGATE' -and $codesT.Contains('RUNTIME_TIMEOUT') -and -not $codesT.Contains('RUNTIME_USE_OBSERVED') -and -not $codesT.Contains('RUNTIME_SESSION_LIVE')) "prazo: investigar por tempo, nunca uso ($codesT)"
        $rowsN = Invoke-AtmPreview -Inventory $inv -InventoryArgs $ia
        $gN = (Get-TestPreviewRow $rowsN $r).Gate
        Assert-True ($gN.Category -ceq 'ELIGIBLE' -and @($gN.RuntimeReasons).Count -eq 0 -and @(@((Get-TestPreviewRow $rowsN $r).Runtime.Notices) | Where-Object { $_.Collector -ceq 'handles' -and $_.Status -ceq 'NOT_OBSERVABLE' -and $_.Kind -ceq 'STRUCTURAL' }).Count -eq 1) "NOT_OBSERVABLE estrutural: aviso, nenhuma recusa ($($gN.Category))"
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Evidencia que surge entre o plano e a revalidacao: sessao viva registrada antes da exclusao -> raiz preservada na revalidacao com RUNTIME_SESSION_LIVE, deleter simulado nunca chamado' {
        # The hook runs inside the engine and reaches these variables and the suite's functions by dynamic scope (the
        # b2* names avoid the engine's own variable names).
        $b2p = New-TestProfile 'b2late'
        $r = New-TestRoot -ProfileInfo $b2p
        $b2t = ConvertTo-TestMicroUtc ((Get-Date).AddMinutes(-15))
        $procs = New-Procs -Extra @((New-TestRuntimeProc 811 'claude.exe' 'claude' $b2t))
        $hook = { param($part) Write-TestSessionFile -ProfileInfo $b2p -SessionId (Split-Path $part.Path -Leaf) -ProcId 811 -ProcStartUtc $b2t -File 'b2late.json' }
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs (Get-InvArgs -Profiles @($b2p) -Procs $procs) -BeforeDeleteHook $hook -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True (@($c.Verified).Count -eq 1) 'no plano a raiz era elegivel (sem sessao registrada)'
        Assert-True ($d.Calls.Count -eq 0 -and @($c.Deleted).Count -eq 0 -and @($c.Skipped).Count -eq 1 -and ((@($c.Skipped)[0].Reasons -join ' ') -match 'RUNTIME_SESSION_LIVE')) "revalidacao: preservada com a evidencia nova ($((@($c.Skipped)[0].Reasons) -join ' ; '))"
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Custo: preview com quatro raizes faz uma unica coleta (uma colecao de processos); clean faz uma no plano e uma por raiz na revalidacao' {
        $p = New-TestProfile 'b2cost'
        $roots = @(1..4 | ForEach-Object { New-TestRoot -ProfileInfo $p -Slug ('C--cost-' + $_) })
        $ia = Get-InvArgs -Profiles @($p)
        $inv = Inv -Profiles @($p)
        $cnt = @{ Runs = 0; Collections = 0 }
        $origRuns = ${function:Get-AtmRuntimeRefusals}; $origColl = ${function:Get-AtmProcessCollection}
        $res = & {
            Set-Item -LiteralPath 'function:local:Get-AtmRuntimeRefusals' -Value { param($Inventory, [hashtable]$InventoryArgs = @{}, [int]$DeadlineSeconds = 60, [scriptblock]$ServiceSource = $null, [scriptblock]$VirtualizationSource = $null, [scriptblock]$ProcessSource = $null, $Providers = $null) $cnt.Runs++; & $origRuns @PSBoundParameters }
            Set-Item -LiteralPath 'function:local:Get-AtmProcessCollection' -Value { param([scriptblock]$Source, [int]$MaxRecords = 65536, [int]$TimeoutSec = 30, $Deadline = $null) $cnt.Collections++; & $origColl @PSBoundParameters }
            $rows = Invoke-AtmPreview -Inventory $inv -InventoryArgs $ia
            $afterPreview = @{ Runs = $cnt.Runs; Collections = $cnt.Collections; Rows = @($rows).Count }
            $d = New-TestCleanDeleter
            $c = Invoke-AtmClean -Entries @($roots[0], $roots[1] | ForEach-Object { [pscustomobject]@{ Source = 't'; Path = $_; Fingerprint = $null } }) -PlanPresenter $presenter -ConfirmationReader ${function:Confirm-Correct} -InventoryArgs $ia -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            [pscustomobject]@{ Preview = $afterPreview; Clean = @{ Runs = $cnt.Runs - $afterPreview.Runs; Collections = $cnt.Collections - $afterPreview.Collections; Calls = $d.Calls.Count; Aborted = $c.Aborted; Stopped = $c.StoppedBy } }
        }
        Assert-True ($res.Preview.Runs -eq 1 -and $res.Preview.Collections -eq 1 -and $res.Preview.Rows -ge 4) "preview: uma coleta para $($res.Preview.Rows) linhas ($($res.Preview.Runs) execucoes, $($res.Preview.Collections) colecoes)"
        Assert-True ($res.Clean.Runs -eq 4 -and $res.Clean.Collections -eq 4 -and $res.Clean.Calls -eq 2) "clean: plano + conferencia do plano antes da execucao (AUT-2) + uma por raiz ($($res.Clean.Runs) execucoes, $($res.Clean.Collections) colecoes, $($res.Clean.Calls) chamadas; $($res.Clean.Aborted) $($res.Clean.Stopped))"
        foreach ($rt in $roots) { Assert-True ([IO.File]::Exists((Join-Path $rt 'sub\b.bin'))) 'nada apagado' }
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Estatico: o motor de limpeza consome so recusas (sem o grafo); preview, plano e revalidacao passam a evidencia; costura de teste so no motor e nula na distribuicao; travas fechadas' {
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-Eq $shippedRuntimeSources $null 'costura distribuida nula'
        Assert-Eq ([regex]::Matches($clean, '\$script:AtmRuntimeEvidenceSources\s*=').Count) 1 'uma unica atribuicao no motor'
        Assert-Eq ([regex]::Matches($clean, '-RuntimeEvidence \$(rt|rtRe)\b').Count) 4 'preview, plano, revalidacao e apresentacao da autorizacao (AUT-1) passam a evidencia'
        Assert-Eq ([regex]::Matches($clean, 'Get-AtmCleanRuntimeEvidence -Inventory').Count) 5 'uma coleta no preview, uma no plano, uma na conferencia do plano antes da execucao (AUT-2), uma por raiz na revalidacao, uma por apresentacao da autorizacao (AUT-1)'
        Assert-True (-not $clean.Contains('Invoke-AtmDiagnose') -and -not $clean.Contains('Get-AtmDependencyGraph')) 'o motor de limpeza nao chama o diagnostico nem o grafo diretamente'
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Clean.ps1' })) {
            Assert-True (-not ([IO.File]::ReadAllText($fi.FullName)).Contains('AtmRuntimeEvidenceSources')) "$($fi.Name) usa a costura de teste"
        }
        $diag = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Diagnose.ps1'))
        $fn = $diag.Substring($diag.IndexOf('function Get-AtmRuntimeRefusals'), $diag.IndexOf('function Invoke-AtmDiagnose {') - $diag.IndexOf('function Get-AtmRuntimeRefusals'))
        foreach ($pat in @('Get-CimInstance', 'Invoke-AtmInventory', 'Invoke-AtmGitCommand', '[IO.File]', 'Get-ChildItem', 'Registry', 'Start-Process')) { Assert-True (-not $fn.Contains($pat)) "recusas sem '$pat'" }
        Assert-True ($fn.Contains('-Inventory $Inventory') -and $fn.Contains('-CpuSampleMs 0')) 'reusa o inventario recebido; sem amostra de CPU'
        Assert-Eq $script:AtmRuntimeDefaultDeadlineSeconds 60 'prazo padrao documentado'
        foreach ($l in @('en-US', 'pt-BR')) {
            foreach ($x in $script:AtmRuntimeRefusalCodes) { Assert-True $script:AtmMessages[$l].ContainsKey("runtime.code.$x") "runtime.code.$x ($l)" }
            foreach ($x in $script:AtmRuntimeNatures) { Assert-True $script:AtmMessages[$l].ContainsKey("runtime.nature.$x") "runtime.nature.$x ($l)" }
            foreach ($x in $script:AtmRuntimeNoticeKinds) { Assert-True $script:AtmMessages[$l].ContainsKey("runtime.notice.$x") "runtime.notice.$x ($l)" }
        }
        Assert-True ($shippedDeletionGate -eq $false -and $script:AtmWorktreeDiagnosticsEnabled -eq $false -and $script:AtmHandleDiagnosticsEnabled -eq $false -and $script:AtmDiagnoseExportEnabled -eq $false) 'travas distribuidas fechadas'
    }
    Test-Case 'Evidencia de execucao (B2-1)' 'Texto do motivo independente da cultura: horario em formato invariante mesmo com outro separador de hora na cultura atual' {
        $ref = New-AtmRuntimeRefusal -Code 'RUNTIME_TIMEOUT' -Decision 'INVESTIGATE' -Collector 'process-snapshot' -Evidence 'DEADLINE_EXCEEDED' -Relation 'COVERAGE' -Nature 'COVERAGE' -ObservedUtc (New-Object DateTime 2026, 10, 30, 1, 2, 3, ([DateTimeKind]::Utc)) -Coverage 'TIMEOUT'
        $ci = [Globalization.CultureInfo]::InvariantCulture.Clone(); $ci.DateTimeFormat.TimeSeparator = '.'; $ci.DateTimeFormat.DateSeparator = '/'
        $prevCi = [Threading.Thread]::CurrentThread.CurrentCulture
        try { [Threading.Thread]::CurrentThread.CurrentCulture = $ci; $txt = Format-AtmRuntimeRefusal $ref } finally { [Threading.Thread]::CurrentThread.CurrentCulture = $prevCi }
        Assert-True ($txt.Contains('2026-10-30 01:02:03Z')) "horario invariante ($txt)"
    }

    # ------------------------------------------------------------------ discard authorization (AUT-1)
    # Simulated operator (tests only), record files under the sandbox, nothing deleted: no clean runs in these cases.
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Declaracoes completas com bloqueio tecnico preservado (RECENT e B1): registro aceito com apresentado, declarado, bloqueio e limites; sem conteudo de conversa; categoria tecnica inalterada' {
        $dir = New-TestCleanLogDir 'auth-ok'
        if (-not $dir) { return }
        foreach ($k in @('recent', 'b1')) {
            $p = New-TestProfile ('authok' + $k)
            $r = New-TestRoot -ProfileInfo $p
            $null = New-TestTranscript -ProfileInfo $p -Root $r
            $procs = New-Procs
            if ($k -ceq 'recent') { [IO.File]::SetLastWriteTimeUtc((Join-Path $r 'a.txt'), $nowFuture.AddHours(-3)) }
            else { $procs = New-Procs -Extra @((New-TestRuntimeProc 820 'secret.exe' $null)) }
            $ia = Get-InvArgs -Profiles @($p) -Procs $procs
            $before = Test-AtmCandidate -Partition (Find-Part (Inv -Profiles @($p) -Procs $procs) $r) -Inventory (Inv -Profiles @($p) -Procs $procs)
            $op = New-TestAuthOperator -Description ("Relatorio entregue`tno repositorio" + ('x' * 400))
            $file = Join-Path $dir ("auth-$k.jsonl")
            $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
            Assert-True ($res.Accepted -and $null -eq $res.Refused -and $res.RecordCreated -and $op.Presented -eq 1) "$($k): aceito ($($res.Refused) $($res.Detail))"
            Assert-Eq ($op.Prompts -join ',') 'task,results,discard,description' "$($k): tres confirmacoes separadas e a descricao opcional"
            $raw = [IO.File]::ReadAllText($file)
            $rec = $raw | ConvertFrom-Json
            Assert-True ($rec.schema -ceq 'atm.discard-authorization/2' -and $rec.planId -ceq $res.PlanId -and $rec.authorizationId -ceq $res.AuthorizationId -and $rec.root.path -ceq $r -and $rec.root.sessionId -ceq (Split-Path $r -Leaf) -and $rec.root.profileSid -ceq $p.Sid) "$($k): identificadores e raiz"
            Assert-True ($rec.association.kind -ceq 'NAME_CONVENTION_CORROBORATED' -and $rec.declarations.declaredBy -ceq 'OPERATOR' -and $rec.declarations.status -ceq 'ALL_PHRASES_TYPED' -and $rec.declarations.taskCompleted -and $rec.declarations.contentDecision -ceq 'RESULTS_PRESERVED' -and $rec.declarations.discardAuthorized -and $rec.revalidation.planRevalidated) "$($k): associacao por convencao, declaracoes do operador, revalidacao"
            Assert-True ($rec.preservation.basis -ceq 'OPERATOR_DECLARED' -and $rec.preservation.verifiedByTool -eq $false -and $null -eq $rec.preservation.evidence -and $res.RecordState -ceq 'COMPLETE' -and $res.ContentDecision -ceq 'RESULTS_PRESERVED') "$($k): preservacao declarada, nao verificada pelo produto; gravacao concluida"
            Assert-True (-not $rec.PSObject.Properties['confirmation'] -and -not $rec.PSObject.Properties['operator'] -and -not $raw.Contains('ACCEPTED')) "$($k): nenhum campo ACCEPTED nem 'operator' (schema /1)"
            Assert-True ($rec.presented.files -eq 2 -and $rec.presented.bytes -eq 2148 -and $rec.presented.fingerprint -ceq (Find-Part (Inv -Profiles @($p) -Procs $procs) $r).Fingerprint -and $null -ne $rec.presented.ageHours) "$($k): o que foi apresentado"
            Assert-True ($rec.technical.category -ceq 'BLOCKED' -and $(if ($k -ceq 'recent') { $rec.technical.recentBlock -and $rec.technical.processCoverage.gate -ceq 'NOT_EVALUATED' } else { $rec.technical.processCoverage.gate -ceq 'BLOCKED' -and $rec.technical.processCoverage.observed -ceq 'INCOMPLETE' })) "$($k): bloqueio tecnico registrado ($($rec.technical.category), B1 $($rec.technical.processCoverage.gate))"
            Assert-True (-not $rec.technical.PSObject.Properties['processCoverageBlock']) "$($k): sem o booleano ambiguo"
            Assert-True (@($rec.limitations) -contains 'NOT_A_DELETION_CREDENTIAL' -and @($rec.limitations) -contains 'STATISTICS_NOT_CONTENT' -and @($rec.limitations) -contains 'RECORD_ALTERABLE_BY_SAME_IDENTITY') "$($k): limites registrados"
            Assert-True ($rec.declarations.taskDescription.Length -eq 200 -and -not $rec.declarations.taskDescription.Contains("`t") -and -not $raw.Contains('ATM-AUT1-TRANSCRIPT-CONTENT')) "$($k): descricao como dado limitado; nenhum conteudo de transcricao"
            $after = Test-AtmCandidate -Partition (Find-Part (Inv -Profiles @($p) -Procs $procs) $r) -Inventory (Inv -Profiles @($p) -Procs $procs)
            Assert-True ($after.Category -ceq $before.Category -and $after.Category -ceq 'BLOCKED') "$($k): autorizada e ainda tecnicamente bloqueada ($($after.Category))"
            $txt = (@(Show-AtmDiscardResult -Result $res 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
            Assert-True ($txt.Contains((Get-AtmText 'auth.acceptedTechnical' 'BLOCKED')) -and -not $txt.Contains('ELIGIBLE')) "$($k): console mostra o bloqueio, nunca elegivel"
            Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) "$($k): nada apagado"
        }
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Declaracao rejeitada ou cancelada em cada passo: nada registrado, nenhum arquivo criado' {
        $dir = New-TestCleanLogDir 'auth-no'
        if (-not $dir) { return }
        $p = New-TestProfile 'authno'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $n = 0
        foreach ($step in @('task', 'results', 'discard')) {
            # TOOL_VERIFIED typed as an answer is only another text: the product never takes it as a verification.
            foreach ($ans in @('nao', $null, '', 'TOOL_VERIFIED')) {
                $n++
                $file = Join-Path $dir ("no-$n.jsonl")
                $op = New-TestAuthOperator -Answers @{ $step = $ans }
                $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs (Get-InvArgs -Profiles @($p)) -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
                $want = $(if ($ans) { 'AUTH_DECLINED' } else { 'AUTH_CANCELLED' })
                Assert-True (-not $res.Accepted -and $res.Refused -ceq $want -and $res.Step -ceq $step -and -not $res.RecordCreated -and $res.RecordState -ceq 'NOT_CREATED' -and -not (Test-Path -LiteralPath $file)) "$step / [$ans]: $($res.Refused) $($res.Step)"
            }
        }
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Caminho, identidade e associacao: caixa divergente, nao-raiz, outra conta, sintaxe invalida, sem transcricao (desconhecida) e mesmo id em dois escopos (ambigua) recusados sem pergunta' {
        $dir = New-TestCleanLogDir 'auth-id'
        if (-not $dir) { return }
        $p = New-TestProfile 'authid'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $po = New-TestProfile 'authother' -Sid 'S-1-5-21-9-9-9-1000'
        $ro = New-TestRoot -ProfileInfo $po; $null = New-TestTranscript -ProfileInfo $po -Root $ro
        $pn = New-TestProfile 'authnotr'
        $rn = New-TestRoot -ProfileInfo $pn
        $u = [guid]::NewGuid().ToString()
        $pa = New-TestProfile 'authamb'
        $ra1 = New-TestRoot -ProfileInfo $pa -Slug 'C--amb-x' -Uuid $u; $null = New-TestRoot -ProfileInfo $pa -Slug 'C--amb-y' -Uuid $u
        $null = New-TestTranscript -ProfileInfo $pa -Root $ra1
        $cases = @(
            @{ Tag = 'caixa'; Path = $r.ToUpperInvariant(); Profiles = @($p); Want = 'AUTH_PATH_CASE_MISMATCH'; Presented = 0 },
            @{ Tag = 'nao-raiz'; Path = (Get-Base $p); Profiles = @($p); Want = 'AUTH_NOT_A_ROOT'; Presented = 0 },
            @{ Tag = 'outra conta'; Path = $ro; Profiles = @($po); Want = 'AUTH_OTHER_USER'; Presented = 0 },
            @{ Tag = 'sintaxe'; Path = ($r + '\..\x'); Profiles = @($p); Want = 'AUTH_PATH_INVALID'; Presented = 0 },
            @{ Tag = 'sem transcricao'; Path = $rn; Profiles = @($pn); Want = 'AUTH_ASSOCIATION_UNKNOWN'; Presented = 1 },
            @{ Tag = 'ambigua'; Path = $ra1; Profiles = @($pa); Want = 'AUTH_ASSOCIATION_AMBIGUOUS'; Presented = 1 })
        $i = 0
        # F05-OWNER-ATTRIBUTION: the other account's base is attributed to it only as its owner (dubbed, no ACL change).
        Set-TestBaseOwner @{ (Get-Base $po) = $po.Sid }
        try { foreach ($k in $cases) {
            $i++
            $file = Join-Path $dir ("id-$i.jsonl")
            $op = New-TestAuthOperator
            $res = Invoke-AtmDiscardAuthorization -Path $k.Path -InventoryArgs (Get-InvArgs -Profiles $k.Profiles) -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
            Assert-True (-not $res.Accepted -and $res.Refused -ceq $k.Want -and $op.Prompts.Count -eq 0 -and $op.Presented -eq $k.Presented -and -not (Test-Path -LiteralPath $file)) "$($k.Tag): $($res.Refused) (apresentado $($op.Presented), perguntas $($op.Prompts.Count))"
        } } finally { $script:AtmBaseOwnerSource = $null }
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Alteracao entre a apresentacao e o registro: arquivo novo na raiz durante as perguntas -> AUTH_PLAN_CHANGED com as diferencas; escrita que mantem as estatisticas nao e detectada (limite registrado)' {
        $dir = New-TestCleanLogDir 'auth-chg'
        if (-not $dir) { return }
        $p = New-TestProfile 'authchg'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ia = Get-InvArgs -Profiles @($p)
        $file = Join-Path $dir 'chg.jsonl'
        # A closure copies only local variables: the suite's $nowFuture is read here, not inside it.
        $when = $nowFuture.AddDays(-5)
        $add = { [IO.File]::WriteAllBytes((Join-Path $r 'apareceu.bin'), (New-Object byte[] 7)); [IO.File]::SetLastWriteTimeUtc((Join-Path $r 'apareceu.bin'), $when) }.GetNewClosure()
        $op = New-TestAuthOperator -Answers @{ discard = $add }
        $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
        Assert-True (-not $res.Accepted -and $res.Refused -ceq 'AUTH_PLAN_CHANGED' -and @($res.Changes) -contains 'FILES' -and @($res.Changes) -contains 'BYTES' -and -not (Test-Path -LiteralPath $file)) "mudanca detectada: $($res.Refused) [$(@($res.Changes) -join ',')]"
        # Limit: a write that keeps size and modification time leaves every statistic equal and is not detected.
        $target = Join-Path $r 'a.txt'
        $mtime = [IO.File]::GetLastWriteTimeUtc($target)
        $same = { [IO.File]::WriteAllBytes($target, ([byte[]](@(65) * 100))); [IO.File]::SetLastWriteTimeUtc($target, $mtime) }.GetNewClosure()
        $op2 = New-TestAuthOperator -Answers @{ discard = $same }
        $file2 = Join-Path $dir 'same.jsonl'
        $res2 = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file2 -Presenter $op2.Presenter -Reader $op2.Reader
        Assert-True ($res2.Accepted -and (([IO.File]::ReadAllText($file2) | ConvertFrom-Json).limitations -contains 'STATISTICS_NOT_CONTENT')) "limite: escrita com as mesmas estatisticas nao e detectada, e o registro diz isso ($($res2.Refused))"
        $script:caseNote = 'conteudo trocado mantendo tamanho e horario: nao detectado (limite declarado no registro e na documentacao)'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Destino: arquivo existente ou pasta em que outra conta pode criar arquivos -> recusado antes das perguntas, sem alterar arquivo nem ACL' {
        $dir = New-TestCleanLogDir 'auth-dest'
        if (-not $dir) { return }
        $p = New-TestProfile 'authdest'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ex = Join-Path $dir 'existente.jsonl'; [IO.File]::WriteAllText($ex, 'antes')
        $op = New-TestAuthOperator
        $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs (Get-InvArgs -Profiles @($p)) -RecordFile $ex -Presenter $op.Presenter -Reader $op.Reader
        Assert-True ($res.Refused -ceq 'AUTH_RECORD_DESTINATION_REFUSED' -and $op.Prompts.Count -eq 0 -and $op.Presented -eq 0 -and [IO.File]::ReadAllText($ex) -ceq 'antes') "existente: $($res.Refused)"
        $open = Join-Path $dir 'aberta'; [void][IO.Directory]::CreateDirectory($open)
        $acl = Get-Acl -LiteralPath $open
        $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier('S-1-1-0')), 'CreateFiles', 'Allow')))
        Set-Acl -LiteralPath $open -AclObject $acl
        $sddl = (Get-Acl -LiteralPath $open).Sddl
        $op2 = New-TestAuthOperator
        $res2 = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs (Get-InvArgs -Profiles @($p)) -RecordFile (Join-Path $open 'x.jsonl') -Presenter $op2.Presenter -Reader $op2.Reader
        Assert-True ($res2.Refused -ceq 'AUTH_RECORD_DESTINATION_REFUSED' -and $res2.Detail -ceq 'PARENT_THIRD_PARTY_WRITE' -and $op2.Prompts.Count -eq 0 -and (Get-Acl -LiteralPath $open).Sddl -ceq $sddl -and -not (Test-Path -LiteralPath (Join-Path $open 'x.jsonl'))) "pasta insegura: $($res2.Refused) $($res2.Detail)"
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Autorizacao registrada nao promove nem e lida: preview igual antes e depois; nada no produto le o registro; CLI sem console interativo nao registra' {
        $dir = New-TestCleanLogDir 'auth-np'
        if (-not $dir) { return }
        $p = New-TestProfile 'authnp'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ia = Get-InvArgs -Profiles @($p)
        $inv = Inv -Profiles @($p)
        $b = @(Invoke-AtmPreview -Inventory $inv -InventoryArgs $ia | ForEach-Object { "$($_.Partition.Name)=$($_.Gate.Category)" }) -join ','
        $op = New-TestAuthOperator
        $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile (Join-Path $dir 'np.jsonl') -Presenter $op.Presenter -Reader $op.Reader
        $a = @(Invoke-AtmPreview -Inventory (Inv -Profiles @($p)) -InventoryArgs $ia | ForEach-Object { "$($_.Partition.Name)=$($_.Gate.Category)" }) -join ','
        Assert-True ($res.Accepted -and $a -ceq $b) "registro aceito e preview identico ($b -> $a)"
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File)) {
            $t = [IO.File]::ReadAllText($fi.FullName)
            Assert-True (-not ($t -match 'ConvertFrom-Json[^\r\n]*discard|discard-authorization[^\r\n]*ConvertFrom-Json')) "$($fi.Name) le o registro de autorizacao"
        }
        $cmd = Join-Path $srcDir 'bin\agent-temp.cmd'
        $out = (& cmd.exe /c "`"$cmd`" authorize -Path `"$r`" -RecordFile `"$(Join-Path $dir 'cli.jsonl')`"" 2>&1) -join ' '
        Assert-True ($LASTEXITCODE -eq 6 -and -not (Test-Path -LiteralPath (Join-Path $dir 'cli.jsonl'))) "CLI sem console interativo: saida $LASTEXITCODE, nada registrado"
        $null = & cmd.exe /c "`"$cmd`" authorize" 2>&1
        Assert-Eq $LASTEXITCODE 2 'CLI sem -Path/-RecordFile'
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Duas declaracoes sobre o conteudo, testadas separadamente: preservados (OPERATOR_DECLARED) e nada necessario (NOTHING_NEEDED_DISCARD_ACCEPTED); nenhuma verificada pelo produto; TOOL_VERIFIED nunca emitido' {
        $dir = New-TestCleanLogDir 'auth-dec'
        if (-not $dir) { return }
        $p = New-TestProfile 'authdec'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ia = Get-InvArgs -Profiles @($p)
        $kept = Get-AtmText 'auth.phrase.results'; $none = Get-AtmText 'auth.phrase.nothingNeeded'
        $cases = @(@{ Tag = 'preservados'; Answer = $kept; Decision = 'RESULTS_PRESERVED'; Basis = 'OPERATOR_DECLARED' },
            @{ Tag = 'nada necessario'; Answer = $none; Decision = 'NOTHING_NEEDED'; Basis = 'NOTHING_NEEDED_DISCARD_ACCEPTED' })
        $i = 0
        foreach ($c in $cases) {
            $i++
            $file = Join-Path $dir ("dec-$i.jsonl")
            $op = New-TestAuthOperator -Answers @{ results = $c.Answer }
            $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
            Assert-True ($res.Accepted -and $res.ContentDecision -ceq $c.Decision -and $res.RecordState -ceq 'COMPLETE') "$($c.Tag): aceito ($($res.Refused) $($res.Detail))"
            Assert-Eq (@($op.Phrases['results']) -join '|') "$kept|$none" "$($c.Tag): as duas frases oferecidas na mesma pergunta"
            $raw = [IO.File]::ReadAllText($file); $rec = $raw | ConvertFrom-Json
            Assert-True ($rec.declarations.contentDecision -ceq $c.Decision -and $rec.preservation.basis -ceq $c.Basis -and $rec.preservation.verifiedByTool -eq $false -and $null -eq $rec.preservation.evidence -and -not $raw.Contains('TOOL_VERIFIED')) "$($c.Tag): base $($rec.preservation.basis), sem verificacao do produto"
            Assert-True (@($rec.limitations) -contains 'PRESERVATION_NOT_VERIFIED_BY_TOOL' -and @($rec.limitations) -contains 'NO_EVIDENCE_IS_NOT_NON_USE') "$($c.Tag): limites: nao verificado e nao prova desuso"
            $txt = (@(Show-AtmDiscardResult -Result $res 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
            Assert-True ($txt.Contains((Get-AtmText ('auth.decision.' + $c.Decision)))) "$($c.Tag): console diz qual declaracao foi feita"
        }
        # The CLI's prompt: the two phrases splatted as format arguments, as its reader does (the reader itself only runs
        # at a real console).
        $fa = @($kept, $none)
        $prompt = Get-AtmText 'auth.prompt.results' @fa
        Assert-True ($prompt.Contains($kept) -and $prompt.Contains($none) -and -not $prompt.Contains('{0}') -and -not $prompt.Contains('{1}')) 'pergunta da CLI mostra as duas frases'
        Assert-True ([IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1')).Contains("Get-AtmText ('auth.prompt.' + `$kind) @fa")) 'CLI formata a pergunta com as frases como argumentos'
        $lit = (@(Get-ChildItem -LiteralPath $srcDir -Recurse -File | ForEach-Object { [regex]::Matches([IO.File]::ReadAllText($_.FullName), "'TOOL_VERIFIED'").Count }) | Measure-Object -Sum).Sum
        Assert-Eq $lit 1 'TOOL_VERIFIED so na lista reservada: nenhum codigo o emite'
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Falhas do escritor depois da criacao (resultado simulado): escrita, descarga e fechamento - sem sucesso, aviso de arquivo remanescente incompleto ou indeterminado, arquivo preservado, nada promovido nem apagado' {
        # Simulated: Open-AtmCleanLog is replaced in this scope only by a wrapper around the real one; the real writer
        # creates the file. write: nothing is written and the write is reported failed. flush: the real writer writes and
        # flushes the line, then a flush failure is reported (as when FlushFileBuffers fails after WriteFile). close: the
        # real writer writes, flushes and closes, then a close failure is reported. No real failure is provoked.
        $dir = New-TestCleanLogDir 'auth-wfail'
        if (-not $dir) { return }
        $p = New-TestProfile 'authwfail'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ia = Get-InvArgs -Profiles @($p)
        $b = @(Invoke-AtmPreview -Inventory (Inv -Profiles @($p)) -InventoryArgs $ia | ForEach-Object { "$($_.Partition.Name)=$($_.Gate.Category)" }) -join ','
        $realOpen = ${function:Open-AtmCleanLog}
        $acceptedHead = (Get-AtmText 'auth.accepted' 'X' 'Y' 'Z').Substring(0, 20)
        foreach ($mode in @(@{ Fail = 'write'; Code = 'LOG_WRITE_FAILED_SIMULATED'; Lines = 0 }, @{ Fail = 'flush'; Code = 'LOG_FLUSH_FAILED_SIMULATED'; Lines = 1 }, @{ Fail = 'close'; Code = 'LOG_CLOSE_FAILED_SIMULATED'; Lines = 1 })) {
            $file = Join-Path $dir ($mode.Fail + '.jsonl')
            $op = New-TestAuthOperator
            $res = & {
                Set-Item -LiteralPath 'function:local:Open-AtmCleanLog' -Value {
                    param([string]$Path, $Inventory, [string]$ProcessUserSid)
                    $o = & $realOpen -Path $Path -Inventory $Inventory -ProcessUserSid $ProcessUserSid
                    if ($null -eq $o.Log) { return $o }
                    $w = [pscustomobject]@{ Inner = $o.Log; Fail = $mode.Fail; Code = $mode.Code }
                    $w | Add-Member -MemberType ScriptMethod -Name AppendLine -Value {
                        param([string]$Line)
                        if ($this.Fail -ceq 'write') { return $this.Code }
                        $c = $this.Inner.AppendLine($Line)
                        if ($null -ne $c) { return $c }
                        if ($this.Fail -ceq 'flush') { return $this.Code }
                        return $null
                    }
                    $w | Add-Member -MemberType ScriptMethod -Name Close -Value { $c = $this.Inner.Close(); if ($null -ne $c) { return $c }; if ($this.Fail -ceq 'close') { return $this.Code }; return $null }
                    $w | Add-Member -MemberType ScriptMethod -Name Dispose -Value { $this.Inner.Dispose() }
                    [pscustomobject]@{ Log = $w; Code = $null; Created = $o.Created }
                }
                Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
            }
            $k = $mode.Fail
            Assert-True (-not $res.Accepted -and $res.Refused -ceq 'AUTH_RECORD_FAILED' -and $res.Detail -ceq $mode.Code -and $null -eq $res.AuthorizationId) "$($k): sem sucesso ($($res.Refused) $($res.Detail))"
            Assert-True ($res.RecordCreated -and $res.RecordState -ceq 'INCOMPLETE_OR_UNDETERMINED' -and [IO.File]::Exists($file)) "$($k): arquivo remanescente preservado ($($res.RecordState))"
            $left = @([IO.File]::ReadAllLines($file) | Where-Object { $_ })
            Assert-Eq $left.Count $mode.Lines "$($k): linhas que permaneceram"
            if ($left.Count -eq 1) {
                $lrec = $left[0] | ConvertFrom-Json
                Assert-True ($lrec.declarations.status -ceq 'ALL_PHRASES_TYPED' -and @($lrec.limitations) -contains 'RECORD_LINE_MAY_REMAIN_AFTER_FAILURE') "$($k): uma linha completa permanece, e ela mesma diz que nao prova a gravacao"
            }
            $txt = (@(Show-AtmDiscardResult -Result $res 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
            Assert-True ($txt.Contains((Get-AtmText 'auth.recordKept' $file)) -and $txt.Contains($mode.Code) -and -not $txt.Contains($acceptedHead) -and $txt.Contains((Get-AtmText 'auth.nothingDeleted'))) "$($k): console: arquivo mantido, registro nao concluido, nunca aceito"
        }
        $a = @(Invoke-AtmPreview -Inventory (Inv -Profiles @($p)) -InventoryArgs $ia | ForEach-Object { "$($_.Partition.Name)=$($_.Gate.Category)" }) -join ','
        Assert-Eq $a $b 'nada promovido: preview identico'
        Assert-Eq ${function:Open-AtmCleanLog}.ToString().Contains('AtmCleanLog]::Pin') $true 'o substituto nao vaza para o resto da suite'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.Contains('exit $(if ($authRes.Accepted) { 0 } else { 3 })')) 'CLI: saida 3 sempre que nao concluiu'
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Identidade e interacao: identidade do processo, nunca da pessoa; chamador e exigencia como informados; console observado pelo proprio motor nesta chamada; exigencia sem console observado recusada sem pergunta' {
        $dir = New-TestCleanLogDir 'auth-int'
        if (-not $dir) { return }
        $p = New-TestProfile 'authint'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ia = Get-InvArgs -Profiles @($p)
        # The suite's own process: the engine's observation here is what the record must say (no claim of a console the
        # run does not have).
        $here = [bool](Test-AtmDiscardConsoleObserved)
        $cases = @(
            @{ Tag = 'chamada direta'; Interaction = @{}; Caller = 'DIRECT_CALL'; Required = $false },
            @{ Tag = 'outro chamador'; Interaction = @{ Caller = 'TUI'; ConsoleRequired = $true }; Caller = 'DIRECT_CALL'; Required = $false },
            @{ Tag = 'CLI sem exigencia'; Interaction = @{ Caller = 'CLI' }; Caller = 'CLI'; Required = $false })
        $i = 0
        foreach ($c in $cases) {
            $i++
            $op = New-TestAuthOperator
            $file = Join-Path $dir ("int-$i.jsonl")
            $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader -Interaction $c.Interaction
            $rec = [IO.File]::ReadAllText($file) | ConvertFrom-Json
            Assert-True ($res.Accepted -and $rec.processIdentity.sid -ceq $p.Sid -and $rec.processIdentity.identifiesRespondent -eq $false) "$($c.Tag): identidade do processo, nao da pessoa"
            Assert-True ($rec.interaction.caller -ceq $c.Caller -and $rec.interaction.consoleRequiredByCaller -eq $c.Required -and $rec.interaction.callerFieldsVerified -eq $false -and $rec.interaction.interactiveConsoleObserved -is [bool] -and $rec.interaction.interactiveConsoleObserved -eq $here -and $rec.interaction.observedBy -ceq 'ENGINE_CONSOLE_CHECK') "$($c.Tag): $($rec.interaction | ConvertTo-Json -Compress)"
            Assert-True (@($rec.limitations) -contains 'PROCESS_IDENTITY_IS_NOT_THE_RESPONDENT' -and @($rec.limitations) -contains 'CALLER_AND_REQUIREMENT_REPORTED_BY_CALLER' -and @($rec.limitations) -contains 'INTERACTIVE_CONSOLE_IS_NOT_PROOF_OF_PRESENCE') "$($c.Tag): limites de identidade, chamador e presenca"
        }
        # A caller that requires a console: without one observed by the engine, refused before any question.
        $op = New-TestAuthOperator
        $file = Join-Path $dir 'int-req.jsonl'
        $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader -Interaction @{ Caller = 'CLI'; ConsoleRequired = $true }
        if ($here) {
            Assert-True ($res.Accepted -and ([IO.File]::ReadAllText($file) | ConvertFrom-Json).interaction.interactiveConsoleObserved -eq $true) 'console observado: registrado com a observacao do motor'
        } else {
            Assert-True (-not $res.Accepted -and $res.Refused -ceq 'AUTH_CONSOLE_NOT_OBSERVED' -and $op.Presented -eq 0 -and $op.Prompts.Count -eq 0 -and -not (Test-Path -LiteralPath $file)) "exigencia sem console observado: $($res.Refused), nada perguntado nem registrado"
        }
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.Contains('$authConsole = [bool](Test-AtmTuiInteractive)') -and $cli.Contains("Caller = 'CLI'; ConsoleRequired = `$true") -and $cli.Contains('-Interaction $authInteraction') -and -not $cli.Contains('ConsoleObserved')) 'CLI informa chamador e exigencia; a observacao e do motor'
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-True (-not $clean.Contains('interactiveConsoleRequiredByCli') -and -not $clean.Contains("result = 'ACCEPTED'")) 'nenhuma constante de interacao nem ACCEPTED no registro'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Revalidacao semantica dos motivos: coleta equivalente (contagens novas, mesmo processo) nao diverge; mesmo codigo vindo de outro processo diverge; motivo novo com mesma categoria e mesmos codigos (escrita concedida a terceiros na raiz) exige novo plano' {
        # The same runtime code from another process: the stable process key (pid@creationTicksUtc) differs.
        $pu = New-TestProfile 'authsemuse'
        $ru = New-TestRoot -ProfileInfo $pu
        $null = New-TestTranscript -ProfileInfo $pu -Root $ru
        $created = (Get-Date).AddMinutes(-40)
        $iaA = Get-InvArgs -Profiles @($pu) -Procs (New-Procs -Extra @((New-TestRuntimeProc 830 'tool.exe' "tool.exe $ru\a.txt" $created)))
        $iaB = Get-InvArgs -Profiles @($pu) -Procs (New-Procs -Extra @((New-TestRuntimeProc 831 'tool.exe' "tool.exe $ru\a.txt" $created)))
        $u1 = Get-AtmDiscardPresentation -Path $ru -InventoryArgs $iaA
        $u1b = Get-AtmDiscardPresentation -Path $ru -InventoryArgs $iaA
        $u2 = Get-AtmDiscardPresentation -Path $ru -InventoryArgs $iaB
        Assert-True (@($u1.Technical.RuntimeCodes) -contains 'RUNTIME_USE_OBSERVED' -and (@($u1.Technical.RuntimeCodes) -join ',') -ceq (@($u2.Technical.RuntimeCodes) -join ',') -and $u1.Technical.Category -ceq $u2.Technical.Category) "mesmo codigo e categoria nos dois ($(@($u1.Technical.RuntimeCodes) -join ','))"
        $useSrc = (@(@(@($u1.Gate.RuntimeReasons) | Where-Object { $_.Code -ceq 'RUNTIME_USE_OBSERVED' })[0].Sources) -join ',')
        Assert-True ($useSrc -match '^830@\d+$') "a recusa traz a chave estavel do processo ($useSrc)"
        Assert-Eq (@(Compare-AtmDiscardPresentation -Before $u1 -After $u1b) -join ',') '' 'mesmo processo, nova coleta: nenhuma divergencia'
        Assert-Eq (@(Compare-AtmDiscardPresentation -Before $u1 -After $u2) -join ',') 'TECHNICAL_REASONS' 'mesmo codigo vindo de outro processo: divergencia'
        $dir = New-TestCleanLogDir 'auth-sem'
        if (-not $dir) { return }
        $p = New-TestProfile 'authsem'
        $r = New-TestRoot -ProfileInfo $p
        $null = New-TestTranscript -ProfileInfo $p -Root $r
        $ia1 = Get-InvArgs -Profiles @($p) -Procs (New-Procs -Extra @((New-TestRuntimeProc 820 'secret.exe' $null)))
        $ia2 = Get-InvArgs -Profiles @($p) -Procs (New-Procs -Extra @((New-TestRuntimeProc 820 'secret.exe' $null), (New-TestRuntimeProc 821 'secret2.exe' $null)))
        $a = Get-AtmDiscardPresentation -Path $r -InventoryArgs $ia1
        $b = Get-AtmDiscardPresentation -Path $r -InventoryArgs $ia2
        Assert-True ($a.Technical.ProcessCoverage.Gate -ceq 'BLOCKED' -and $b.Technical.ProcessCoverage.Gate -ceq 'BLOCKED' -and (@($a.Technical.Reasons) -join '|') -cne (@($b.Technical.Reasons) -join '|')) 'o texto dos motivos difere (contagem de processos nao inspecionaveis)'
        Assert-Eq (@(Compare-AtmDiscardPresentation -Before $a -After $b) -join ',') '' 'coleta equivalente: nenhuma divergencia'
        Assert-Eq (@(Compare-AtmDiscardPresentation -Before $a -After (Get-AtmDiscardPresentation -Path $r -InventoryArgs $ia1)) -join ',') '' 'nova coleta igual: nenhuma divergencia'
        $file = Join-Path $dir 'sem.jsonl'
        $grant = { $acl = Get-Acl -LiteralPath $r; $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier('S-1-1-0')), 'Write', 'Allow'))); Set-Acl -LiteralPath $r -AclObject $acl }.GetNewClosure()
        $op = New-TestAuthOperator -Answers @{ discard = $grant }
        $res = Invoke-AtmDiscardAuthorization -Path $r -InventoryArgs $ia1 -RecordFile $file -Presenter $op.Presenter -Reader $op.Reader
        Assert-True (-not $res.Accepted -and $res.Refused -ceq 'AUTH_PLAN_CHANGED' -and (@($res.Changes) -join ',') -ceq 'TECHNICAL_REASONS' -and -not (Test-Path -LiteralPath $file)) "motivo novo: $($res.Refused) [$(@($res.Changes) -join ',')]"
        $c = Get-AtmDiscardPresentation -Path $r -InventoryArgs $ia1
        Assert-True ($c.Technical.Category -ceq $a.Technical.Category -and (@($c.Technical.RuntimeCodes) -join ',') -ceq (@($a.Technical.RuntimeCodes) -join ',') -and $c.Partition.Fingerprint -ceq $a.Partition.Fingerprint) "mesma categoria ($($c.Technical.Category)), mesmos codigos e estatisticas: so o motivo mudou"
        Assert-True ([IO.File]::Exists((Join-Path $r 'sub\b.bin'))) 'nada apagado'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Estado do gate B1 separado da cobertura observada: retorno antecipado por ACTIVE_EVIDENCE e por RECENT = NOT_EVALUATED (com cobertura incompleta observada); B1 avaliado bloqueando = BLOCKED; avaliado passando = PASSED; categoria e motivos iguais aos dos gates; gate inalterado' {
        $secret = { New-Procs -Extra @((New-TestRuntimeProc 840 'secret.exe' $null)) }
        $created = (Get-Date).AddMinutes(-40)
        $pa = New-TestProfile 'authb1act'; $ra = New-TestRoot -ProfileInfo $pa; $null = New-TestTranscript -ProfileInfo $pa -Root $ra
        $pr = New-TestProfile 'authb1rec'; $rr = New-TestRoot -ProfileInfo $pr; $null = New-TestTranscript -ProfileInfo $pr -Root $rr
        [IO.File]::SetLastWriteTimeUtc((Join-Path $rr 'a.txt'), $nowFuture.AddHours(-3))
        $pb = New-TestProfile 'authb1blk'; $rb = New-TestRoot -ProfileInfo $pb; $null = New-TestTranscript -ProfileInfo $pb -Root $rb
        $pp = New-TestProfile 'authb1ok'; $rp = New-TestRoot -ProfileInfo $pp; $null = New-TestTranscript -ProfileInfo $pp -Root $rp
        $cases = @(
            @{ Tag = 'ACTIVE_EVIDENCE + cobertura incompleta'; Root = $ra; Profile = $pa; Procs = (New-Procs -Extra @((New-TestRuntimeProc 841 'tool.exe' "tool.exe $ra\a.txt" $created), (New-TestRuntimeProc 840 'secret.exe' $null))); Observed = 'INCOMPLETE'; Gate = 'NOT_EVALUATED' },
            @{ Tag = 'RECENT + cobertura incompleta'; Root = $rr; Profile = $pr; Procs = (& $secret); Observed = 'INCOMPLETE'; Gate = 'NOT_EVALUATED' },
            @{ Tag = 'B1 avaliado bloqueando'; Root = $rb; Profile = $pb; Procs = (& $secret); Observed = 'INCOMPLETE'; Gate = 'BLOCKED' },
            @{ Tag = 'B1 avaliado passando'; Root = $rp; Profile = $pp; Procs = (New-Procs); Observed = 'COMPLETE'; Gate = 'PASSED' })
        foreach ($c in $cases) {
            $ia = Get-InvArgs -Profiles @($c.Profile) -Procs $c.Procs
            $inv = Inv -Profiles @($c.Profile) -Procs $c.Procs
            $g0 = Get-AtmCandidateGate -Partition (Find-Part $inv $c.Root) -Inventory $inv -ForClean
            $pres = Get-AtmDiscardPresentation -Path $c.Root -InventoryArgs $ia
            $b1Reason = @(@($pres.Technical.Reasons) | Where-Object { [string]$_ -like 'COBERTURA_DE_PROCESSOS_INCOMPLETA*' }).Count -gt 0
            Assert-True ($pres.Technical.ProcessCoverage.Observed -ceq $c.Observed -and $pres.Technical.ProcessCoverage.Gate -ceq $c.Gate) "$($c.Tag): observado $($pres.Technical.ProcessCoverage.Observed), gate $($pres.Technical.ProcessCoverage.Gate)"
            Assert-True ($b1Reason -eq ($c.Gate -ceq 'BLOCKED')) "$($c.Tag): motivo B1 presente so quando o gate bloqueou"
            $n = @($g0.Reasons).Count
            $head = $(if ($n) { @(@($pres.Technical.Reasons)[0..($n - 1)]) } else { @() })
            Assert-True ($g0.ProcessCoverageGate -ceq $c.Gate -and (@($g0.Reasons) -join '|') -ceq (@($head) -join '|')) "$($c.Tag): os motivos dos gates sao os mesmos do gate direto"
            Assert-True (@($pres.Technical.ReasonSignature) -contains ('B1_GATE:' + $c.Gate) -and @($pres.Technical.ReasonSignature) -contains ('COVERAGE:' + $c.Observed)) "$($c.Tag): assinatura com o estado do gate e a cobertura"
            if ($c.Gate -ceq 'NOT_EVALUATED') {
                Assert-True ($pres.Technical.Category -ceq 'BLOCKED') "$($c.Tag): continua BLOCKED (o retorno antecipado nao aprova B1)"
                $txt = (@(Show-AtmDiscardPresentation -Presentation $pres 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
                Assert-True ($txt.Contains((Get-AtmText 'auth.b1NotEvaluated' 'INCOMPLETE')) -and -not $txt.Contains((Get-AtmText 'auth.b1Note'))) "$($c.Tag): console diz que B1 nao foi avaliado"
            }
            if ($c.Gate -ceq 'PASSED') { Assert-True (-not $b1Reason) "$($c.Tag): PASSED so com cobertura completa e o gate alcancado" }
        }
        # The gate's B1 block is unchanged (only the returned data gained the state).
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-True ($clean.Contains('if (-not $Inventory.ProcessCoverageComplete) {') -and $clean.Contains("if (`$p.Class -in @('ACTIVE_EVIDENCE', 'RECENT')) { `$reasons.Add((Get-AtmText 'reason.class' `$p.Class)) }")) 'gates B1 e RECENT inalterados'
        Assert-True ($shippedDeletionGate -eq $false) 'trava de exclusao fechada'
    }
    Test-Case 'Autorizacao de descarte (AUT-1)' 'Estatico: console interativo exigido antes de registrar; leitura so por Read-Host na CLI; sem parametro que dispense a interacao; autorizacao nunca chama exclusao; schema gravado em um unico lugar; travas fechadas' {
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        $blk = $cli.Substring($cli.IndexOf("'authorize' {"), $cli.IndexOf("'version' {") - $cli.IndexOf("'authorize' {"))
        Assert-True ($blk.IndexOf('Test-AtmTuiInteractive') -gt 0 -and $blk.IndexOf('Test-AtmTuiInteractive') -lt $blk.IndexOf('Invoke-AtmDiscardAuthorization') -and $blk.Contains('Read-Host')) 'console interativo antes do registro; respostas so por Read-Host'
        $param = $cli.Substring($cli.IndexOf('param('), $cli.IndexOf('$ErrorActionPreference') - $cli.IndexOf('param('))
        # The only switch with 'Accept' is -AcceptB1ResidualRisk (maintainer's decision): it answers nothing and skips no console.
        $paramNoB1 = $param.Replace('[switch]$AcceptB1ResidualRisk', '')
        foreach ($pat in @('Answer', 'Yes', 'Confirm', 'NonInteractive', 'Force', 'Accept')) { Assert-True (-not $paramNoB1.Contains($pat)) "nenhum parametro publico '$pat'" }
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        $auth = $clean.Substring($clean.IndexOf('$script:AtmDiscardAuthSchema ='), $clean.IndexOf('function Test-AtmOutputPathOutsideBases') - $clean.IndexOf('$script:AtmDiscardAuthSchema ='))
        foreach ($pat in @('DeleteTree', 'AtmDeleter', 'Invoke-AtmClean', 'AtmRealDeletionEnabled', 'AtmCleanLock')) { Assert-True (-not $auth.Contains($pat)) "autorizacao sem '$pat'" }
        Assert-Eq ([regex]::Matches($clean, "atm\.discard-authorization/").Count) 1 'schema definido uma vez'
        Assert-True ($auth.Contains('Open-AtmCleanLog -Path $RecordFile')) 'registro pelo escritor fixado (arquivo novo)'
        Assert-True ($shippedDeletionGate -eq $false -and $script:AtmWorktreeDiagnosticsEnabled -eq $false -and $script:AtmHandleDiagnosticsEnabled -eq $false -and $script:AtmDiagnoseExportEnabled -eq $false) 'travas distribuidas fechadas'
    }

    # ------------------------------------------------------------------ plan-bound confirmation in clean (AUT-2)
    # Synthetic roots, the stand-in deleter (counter of calls) and the in-memory writer; the deletion gate is open only in
    # this process (as for T1/B8) and the console observation is the suite's seam unless a case sets its own.
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Duas raizes com decisoes diferentes: perguntas por raiz com o caminho, confirmacao unica com planId e quantidade; declaracoes e confirmacao gravadas antes do primeiro intent; nada apagado' {
        $f = New-TestT1Fixture 'aut2two' 2
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $kept = Get-AtmText 'auth.phrase.results'; $none = Get-AtmText 'auth.phrase.nothingNeeded'
        $op = New-TestCleanOperator -Decisions @{ ($f.Roots[0]) = $kept; ($f.Roots[1]) = $none }
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($null -eq $c.Aborted -and $null -eq $c.StoppedBy -and $c.Confirmed -and $d.Calls.Count -eq 2) "executado com o deleter simulado ($($c.Aborted) $($c.StoppedBy); chamadas $($d.Calls.Count))"
        Assert-Eq ($op.Calls -join ',') ("task|$($f.Roots[0]),results|$($f.Roots[0]),task|$($f.Roots[1]),results|$($f.Roots[1]),confirm|") 'perguntas por raiz com o caminho, depois uma confirmacao'
        $recs = Get-TestCleanLogRecords $w
        Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,plan,declaration,declaration,confirmation,plan-check,intent,result,intent,result,run-end' 'ordem: declaracoes e confirmacao antes de qualquer intent'
        $start = @($recs | Where-Object { $_.type -ceq 'run-start' })[0]; $conf = @($recs | Where-Object { $_.type -ceq 'confirmation' })[0]
        $expected = Get-AtmCleanPlanId -RunId $c.RunId -Parts @($c.Verified)
        Assert-True ($c.PlanId -ceq $expected -and $start.planId -ceq $expected -and $conf.planId -ceq $expected -and $conf.accepted -eq $true -and $conf.roots -eq 2) 'planId do conjunto apresentado no estado, no run-start e na confirmacao'
        Assert-Eq $c.Phrase ('APAGAR 2 CAMINHOS ' + $expected.Substring(0, 8).ToUpperInvariant()) 'frase com a quantidade exata e o planId'
        $plans = @($recs | Where-Object { $_.type -ceq 'plan' }); $decl = @($recs | Where-Object { $_.type -ceq 'declaration' })
        for ($i = 0; $i -lt 2; $i++) {
            Assert-True ($decl[$i].opId -ceq $plans[$i].opId -and $decl[$i].path -ceq $plans[$i].path -and $decl[$i].fingerprint -ceq $plans[$i].fingerprint -and $decl[$i].declaredBy -ceq 'OPERATOR' -and $decl[$i].taskCompleted -eq $true -and $decl[$i].preservation.verifiedByTool -eq $false) "declaracao $($i + 1) ligada a raiz do plano"
        }
        Assert-True ($decl[0].contentDecision -ceq 'RESULTS_PRESERVED' -and $decl[0].preservation.basis -ceq 'OPERATOR_DECLARED' -and $decl[1].contentDecision -ceq 'NOTHING_NEEDED' -and $decl[1].preservation.basis -ceq 'NOTHING_NEEDED_DISCARD_ACCEPTED') 'decisoes diferentes por raiz, com a semantica do AUT-1'
        Assert-True ($conf.interaction.observedBy -ceq 'TEST_SEAM' -and $conf.interaction.identifiesRespondent -eq $false -and @($conf.limitations) -contains 'PRESERVATION_NOT_VERIFIED_BY_TOOL' -and @($conf.limitations) -contains 'INTERACTIVE_CONSOLE_IS_NOT_PROOF_OF_PRESENCE') 'confirmacao com interacao honesta e limites'
        Assert-True (-not (($w.Lines -join "`n").Contains('TOOL_VERIFIED'))) 'TOOL_VERIFIED nunca gravado'
        foreach ($call in $d.Calls) { Assert-True ($call.LastType -ceq 'intent') "intent antes de cada chamada ($($call.LastType))" }
        $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.declared.RESULTS_PRESERVED' $f.Roots[0])) -and $txt.Contains((Get-AtmText 'clean.declared.NOTHING_NEEDED' $f.Roots[1]))) 'console mostra o que foi declarado por raiz'
        Assert-True (Test-TestT1RootsIntact $f) 'deleter simulado: nada apagado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Recusa e cancelamento em cada etapa (tarefa, conteudo, em cada raiz, e confirmacao final): execucao inteira abortada antes da primeira exclusao; recusa registrada com etapa; deleter nunca chamado' {
        $steps = @('task#1', 'results#1', 'task#2', 'results#2', 'confirm')
        $n = 0
        foreach ($step in $steps) {
            foreach ($ans in @('nao', $null, '', 'TOOL_VERIFIED')) {
                $n++
                $f = New-TestT1Fixture ('aut2no' + $n) 2
                $w = New-TestCleanLogWriter
                $d = New-TestCleanDeleter -Writer $w
                $op = New-TestCleanOperator -Answers @{ $step = $ans }
                $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
                $want = $(if ($step -ceq 'confirm') { 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' } elseif ($ans) { 'DECLARATION_DECLINED' } else { 'DECLARATION_CANCELLED' })
                $recs = Get-TestCleanLogRecords $w
                $conf = @($recs | Where-Object { $_.type -ceq 'confirmation' })[0]
                Assert-True ($c.Aborted -ceq $want -and $d.Calls.Count -eq 0 -and -not $c.Confirmed -and $c.RefusedAt.Step -ceq ($step -replace '#\d$', '') -and @($c.Declarations).Count -eq 0) "$step / [$ans]: $($c.Aborted) (chamadas $($d.Calls.Count))"
                Assert-True ((@($recs | ForEach-Object { $_.type }) -join ',') -ceq 'run-start,plan,plan,confirmation,run-end' -and $conf.accepted -eq $false -and $conf.refusal -ceq $want -and $conf.step -ceq ($step -replace '#\d$', '')) "$step / [$ans]: nenhuma declaracao gravada, recusa registrada"
                Assert-True (Test-TestT1RootsIntact $f) "$step / [$ans]: nada apagado"
            }
        }
        $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.refusedAt' 'confirm' '-')) -and $txt.Contains((Get-AtmText 'clean.nothing'))) 'console diz onde parou e que nada foi executado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Frase de outro plano (outra execucao do mesmo conjunto), quantidade errada ou frase antiga sem planId: recusadas; deleter nunca chamado' {
        $f = New-TestT1Fixture 'aut2phr' 2
        $ia = Get-InvArgs -Profiles @($f.Profile)
        $op0 = New-TestCleanOperator -Answers @{ confirm = 'nao' }
        $d0 = New-TestCleanDeleter
        $c0 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op0.Reader -InventoryArgs $ia -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d0.Delete -PathPresenceImpl $d0.Present
        $otherRun = $c0.Phrase
        Assert-True ($c0.Aborted -ceq 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' -and $d0.Calls.Count -eq 0) "execucao de referencia recusada sem chamadas ($($c0.Aborted))"
        $variants = @(
            @{ Tag = 'outra execucao'; Answer = { param($ph) $otherRun }.GetNewClosure() },
            @{ Tag = 'quantidade errada'; Answer = { param($ph) $ph -replace '^APAGAR 2 ', 'APAGAR 1 ' } },
            @{ Tag = 'frase antiga'; Answer = 'APAGAR 2 CAMINHOS' })
        foreach ($v in $variants) {
            $d = New-TestCleanDeleter
            $op = New-TestCleanOperator -Answers @{ confirm = $v.Answer }
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $ia -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            Assert-True ($c.Aborted -ceq 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' -and $d.Calls.Count -eq 0 -and $c.Phrase -cne $otherRun) "$($v.Tag): recusada ($($c.Aborted), chamadas $($d.Calls.Count))"
        }
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Plano muda durante as perguntas (raiz alterada na confirmacao): PLAN_CHANGED_BEFORE_EXECUTION, nenhuma raiz executada, plano nunca reduzido nem atualizado silenciosamente' {
        $f = New-TestT1Fixture 'aut2chg' 2
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $target = $f.Roots[1]
        $when = $nowFuture.AddDays(-5)
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) [IO.File]::WriteAllBytes((Join-Path $target 'apareceu.bin'), (New-Object byte[] 5)); [IO.File]::SetLastWriteTimeUtc((Join-Path $target 'apareceu.bin'), $when) }.GetNewClosure() }
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        $recs = Get-TestCleanLogRecords $w
        $chk = @($recs | Where-Object { $_.type -ceq 'plan-check' })[0]
        Assert-True ($c.Aborted -ceq 'PLAN_CHANGED_BEFORE_EXECUTION' -and $d.Calls.Count -eq 0 -and @($c.Deleted).Count -eq 0) "mudanca recusada antes da execucao ($($c.Aborted), chamadas $($d.Calls.Count))"
        Assert-True ($chk.matched -eq $false -and (@($chk.changed) -join ',') -ceq ('{0}:2' -f $c.RunId) -and $chk.planId -ceq $c.PlanId) "plan-check registra a raiz alterada ($(@($chk.changed) -join ','))"
        Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,plan,declaration,declaration,confirmation,plan-check,run-end' 'sem intent: a raiz inalterada tambem nao foi executada'
        $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.planChanged'))) 'console pede nova apresentacao'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Falha de gravacao ou de descarga das declaracoes, da confirmacao ou da conferencia do plano (escritor simulado): LOG_WRITE_FAILED antes de qualquer intent; deleter nunca chamado' {
        $cases = @(
            @{ FailOn = 'declaration'; FailAt = 1; Code = 'LOG_WRITE_FAILED_WIN32_112' }, @{ FailOn = 'declaration'; FailAt = 2; Code = 'LOG_FLUSH_FAILED_WIN32_1117' },
            @{ FailOn = 'confirmation'; FailAt = 1; Code = 'LOG_FLUSH_FAILED_WIN32_1117' }, @{ FailOn = 'plan-check'; FailAt = 1; Code = 'LOG_WRITE_FAILED_WIN32_112' })
        foreach ($k in $cases) {
            $f = New-TestT1Fixture ('aut2lf' + $k.FailOn.Substring(0, 3) + $k.FailAt) 2
            $w = New-TestCleanLogWriter -FailOn $k.FailOn -FailAt $k.FailAt -FailCode $k.Code
            $d = New-TestCleanDeleter -Writer $w
            $op = New-TestCleanOperator
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            $tag = "$($k.FailOn)#$($k.FailAt) $($k.Code)"
            $types = @(Get-TestCleanLogRecords $w | ForEach-Object { $_.type })
            Assert-True ($c.Aborted -ceq 'LOG_WRITE_FAILED' -and $d.Calls.Count -eq 0 -and @($c.LogErrors)[0].Stage -ceq $k.FailOn -and @($c.LogErrors)[0].Code -ceq $k.Code -and $types -notcontains 'intent') "$($tag): abortado antes de qualquer intent ($($c.Aborted), chamadas $($d.Calls.Count))"
            Assert-True ((-not $c.Confirmed) -eq ($k.FailOn -cne 'plan-check')) "$($tag): confirmado so depois de declaracoes e confirmacao gravadas"
            Assert-True (Test-TestT1RootsIntact $f) "$($tag): nada apagado"
        }
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Sem console observado pelo motor: CONSOLE_NOT_OBSERVED antes de log, perguntas ou deleter; CLI exige console so com a trava aberta; seam distribuido nulo e usado so pelo motor' {
        $f = New-TestT1Fixture 'aut2con' 1
        $w = New-TestCleanLogWriter
        $d = New-TestCleanDeleter -Writer $w
        $op = New-TestCleanOperator
        $prev = $script:AtmCleanConsoleSource
        try { $script:AtmCleanConsoleSource = { $false }; $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present }
        finally { $script:AtmCleanConsoleSource = $prev }
        Assert-True ($c.Aborted -ceq 'CONSOLE_NOT_OBSERVED' -and $op.Calls.Count -eq 0 -and $w.Lines.Count -eq 0 -and $d.Calls.Count -eq 0 -and $null -eq $c.RunId) "sem console: $($c.Aborted) (perguntas $($op.Calls.Count), registros $($w.Lines.Count), chamadas $($d.Calls.Count))"
        $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.consoleRequired'))) 'console explica a exigencia'
        # The engine's own observation (no seam): in this suite's process (redirected output) it observes no console.
        if (-not (Test-AtmDiscardConsoleObserved)) {
            $op2 = New-TestCleanOperator; $d2 = New-TestCleanDeleter
            try { $script:AtmCleanConsoleSource = $null; $c2 = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op2.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present }
            finally { $script:AtmCleanConsoleSource = $prev }
            Assert-True ($c2.Aborted -ceq 'CONSOLE_NOT_OBSERVED' -and $op2.Calls.Count -eq 0 -and $d2.Calls.Count -eq 0) "observacao real do motor sem console: $($c2.Aborted)"
        }
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        $blk = $cli.Substring($cli.IndexOf("'clean' {"), $cli.IndexOf("'authorize' {") - $cli.IndexOf("'clean' {"))
        $gi = $blk.IndexOf('if ($script:AtmRealDeletionEnabled -and -not (Test-AtmTuiInteractive))')
        Assert-True ($gi -gt 0 -and $gi -lt $blk.IndexOf('Invoke-AtmClean')) 'CLI clean: console exigido antes do motor, so com a trava aberta'
        Assert-True ($null -eq $shippedConsoleSource) 'seam distribuido nulo'
        $assign = 0; $refs = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File)) {
            $t = [IO.File]::ReadAllText($fi.FullName)
            $assign += ([regex]::Matches($t, '\$script:AtmCleanConsoleSource\s*=')).Count
            if ($fi.Name -ne 'Engine.Clean.ps1' -and $t.Contains('AtmCleanConsoleSource')) { $refs += $fi.Name }
        }
        Assert-True ($assign -eq 1 -and $refs.Count -eq 0) "seam atribuido uma vez, so no motor ($assign; $($refs -join ','))"
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Recusa da revalidacao depois da confirmacao para a execucao: primeira concluida, segunda recusada, terceira nao tentada (uma chamada, StoppedBy); primeira recusada (zero chamadas, Aborted); sem rollback' {
        foreach ($k in @(@{ Tag = 'segunda recusada'; Refused = 2; Calls = 1 }, @{ Tag = 'primeira recusada'; Refused = 1; Calls = 0 })) {
            $f = New-TestT1Fixture ('aut2rev' + $k.Refused) 3
            $w = New-TestCleanLogWriter
            $d = New-TestCleanDeleter -Writer $w
            $target = $f.Roots[$k.Refused - 1]
            $hook = { param($part) if ([string]::Equals($part.Path, $target, [StringComparison]::OrdinalIgnoreCase)) { [IO.File]::WriteAllBytes((Join-Path $part.Path 'apareceu.bin'), (New-Object byte[] 9)) } }.GetNewClosure()
            $op = New-TestCleanOperator
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -BeforeDeleteHook $hook -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            $recs = Get-TestCleanLogRecords $w
            $tag = $k.Tag
            $stopOp = '{0}:{1}' -f $c.RunId, $k.Refused
            $after = @(($k.Refused + 1)..3 | ForEach-Object { '{0}:{1}' -f $c.RunId, $_ })
            $wantTypes = 'run-start,plan,plan,plan,declaration,declaration,declaration,confirmation,plan-check,' + $(if ($k.Refused -eq 2) { 'intent,result,' } else { '' }) + 'skip,run-end'
            Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') $wantTypes "$($tag): registros (nada depois do skip)"
            Assert-True ($d.Calls.Count -eq $k.Calls -and @($c.Deleted).Count -eq $k.Calls -and @($c.Skipped).Count -eq 1 -and [string]::Equals(@($c.Skipped)[0].Path, $target, [StringComparison]::OrdinalIgnoreCase) -and ((@(@($c.Skipped)[0].Reasons) -join ' ') -match 'ALTERADO_APOS_CONFIRMACAO')) "$($tag): $($d.Calls.Count) chamada(s); a declaracao nao substitui a revalidacao"
            if ($k.Calls -eq 0) { Assert-True ($c.Aborted -ceq 'REVALIDATION_REFUSED' -and $null -eq $c.StoppedBy) "$($tag): Aborted ($($c.Aborted))" }
            else { Assert-True ($c.StoppedBy -ceq 'REVALIDATION_REFUSED' -and $null -eq $c.Aborted -and @($c.Deleted)[0].Outcome -ceq 'COMPLETE') "$($tag): StoppedBy depois de uma operacao concluida ($($c.StoppedBy))" }
            Assert-True ($c.StoppedAtOpId -ceq $stopOp -and (@($c.NotAttempted | ForEach-Object { $_.OpId }) -join ',') -ceq ($after -join ',')) "$($tag): raiz que parou e raizes nao tentadas"
            $end = @($recs | Where-Object { $_.type -ceq 'run-end' })[0]
            Assert-True ($end.stoppedBy -ceq 'REVALIDATION_REFUSED' -and $end.stoppedAtOpId -ceq $stopOp -and (@($end.notAttempted) -join ',') -ceq ($after -join ',') -and $end.complete -eq $k.Calls) "$($tag): run-end distingue concluidas, a que parou e as nao tentadas"
            $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
            Assert-True ($txt.Contains((Get-AtmText 'clean.revalStopped' $stopOp)) -and @($c.NotAttempted | Where-Object { -not $txt.Contains((Get-AtmText 'clean.notAttempted' $_.Path)) }).Count -eq 0) "$($tag): console mostra a parada e as raizes nao tentadas"
            Assert-True (Test-TestT1RootsIntact $f) "$($tag): deleter simulado: nada apagado"
        }
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.Contains('exit $(if ($res.Aborted -or $res.StoppedBy) { 3 } else { 0 })')) 'CLI: saida 3 para Aborted ou StoppedBy'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Falha ao gravar o registro da recusa da revalidacao: LOG_WRITE_FAILED, nenhuma chamada seguinte; terceira raiz nao tentada' {
        $f = New-TestT1Fixture 'aut2revlf' 3
        $w = New-TestCleanLogWriter -FailOn 'skip' -FailCode 'LOG_FLUSH_FAILED_WIN32_1117'
        $d = New-TestCleanDeleter -Writer $w
        $target = $f.Roots[1]
        $hook = { param($part) if ([string]::Equals($part.Path, $target, [StringComparison]::OrdinalIgnoreCase)) { [IO.File]::WriteAllBytes((Join-Path $part.Path 'apareceu.bin'), (New-Object byte[] 9)) } }.GetNewClosure()
        $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader (New-TestCleanOperator).Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -BeforeDeleteHook $hook -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($c.StoppedBy -ceq 'LOG_WRITE_FAILED' -and $d.Calls.Count -eq 1 -and @($c.LogErrors)[0].Stage -ceq 'skip' -and @($c.LogErrors)[0].Code -ceq 'LOG_FLUSH_FAILED_WIN32_1117') "parada pela falha do log ($($c.StoppedBy); chamadas $($d.Calls.Count))"
        Assert-True ((@($c.NotAttempted | ForEach-Object { $_.OpId }) -join ',') -ceq ('{0}:3' -f $c.RunId) -and -not (@(Get-TestCleanLogRecords $w | ForEach-Object { $_.type }) -contains 'run-end')) 'terceira nao tentada; nada mais gravado depois da falha'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'Trava fechada: fluxo de plano inalterado - nenhuma pergunta, sem exigencia de console nem log, frase sem planId; leitor e deleter nunca chamados' {
        $f = New-TestT1Fixture 'aut2gate' 2
        $op = New-TestCleanOperator
        $d = New-TestCleanDeleter
        $prevGate = $script:AtmRealDeletionEnabled; $prevCon = $script:AtmCleanConsoleSource
        try {
            $script:AtmRealDeletionEnabled = $false; $script:AtmCleanConsoleSource = { $false }
            $c = Invoke-AtmClean -Entries $f.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($f.Profile)) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        } finally { $script:AtmRealDeletionEnabled = $prevGate; $script:AtmCleanConsoleSource = $prevCon }
        Assert-True ($c.Aborted -ceq 'EXCLUSAO_REAL_DESABILITADA_V0_1' -and $op.Calls.Count -eq 0 -and $d.Calls.Count -eq 0 -and $null -eq $c.PlanId -and @($c.Declarations).Count -eq 0 -and $c.Phrase -ceq 'APAGAR 2 CAMINHOS' -and $null -eq $c.RunId) "plano apenas ($($c.Aborted); perguntas $($op.Calls.Count); frase $($c.Phrase))"
        Assert-True ($shippedDeletionGate -eq $false) 'trava distribuida fechada'
        Assert-True (Test-TestT1RootsIntact $f) 'nada apagado'
    }
    Test-Case 'Confirmacao vinculada ao plano (AUT-2)' 'B1 e RECENT intactos: raiz RECENT nunca recebe declaracao; com cobertura incompleta nenhuma raiz entra e nada e perguntado; so o conjunto executavel e declarado e confirmado' {
        $p = New-TestProfile 'aut2b1'
        $ok = New-TestRoot -ProfileInfo $p; $rec = New-TestRoot -ProfileInfo $p
        [IO.File]::SetLastWriteTimeUtc((Join-Path $rec 'a.txt'), $nowFuture.AddHours(-3))
        $e = @($ok, $rec | ForEach-Object { [pscustomobject]@{ Source = 't'; Path = $_; Fingerprint = $null } })
        $op = New-TestCleanOperator -Answers @{ confirm = 'nao' }
        $d = New-TestCleanDeleter
        $c = Invoke-AtmClean -Entries $e -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs (Get-InvArgs -Profiles @($p)) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True (@($c.Verified).Count -eq 1 -and @($c.Rejected | Where-Object { $_.Path -ceq $rec }).Count -eq 1 -and ($op.Calls -join ',') -ceq "task|$ok,results|$ok,confirm|" -and $c.Phrase -like 'APAGAR 1 CAMINHOS *') "RECENT fora do conjunto; perguntas so da raiz executavel ($($op.Calls -join ','))"
        $op2 = New-TestCleanOperator
        $d2 = New-TestCleanDeleter
        $c2 = Invoke-AtmClean -Entries $e -PlanPresenter $presenter -ConfirmationReader $op2.Reader -InventoryArgs (Get-InvArgs -Profiles @($p) -Procs (New-Procs -Extra @((New-TestRuntimeProc 850 'secret.exe' $null)))) -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present
        Assert-True ($c2.Aborted -ceq 'NENHUM_CAMINHO_ELEGIVEL' -and $op2.Calls.Count -eq 0 -and $d.Calls.Count -eq 0 -and $d2.Calls.Count -eq 0) "B1: nenhum candidato executavel, nenhuma pergunta ($($c2.Aborted))"
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-True ($clean.Contains('if (-not $Inventory.ProcessCoverageComplete) {') -and $clean.Contains("if (`$p.Class -in @('ACTIVE_EVIDENCE', 'RECENT')) { `$reasons.Add((Get-AtmText 'reason.class' `$p.Class)) }")) 'gates B1 e RECENT inalterados'
        Assert-True ([IO.Directory]::Exists($ok) -and [IO.Directory]::Exists($rec)) 'nada apagado'
    }

    # ------------------------------------------------------------------ B1 restricted exception (V0.3)
    # Synthetic roots of a non-elevated identity with one process whose command line cannot be read (B1 incomplete);
    # stand-in deleter (call counters); the deletion gate open only in this process.
    Test-Case 'Excecao restrita de B1' 'Dentro do escopo, ponta a ponta com -AcceptB1ResidualRisk: categoria nova nunca ELIGIBLE; pergunta de risco por raiz com a contagem; chaves pid@criacao no plano e no planId; declaracao com o risco; nada apagado' {
        $x = New-TestB1Context 'b1in' 1
        $r = $x.F.Roots[0]
        $row = Get-TestB1PreviewRow $x $r
        Assert-True ($row.Gate.Category -ceq 'ELIGIBLE_WITH_DECLARED_RISK' -and $row.Gate.Category -cne 'ELIGIBLE' -and ([string]@($row.Gate.Reasons)[0]).StartsWith('B1_EXCEPTION_RESIDUAL_RISK') -and $row.Gate.B1Risk.Uninspectable -eq 1) "preview: categoria nova ($($row.Gate.Category))"
        $key = @($row.Gate.B1Risk.Keys)[0]
        Assert-True ($key -match '^860@\d+$') "chave do processo nao inspecionavel ($key)"
        $w = New-TestCleanLogWriter; $d = New-TestCleanDeleter -Writer $w; $op = New-TestCleanOperator
        $c = Invoke-AtmClean -Entries $x.F.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $x.IA -AcceptB1ResidualRisk -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($null -eq $c.Aborted -and $null -eq $c.StoppedBy -and $d.Calls.Count -eq 1) "executado com o deleter simulado ($($c.Aborted) $($c.StoppedBy); chamadas $($d.Calls.Count))"
        Assert-Eq ($op.Calls -join ',') "task|$r,results|$r,risk|$r,confirm|" 'tarefa, conteudo, risco por raiz e confirmacao'
        $recs = Get-TestCleanLogRecords $w
        Assert-Eq (@($recs | ForEach-Object { $_.type }) -join ',') 'run-start,plan,declaration,confirmation,plan-check,intent,result,run-end' 'log'
        $start = $recs[0]; $plan = @($recs | Where-Object { $_.type -ceq 'plan' })[0]; $decl = @($recs | Where-Object { $_.type -ceq 'declaration' })[0]
        Assert-True ($start.b1Exception -eq $true -and $start.uninspectableProcesses -eq 1 -and $plan.category -ceq 'ELIGIBLE_WITH_DECLARED_RISK' -and $plan.uninspectableProcesses -eq 1 -and (@($plan.uninspectableKeys) -join ',') -ceq $key) 'run-start e plan com a contagem e as chaves'
        Assert-True ($decl.b1ResidualRiskAccepted -eq $true -and $decl.uninspectableProcesses -eq 1) 'declaracao com o risco aceito e a contagem'
        Assert-Eq $c.PlanId (Get-AtmCleanPlanId -RunId $c.RunId -Parts @($c.Verified) -RiskKeys @($key)) 'planId deriva tambem das chaves aceitas'
        Assert-True ($op.Phrases[2] -ceq (Get-AtmText 'clean.phrase.b1Risk')) 'frase de risco exata'
        Assert-True (-not (($w.Lines -join "`n").Contains('svc-b1-test'))) 'nomes de processos nunca gravados'
        Assert-True (Test-TestT1RootsIntact $x.F) 'nada apagado'
    }
    Test-Case 'Excecao restrita de B1' 'Fora do escopo por dimensao: elevado, -IncludeOtherUsers, RECENT (NOT_EVALUATED), outro motivo V0.1 (ACL), recusa B2-1, processo sem identidade, outra conta - B1 identico (BLOCKED com o mesmo motivo) e nunca a categoria nova' {
        $cases = New-Object System.Collections.Generic.List[object]
        $a = New-TestB1Context 'b1adm' 1 $true; $cases.Add(@{ Tag = 'elevado'; X = $a; Others = $false; B1 = $true })
        $o = New-TestB1Context 'b1oth' 1; $cases.Add(@{ Tag = '-IncludeOtherUsers'; X = $o; Others = $true; B1 = $true })
        $rc = New-TestB1Context 'b1rec' 1; [IO.File]::SetLastWriteTimeUtc((Join-Path $rc.F.Roots[0] 'a.txt'), $nowFuture.AddHours(-3)); $cases.Add(@{ Tag = 'RECENT'; X = $rc; Others = $false; B1 = $false; Gate = 'NOT_EVALUATED' })
        $ac = New-TestB1Context 'b1acl' 1
        $acl = Get-Acl -LiteralPath $ac.F.Roots[0]; $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier('S-1-1-0')), 'Write', 'Allow'))); Set-Acl -LiteralPath $ac.F.Roots[0] -AclObject $acl
        $cases.Add(@{ Tag = 'outro motivo V0.1'; X = $ac; Others = $false; B1 = $true })
        $bf = New-TestT1Fixture 'b1b2' 1
        $bx = New-TestB1Context 'b1b2x' 1 $false @((New-TestRuntimeProc 861 'node.exe' "node $([IO.Path]::GetDirectoryName($bf.Roots[0]))"))
        $bx.IA['ProfilesOverride'] = @($bf.Profile); $bx = [pscustomobject]@{ F = $bf; Procs = $bx.Procs; Identity = $bx.Identity; IA = $bx.IA }
        $cases.Add(@{ Tag = 'recusa B2-1'; X = $bx; Others = $false; B1 = $null })
        $nk = New-TestB1Context 'b1nokey' 1 $false @([pscustomobject]@{ ProcessId = 862; Name = 'nocreation.exe'; ParentProcessId = 1; CommandLine = $null; CreationDate = $null }); $cases.Add(@{ Tag = 'processo sem identidade'; X = $nk; Others = $false; B1 = $true })
        foreach ($k in $cases) {
            $row = Get-TestB1PreviewRow $k.X $k.X.F.Roots[0] -Others:$k.Others
            Assert-True ($null -ne $row) "$($k.Tag): raiz presente no preview"
            $hasB1 = @(@($row.Gate.Reasons) | Where-Object { [string]$_ -like 'COBERTURA_DE_PROCESSOS_INCOMPLETA*' }).Count -gt 0
            Assert-True ($row.Gate.Category -cne 'ELIGIBLE_WITH_DECLARED_RISK' -and $row.Gate.Category -cne 'ELIGIBLE' -and $null -eq $row.Gate.B1Risk) "$($k.Tag): fora da excecao ($($row.Gate.Category))"
            if ($k.B1 -eq $true) { Assert-True ($hasB1 -and $row.Gate.Category -ceq 'BLOCKED' -and $row.Gate.ProcessCoverageGate -ceq 'BLOCKED') "$($k.Tag): B1 identico (BLOCKED, mesmo motivo)" }
            if ($k.ContainsKey('Gate')) { Assert-True ($row.Gate.ProcessCoverageGate -ceq $k['Gate'] -and -not $hasB1) "$($k.Tag): RECENT antes de B1 ($($row.Gate.ProcessCoverageGate))" }
            $d = New-TestCleanDeleter; $op = New-TestCleanOperator
            $c = Invoke-AtmClean -Entries $k.X.F.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $k.X.IA -AcceptB1ResidualRisk -IncludeOtherUsers:$k.Others -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            Assert-True ($c.Aborted -ceq 'NENHUM_CAMINHO_ELEGIVEL' -and $op.Calls.Count -eq 0 -and $d.Calls.Count -eq 0) "$($k.Tag): clean com a opcao recusa ($($c.Aborted))"
            Assert-True (Test-TestT1RootsIntact $k.X.F) "$($k.Tag): nada apagado"
        }
        $po = New-TestProfile 'b1acct' -Sid 'S-1-5-21-9-9-9-1001'; $ro = New-TestRoot -ProfileInfo $po
        $xo = New-TestB1Context 'b1acctx' 1; $xo.IA['ProfilesOverride'] = @($po); $xoIa = $xo.IA
        # F05-OWNER-ATTRIBUTION: the other account's base is attributed to it only as its owner (dubbed, no ACL change).
        Set-TestBaseOwner @{ (Get-Base $po) = $po.Sid }
        try { $rowo = Get-TestPreviewRow (Invoke-AtmPreview -Inventory (Invoke-AtmInventory @xoIa) -InventoryArgs $xo.IA) $ro } finally { $script:AtmBaseOwnerSource = $null }
        Assert-True ($null -ne $rowo) 'outra conta: raiz inventariada'
        Assert-True ($rowo.Gate.Category -cne 'ELIGIBLE_WITH_DECLARED_RISK' -and $null -eq $rowo.Gate.B1Risk) "outra conta: fora da excecao ($($rowo.Gate.Category))"
    }
    Test-Case 'Excecao restrita de B1' 'Processo nao inspecionavel novo depois da confirmacao: recusa na conferencia do plano e na revalidacao; process-snapshot PARTIAL na revalidacao: recusa; zero chamadas ao deleter' {
        $late = (Get-Date).AddMinutes(-1)
        $x1 = New-TestB1Context 'b1newchk' 1
        $procs1 = $x1.Procs
        # A closure copies only local variables (no script functions): the process is built here, added inside it.
        $lateProc1 = New-TestRuntimeProc 870 'late.exe' $null $late
        $op1 = New-TestCleanOperator -Answers @{ confirm = { param($ph) [void]$procs1.Add($lateProc1) }.GetNewClosure() }
        $w1 = New-TestCleanLogWriter; $d1 = New-TestCleanDeleter -Writer $w1
        $c1 = Invoke-AtmClean -Entries $x1.F.Entries -PlanPresenter $presenter -ConfirmationReader $op1.Reader -InventoryArgs $x1.IA -AcceptB1ResidualRisk -LogWriter $w1 -DeleteTreeImpl $d1.Delete -PathPresenceImpl $d1.Present
        Assert-True ($c1.Aborted -ceq 'PLAN_CHANGED_BEFORE_EXECUTION' -and $d1.Calls.Count -eq 0) "conferencia do plano: processo novo recusado ($($c1.Aborted))"
        $x2 = New-TestB1Context 'b1newrev' 1
        $procs2 = $x2.Procs
        $lateProc2 = New-TestRuntimeProc 871 'late2.exe' $null $late
        $hook2 = { param($part) [void]$procs2.Add($lateProc2) }.GetNewClosure()
        $d2 = New-TestCleanDeleter
        $c2 = Invoke-AtmClean -Entries $x2.F.Entries -PlanPresenter $presenter -ConfirmationReader (New-TestCleanOperator).Reader -InventoryArgs $x2.IA -AcceptB1ResidualRisk -BeforeDeleteHook $hook2 -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d2.Delete -PathPresenceImpl $d2.Present
        Assert-True ($c2.Aborted -ceq 'REVALIDATION_REFUSED' -and $d2.Calls.Count -eq 0 -and ((@(@($c2.Skipped)[0].Reasons) -join ' ') -match 'B1_EXCEPTION_NEW_UNINSPECTABLE_PROCESS')) "revalidacao: processo novo recusado ($($c2.Aborted); $((@(@($c2.Skipped)[0].Reasons)) -join ';'))"
        $x3 = New-TestB1Context 'b1snap' 1
        $procs3 = $x3.Procs
        $hook3 = { param($part) [void]$procs3.Add([pscustomobject]@{ ProcessId = 1; Name = 'idle.exe'; ParentProcessId = 0; CommandLine = 'idle.exe'; CreationDate = (Get-Date).AddHours(-1) }) }.GetNewClosure()
        $d3 = New-TestCleanDeleter
        $c3 = Invoke-AtmClean -Entries $x3.F.Entries -PlanPresenter $presenter -ConfirmationReader (New-TestCleanOperator).Reader -InventoryArgs $x3.IA -AcceptB1ResidualRisk -BeforeDeleteHook $hook3 -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d3.Delete -PathPresenceImpl $d3.Present
        Assert-True ($c3.Aborted -ceq 'REVALIDATION_REFUSED' -and $d3.Calls.Count -eq 0 -and ((@(@($c3.Skipped)[0].Reasons) -join ' ') -match 'B1_EXCEPTION_NO_LONGER_APPLIES')) "process-snapshot PARTIAL (PID duplicado) na revalidacao: recusa ($($c3.Aborted); $((@(@($c3.Skipped)[0].Reasons)) -join ';'))"
        foreach ($f in @($x1.F, $x2.F, $x3.F)) { Assert-True (Test-TestT1RootsIntact $f) 'nada apagado' }
    }
    Test-Case 'Excecao restrita de B1' 'Limite fixo (1 raiz por execucao com a excecao): excesso recusa a execucao inteira antes de qualquer pergunta; frase de risco recusada ou cancelada aborta tudo; limites sem parametro' {
        $x = New-TestB1Context 'b1lim' 2
        $op = New-TestCleanOperator; $w = New-TestCleanLogWriter; $d = New-TestCleanDeleter -Writer $w
        $c = Invoke-AtmClean -Entries $x.F.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $x.IA -AcceptB1ResidualRisk -LogWriter $w -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        Assert-True ($c.Aborted -ceq 'B1_EXCEPTION_LIMIT_EXCEEDED' -and $op.Calls.Count -eq 0 -and $d.Calls.Count -eq 0 -and $w.Lines.Count -eq 0) "limite: $($c.Aborted) (perguntas $($op.Calls.Count), registros $($w.Lines.Count))"
        $txt = (@(Show-AtmCleanResult -Result $c 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($txt.Contains((Get-AtmText 'clean.b1LimitExceeded' 1 2))) 'console explica o limite'
        foreach ($ans in @('nao', $null)) {
            $x1 = New-TestB1Context 'b1riskno' 1
            $op1 = New-TestCleanOperator -Answers @{ 'risk#1' = $ans }; $d1 = New-TestCleanDeleter
            $c1 = Invoke-AtmClean -Entries $x1.F.Entries -PlanPresenter $presenter -ConfirmationReader $op1.Reader -InventoryArgs $x1.IA -AcceptB1ResidualRisk -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d1.Delete -PathPresenceImpl $d1.Present
            Assert-True ($c1.Aborted -ceq $(if ($ans) { 'DECLARATION_DECLINED' } else { 'DECLARATION_CANCELLED' }) -and $c1.RefusedAt.Step -ceq 'risk' -and $d1.Calls.Count -eq 0) "frase de risco [$ans]: $($c1.Aborted)"
        }
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-True ([regex]::Matches($clean, '\$script:AtmB1ExceptionActiveMaxRoots\s*=').Count -eq 1 -and $clean.Contains('$script:AtmB1ExceptionActiveMaxRoots = 1') -and $clean.Contains('$script:AtmB1ExceptionLaterMaxRoots = 5') -and $clean.Contains('$script:AtmB1ExceptionLaterMaxBytes = 2GB')) 'limites fixos no codigo (1 ativo; 5/2 GiB definidos)'
        $usesLater = [regex]::Matches($clean, 'AtmB1ExceptionLaterMax').Count
        Assert-Eq $usesLater 2 'limites da etapa posterior definidos e nao usados'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        $param = $cli.Substring($cli.IndexOf('param('), $cli.IndexOf('$ErrorActionPreference') - $cli.IndexOf('param('))
        Assert-True (-not ($param -match 'MaxRoots|MaxBytes|Limit')) 'nenhum parametro altera os limites'
        foreach ($f in @($x.F, $x1.F)) { Assert-True (Test-TestT1RootsIntact $f) 'nada apagado' }
    }
    Test-Case 'Excecao restrita de B1' 'Sem a opcao: B1 identico mesmo dentro do escopo; trava fechada com a opcao: fluxo de plano inalterado; TUI nunca passa a opcao; nenhuma lista de nomes, contas ou caminhos' {
        $x = New-TestB1Context 'b1noopt' 1
        $xIa = $x.IA
        $d = New-TestCleanDeleter; $op = New-TestCleanOperator
        $c = Invoke-AtmClean -Entries $x.F.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $x.IA -LogWriter (New-TestCleanLogWriter) -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        $rej = @(@($c.Rejected)[0].Reasons)
        Assert-True ($c.Aborted -ceq 'NENHUM_CAMINHO_ELEGIVEL' -and $rej.Count -eq 1 -and ([string]$rej[0]).StartsWith('COBERTURA_DE_PROCESSOS_INCOMPLETA') -and $op.Calls.Count -eq 0 -and $d.Calls.Count -eq 0) "sem a opcao: B1 identico ($($c.Aborted); $($rej -join ';'))"
        $g = Test-AtmCandidate -Partition (Find-Part (Invoke-AtmInventory @xIa) $x.F.Roots[0]) -Inventory (Invoke-AtmInventory @xIa) -ForClean -RuntimeEvidence (Get-AtmCleanRuntimeEvidence -Inventory (Invoke-AtmInventory @xIa) -InventoryArgs $x.IA)
        Assert-True ($g.Category -ceq 'BLOCKED' -and $null -eq $g.B1Risk) "gate para clean sem a opcao: BLOCKED ($($g.Category))"
        $prev = $script:AtmRealDeletionEnabled
        try {
            $script:AtmRealDeletionEnabled = $false
            $cA = Invoke-AtmClean -Entries $x.F.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $x.IA -AcceptB1ResidualRisk -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
            $cB = Invoke-AtmClean -Entries $x.F.Entries -PlanPresenter $presenter -ConfirmationReader $op.Reader -InventoryArgs $x.IA -DeleteTreeImpl $d.Delete -PathPresenceImpl $d.Present
        } finally { $script:AtmRealDeletionEnabled = $prev }
        Assert-True ($cA.Aborted -ceq $cB.Aborted -and (@($cA.Rejected | ForEach-Object { @($_.Reasons) -join ';' }) -join '|') -ceq (@($cB.Rejected | ForEach-Object { @($_.Reasons) -join ';' }) -join '|') -and @($cA.Verified).Count -eq @($cB.Verified).Count -and $op.Calls.Count -eq 0 -and $d.Calls.Count -eq 0) "trava fechada: com e sem a opcao iguais ($($cA.Aborted) / $($cB.Aborted))"
        $tui = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Tui.ps1'))
        Assert-True (-not $tui.Contains('AcceptB1ResidualRisk')) 'TUI nunca passa a opcao (B1 identico na TUI)'
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        $fn = $clean.Substring($clean.IndexOf('function Get-AtmB1ExceptionRisk'), $clean.IndexOf('function Test-AtmCandidate') - $clean.IndexOf('function Get-AtmB1ExceptionRisk'))
        foreach ($pat in @('UninspectableByName', '.Name ', '.Name)', 'svchost', 'SYSTEM', 'S-1-5-18', 'Program Files', 'Windows\')) { Assert-True (-not $fn.Contains($pat)) "excecao sem lista por nome, conta ou caminho ('$pat')" }
        Assert-True (Test-TestT1RootsIntact $x.F) 'nada apagado'
    }
    Test-Case 'Excecao restrita de B1' 'Cada condicao isolada (Get-AtmB1ExceptionRisk direto): provedor, tipo, classe, flag, elevado, motivo V0.1 adicional, recusa B2-1, process-snapshot nao COMPLETE, processes com outro motivo ou FAILED -> sem excecao; base dentro do escopo; sonda de bloqueio so no clean' {
        $x = New-TestB1Context 'b1unit' 1
        $ia = $x.IA
        $inv = Invoke-AtmInventory @ia
        $rt = Get-AtmCleanRuntimeEvidence -Inventory $inv -InventoryArgs $ia
        $p = Find-Part $inv $x.F.Roots[0]
        $g = Get-AtmCandidateGate -Partition $p -Inventory $inv -ForClean
        $call = { param($Part = $p, $Inv = $inv, $Gate = $g, $Refs = @(), $Rt = $rt) Get-AtmB1ExceptionRisk -Partition $Part -Inventory $Inv -Gate $Gate -Refusals $Refs -RuntimeEvidence $Rt -SkipLockProbe }
        $base = & $call
        Assert-True ($null -ne $base -and $base.Uninspectable -eq 1) 'base dentro do escopo: excecao'
        $part = { param([hashtable]$Set) $c = $p.PSObject.Copy(); foreach ($k in $Set.Keys) { $c.$k = $Set[$k] }; $c }
        $cov = { param([object[]]$Records) $c = $rt.PSObject.Copy(); $c.Coverage = @(@($rt.Coverage | Where-Object { @('process-snapshot', 'processes') -cnotcontains [string]$_.Collector }) + @($Records)); $c }
        $rec = { param([string]$C, [string]$S, [string[]]$R) [pscustomobject]@{ Collector = $C; Status = $S; Reasons = @($R); StartedUtc = $null; ElapsedMs = 0 } }
        $okSnap = & $rec 'process-snapshot' 'COMPLETE' @(); $okProc = & $rec 'processes' 'PARTIAL' @('UNINSPECTABLE_PROCESSES')
        Assert-True ($null -ne (& $call -Rt (& $cov @($okSnap, $okProc)))) 'coberturas validas reconstituidas: excecao'
        $adm = $inv.PSObject.Copy(); $adm.Identity = [pscustomobject]@{ Sid = $inv.Identity.Sid; Name = $inv.Identity.Name; IsAdmin = $true }
        $gate2 = [pscustomobject]@{ Category = 'BLOCKED'; Reasons = @(@($g.Reasons) + @('ESTRUTURA_PAI_INVALIDA')); ProcessCoverageGate = 'BLOCKED' }
        $refusal = New-AtmRuntimeRefusal -Code 'RUNTIME_OBSERVATION_INCOMPLETE' -Decision 'INVESTIGATE' -Collector 'process-snapshot' -Evidence 'COLLECTOR_FAILED' -Relation 'COVERAGE' -Nature 'COVERAGE' -ObservedUtc (Get-Date) -Coverage 'FAILED'
        $cases = @(
            @{ Tag = 'provedor'; R = (& $call -Part (& $part @{ Provider = 'claude-desktop' })) },
            @{ Tag = 'tipo'; R = (& $call -Part (& $part @{ Kind = 'ScopeRoot' })) },
            @{ Tag = 'classe'; R = (& $call -Part (& $part @{ Class = 'LIVENESS_UNKNOWN' })) },
            @{ Tag = 'flag'; R = (& $call -Part (& $part @{ Flags = @('TRANSCRIPT_RECENT') })) },
            @{ Tag = 'elevado'; R = (& $call -Inv $adm) },
            @{ Tag = 'motivo V0.1 adicional'; R = (& $call -Gate $gate2) },
            @{ Tag = 'recusa B2-1'; R = (& $call -Refs @($refusal)) },
            @{ Tag = 'process-snapshot PARTIAL'; R = (& $call -Rt (& $cov @((& $rec 'process-snapshot' 'PARTIAL' @('DUPLICATE_PID')), $okProc))) },
            @{ Tag = 'sem process-snapshot'; R = (& $call -Rt (& $cov @($okProc))) },
            @{ Tag = 'processes com outro motivo'; R = (& $call -Rt (& $cov @($okSnap, (& $rec 'processes' 'PARTIAL' @('UNINSPECTABLE_PROCESSES', 'PROCESS_LIMIT_EXCEEDED'))))) },
            @{ Tag = 'processes FAILED'; R = (& $call -Rt (& $cov @($okSnap, (& $rec 'processes' 'FAILED' @('PROCESS_SNAPSHOT_FAILED'))))) },
            @{ Tag = 'coleta de execucao falhou'; R = (& $call -Rt ([pscustomobject]@{ Failed = 'IOException'; Coverage = @($okSnap, $okProc) })) })
        foreach ($k in $cases) { Assert-True ($null -eq $k.R) "$($k.Tag): sem excecao" }
        # The lock probe (exclusive DELETE opens) is asked only for clean: with a file of the root held open without
        # sharing, preview still shows the category (unprobed) and clean's evaluation refuses (B1 as before).
        $fs = [IO.File]::Open((Join-Path $x.F.Roots[0] 'a.txt'), 'Open', 'Read', 'None')
        try {
            $gp = Test-AtmCandidate -Partition $p -Inventory $inv -RuntimeEvidence $rt
            $gc = Test-AtmCandidate -Partition $p -Inventory $inv -ForClean -AcceptB1ResidualRisk -RuntimeEvidence $rt
        } finally { $fs.Dispose() }
        Assert-True ($gp.Category -ceq 'ELIGIBLE_WITH_DECLARED_RISK' -and $gc.Category -ceq 'BLOCKED' -and $null -eq $gc.B1Risk) "sonda so no clean (preview $($gp.Category); clean $($gc.Category))"
        Assert-True (Test-TestT1RootsIntact $x.F) 'nada apagado'
    }
    Test-Case 'Excecao restrita de B1' 'Preview com a trava fechada (en-US e pt-BR): bloco proprio de risco declarado, texto de nao liberada, nunca no bloco ELIGIBLE nem na lista para allowlist' {
        $x = New-TestB1Context 'b1prev' 1
        $xIa = $x.IA
        $r = $x.F.Roots[0]
        $old = Get-AtmLanguage
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $inv = Invoke-AtmInventory @xIa
                $rows = Invoke-AtmPreview -Inventory $inv -InventoryArgs $x.IA
                $txt = (@(Show-AtmPreview -Inventory $inv -Rows $rows 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
                $hdr = $txt.IndexOf((Get-AtmText 'preview.declaredRisk'))
                $line = $txt.IndexOf("[ELIGIBLE_WITH_DECLARED_RISK] $r")
                Assert-True ($hdr -ge 0 -and $line -gt $hdr -and -not $txt.Contains("[ELIGIBLE] $r") -and -not $txt.Contains("$r|") -and $txt.Contains((Get-AtmText 'reason.b1Exception' 'B1_EXCEPTION_RESIDUAL_RISK' 1))) "$($lang): bloco proprio, nao liberada, fora da allowlist"
            }
        } finally { Set-AtmLanguage -Requested $old }
    }

    # ------------------------------------------------------------------ read-only guarantee
    Test-Case 'Somente leitura' 'audit + preview e uma sessao da GUI (V0.2.1 P2 a P5, sem janela) com tres auditorias dubladas, navegacao pelas telas entre elas, o preview real (P e 8), o diagnose real (D e cada tela da area) e o monitoramento ao vivo ligado com dois ticks do inventario real nao alteram nada no sandbox' {
        $p = New-TestProfile 'ro'
        1..3 | ForEach-Object { $null = New-TestRoot -ProfileInfo $p }
        # NTFS updates directory timestamps lazily after recent creations: wait until the tree is stable.
        $before = Get-TreeListing $p.ProfilePath
        for ($w = 0; $w -lt 20; $w++) { Start-Sleep -Milliseconds 500; $again = Get-TreeListing $p.ProfilePath; if ($again -eq $before) { break }; $before = $again }
        $i = Inv -Profiles @($p)
        Show-AtmAudit -Inventory $i
        $rows = Invoke-AtmPreview -Inventory $i
        Show-AtmPreview -Inventory $i -Rows $rows
        # V0.2.1 P2: a GUI session (the refresh logic of the window, no window) audits the same sandbox three times
        # through the real engine, with the dubbed profile, and shows its dashboard and state each time.
        $script:guiRoArgs = Get-InvArgs -Profiles @($p)
        $savedGuiSource = $script:AtmGuiInventorySource
        try {
            $script:AtmGuiInventorySource = { param($a) $m = @{} + $script:guiRoArgs; $m['ProgressCallback'] = $a['ProgressCallback']; $m['NoProgress'] = $false; Invoke-AtmInventory @m }
            $gs = Initialize-AtmGuiSession -ConfigDir $cfgDir
            # V0.2.1 P4a: the session's inventory arguments are the dubbed profile's, as the preview receives them.
            $gs.InventoryArgs = @{} + $script:guiRoArgs
            # V0.2.1 P3: between the audits the session moves through the new screens (users, projects, roots, the detail,
            # coverage and errors), each computed again over the new result.
            $walks = @(@('D2', 'Return', 'Return', 'Escape'), @('D3', 'Return', 'Return'), @('D9', 'Escape', 'D4', 'Return'))
            foreach ($n in 1..3) {
                Assert-Eq (Invoke-AtmGuiRefresh -Session $gs -Pump { }) 'OK' "sessao da GUI: auditoria $n"
                $null = Get-AtmGuiDashboard -Inventory $gs.Inventory
                $null = Get-AtmGuiViewState -Inventory $gs.Inventory -RefreshedUtc $gs.RefreshedUtc
                Invoke-AtmGuiNavRefreshed -Nav $gs.Nav -Inventory $gs.Inventory
                foreach ($k in $walks[$n - 1]) {
                    Assert-Eq (Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key $k -Busy $false) 'RENDER' "sessao da GUI: tecla $k depois da auditoria $n"
                    $null = Get-AtmGuiScreen -Inventory $gs.Inventory -Screen (Get-AtmGuiNavTop -Nav $gs.Nav)
                }
            }
            Assert-Eq (Get-AtmGuiNavTop -Nav $gs.Nav).Name 'detail' 'sessao da GUI: termina no detalhe de uma raiz'
            # V0.2.1 P4a: P, 8 and P again with the real preview (the engine's, not dubbed) over the same sandbox: one call
            # for the last audit, then the kept rows; Enter on a row of P opens its detail with the Preview line.
            Assert-True ($null -eq $script:AtmGuiPreviewSource) 'sessao da GUI: o preview e o do motor (sem costura)'
            $prs = New-Object System.Collections.Generic.List[string]
            foreach ($k in @('P', 'D8', 'P')) {
                Assert-Eq (Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key $k -Busy $false -Preview $gs.Preview) 'RENDER' "sessao da GUI: tecla $k"
                $prs.Add((Invoke-AtmGuiPreview -Session $gs))
                $null = Get-AtmGuiScreen -Inventory $gs.Inventory -Screen (Get-AtmGuiNavTop -Nav $gs.Nav) -Preview $gs.Preview
            }
            Assert-True (($prs.ToArray() -join ',') -ceq 'OK,CACHED,CACHED' -and $gs.PreviewCalls -eq 1 -and $null -eq $gs.PreviewFailureType) "sessao da GUI: um preview, depois o guardado ($($prs.ToArray() -join ','); $($gs.PreviewFailureType))"
            $pvm = Get-AtmGuiScreen -Inventory $gs.Inventory -Screen (Get-AtmGuiNavTop -Nav $gs.Nav) -Preview $gs.Preview
            Assert-Eq @($pvm.Rows).Count @($gs.Preview).Count 'sessao da GUI: P mostra uma linha por linha do preview'
            if (@($pvm.Items).Count -gt 0) {
                Assert-Eq (Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key 'Return' -Busy $false -Preview $gs.Preview) 'RENDER' 'sessao da GUI: Enter numa linha do preview'
                $dvm = Get-AtmGuiScreen -Inventory $gs.Inventory -Screen (Get-AtmGuiNavTop -Nav $gs.Nav) -Preview $gs.Preview
                Assert-True (@($dvm.Pairs | Where-Object { $_.Label -ceq 'Preview' }).Count -eq 1) 'sessao da GUI: o detalhe do preview tem a linha Preview'
            }
            # V0.2.1 P4b: D twice with the real diagnose (the engine's, not dubbed) over the same sandbox and the session's
            # arguments: one call, then the kept result; the lines of the V0.2 gates (worktrees, open files) are there;
            # then every screen of the area, Enter on the first row of each list, and back.
            Assert-True ($null -eq $script:AtmGuiDiagnoseSource) 'sessao da GUI: o diagnose e o do motor (sem costura)'
            $drs = New-Object System.Collections.Generic.List[string]
            foreach ($k in @('D', 'D')) {
                Assert-Eq (Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key $k -Busy $false -Diag $gs.Diag) 'DIAG_OPEN' "sessao da GUI: tecla $k"
                $dr = Invoke-AtmGuiDiagnose -Session $gs -Pump { }
                $drs.Add($dr)
                Invoke-AtmGuiNavDiag -Nav $gs.Nav -Diag $gs.Diag -Result $dr
            }
            Assert-True (($drs.ToArray() -join ',') -ceq 'OK,CACHED' -and $gs.DiagCalls -eq 1 -and $null -eq $gs.Diag.Error -and (Get-AtmGuiNavTop -Nav $gs.Nav).Name -ceq 'diag') "sessao da GUI: um diagnose, depois o guardado ($($drs.ToArray() -join ','); $($gs.Diag.Error))"
            $gcodes = @(@($gs.Diag.Gates) | ForEach-Object { $_.Code + '|' + $_.Collector })
            Assert-True ($gcodes -ccontains 'WORKTREE_DIAGNOSTICS_GATE_CLOSED|worktree-discovery' -and $gcodes -ccontains 'HANDLE_SECURITY_GATE_CLOSED|handles') "sessao da GUI: as linhas das travas de worktrees e de arquivos abertos ($($gcodes -join ','))"
            $nScreens = 1
            for ($ci = 0; $ci -lt 9; $ci++) {
                (Get-AtmGuiNavTop -Nav $gs.Nav).Sel = $ci
                Assert-Eq (Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key 'Return' -Busy $false -Diag $gs.Diag) 'RENDER' "sessao da GUI: Enter na categoria $ci da area"
                $dvm = Get-AtmGuiScreen -Inventory $gs.Inventory -Screen (Get-AtmGuiNavTop -Nav $gs.Nav) -Diag $gs.Diag
                $nScreens++
                if ($dvm.Kind -ceq 'table' -and @($dvm.Items).Count -gt 0) {
                    Assert-Eq (Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key 'Return' -Busy $false -Diag $gs.Diag) 'RENDER' "sessao da GUI: Enter na primeira linha da categoria $ci"
                    $null = Get-AtmGuiScreen -Inventory $gs.Inventory -Screen (Get-AtmGuiNavTop -Nav $gs.Nav) -Diag $gs.Diag
                    $nScreens++
                    $null = Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key 'Escape' -Busy $false -Diag $gs.Diag
                }
                $null = Invoke-AtmGuiNavKey -Nav $gs.Nav -Inventory $gs.Inventory -Key 'Escape' -Busy $false -Diag $gs.Diag
            }
            Assert-True ((Get-AtmGuiNavTop -Nav $gs.Nav).Name -ceq 'diag' -and $gs.DiagCalls -eq 1) "sessao da GUI: de volta a area, nenhum diagnose a mais ($nScreens telas)"
            # V0.2.1 P5: the live monitoring on and two due ticks with the real inventory (only the clock is dubbed): two
            # audits, the area's screen stays, the diagnose is not called again.
            $savedGuiClock = $script:AtmGuiClockSource
            try {
                $script:guiRoClk = New-Object DateTime(2026, 11, 1, 10, 0, 0, [DateTimeKind]::Utc)
                $script:AtmGuiClockSource = { $script:guiRoClk }
                Set-AtmGuiMonitor -Session $gs -On $true -Now $script:guiRoClk
                $trs = New-Object System.Collections.Generic.List[string]
                foreach ($n in 1..2) {
                    $script:guiRoClk = [datetime]$gs.NextDueUtc
                    $trs.Add((Invoke-AtmGuiTick -Session $gs -Now $script:guiRoClk -Pump { }))
                }
                Assert-True (($trs.ToArray() -join ',') -ceq 'REFRESHED,REFRESHED' -and (Get-AtmGuiNavTop -Nav $gs.Nav).Name -ceq 'diag' -and $gs.DiagCalls -eq 1 -and $null -eq $gs.FailureType) "sessao da GUI: dois ticks do monitoramento, dois audits; a area fica; nenhum diagnose ($($trs.ToArray() -join ','); $($gs.FailureType))"
                Set-AtmGuiMonitor -Session $gs -On $false -Now $script:guiRoClk
            } finally { $script:AtmGuiClockSource = $savedGuiClock }
            Assert-Eq $gs.SourceCalls 5 'sessao da GUI: cinco auditorias (tres pedidas e duas do monitoramento), nenhuma a mais'
        } finally { $script:AtmGuiInventorySource = $savedGuiSource }
        $after = Get-TreeListing $p.ProfilePath
        $diff = @(Compare-Object ($before -split "`n") ($after -split "`n") | ForEach-Object { $_.SideIndicator + ' ' + ($_.InputObject -replace '^.*\\(Users\d+)', '$1') })
        Assert-Eq $diff.Count 0 ('listagem identica (nomes, tamanhos, mtime, atributos): ' + ($diff -join ' ; '))
        Assert-Eq @($rows | Where-Object { $_.Gate.Category -eq 'ELIGIBLE' }).Count 3 'elegiveis para revisao'
    }

    # ------------------------------------------------------------------ real machine (read-only)
    Test-Case 'Maquina real (somente leitura)' 'Descoberta de perfis pelo Windows (ProfileList, Public, Default, reparse)' {
        $script:AtmDiscoveryNotes = New-Object System.Collections.Generic.List[string]
        $ps = @(Get-AtmProfiles -Identity $me)
        $mine = @($ps | Where-Object { $_.Sid -eq $me.Sid })
        Assert-Eq $mine.Count 1 'perfil atual por SID'
        Assert-True (@($ps | Where-Object { $_.Sid -eq 'S-1-5-18' }).Count -eq 1) 'SYSTEM'
        $pub = @($ps | Where-Object { $_.Sid -eq 'SHARED-PUBLIC' })
        Assert-Eq $pub.Count 1 'Public como compartilhado, sem SID proprio'
        Assert-True (@($ps | Where-Object { $_.ProfilePath -like '*\Public' -and $_.Sid -like 'S-1-5-21-*' }).Count -eq 0) 'Public nao e perfil de usuario'
        Assert-True (@($script:AtmDiscoveryNotes | Where-Object { $_ -like '*reparse*' }).Count -ge 1) 'junctions/symlinks registrados, nao atravessados'
        foreach ($x in $ps) { Write-Host ("   {0,-48} {1,-30} {2}" -f $x.Sid, $x.UserName, $x.ProfilePath) }
    }
    Test-Case 'Maquina real (somente leitura)' 'Inventario real completo nao falha e reporta cobertura' {
        $i = Invoke-AtmInventory -NoProgress -ConfigDir $cfgDir
        Assert-True (@($i.Profiles).Count -ge 2) 'perfis'
        Assert-True ($i.Snapshot.Total -gt 0) 'processos coletados'
        if (-not $me.IsAdmin) { Assert-True (-not $i.CoverageComplete) 'sem elevacao a cobertura e declarada incompleta' }
        $own = @($i.Partitions | Where-Object { $_.Class -eq 'ACTIVE_EVIDENCE' })
        Write-Host ("   particoes={0} ativas={1} bytes={2} inacessiveis={3}" -f @($i.Partitions).Count, $own.Count, (Get-AtmSum $i.Partitions 'Bytes'), (@($i.InaccessibleProfiles | ForEach-Object { $_.UserName }) -join ','))
    }

    # ------------------------------------------------------------------ security review regressions
    Test-Case 'Revisao de seguranca' 'H1: troca por junction durante a exclusao e impossivel (cadeia fixada por handle)' {
        $p = New-TestProfile 'pin'
        $r = New-TestRoot -ProfileInfo $p -Files @{ 'sub\alvo.txt' = 5; 'a.txt' = 1 }
        $victim = Join-Path $sandbox 'vitima-pin'; [void][IO.Directory]::CreateDirectory($victim); [IO.File]::WriteAllText((Join-Path $victim 'alvo.txt'), 'vivo')
        $slugDir = [IO.Path]::GetDirectoryName($r)
        # Control: without pinning the same renames succeed (so the assertion below proves the pin, not something else).
        [IO.Directory]::Move((Join-Path $r 'sub'), (Join-Path $r 'sub-c')); [IO.Directory]::Move((Join-Path $r 'sub-c'), (Join-Path $r 'sub'))
        [IO.Directory]::Move($slugDir, ($slugDir + '-c')); [IO.Directory]::Move(($slugDir + '-c'), $slugDir)
        $script:pinAttempts = @()
        $hook = [Action[string]]{
            param($root)
            foreach ($pair in @(@((Join-Path $root 'sub'), (Join-Path $root 'sub-movido')), @($slugDir, ($slugDir + '-movido')), @((Get-Base $p), ((Get-Base $p) + '-movido')))) {
                try { [IO.Directory]::Move($pair[0], $pair[1]); $script:pinAttempts += "RENOMEOU $($pair[0])" } catch { $script:pinAttempts += 'bloqueado' }
            }
        }
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r, $hook)
        Assert-Eq (@($script:pinAttempts | Where-Object { $_ -ne 'bloqueado' }) -join ';') '' 'nenhuma renomeacao possivel durante a exclusao'
        Assert-True $d.Completed "exclusao concluida ($($d.AbortReason))"
        Assert-True (-not [IO.Directory]::Exists($r)) 'root excluida'
        Assert-True ([IO.File]::Exists((Join-Path $victim 'alvo.txt'))) 'nada fora da arvore foi atingido'
        Assert-True ([IO.Directory]::Exists($slugDir)) 'ancestrais preservados'
    }
    Test-Case 'Revisao de seguranca' 'H1: redirecionamento ja existente no caminho e recusado pelo deleter' {
        $real = Join-Path $sandbox 'real-redir'; [void][IO.Directory]::CreateDirectory((Join-Path $real 'x')); [IO.File]::WriteAllText((Join-Path $real 'x\f.txt'), 'vivo')
        $link = Join-Path $sandbox 'link-redir'
        New-Junction -Link $link -Target $real
        $d = [AgentTempManager.AtmDeleter]::DeleteTree((Join-Path $link 'x'))
        Assert-True (-not $d.Attempted) "recusado: $($d.AbortReason)"
        Assert-True ($d.AbortReason -match 'REPARSE|REDIRECTED') $d.AbortReason
        Assert-True ([IO.File]::Exists((Join-Path $real 'x\f.txt'))) 'alvo intacto'
    }
    Test-Case 'Revisao de seguranca' 'M1: base/projeto com escrita concedida a terceiros bloqueia; %WINDIR%\Temp e compartilhado' {
        $p = New-TestProfile 'aclbase'
        $r = New-TestRoot -ProfileInfo $p
        $b = Get-Base $p
        $null = icacls $b /grant '*S-1-5-32-545:(OI)(CI)(M)' 2>&1
        $i = Inv -Profiles @($p)
        $g = Test-AtmCandidate -Partition (Find-Part $i $r) -Inventory $i
        Assert-Eq $g.Category 'BLOCKED' 'bloqueado'
        Assert-True (($g.Reasons -join ' ') -match 'ESCRITA_CONCEDIDA_A_TERCEIROS') ($g.Reasons -join ';')
        $ps = New-TestProfile 'wintemp'
        $ps.TempCandidates = @([pscustomobject]@{ TempPath = (Join-Path $env:SystemRoot 'Temp'); Source = 'test' })
        $i2 = Inv -Profiles @($ps)
        Assert-True (@($i2.Bases)[0].Shared) 'Windows\Temp marcado como compartilhado'
    }
    Test-Case 'Revisao de seguranca' 'M2: procStart em formato inesperado nunca vira "sessao encerrada"' {
        $p = New-TestProfile 'procstart'
        $r = New-TestRoot -ProfileInfo $p
        $u = Split-Path $r -Leaf
        $ms = [long]([datetime]::UtcNow - [datetime]'1970-01-01').TotalMilliseconds
        [IO.File]::WriteAllText((Join-Path (Join-Path $p.ProfilePath '.claude') 'sessions\910.json'), "{`"pid`":910,`"sessionId`":`"$u`",`"procStart`":`"$ms`"}")
        $procs = New-Procs -Extra @([pscustomobject]@{ ProcessId = 910; Name = 'claude.exe'; ParentProcessId = 1; CommandLine = 'claude'; CreationDate = (Get-Date) })
        $x = Find-Part (Inv -Profiles @($p) -Procs $procs) $r
        Assert-True ($x.Flags -contains 'SESSION_PID_ALIVE_UNVERIFIED') ($x.Flags -join ',')
        Assert-True ($x.Class -ne 'ORPHAN_SUSPECTED') 'nao suspeito de orfao'
    }
    Test-Case 'Revisao de seguranca' 'L1/L2/L4: drill-down e saidas validados; tokens de linha de comando nao sao exibidos' {
        $p = New-TestProfile 'lows'
        $r = New-TestRoot -ProfileInfo $p -Slug 'C--longo-projeto'
        $procs = New-Procs -Extra @([pscustomobject]@{ ProcessId = 920; Name = 'z.exe'; ParentProcessId = 1; CommandLine = "z.exe $(Get-Base $p)\C--LON~1\SEGREDO-TOKEN"; CreationDate = (Get-Date) })
        $i = Inv -Profiles @($p) -Procs $procs
        $x = Find-Part $i $r
        Assert-True (($x.AmbiguousRefs -join ' ') -notmatch 'LON~1|SEGREDO') 'sem fragmentos da linha de comando'
        $out = (Show-AtmPathDetail -Inventory $i -Path ((Get-Base $p) + '\..\..\..\..') 6>&1 | Out-String)
        Assert-True ($out -match 'recusado') 'drill-down com .. recusado'
        $existing = Join-Path $sandbox 'ja-existe.json'; [IO.File]::WriteAllText($existing, '{}')
        Assert-True (-not (Test-AtmOutputPathOutsideBases -Path $existing -Inventory $i -MustNotExist)) 'nao sobrescreve'
        Assert-True (-not (Test-AtmOutputPathOutsideBases -Path (Join-Path (Get-Base $p) 'out.json') -Inventory $i)) 'dentro da base recusado'
        Assert-True (-not (Test-AtmOutputPathOutsideBases -Path ((Get-Base $p) + '\..\x.json') -Inventory $i)) 'caminho nao canonico recusado'
        Assert-True (Test-AtmOutputPathOutsideBases -Path (Join-Path $sandbox 'novo.json') -Inventory $i -MustNotExist) 'caminho valido aceito'
    }

    # ------------------------------------------------------------------ final gate V0.1
    Test-Case 'Gate V0.1' 'Versao distribuida: exclusao real DESABILITADA; clean so valida e mostra o plano' {
        Assert-Eq $shippedDeletionGate $false 'Engine.Clean.ps1 distribuido com $script:AtmRealDeletionEnabled = $false'
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-Eq ([regex]::Matches($clean, '\$script:AtmRealDeletionEnabled\s*=').Count) 1 'uma unica atribuicao (a constante)'
        Assert-True ($clean -match '\$script:AtmRealDeletionEnabled = \$false') 'constante = $false'
        foreach ($f in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Clean.ps1' })) {
            Assert-True (-not ([regex]::IsMatch([IO.File]::ReadAllText($f.FullName), 'AtmRealDeletionEnabled\s*='))) "$($f.Name) nao pode alterar a trava"
        }
        $p = New-TestProfile 'gate01'
        $r = New-TestRoot -ProfileInfo $p
        $before = Get-StableTreeListing $r
        $script:readerCalled = $false
        $script:AtmRealDeletionEnabled = $false
        try {
            $c = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $presenter -ConfirmationReader { param($x) $script:readerCalled = $true; $x } -InventoryArgs (Get-InvArgs -Profiles @($p))
        } finally { $script:AtmRealDeletionEnabled = $true }
        Assert-Eq $c.Aborted 'EXCLUSAO_REAL_DESABILITADA_V0_1' 'abortado pela trava'
        Assert-Eq @($c.Verified).Count 1 'plano validado e exibido'
        Assert-True (-not $script:readerCalled) 'confirmacao nunca solicitada'
        Assert-Eq @($c.Deleted).Count 0 'nada excluido'
        Assert-Eq (Get-StableTreeListing $r) $before 'root intacta'
    }
    Test-Case 'Gate V0.1' 'TOCTOU: plano fixado diferente da medicao validada -> nada e excluido' {
        $p = New-TestProfile 'planmismatch'
        $r = New-TestRoot -ProfileInfo $p
        $s = [AgentTempManager.AtmScanner]::ScanTree($r, 3, 4096)
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r, $s.Files + 1, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $null)
        Assert-True (-not $d.Attempted) 'nao tentou'
        Assert-True ($d.AbortReason -like 'PLAN_DIFFERS_FROM_VALIDATED_MEASUREMENT*') $d.AbortReason
        Assert-True ([IO.File]::Exists((Join-Path $r 'a.txt'))) 'intacto'
        $s = [AgentTempManager.AtmScanner]::ScanTree($r, 3, 4096)
        $hook = [Action[string]]{ param($root) foreach ($f in [IO.Directory]::GetFiles($root, '*', 'AllDirectories')) { [IO.File]::SetLastWriteTimeUtc($f, [datetime]::UtcNow.AddMinutes(-1)) } }
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $hook)
        Assert-Eq $d.AbortReason 'FILE_CHANGED_AFTER_PLANNING' 'arquivo alterado apos o plano'
        Assert-Eq $d.FilesDeleted 0 'nenhum arquivo excluido'
        $s = [AgentTempManager.AtmScanner]::ScanTree($r, 3, 4096)
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $null)
        Assert-True $d.Completed "medicao identica: excluido no sandbox ($($d.AbortReason))"
    }
    Test-Case 'Gate V0.1' 'H1 entre processos: outro processo nao consegue renomear root, projeto ou base durante a exclusao' {
        $p = New-TestProfile 'pinxproc'
        $r = New-TestRoot -ProfileInfo $p -Files @{ 'sub\x.txt' = 3 }
        $slugDir = [IO.Path]::GetDirectoryName($r)
        $script:xprocResults = @()
        $hook = [Action[string]]{
            param($root)
            foreach ($target in @((Join-Path $root 'sub'), $root, $slugDir, (Get-Base $p))) {
                $cmd = "try { Rename-Item -LiteralPath '$($target.Replace("'", "''"))' -NewName 'tomado' -ErrorAction Stop; exit 0 } catch { exit 3 }"
                $pr = Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList @('-NoProfile', '-Command', $cmd) -Wait -PassThru -WindowStyle Hidden
                $script:xprocResults += $pr.ExitCode
            }
        }
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r, $hook)
        Assert-Eq ($script:xprocResults -join ',') '3,3,3,3' 'todas as renomeacoes externas falharam'
        Assert-True $d.Completed "exclusao concluida ($($d.AbortReason))"
        Assert-True ([IO.Directory]::Exists($slugDir)) 'projeto preservado'
    }
    Test-Case 'Gate V0.1' 'Referencias com ":" ou "." colados e nomes nao resolvidos nunca sao ignorados' {
        $p = New-TestProfile 'refterm'
        $r = New-TestRoot -ProfileInfo $p -Slug 'C--proj'
        $r2 = New-TestRoot -ProfileInfo $p -Slug 'C--proj'
        $other = New-TestRoot -ProfileInfo $p -Slug 'C--outro'
        foreach ($cl in @("docker run -v $($r):/work img", "tool --dir=$r.", "x `"$r`".bak")) {
            $procs = New-Procs -Extra @([pscustomobject]@{ ProcessId = 930; Name = 't.exe'; ParentProcessId = 1; CommandLine = $cl; CreationDate = (Get-Date) })
            Assert-Eq (Find-Part (Inv -Profiles @($p) -Procs $procs) $r).Class 'ACTIVE_EVIDENCE' "referencia detectada em: $($cl.Substring(0, 12))..."
        }
        $procs = New-Procs -Extra @([pscustomobject]@{ ProcessId = 931; Name = 't.exe'; ParentProcessId = 1; CommandLine = "t $($r)sufixo\x"; CreationDate = (Get-Date) })
        $i = Inv -Profiles @($p) -Procs $procs
        Assert-True ((Find-Part $i $r2).Flags -contains 'AMBIGUOUS_REFERENCE') 'nome nao resolvido marca todo o projeto'
        Assert-Eq (Test-AtmCandidate -Partition (Find-Part $i $r) -Inventory $i).Category 'INVESTIGATE' 'exige investigacao'
        Assert-Eq (Find-Part $i $other).Class 'ORPHAN_SUSPECTED' 'outro projeto nao afetado'
        $procs = New-Procs -Extra @([pscustomobject]@{ ProcessId = 932; Name = 't.exe'; ParentProcessId = 1; CommandLine = "t $(Get-Base $p)\C--naoexiste\y"; CreationDate = (Get-Date) })
        Assert-True ((Find-Part (Inv -Profiles @($p) -Procs $procs) $other).Flags -contains 'AMBIGUOUS_REFERENCE') 'nao resolvido sob a base marca a base inteira'
    }
    Test-Case 'Gate V0.1' 'Diretorio fixado nao pode ser aberto para escrita (conversao em junction impossivel)' {
        if (-not ('AtmTestOpen' -as [type])) {
            Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; using Microsoft.Win32.SafeHandles; public static class AtmTestOpen { [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern SafeFileHandle CreateFileW(string n, uint a, uint s, IntPtr sa, uint d, uint f, IntPtr t); public static int TryOpenDirForWrite(string p) { using (SafeFileHandle h = CreateFileW(p, 0x0002 | 0x0100, 7, IntPtr.Zero, 3, 0x02000000 | 0x00200000, IntPtr.Zero)) { return h.IsInvalid ? Marshal.GetLastWin32Error() : 0; } } }'
        }
        $p = New-TestProfile 'pinwrite'
        $r = New-TestRoot -ProfileInfo $p -Files @{ 'a.txt' = 1 }
        [void][IO.Directory]::CreateDirectory((Join-Path $r 'vazio'))
        Assert-Eq ([AtmTestOpen]::TryOpenDirForWrite((Join-Path $r 'vazio'))) 0 'controle: sem fixacao a abertura para escrita funciona'
        $script:pinWrite = -1
        $d = [AgentTempManager.AtmDeleter]::DeleteTree($r, [Action[string]]{ param($root) $script:pinWrite = [AtmTestOpen]::TryOpenDirForWrite((Join-Path $root 'vazio')) })
        Assert-Eq $script:pinWrite 32 'durante a exclusao: violacao de compartilhamento (32)'
        Assert-True $d.Completed "exclusao concluida ($($d.AbortReason))"
    }
    Test-Case 'Gate V0.1' 'Preview sempre exibe o motivo do bloqueio, mesmo com evidencias longas' {
        $p = New-TestProfile 'whyshown'
        $r = New-TestRoot -ProfileInfo $p
        $extra = @(1..40 | ForEach-Object { [pscustomobject]@{ ProcessId = 1000 + $_; Name = ('processo-com-nome-longo-' + $_ + '.exe'); ParentProcessId = 1; CommandLine = "x `"$r\sub`""; CreationDate = (Get-Date) } })
        $i = Inv -Profiles @($p) -Procs (New-Procs -Extra $extra)
        $rows = Invoke-AtmPreview -Inventory $i
        $out = (@(Show-AtmPreview -Inventory $i -Rows $rows 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n")
        Assert-True ($out -match [regex]::Escape("[BLOCKED] $r")) 'caminho exibido'
        Assert-True ($out -match 'motivo: classe ACTIVE_EVIDENCE') 'motivo exibido'
        Assert-True ($out -match 'PID 1040') 'evidencias exibidas por completo'
    }
    Test-Case 'Gate V0.1' 'Nenhum script do produto altera politica de execucao' {
        $repo = Split-Path -Parent $testsDir
        foreach ($f in @(Get-ChildItem -LiteralPath $repo -Recurse -File -Include '*.ps1', '*.cmd' | Where-Object { $_.FullName -notmatch '\\(tests|\.git|dist)\\' })) {
            Assert-True (-not ([IO.File]::ReadAllText($f.FullName) -match 'Set-ExecutionPolicy')) "$($f.Name) altera politica"
        }
        $cmdTxt = [IO.File]::ReadAllText((Join-Path $srcDir 'bin\agent-temp.cmd'))
        Assert-True ($cmdTxt -match '-ExecutionPolicy Bypass -File') 'politica apenas no escopo do processo filho'
    }

    # ------------------------------------------------------------------ 0.3.x isolation, phase P1: native primitives (ISO-P1)
    # AtmMover, AtmSafeCreate.CreateNewDirectory and AtmCleanLog.OpenExisting, on sandbox fixtures only (no product caller
    # yet). A destination is a folder created by CreateNewDirectory inside a pinned sandbox folder.
    function New-IsoFixture {
        param([string]$Name, [hashtable]$Files = @{ 'a.txt' = 3; 'sub\b.bin' = 5 })
        $base = Join-Path $sandbox ('iso-' + $Name)
        $root = Join-Path $base 'src\root'
        foreach ($k in $Files.Keys) {
            $f = Join-Path $root $k
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($f))
            [IO.File]::WriteAllBytes($f, (New-Object byte[] $Files[$k]))
        }
        [void][IO.Directory]::CreateDirectory((Join-Path $base 'q'))
        $q = [AgentTempManager.AtmSafeCreate]::Pin((Join-Path $base 'q'))
        $e = [AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'e', (Get-AtmCurrentIdentity).Sid)
        $cleanupActions.Add({ $e.Dispose(); $q.Dispose() }.GetNewClosure())
        return [pscustomobject]@{ Base = $base; Root = $root; Q = $q; E = $e }
    }
    function Get-IsoMeasure {
        param([string]$Root)
        $null = Get-StableTreeListing $Root
        return [AgentTempManager.AtmScanner]::ScanTree($Root, 3, 4096)
    }
    function Invoke-IsoMove {
        param($Fx, [string]$Root, [string]$Name = 'payload', $Hook = $null, $Measure = $null)
        $s = $(if ($null -ne $Measure) { $Measure } else { Get-IsoMeasure $Root })
        return [AgentTempManager.AtmMover]::MoveTree($Root, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $Fx.E, $Name, $Hook)
    }

    Test-Case 'Isolamento P1' 'CreateNewDirectory: diretorio novo pela handle do pai fixado, DACL protegida e herdavel (dono, SYSTEM, Administradores); nome existente, juncao e nome invalido recusados; ACL existente intacta' {
        $base = Join-Path $sandbox 'iso-newdir'
        [void][IO.Directory]::CreateDirectory((Join-Path $base 'q'))
        $before = (Get-Acl -LiteralPath (Join-Path $base 'q')).Sddl
        $sid = (Get-AtmCurrentIdentity).Sid
        $q = [AgentTempManager.AtmSafeCreate]::Pin((Join-Path $base 'q'))
        try {
            Assert-True $q.IsPinned "pasta fixada ($($q.Error))"
            $e = [AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'entrada', $sid)
            try {
                Assert-True ($e.IsPinned -and $null -eq $e.Error) "criado e fixado ($($e.Error))"
                Assert-Eq $e.ParentPath (Join-Path $base 'q\entrada') 'caminho do novo diretorio'
                $sddl = (Get-Acl -LiteralPath (Join-Path $base 'q\entrada')).Sddl
                Assert-True ($sddl.Contains('D:P(A;OICI;FA;;;OW)(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)')) 'DACL protegida, herdavel, so dono, SYSTEM e Administradores'
                # Pinned without FILE_SHARE_DELETE: no one renames it while held.
                $renamed = $true; try { [IO.Directory]::Move((Join-Path $base 'q\entrada'), (Join-Path $base 'q\outra')) } catch { $renamed = $false }
                Assert-True (-not $renamed) 'diretorio fixado nao pode ser renomeado'
            } finally { $e.Dispose() }
            Assert-Eq ([AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'entrada', $sid)).Error 'EXISTS' 'nome existente nunca reutilizado'
            [void][IO.Directory]::CreateDirectory((Join-Path $base 'alvo'))
            New-Junction (Join-Path $base 'q\j') (Join-Path $base 'alvo')
            Assert-Eq ([AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'j', $sid)).Error 'EXISTS' 'juncao com o nome: recusada, nada criado no alvo'
            Assert-Eq @(Get-ChildItem -LiteralPath (Join-Path $base 'alvo') -Force).Count 0 'alvo da juncao intacto'
            Assert-Eq ([AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'CON', $sid)).Error 'DIR_NAME_INVALID' 'nome de dispositivo recusado'
            Assert-Eq ([AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'x', 'nao-sid')).Error 'PROCESS_USER_UNKNOWN' 'usuario do processo obrigatorio'
        } finally { $q.Dispose() }
        Assert-Eq (Get-Acl -LiteralPath (Join-Path $base 'q')).Sddl $before 'ACL da pasta existente inalterada'
    }
    Test-Case 'Isolamento P1' 'OpenExisting: acrescenta a um manifesto existente com as checagens do escritor; ausente, aberto por outro escritor, diretorio e arquivo sem DACL protegida recusados sem escrever' {
        $fx = New-IsoFixture 'openexisting'
        $sid = (Get-AtmCurrentIdentity).Sid
        $dir = $fx.E.ParentPath
        $l = [AgentTempManager.AtmCleanLog]::Pin($dir, $sid)
        try { Assert-Eq $l.Error $null "pasta da entrada aceita ($($l.Error))"; Assert-Eq $l.Create('manifest.jsonl') $null 'manifesto criado'; Assert-Eq $l.AppendLine('{"r":1}') $null 'registro 1'; Assert-Eq $l.Close() $null 'fechado' } finally { $l.Dispose() }
        $l = [AgentTempManager.AtmCleanLog]::Pin($dir, $sid)
        try { Assert-Eq $l.OpenExisting('manifest.jsonl') $null 'reaberto'; Assert-True (-not $l.Created) 'nao foi criado'; Assert-Eq $l.AppendLine('{"r":2}') $null 'registro 2'; Assert-Eq $l.Close() $null 'fechado' } finally { $l.Dispose() }
        Assert-Eq ([IO.File]::ReadAllText((Join-Path $dir 'manifest.jsonl'))) ("{`"r`":1}`n{`"r`":2}`n") 'so acrescimo, na ordem'
        $l = [AgentTempManager.AtmCleanLog]::Pin($dir, $sid)
        try { Assert-Eq $l.OpenExisting('ausente.jsonl') 'NOT_FOUND' 'ausente: nunca criado'; Assert-True (-not [IO.File]::Exists((Join-Path $dir 'ausente.jsonl'))) 'nada criado' } finally { $l.Dispose() }
        $w = [IO.File]::Open((Join-Path $dir 'manifest.jsonl'), 'Open', 'Write', 'ReadWrite')
        try {
            $l = [AgentTempManager.AtmCleanLog]::Pin($dir, $sid)
            try { Assert-Eq $l.OpenExisting('manifest.jsonl') 'IN_USE' 'outro escritor aberto: recusado' } finally { $l.Dispose() }
        } finally { $w.Dispose() }
        [void][IO.Directory]::CreateDirectory((Join-Path $dir 'pasta'))
        $l = [AgentTempManager.AtmCleanLog]::Pin($dir, $sid)
        try { Assert-Eq $l.OpenExisting('pasta') 'NOT_A_FILE' 'diretorio recusado' } finally { $l.Dispose() }
        # A file that inherited the entry's DACL (not protected): refused after opening, nothing written.
        [IO.File]::WriteAllText((Join-Path $dir 'herdado.jsonl'), 'x')
        $l = [AgentTempManager.AtmCleanLog]::Pin($dir, $sid)
        try { Assert-Eq $l.OpenExisting('herdado.jsonl') 'OPENED_DACL_NOT_PROTECTED' 'DACL nao protegida: recusado'; Assert-Eq $l.AppendLine('y') 'LOG_STOPPED' 'nada escrito depois da recusa' } finally { $l.Dispose() }
        Assert-Eq ([IO.File]::ReadAllText((Join-Path $dir 'herdado.jsonl'))) 'x' 'arquivo recusado intacto'
    }
    Test-Case 'Isolamento P1' 'AtmMover: move pelo handle no mesmo volume, medicao conferida antes e depois, nomes Unicode; sem medicao, medicao divergente, destino existente e destino dentro da origem recusados sem mover' {
        $u = [string]::new([char[]]@(0x00E7, 0x00E3, 0x65E5, 0x672C))
        $fx = New-IsoFixture 'move' @{ 'a.txt' = 3; 'sub\b.bin' = 5; "$u\$u.txt" = 7 }
        $listing = { param($p) @((Get-StableTreeListing $p) -split "`n" | ForEach-Object { $_.Substring($p.Length) }) -join "`n" }
        $before = & $listing $fx.Root
        $s = Get-IsoMeasure $fx.Root
        $r = [AgentTempManager.AtmMover]::MoveTree($fx.Root, -1, -1, -1, -1, $fx.E, 'payload', $null)
        Assert-True (-not $r.Attempted -and $r.AbortReason -eq 'NO_VALIDATED_MEASUREMENT') "sem medicao: recusado ($($r.AbortReason))"
        $r = [AgentTempManager.AtmMover]::MoveTree($fx.Root, $s.Files + 1, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $fx.E, 'payload', $null)
        Assert-True (-not $r.Attempted -and $r.AbortReason -like 'PLAN_DIFFERS_FROM_VALIDATED_MEASUREMENT*') "medicao divergente: recusado ($($r.AbortReason))"
        Assert-Eq (& $listing $fx.Root) $before 'origem intacta depois das recusas'
        $r = Invoke-IsoMove $fx $fx.Root -Measure $s
        Assert-True ($r.Attempted -and $r.Moved -and $r.Verified -and $null -eq $r.AbortReason) "movido e verificado ($($r.AbortReason))"
        Assert-True ($r.RenameStatus -eq '0x00000000' -and $r.FilesAfter -eq $s.Files -and $r.BytesAfter -eq $s.Bytes -and $r.DigestAfter -ceq $r.DigestPlanned) 'mesma medicao e mesmo resumo no destino'
        Assert-True (-not [IO.Directory]::Exists($fx.Root)) 'origem nao existe mais'
        $dst = Join-Path $fx.E.ParentPath 'payload'
        Assert-Eq (& $listing $dst) $before 'mesmo conteudo, nomes, tamanhos e horarios no destino'
        # A second tree into the same name: never replaced.
        $root2 = Join-Path $fx.Base 'src\root2'; [void][IO.Directory]::CreateDirectory($root2); [IO.File]::WriteAllText((Join-Path $root2 'x.txt'), 'x')
        $b2 = & $listing $root2
        $r = Invoke-IsoMove $fx $root2
        Assert-True ($r.Attempted -and -not $r.Moved -and $r.AbortReason -eq 'MOVE_DEST_EXISTS') "destino existente ($($r.AbortReason))"
        Assert-True ((& $listing $root2) -eq $b2 -and (& $listing $dst) -eq $before) 'origem e destino intactos'
        # The destination folder inside the source tree.
        $root3 = Join-Path $fx.Base 'src\root3'; [void][IO.Directory]::CreateDirectory((Join-Path $root3 'q')); [IO.File]::WriteAllText((Join-Path $root3 'x.txt'), 'x')
        $q3 = [AgentTempManager.AtmSafeCreate]::Pin((Join-Path $root3 'q'))
        try {
            $s3 = Get-IsoMeasure $root3
            $r = [AgentTempManager.AtmMover]::MoveTree($root3, $s3.Files, $s3.Dirs, $s3.Bytes, $s3.NewestWriteTimeUtc.Ticks, $q3, 'payload', $null)
            Assert-True (-not $r.Attempted -and $r.AbortReason -eq 'DESTINATION_INSIDE_SOURCE') "destino dentro da origem ($($r.AbortReason))"
        } finally { $q3.Dispose() }
    }
    Test-Case 'Isolamento P1' 'AtmMover: pontos de reparse - raiz, interior e ancestral recusados sem mover; juncao trocada na janela e detectada depois do movimento (nada fora da arvore e seguido)' {
        $fx = New-IsoFixture 'reparse'
        $outside = Join-Path $fx.Base 'fora'; [void][IO.Directory]::CreateDirectory($outside); [IO.File]::WriteAllText((Join-Path $outside 'alvo.txt'), 'fora')
        # The root itself is a junction.
        $jr = Join-Path $fx.Base 'src\jroot'; New-Junction $jr $outside
        $r = [AgentTempManager.AtmMover]::MoveTree($jr, 1, 0, 4, 0, $fx.E, 'p1', $null)
        Assert-True (-not $r.Attempted -and $r.AbortReason -eq 'ROOT_REPARSE_POINT') "raiz juncao ($($r.AbortReason))"
        # A junction inside the tree.
        New-Junction (Join-Path $fx.Root 'sub\j') $outside
        $s = Get-IsoMeasure $fx.Root
        $r = [AgentTempManager.AtmMover]::MoveTree($fx.Root, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $fx.E, 'p2', $null)
        Assert-True (-not $r.Attempted -and $r.AbortReason -eq 'REPARSE_POINT_FOUND') "juncao interna ($($r.AbortReason))"
        Assert-True ([IO.Directory]::Exists($fx.Root)) 'origem no lugar'
        # An ancestor is a junction.
        $real = Join-Path $fx.Base 'real'; [void][IO.Directory]::CreateDirectory((Join-Path $real 'arvore')); [IO.File]::WriteAllText((Join-Path $real 'arvore\x.txt'), 'x')
        $via = Join-Path $fx.Base 'via'; New-Junction $via $real
        $r = [AgentTempManager.AtmMover]::MoveTree((Join-Path $via 'arvore'), 1, 0, 1, 0, $fx.E, 'p3', $null)
        Assert-True (-not $r.Attempted -and $r.AbortReason -eq 'ANCESTOR_REPARSE_POINT') "ancestral juncao ($($r.AbortReason))"
        Assert-True ([IO.File]::Exists((Join-Path $real 'arvore\x.txt'))) 'arvore real intacta'
        # Swapped in the window (after the measurement, before the rename): the move happens, the verification refuses it.
        $root2 = Join-Path $fx.Base 'src\root2'; [void][IO.Directory]::CreateDirectory((Join-Path $root2 'a\sub')); [IO.File]::WriteAllText((Join-Path $root2 'a\sub\y.txt'), 'y')
        $hook = [Action[string]]{ param($p) [IO.Directory]::Move((Join-Path $p 'a\sub'), (Join-Path $p 'a\sub-antes')); $o = cmd /c mklink /J "`"$(Join-Path $p 'a\sub')`"" "`"$outside`"" 2>&1; $null = $o }.GetNewClosure()
        $r = Invoke-IsoMove $fx $root2 -Name 'p4' -Hook $hook
        $movedLink = Join-Path $fx.E.ParentPath 'p4\a\sub'
        $cleanupActions.Add([scriptblock]::Create("try { [IO.Directory]::Delete('$($movedLink.Replace("'", "''"))', `$false) } catch { }"))
        Assert-True ($r.Moved -and -not $r.Verified -and $r.AbortReason -eq 'VERIFY_REPARSE_POINT_FOUND') "troca na janela detectada depois ($($r.AbortReason))"
        Assert-True ([IO.File]::ReadAllText((Join-Path $outside 'alvo.txt')) -eq 'fora' -and @(Get-ChildItem -LiteralPath $outside -Force).Count -eq 1) 'nada fora da arvore foi seguido ou alterado'
    }
    Test-Case 'Isolamento P1' 'AtmMover: entradas abertas dentro da arvore (medicao do limite): ou recusado sem mover, ou movido e verificado; o resultado de cada caso e registrado' {
        $outcomes = New-Object System.Collections.Generic.List[string]
        $cases = @(
            @{ Label = 'arquivo exclusivo'; Open = { param($root) [IO.File]::Open((Join-Path $root 'sub\b.bin'), 'Open', 'ReadWrite', 'None') } },
            @{ Label = 'arquivo compartilhado (ReadWrite|Delete)'; Open = { param($root) [IO.File]::Open((Join-Path $root 'sub\b.bin'), 'Open', 'Read', ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)) } },
            @{ Label = 'diretorio corrente de processo'; Open = { param($root) Start-AtmTestHelperProcess -File "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Arguments '-NoProfile -Command Start-Sleep 60' -WorkingDirectory (Join-Path $root 'sub') } }
        )
        $n = 0
        foreach ($c in $cases) {
            $n++
            $fx = New-IsoFixture ('inuse' + $n)
            $before = Get-StableTreeListing $fx.Root
            $s = Get-IsoMeasure $fx.Root
            $h = & $c.Open $fx.Root
            if ($h -is [Diagnostics.Process]) { $cleanupActions.Add({ Stop-AtmTestHelperProcess -Process $h }.GetNewClosure()); Start-Sleep -Milliseconds 1500 }
            try { $r = Invoke-IsoMove $fx $fx.Root -Measure $s }
            finally { if ($h -is [Diagnostics.Process]) { Stop-AtmTestHelperProcess -Process $h } else { $h.Dispose() } }
            if ($r.Moved) { Assert-True $r.Verified "$($c.Label): movido e verificado ($($r.AbortReason))"; $outcomes.Add("$($c.Label): MOVED") }
            else {
                Assert-True ($r.AbortReason -like 'MOVE_*' -or $r.AbortReason -like 'ROOT_*') "$($c.Label): recusado com codigo ($($r.AbortReason))"
                Assert-Eq (Get-StableTreeListing $fx.Root) $before "$($c.Label): origem intacta"
                $outcomes.Add("$($c.Label): $($r.AbortReason) $($r.RenameStatus)")
            }
        }
        $os = [Environment]::OSVersion.Version.ToString(); $arch = $env:PROCESSOR_ARCHITECTURE
        $script:caseNote = "medido ($os $arch, $($PSVersionTable.PSEdition)): " + ($outcomes -join '; ')
    }
    Test-Case 'Isolamento P1' 'AtmMover: caminho que passaria do limite classico so por causa do destino e recusado antes de mover; abaixo do limite move' {
        $base = Join-Path $sandbox 'iso-long'
        $root = Join-Path $base 's'
        [void][IO.Directory]::CreateDirectory((Join-Path $base 'q'))
        $q = [AgentTempManager.AtmSafeCreate]::Pin((Join-Path $base 'q'))
        $e = [AgentTempManager.AtmSafeCreate]::CreateNewDirectory($q, 'entrada-com-nome-mais-longo', (Get-AtmCurrentIdentity).Sid)
        try {
            $growth = ($e.ParentPath + '\payload').Length - $root.Length
            Assert-True ($growth -gt 0) 'o destino alonga os caminhos'
            # The longest file path at the source is 259 (below the classic limit); after the move it would pass it.
            $need = 259 - ($root.Length + 1)
            $rel = ''
            # Directory parts of 50 characters; the file name keeps 60 to 110, so every folder stays below 248 characters.
            while ($need - $rel.Length -gt 110) { $rel += ('d' * 50) + '\' }
            $rel += ('f' * ($need - $rel.Length))
            $file = Join-Path $root $rel
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file)); [IO.File]::WriteAllText($file, 'x')
            Assert-Eq $file.Length 259 'caminho de teste com 259 caracteres'
            $s = Get-IsoMeasure $root
            $r = [AgentTempManager.AtmMover]::MoveTree($root, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $e, 'payload', $null)
            Assert-True (-not $r.Attempted -and $r.AbortReason -like 'PATH_TOO_LONG_AFTER_MOVE*' -and $r.MaxPathPlanned -eq 259) "recusado antes ($($r.AbortReason))"
            Assert-True ([IO.File]::Exists($file)) 'origem intacta'
            # Shortened below the limit: moved and verified.
            $short = Join-Path $base 't'; [void][IO.Directory]::CreateDirectory((Join-Path $short 'dd')); [IO.File]::WriteAllText((Join-Path $short 'dd\f.txt'), 'x')
            $s = Get-IsoMeasure $short
            $r = [AgentTempManager.AtmMover]::MoveTree($short, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $e, 'payload', $null)
            Assert-True ($r.Moved -and $r.Verified) "abaixo do limite: movido ($($r.AbortReason))"
        } finally { $e.Dispose(); $q.Dispose() }
        $script:caseNote = 'origem ja com caminho >= 260: NAO_TESTADO (o Windows PowerShell 5.1 nao enumera; a regra so aceita quando a origem ja provou)'
    }
    Test-Case 'Isolamento P1' 'AtmMover: outro volume recusado antes do rename (runner com segundo volume fixo)' {
        $fx = New-IsoFixture 'xvol'
        $other = $null
        $sysDrive = [IO.Path]::GetPathRoot($fx.Root)
        if ($env:GITHUB_ACTIONS -eq 'true' -and $env:RUNNER_TEMP -and -not [string]::Equals([IO.Path]::GetPathRoot($env:RUNNER_TEMP), $sysDrive, [StringComparison]::OrdinalIgnoreCase)) { $other = Join-Path $env:RUNNER_TEMP ('atm-tests-xvol-' + [guid]::NewGuid().ToString('N').Substring(0, 8)) }
        if (-not $other) { $script:caseSkipped = $true; $script:caseNote = 'sem segundo volume fixo disponivel (fora da CI, ou runner com um volume so)'; return }
        [void][IO.Directory]::CreateDirectory($other)
        $q = [AgentTempManager.AtmSafeCreate]::Pin($other)
        try {
            if (-not $q.IsPinned) { $script:caseSkipped = $true; $script:caseNote = "segundo volume nao fixavel ($($q.Error))"; return }
            $before = Get-StableTreeListing $fx.Root
            $s = Get-IsoMeasure $fx.Root
            $r = [AgentTempManager.AtmMover]::MoveTree($fx.Root, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $q, 'payload', $null)
            Assert-True (-not $r.Attempted -and $r.AbortReason -eq 'OTHER_VOLUME') "outro volume ($($r.AbortReason))"
            Assert-Eq (Get-StableTreeListing $fx.Root) $before 'origem intacta'
            Assert-True (-not [IO.Directory]::Exists((Join-Path $other 'payload'))) 'nada no outro volume'
        } finally { $q.Dispose() }
    }
    Test-Case 'Isolamento P1' 'Estatico: primitivas chamadas so pelo motor de isolamento (P3a: uma unica chamada ao mover); o mover nunca copia, substitui, exclui, altera ACL/dono nem encerra processo; rename so pelo handle com ReplaceIfExists falso; NtSetInformationFile so no mover' {
        $ncs = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Native.cs'))
        $mv = $ncs.Substring($ncs.IndexOf('public static class AtmMover'))
        $mv = $mv.Substring(0, $mv.IndexOf('public sealed class AtmJobResult'))
        foreach ($pat in @('DeleteFile', 'DeleteTree', 'Dispose(fh)', 'FileDispositionInfo', 'DELETE_ON_CLOSE', 'CopyFile', 'MoveFileEx', 'File.Copy', 'File.Move', 'Directory.Move', 'SetSecurityInfo', 'SetNamedSecurityInfo', 'SetFileAttributes', 'TerminateProcess', 'OpenProcess', 'AdjustTokenPrivileges')) { Assert-True (-not $mv.Contains($pat)) "mover nao usa $pat" }
        Assert-True ($mv.Contains('for (int i = 0; i < size; i++) Marshal.WriteByte(buf, i, 0);   // ReplaceIfExists = FALSE') -and $mv.Contains('int st = NtSetInformationFile(rh, out io, buf, (uint)size, FileRenameInformation);') -and $mv.Contains('const int FileRenameInformation = 10;')) 'rename pelo handle da raiz, sem substituir'
        Assert-True ($mv.Contains('if (rinfo.VolumeSerialNumber != destination.VolumeSerial) { r.AbortReason = "OTHER_VOLUME"; return r; }') -and $mv.IndexOf('"OTHER_VOLUME"') -lt $mv.IndexOf('NtSetInformationFile(rh')) 'mesmo volume conferido antes do rename'
        Assert-True ($mv.IndexOf('PLAN_DIFFERS_FROM_VALIDATED_MEASUREMENT') -lt $mv.IndexOf('NtSetInformationFile(rh') -and $mv.Contains('"NO_VALIDATED_MEASUREMENT"')) 'medicao obrigatoria e conferida antes do rename'
        Assert-Eq ([regex]::Matches($ncs, 'extern int NtSetInformationFile\(').Count) 1 'NtSetInformationFile declarado uma vez'
        Assert-True ($ncs.IndexOf('extern int NtSetInformationFile(') -gt $ncs.IndexOf('public static class AtmMover') -and $ncs.IndexOf('extern int NtSetInformationFile(') -lt $ncs.IndexOf('public sealed class AtmJobResult')) 'NtSetInformationFile so dentro do mover'
        $nd = $ncs.Substring($ncs.IndexOf('public static AtmSafeCreateSession CreateNewDirectory'))
        $nd = $nd.Substring(0, $nd.IndexOf('public static bool ValidName'))
        Assert-True ($nd.Contains('FILE_SHARE_READ | FILE_SHARE_WRITE, FILE_CREATE, FILE_DIRECTORY_FILE | FILE_SYNCHRONOUS_IO_NONALERT | FILE_OPEN_REPARSE_POINT') -and $nd.Contains('OBJ_CASE_INSENSITIVE | OBJ_DONT_REPARSE') -and $nd.Contains('"D:P(A;OICI;FA;;;OW)(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)"') -and -not $nd.Contains('SetSecurityInfo')) 'diretorio novo relativo ao pai, sem seguir reparse, DACL so do objeto novo'
        $oe = $ncs.Substring($ncs.IndexOf('public string OpenExisting('))
        $oe = $oe.Substring(0, $oe.IndexOf('internal static string CheckNewFolderSecurity'))
        Assert-True ($oe.Contains('FILE_APPEND_DATA | FILE_READ_ATTRIBUTES | READ_CONTROL | SYNCHRONIZE, ref oa') -and $oe.Contains('FILE_SHARE_READ, FILE_OPEN,') -and -not $oe.Contains('FILE_CREATE') -and -not $oe.Contains('FILE_WRITE_DATA')) 'abre so existente, so acrescimo, compartilhado so para leitura'
        # -Include is ignored with -LiteralPath on Windows PowerShell 5.1: filtered by extension.
        # P3a: the isolation engine is the only product caller. P3b: two calls to the mover (isolate, and restore: the move back
        # is the same mover, on the same volume); OpenExisting only to reopen an entry's manifest (isolate, restore and, since
        # P4, purge).
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd') -and $_.Name -ne 'Engine.Isolate.ps1' })) {
            $t = [IO.File]::ReadAllText($fi.FullName)
            # V0.5 M1: the monitoring engine creates its history folder with CreateNewDirectory too (past its own gate,
            # Open-AtmMonitorFolder only: the V0.5 M1 statics); the mover and OpenExisting stay the isolation engine's.
            foreach ($api in @('AtmMover', 'CreateNewDirectory', 'OpenExisting')) { if ($api -ceq 'CreateNewDirectory' -and $fi.Name -ceq 'Engine.Monitor.ps1') { continue }; Assert-True (-not $t.Contains($api)) "$($fi.Name) nao chama $api (so o motor de isolamento)" }
        }
        $isoSrc = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        Assert-Eq ([regex]::Matches($isoSrc, '\[AgentTempManager\.AtmMover\]::MoveTree\(').Count) 2 'duas chamadas de produto ao mover: isolar e restaurar (P3b)'
        Assert-Eq ([regex]::Matches($isoSrc, 'OpenExisting\(').Count) 3 'OpenExisting so para reabrir o manifesto de uma entrada (isolar, restaurar e expurgar)'
        Assert-True ($isoSrc.Contains("`$man.OpenExisting('manifest.jsonl')") -and $isoSrc.IndexOf('$man.Close(); $man.Dispose(); $man = $null') -lt $isoSrc.IndexOf('[AgentTempManager.AtmMover]::MoveTree(') -and $isoSrc.IndexOf("`$man.OpenExisting('manifest.jsonl')") -gt $isoSrc.IndexOf('[AgentTempManager.AtmMover]::MoveTree(')) 'manifesto fechado antes do mover e reaberto depois (o pino da pasta impediria a renomeacao para dentro dela)'
    }

    # ------------------------------------------------------------------ 0.3.x isolation, phase P2: plan-only engine and gate (ISO-P2)
    # The isolation gate stays $false in this process except inside the one case that flips it (and restores it).
    function New-IsoPlanRecorder {
        $st = @{ Calls = (New-Object System.Collections.Generic.List[object]) }
        $st.Presenter = { param($v, $r, $i, $planId) $st.Calls.Add([pscustomobject]@{ Verified = @($v); Rejected = @($r); PlanId = $planId }) }.GetNewClosure()
        return $st
    }
    function Get-IsoRejectedReason { param($Result, [string]$Path) return (@(@($Result.Rejected) | Where-Object { $_.Path -eq $Path } | ForEach-Object { @($_.Reasons) }) -join ' ; ') }

    Test-Case 'Isolamento P2' 'Trava do isolamento: uma unica atribuicao a $false na fonte, conferida pelo build, pelo e2e da instalacao e mostrada em version; nenhum outro arquivo a altera; o motor e obrigatorio e carregado pelo lancador' {
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        Assert-Eq ([regex]::Matches($iso, '\$script:AtmIsolationEnabled\s*=').Count) 1 'uma unica atribuicao no motor'
        Assert-True ($iso -match '(?m)^\$script:AtmIsolationEnabled = \$false\r?$') 'a trava distribuida e $false (linha inteira)'
        Assert-Eq $script:AtmIsolationEnabled $false 'trava fechada neste processo'
        foreach ($f in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Isolate.ps1' })) {
            Assert-True (-not ([regex]::IsMatch([IO.File]::ReadAllText($f.FullName), 'AtmIsolationEnabled\s*='))) "$($f.Name) nao pode alterar a trava"
        }
        $root = Split-Path -Parent $testsDir
        $br = [IO.File]::ReadAllText((Join-Path $root 'tools\Build-Release.ps1'))
        Assert-True ($br.Contains("`$isoTxt = & `$read 'src/lib/Engine.Isolate.ps1'") -and $br.Contains("@(`$isoTxt, 'AtmIsolationEnabled')")) 'build recusa o pacote sem a trava fechada (atribuicao unica)'
        $e2e = [IO.File]::ReadAllText((Join-Path $testsDir 'e2e\Invoke-InstallE2E.ps1'))
        Assert-True ($e2e.Contains("AtmIsolationEnabled = 'lib\Engine.Isolate.ps1'") -and $e2e.Contains("Step 'shipped-isolation-gate'")) 'e2e confere a trava instalada'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.Contains("Get-AtmText 'cli.isolation' `$(if (`$script:AtmIsolationEnabled)") -and $cli.Contains("'lib\Engine.Isolate.ps1'") -and $cli.Contains(". (Join-Path `$here 'lib\Engine.Isolate.ps1')")) 'version mostra a trava; o lancador lista e carrega o motor'
        Assert-True ($script:AtmRequiredFiles -contains 'lib\Engine.Isolate.ps1') 'motor de isolamento obrigatorio na instalacao'
        Assert-Eq (Get-AtmText 'cli.isolation' 'X') 'isolamento: X' 'texto de version (pt-BR)'
    }
    Test-Case 'Isolamento P2' 'Plano com a trava fechada: raiz de sessao elegivel do proprio perfil aprovada e mostrada com plan id; nada perguntado, nenhum lock, nenhum log, nada criado, movido ou removido' {
        $p = New-TestProfile 'isoplan'
        $r = New-TestRoot -ProfileInfo $p
        $before = Get-StableTreeListing $p.ProfilePath
        $rec = New-IsoPlanRecorder
        $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $rec.Presenter -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-Eq $res.Aborted 'ISOLAMENTO_REAL_DESABILITADO' 'parado pela trava'
        Assert-True (@($res.Verified).Count -eq 1 -and $res.Verified[0].Path -eq $r) "raiz aprovada ($(Get-IsoRejectedReason $res $r))"
        Assert-True ($rec.Calls.Count -eq 1 -and $rec.Calls[0].PlanId -match '^[0-9a-f]{64}$' -and $rec.Calls[0].PlanId -eq $res.PlanId) 'plano apresentado uma vez, com o plan id'
        Assert-Eq (Get-StableTreeListing $p.ProfilePath) $before 'perfil identico: nada criado, movido ou removido'
        # P3a: the flow past the gate exists, and none of it is reached with the gate closed. Behavioural: the lock is held
        # by another process (a run that took it would refuse BUSY), the reader counts its calls, and neither the log nor
        # the quarantine appears.
        $qSaved = $script:AtmIsolationQuarantineRoot
        $script:AtmIsolationQuarantineRoot = Join-Path $sandbox 'iso-p2-closed\AgentTempManager\Q'
        [void][IO.Directory]::CreateDirectory((Join-Path $sandbox 'iso-p2-closed'))
        $log = Join-Path $sandbox 'iso-p2-closed\run.jsonl'
        $script:isoReaderCalls = 0
        $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
        try {
            Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
            $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter (New-IsoPlanRecorder).Presenter -ConfirmationReader { param($x) $script:isoReaderCalls++; $x } -InventoryArgs (Get-InvArgs -Profiles @($p)) -LogFile $log -MoveTreeImpl { param($c, $e, $n) throw 'nunca' }
        } finally { $null = Stop-TestLockHolderByGo $h; $script:AtmIsolationQuarantineRoot = $qSaved }
        Assert-Eq $res.Aborted 'ISOLAMENTO_REAL_DESABILITADO' 'trava fechada: so o plano, sem tentar o lock'
        Assert-True ($script:isoReaderCalls -eq 0 -and -not (Test-Path -LiteralPath $log) -and -not (Test-Path -LiteralPath (Join-Path $sandbox 'iso-p2-closed\AgentTempManager')) -and @($res.Results).Count -eq 0) 'nada perguntado; nenhum log; nenhuma quarentena; mover nunca chamado'
        Assert-Eq (Get-StableTreeListing $p.ProfilePath) $before 'raiz intacta'
        # Static: the gate is checked before the lock, and the plan-only return comes before every step that acts.
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        $w = $iso.Substring($iso.IndexOf('function Invoke-AtmIsolate {'), $iso.IndexOf('function Invoke-AtmIsolateCore') - $iso.IndexOf('function Invoke-AtmIsolate {'))
        Assert-True ($w.IndexOf('if (-not $script:AtmIsolationEnabled) { return (Invoke-AtmIsolateCore @PSBoundParameters) }') -gt 0 -and $w.IndexOf('if (-not $script:AtmIsolationEnabled)') -lt $w.IndexOf('Invoke-AtmUnderSharedLock') -and -not $w.Contains('Invoke-AtmInventory')) 'trava antes do lock; nenhum inventario antes do lock'
        $core = $iso.Substring($iso.IndexOf('function Invoke-AtmIsolateCore'))
        $iStop = $core.IndexOf("if (-not `$script:AtmIsolationEnabled) { `$state.Aborted = 'ISOLAMENTO_REAL_DESABILITADO'; return (& `$finish) }")
        Assert-True ($iStop -gt 0) 'parada da trava no nucleo'
        foreach ($act in @('& $ConfirmationReader', 'Open-AtmCleanLog', 'Open-AtmQuarantine -Path', '::CreateNewDirectory(', '[AgentTempManager.AtmMover]::MoveTree(', '& $MoveTreeImpl', 'Get-AtmEngineConsoleObservation')) { Assert-True ($core.IndexOf($act) -gt $iStop) "'$act' so depois da parada da trava" }
        foreach ($pat in @('Remove-Item', 'Move-Item', '::Delete(', 'Write-Host', 'Read-Host')) { Assert-True (-not $iso.Contains($pat)) "motor de isolamento nao contem '$pat'" }
        # P4: the deleter only in the purge (one product call, in Invoke-AtmPurgeCore); never in isolate or restore.
        Assert-Eq ([regex]::Matches($iso, 'AtmDeleter').Count) 1 'o motor de isolamento so referencia o deleter na chamada do expurgo'
        Assert-True ($core.Substring(0, $core.IndexOf('function Invoke-AtmPurgeCore')).IndexOf('AtmDeleter') -lt 0) 'isolar e restaurar nunca chamam o deleter'
    }
    Test-Case 'Isolamento P2' 'Regra de alvo da 0.3.x: escopo e base inteira recusados com codigo proprio (J-ISO-9 a); outro perfil, alvo que nao e raiz de sessao, caixa divergente, duplicado, sintaxe e caminho fora do inventario recusados; RECENT bloqueia (J-ISO-3 a); fingerprint divergente recusado' {
        $p = New-TestProfile 'isotarget'
        $r = New-TestRoot -ProfileInfo $p
        $scope = [IO.Path]::GetDirectoryName($r)
        $base = Get-Base $p
        $odd = Join-Path $scope 'nao-e-uma-sessao'; [void][IO.Directory]::CreateDirectory($odd); [IO.File]::WriteAllText((Join-Path $odd 'x.txt'), 'x')
        $p2 = New-TestProfile 'isooutro' -Sid 'S-1-5-21-1-2-3-4444'
        $r2 = New-TestRoot -ProfileInfo $p2
        $ia = Get-InvArgs -Profiles @($p, $p2)
        $paths = @($scope, $base, $r2, $odd, $r, $r, 'relativo\x', (Join-Path $sandbox 'nao-inventariado'))
        # F05-OWNER-ATTRIBUTION: the other profile's base is attributed to it only as its owner (dubbed, no ACL change).
        Set-TestBaseOwner @{ (Get-Base $p2) = $p2.Sid }
        try { $res = Invoke-AtmIsolate -Entries @($paths | ForEach-Object { [pscustomobject]@{ Source = 't'; Path = $_; Fingerprint = $null } }) -PlanPresenter (New-IsoPlanRecorder).Presenter -InventoryArgs $ia } finally { $script:AtmBaseOwnerSource = $null }
        Assert-True ((Get-IsoRejectedReason $res $scope) -match '^ISOLAMENTO_ESCOPO_NAO_LIBERADO_0_3X') "escopo ($(Get-IsoRejectedReason $res $scope))"
        Assert-True ((Get-IsoRejectedReason $res $base) -match '^ISOLAMENTO_BASE_NAO_LIBERADA_0_3X') "base ($(Get-IsoRejectedReason $res $base))"
        Assert-True ((Get-IsoRejectedReason $res $r2) -match 'ALVO_FORA_DO_PROPRIO_PERFIL') "outro perfil ($(Get-IsoRejectedReason $res $r2))"
        Assert-True ((Get-IsoRejectedReason $res $odd) -match 'ALVO_NAO_ISOLAVEL_0_3X \(UnrecognizedDir\)') "nao e raiz de sessao ($(Get-IsoRejectedReason $res $odd))"
        Assert-True ((Get-IsoRejectedReason $res $r) -match 'DUPLICADO_NA_ALLOWLIST') 'duplicado recusado'
        Assert-True ((Get-IsoRejectedReason $res 'relativo\x') -match 'NOT_ABSOLUTE_LOCAL_PATH') 'sintaxe recusada'
        Assert-True ((Get-IsoRejectedReason $res (Join-Path $sandbox 'nao-inventariado')) -match '^FORA_DAS_ROOTS_PERMITIDAS') 'fora do inventario recusado'
        Assert-True (@($res.Verified).Count -eq 1 -and $res.Verified[0].Path -eq $r -and $res.Aborted -eq 'ISOLAMENTO_REAL_DESABILITADO') 'so a raiz de sessao exata do proprio perfil passa'
        # RECENT: the same root seen now (not ten days later) is recent and blocked.
        $iaNow = Get-InvArgs -Profiles @($p); $iaNow['NowUtc'] = [datetime]::UtcNow
        $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter (New-IsoPlanRecorder).Presenter -InventoryArgs $iaNow
        Assert-True ($res.Aborted -eq 'NENHUM_CAMINHO_ISOLAVEL' -and (Get-IsoRejectedReason $res $r) -match 'RECENT') "RECENT bloqueia ($(Get-IsoRejectedReason $res $r))"
        $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = 'diferente' }) -PlanPresenter (New-IsoPlanRecorder).Presenter -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-True ((Get-IsoRejectedReason $res $r) -match 'ALTERADO_DESDE_O_PREVIEW') 'fingerprint divergente recusado'
        # The exact case of the inventoried path is required (the same rule as clean).
        $last = Split-Path -Leaf $r; $upper = (Split-Path -Parent $r) + '\' + $last.ToUpperInvariant()
        $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $upper; Fingerprint = $null }) -PlanPresenter (New-IsoPlanRecorder).Presenter -InventoryArgs (Get-InvArgs -Profiles @($p))
        Assert-True ((Get-IsoRejectedReason $res $upper) -match 'CAIXA_DIVERGENTE') "caixa divergente ($(Get-IsoRejectedReason $res $upper))"
    }
    Test-Case 'Isolamento P2' 'Excecao B1 por raiz (J-ISO-2 b): com a trava fechada a raiz sob B1 e recusada mesmo com -AcceptB1ResidualRisk; alem da trava (so no processo da suite) entra no plano como risco declarado; sem leitor de confirmacao a execucao para depois do plano, nada movido' {
        $ctx = New-TestB1Context 'isob1'
        $r = $ctx.F.Roots[0]
        $before = Get-StableTreeListing $r
        $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter (New-IsoPlanRecorder).Presenter -InventoryArgs $ctx.IA -AcceptB1ResidualRisk
        Assert-True ($res.Aborted -eq 'NENHUM_CAMINHO_ISOLAVEL' -and (Get-IsoRejectedReason $res $r) -match 'COBERTURA_DE_PROCESSOS_INCOMPLETA') "trava fechada: B1 recusa ($(Get-IsoRejectedReason $res $r))"
        $rec = New-IsoPlanRecorder
        $script:AtmIsolationEnabled = $true
        try { $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $r; Fingerprint = $null }) -PlanPresenter $rec.Presenter -InventoryArgs $ctx.IA -AcceptB1ResidualRisk }
        finally { $script:AtmIsolationEnabled = $false }
        Assert-True ($res.Aborted -eq 'SEM_APRESENTACAO_OU_CONFIRMACAO' -and @($res.Verified).Count -eq 1 -and @($res.Results).Count -eq 0) "alem da trava: plano com a raiz sob B1, depois parado ($($res.Aborted); $(Get-IsoRejectedReason $res $r))"
        Assert-True ($rec.Calls.Count -eq 1 -and $rec.Calls[0].PlanId -match '^[0-9a-f]{64}$') 'plano apresentado com plan id'
        Assert-Eq (Get-StableTreeListing $r) $before 'raiz intacta'
        Assert-Eq $script:AtmIsolationEnabled $false 'trava restaurada'
    }
    Test-Case 'Isolamento P2' 'CLI isolate (processo filho, origem): sem -Path sai com 2; -IncludeOtherUsers sai com 2; caminho fora do inventario: plano, resultado e saida 3, -LogFile nunca criado, nada criado no caminho pedido' {
        $shell = (Get-Process -Id $PID).Path
        $cli = Join-Path $srcDir 'agent-temp.ps1'
        $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$cli`" isolate -Lang en-US -NoProgress") -TimeoutSec 180
        Assert-True ($r.Exit -eq 2 -and $r.Text.Contains('isolate requires -Path')) "sem -Path: exit $($r.Exit)"
        $target = Join-Path $sandbox 'iso-cli-alvo'
        $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$cli`" isolate -Path `"$target`" -IncludeOtherUsers -Lang en-US -NoProgress") -TimeoutSec 180
        Assert-True ($r.Exit -eq 2 -and $r.Text.Contains('-IncludeOtherUsers is not accepted')) "-IncludeOtherUsers: exit $($r.Exit)"
        $log = Join-Path $sandbox 'iso-cli-log.jsonl'
        $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$cli`" isolate -Path `"$target`" -LogFile `"$log`" -Lang en-US -NoProgress") -TimeoutSec 300
        Assert-True ($r.Exit -eq 3 -and $r.Text.Contains('NENHUM_CAMINHO_ISOLAVEL') -and $r.Text.Contains('Nothing was moved, created or removed.')) "fora do inventario: exit $($r.Exit)"
        Assert-True (-not (Test-Path -LiteralPath $target) -and -not (Test-Path -LiteralPath $log)) 'nada criado: nem o caminho pedido nem o log'
    }
    Test-Case 'Isolamento P2' 'Camadas: relatorio e TUI nunca chamam o mover nem o deleter; so o motor de isolamento referencia o mover (P3a); so o lancador e a TUI (P3b, acao padrao sobre uma raiz) chamam o motor de isolamento' {
        foreach ($f in @('Report.ps1', 'Tui.ps1')) {
            $txt = [IO.File]::ReadAllText((Join-Path $srcDir "lib\$f"))
            foreach ($pat in @('AtmMover', 'MoveTree', 'AtmDeleter', 'DeleteTree')) { Assert-True (-not $txt.Contains($pat)) "$f contem '$pat'" }
        }
        $calls = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd') })) {
            $t = [IO.File]::ReadAllText($fi.FullName)
            if ($fi.Name -ne 'Engine.Isolate.ps1') { Assert-True (-not $t.Contains('AtmMover')) "$($fi.Name) nao chama o mover (so o motor de isolamento)" }
            if ($fi.Name -ne 'Engine.Isolate.ps1' -and $t.Contains('Invoke-AtmIsolate')) { $calls += $fi.Name }
        }
        Assert-Eq (($calls | Sort-Object) -join ',') 'agent-temp.ps1,Tui.ps1' 'so o lancador e a TUI chamam o motor de isolamento'
        Assert-Eq ([regex]::Matches([IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1')), 'Invoke-AtmIsolate ').Count) 1 'uma unica chamada no lancador'
    }

    # ------------------------------------------------------------------ 0.3.x isolation, phase P3a: isolate past the gate (ISO-P3a)
    # The isolation gate is opened only around each call (Invoke-IsoOpen) and restored; the quarantine is the sandbox folder
    # set at the top; the log folder follows the T1 folder policy (NAO_TESTADO where the sandbox cannot get it).
    function New-IsoRun {
        param([string]$Name, $Context = $null)
        $dir = New-TestCleanLogDir ('iso-' + $Name)
        if (-not $dir) { return $null }
        [void][IO.Directory]::CreateDirectory((Join-Path $sandbox 'quarantine-home'))
        if ($null -ne $Context) { $run = [pscustomobject]@{ Profile = $Context.F.Profile; Root = $Context.F.Roots[0]; Log = (Join-Path $dir 'isolate.jsonl'); IA = $Context.IA } }
        else {
            $p = New-TestProfile $Name
            $run = [pscustomobject]@{ Profile = $p; Root = (New-TestRoot -ProfileInfo $p); Log = (Join-Path $dir 'isolate.jsonl'); IA = (Get-InvArgs -Profiles @($p)) }
        }
        # Every run compares exact measurements several times: NTFS updates directory times lazily after recent creations.
        $null = Get-StableTreeListing $run.Profile.ProfilePath
        return $run
    }
    function Invoke-IsoOpen {
        param([hashtable]$Arguments)
        # Past the gate the quarantine must be the sandbox's (never the runner's or a developer's %LOCALAPPDATA%).
        Assert-True ([string]$script:AtmIsolationQuarantineRoot -and ([string]$script:AtmIsolationQuarantineRoot).StartsWith($sandbox + '\', [StringComparison]::OrdinalIgnoreCase)) "quarentena dentro do sandbox ($($script:AtmIsolationQuarantineRoot))"
        $script:AtmIsolationEnabled = $true
        try { return (Invoke-AtmIsolate @Arguments) } finally { $script:AtmIsolationEnabled = $false }
    }
    function Get-IsoLiveLastType {
        # The type of the last record of a log or manifest still held open by its writer (read with write sharing).
        param([string]$Path)
        $fs = [IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite')
        try { $txt = (New-Object IO.StreamReader($fs, (New-Object Text.UTF8Encoding($false)))).ReadToEnd() } finally { $fs.Dispose() }
        $lines = @($txt.Split([char]10) | Where-Object { $_ -ne '' })
        return ($lines[$lines.Count - 1] | ConvertFrom-Json).type
    }
    function Get-IsoRelativeListing { param([string]$Path) return (@((Get-StableTreeListing $Path) -split "`n" | ForEach-Object { $_.Substring($Path.Length) }) -join "`n") }
    function Get-IsoEntryCount { $q = $script:AtmIsolationQuarantineRoot; if ([IO.Directory]::Exists($q)) { return @(Get-ChildItem -LiteralPath $q -Directory -Force).Count } else { return 0 } }
    function Get-IsoArgs {
        param($Run, $Operator, [hashtable]$Extra = @{})
        $a = @{ Entries = @([pscustomobject]@{ Source = 't'; Path = $Run.Root; Fingerprint = $null }); PlanPresenter = (New-IsoPlanRecorder).Presenter; ConfirmationReader = $Operator.Reader; InventoryArgs = $Run.IA; LogFile = $Run.Log }
        foreach ($k in $Extra.Keys) { $a[$k] = $Extra[$k] }
        return $a
    }

    Test-Case 'Isolamento P3a' 'Isolar alem da trava: uma raiz de sessao do proprio perfil vai inteira para uma entrada nova da quarentena; confirmacao ISOLAR 1 CAMINHOS <planid8> sem declaracoes; log atm.isolatelog/1 e manifesto atm.quarantine/1 completos e sem nomes de arquivo; plan id com prefixo proprio' {
        $x = New-IsoRun 'isofull'
        if (-not $x) { return }
        $before = Get-IsoRelativeListing $x.Root
        $op = New-TestCleanOperator
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op)
        Assert-True (-not $res.Aborted -and -not $res.StoppedBy -and @($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'COMPLETE' -and $res.Results[0].Moved -and $res.Results[0].Verified) "isolado ($($res.Aborted)$($res.StoppedBy) $(@($res.Results | ForEach-Object { $_.AbortReason }) -join ';'))"
        Assert-True ($res.Phrase -cmatch '^ISOLAR 1 CAMINHOS [0-9A-F]{8}$' -and ($op.Calls -join ',') -ceq 'confirm|') "so a confirmacao do plano, sem declaracoes AUT-2 ($($op.Calls -join ','))"
        Assert-True (-not [IO.Directory]::Exists($x.Root)) 'a raiz saiu do ambiente ativo'
        Assert-True ($res.EntryId -cmatch '^\d{8}T\d{6}Z-[0-9a-f]{8}$' -and $res.EntryPath -eq (Join-Path $script:AtmIsolationQuarantineRoot $res.EntryId)) "entrada nova na quarentena ($($res.EntryId))"
        Assert-Eq (Get-IsoRelativeListing (Join-Path $res.EntryPath 'payload')) $before 'conteudo intacto: nomes, tamanhos, horarios e atributos'
        Assert-True ((Get-Acl -LiteralPath $res.EntryPath).Sddl.Contains('D:P(A;OICI;FA;;;OW)(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)') -and (Get-Acl -LiteralPath $script:AtmIsolationQuarantineRoot).Sddl.Contains('D:P(')) 'entrada e quarentena com DACL protegida'
        $lg = Read-TestCleanLogFile $x.Log
        Assert-Eq (@($lg.Records | ForEach-Object { $_.type }) -join ',') 'run-start,plan,confirmation,plan-check,move-intent,move-result,run-end' 'registros do log'
        Assert-True (@($lg.Records | Where-Object { $_.schema -cne 'atm.isolatelog/1' }).Count -eq 0 -and -not $lg.Bom -and $lg.EndsLf) 'esquema do log'
        $mf = Read-TestCleanLogFile (Join-Path $res.EntryPath 'manifest.jsonl')
        Assert-Eq (@($mf.Records | ForEach-Object { $_.type }) -join ',') 'entry,move-intent,move-result' 'registros do manifesto'
        $e0 = $mf.Records[0]; $r2 = $mf.Records[2]
        Assert-True ($e0.schema -ceq 'atm.quarantine/1' -and $e0.id -ceq $res.EntryId -and $e0.originalPath -eq $x.Root -and $e0.targetKind -ceq 'SessionRoot' -and $e0.planId -ceq $res.PlanId -and $e0.actor.sid -ceq $testIdentity.Sid) 'registro entry'
        Assert-True ($r2.outcome -ceq 'COMPLETE' -and $r2.verified -and $r2.digestAfter -ceq $r2.digestPlanned -and $r2.filesAfter -eq $mf.Records[1].files) 'registro move-result: verificado, mesmo resumo'
        $mText = [IO.File]::ReadAllText((Join-Path $res.EntryPath 'manifest.jsonl'))
        foreach ($leaf in @('a.txt', 'b.bin')) { Assert-True (-not $mText.Contains($leaf)) "manifesto sem nome de arquivo ($leaf)" }
        Assert-True ($res.PlanId -ceq (Get-AtmIsolatePlanId -RunId $res.RunId -Parts $res.Verified) -and $res.PlanId -cne (Get-AtmCleanPlanId -RunId $res.RunId -Parts $res.Verified)) 'plan id do isolamento nunca igual ao do clean'
    }
    Test-Case 'Isolamento P3a' 'Recusas antes do mover (nada movido, nenhuma entrada): frase errada, sem log, log dentro da quarentena, sem console, duas raizes, lock ocupado, plano alterado durante as perguntas, revalidacao recusada' {
        $x = New-IsoRun 'isorefuse'
        if (-not $x) { return }
        $before = Get-IsoRelativeListing $x.Root
        $n0 = Get-IsoEntryCount
        $check = { param($Res, [string]$Code, [string]$Label) Assert-True ($Res.Aborted -ceq $Code -and @($Res.Results).Count -eq 0) "${Label}: $($Res.Aborted) (esperado $Code)"; Assert-Eq (Get-IsoRelativeListing $x.Root) $before "${Label}: raiz intacta"; Assert-Eq (Get-IsoEntryCount) $n0 "${Label}: nenhuma entrada" }
        & $check (Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator -Answers @{ confirm = 'ISOLAR ERRADO' }))) 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' 'frase errada'
        $a = Get-IsoArgs $x (New-TestCleanOperator); $a.Remove('LogFile')
        & $check (Invoke-IsoOpen $a) 'LOG_REQUIRED' 'sem log'
        & $check (Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator) @{ LogFile = (Join-Path $script:AtmIsolationQuarantineRoot 'x.jsonl') })) 'LOG_DESTINATION_NOT_ALLOWED' 'log dentro da quarentena'
        $script:AtmCleanConsoleSource = { $false }
        try { $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator) @{ LogFile = ($x.Log + '.c') }) } finally { $script:AtmCleanConsoleSource = { $true } }
        & $check $res 'CONSOLE_NOT_OBSERVED' 'sem console'
        $r2 = New-TestRoot -ProfileInfo $x.Profile
        $a = Get-IsoArgs $x (New-TestCleanOperator) @{ LogFile = ($x.Log + '.d') }; $a.Entries = @($a.Entries + @([pscustomobject]@{ Source = 't'; Path = $r2; Fingerprint = $null }))
        & $check (Invoke-IsoOpen $a) 'ISOLAMENTO_UMA_RAIZ_POR_EXECUCAO' 'duas raizes'
        $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
        try { $op = New-TestCleanOperator; $res = Invoke-IsoOpen (Get-IsoArgs $x $op @{ LogFile = ($x.Log + '.e') }) } finally { $null = Stop-TestLockHolderByGo $h }
        & $check $res 'CLEAN_LOCK_BUSY' 'lock ocupado (o mesmo do clean)'
        Assert-True ($op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath ($x.Log + '.e'))) 'lock ocupado: nada perguntado, nenhum log'
        $plus = Join-Path $x.Root 'durante.txt'
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) [IO.File]::WriteAllText($plus, 'novo'); $null } }
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op @{ LogFile = ($x.Log + '.f') })
        Assert-True ($res.Aborted -ceq 'PLAN_CHANGED_BEFORE_EXECUTION' -and @($res.Results).Count -eq 0 -and (Get-IsoEntryCount) -eq $n0) "plano alterado durante as perguntas ($($res.Aborted))"
        [IO.File]::Delete($plus)
        $hook = { param($part) [IO.File]::WriteAllText((Join-Path $part.Path 'antes-do-mover.txt'), 'novo') }
        $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator) @{ LogFile = ($x.Log + '.g'); BeforeMoveHook = $hook })
        Assert-True ($res.Aborted -ceq 'REVALIDATION_REFUSED' -and @($res.Results).Count -eq 0 -and (Get-IsoEntryCount) -eq $n0) "revalidacao recusada ($($res.Aborted))"
        Assert-True (@((Read-TestCleanLogFile ($x.Log + '.g')).Records | ForEach-Object { $_.type }) -contains 'skip') 'skip registrado'
        Assert-True ([IO.Directory]::Exists($x.Root)) 'raiz ainda no lugar'
    }
    Test-Case 'Isolamento P3a' 'ISO-PLANCHECK-REASONS: o plan-check do isolate grava reasons (so codigos, contagens e nomes de campo): raiz ausente, chave mudada, processo novo sob B1, raiz fora da excecao B1, cada um PLAN_CHANGED_BEFORE_EXECUTION; matched true com reasons vazio; processo que saiu nao recusa; nunca chave de processo, caminho ou texto localizado' {
        # The one plan-check line of a log, raw (for the privacy checks) and parsed.
        $pcOf = {
            param([string]$Log)
            $ln = @([IO.File]::ReadAllLines($Log) | Where-Object { $_ -and ($_ | ConvertFrom-Json).type -ceq 'plan-check' })
            Assert-Eq $ln.Count 1 'um registro plan-check'
            return [pscustomobject]@{ Line = [string]$ln[0]; Rec = ($ln[0] | ConvertFrom-Json) }
        }
        $fieldsOf = { param($Pc) $pr = $Pc.Rec.PSObject.Properties['changedFields']; if ($null -eq $pr) { return $null }; return @($pr.Value) }
        # Only codes, counts and field names: no process identity (pid@ticks), no path (raw or JSON-escaped), no localized text.
        $private = {
            param($Pc, [string]$Root, [string]$Label)
            $esc = $Root.Replace('\', '\\')
            Assert-True (-not $Pc.Line.Contains('@') -and -not $Pc.Line.Contains($Root) -and -not $Pc.Line.Contains($esc)) "${Label}: sem chave de processo nem caminho ($($Pc.Line))"
            foreach ($c in @($Pc.Rec.reasons)) { Assert-True ([string]$c -cmatch '^[A-Z][A-Z0-9_]*( \(\d+\))?$') "${Label}: motivo so como codigo ($c)" }
            $cf = & $fieldsOf $Pc
            foreach ($f in @($cf)) { if ($null -ne $f) { Assert-True (@('path', 'fingerprint', 'files', 'dirs', 'bytes', 'newestWrite') -ccontains [string]$f) "${Label}: changedFields so com nomes ($f)" } }
        }
        $refused = { param($Res, $Pc, [string]$Label) Assert-True ($Res.Aborted -ceq 'PLAN_CHANGED_BEFORE_EXECUTION' -and @($Res.Results).Count -eq 0 -and $Pc.Rec.matched -eq $false) "${Label}: PLAN_CHANGED_BEFORE_EXECUTION, matched false ($($Res.Aborted); $($Pc.Line))" }
        $n0 = Get-IsoEntryCount

        # matched: true -> reasons [] and no changedFields (stopped afterwards at the revalidation, nothing moved).
        $x = New-IsoRun 'isopc-ok'
        if (-not $x) { return }
        $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator) @{ BeforeMoveHook = { param($part) [IO.File]::WriteAllText((Join-Path $part.Path 'pc-hook.txt'), 'x') } })
        $pc = & $pcOf $x.Log
        Assert-True ($res.Aborted -ceq 'REVALIDATION_REFUSED' -and $pc.Rec.matched -eq $true -and @($pc.Rec.reasons).Count -eq 0 -and $pc.Line.Contains('"reasons":[]') -and $null -eq (& $fieldsOf $pc)) "matched: reasons vazio, sem changedFields ($($res.Aborted); $($pc.Line))"
        & $private $pc $x.Root 'matched'

        # The root is not in the fresh inventory (renamed while the operator answered): ROOT_NOT_SEEN_ONCE (0).
        $x = New-IsoRun 'isopc-gone'
        if (-not $x) { return }
        $pcRoot = $x.Root; $pcAway = $x.Root + '-fora'
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) [IO.Directory]::Move($pcRoot, $pcAway); $null }.GetNewClosure() }
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op)
        $pc = & $pcOf $x.Log
        & $refused $res $pc 'raiz ausente'
        Assert-True ((@($pc.Rec.reasons) -join '|') -ceq 'ROOT_NOT_SEEN_ONCE (0)' -and $null -eq (& $fieldsOf $pc)) "raiz ausente: ROOT_NOT_SEEN_ONCE (0) ($($pc.Line))"
        & $private $pc $pcRoot 'raiz ausente'
        [IO.Directory]::Move($pcAway, $pcRoot)

        # The plan item key changed (a file added while the operator answered): PLAN_ITEM_CHANGED with the field names.
        $x = New-IsoRun 'isopc-key'
        if (-not $x) { return }
        $pcPlus = Join-Path $x.Root 'durante-pc.txt'
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) [IO.File]::WriteAllText($pcPlus, 'novo'); $null }.GetNewClosure() }
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op)
        $pc = & $pcOf $x.Log
        & $refused $res $pc 'chave mudada'
        $cf = @(& $fieldsOf $pc)
        Assert-True ((@($pc.Rec.reasons) -join '|') -ceq 'PLAN_ITEM_CHANGED' -and $cf -ccontains 'files' -and $cf -ccontains 'bytes' -and $cf -cnotcontains 'path' -and $cf -cnotcontains 'dirs') "chave mudada: PLAN_ITEM_CHANGED, changedFields $($cf -join ',') ($($pc.Line))"
        & $private $pc $x.Root 'chave mudada'

        # B1: a new process not inspectable while the operator answered: B1_EXCEPTION_NEW_UNINSPECTABLE_PROCESS (1).
        $ctx = New-TestB1Context 'isopc-b1new'
        $x = New-IsoRun 'isopc-b1new' $ctx
        if (-not $x) { return }
        $pcProcs = $ctx.Procs; $pcLate = New-TestRuntimeProc 873 'late-iso.exe' $null ((Get-Date).AddMinutes(-1))
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) [void]$pcProcs.Add($pcLate); $null }.GetNewClosure() }
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op @{ AcceptB1ResidualRisk = $true })
        $pc = & $pcOf $x.Log
        & $refused $res $pc 'B1 processo novo'
        Assert-True ((@($pc.Rec.reasons) -join '|') -ceq 'B1_EXCEPTION_NEW_UNINSPECTABLE_PROCESS (1)') "B1 processo novo: o codigo com a contagem ($($pc.Line))"
        & $private $pc $x.Root 'B1 processo novo'

        # B1: the root left the exception (a duplicate PID makes the process snapshot PARTIAL): B1_EXCEPTION_NO_LONGER_APPLIES.
        $ctx = New-TestB1Context 'isopc-b1out'
        $x = New-IsoRun 'isopc-b1out' $ctx
        if (-not $x) { return }
        $pcProcs = $ctx.Procs; $pcDup = [pscustomobject]@{ ProcessId = 1; Name = 'idle.exe'; ParentProcessId = 0; CommandLine = 'idle.exe'; CreationDate = (Get-Date).AddHours(-1) }
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) [void]$pcProcs.Add($pcDup); $null }.GetNewClosure() }
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op @{ AcceptB1ResidualRisk = $true })
        $pc = & $pcOf $x.Log
        & $refused $res $pc 'B1 fora da excecao'
        Assert-True (@($pc.Rec.reasons) -ccontains 'B1_EXCEPTION_NO_LONGER_APPLIES' -and $null -eq (& $fieldsOf $pc)) "B1 fora da excecao: B1_EXCEPTION_NO_LONGER_APPLIES entre os codigos ($($pc.Line))"
        & $private $pc $x.Root 'B1 fora da excecao'

        # Decision unchanged: an accepted process that left does not refuse (matched, reasons []); stopped afterwards at
        # the revalidation, nothing moved.
        $ctx = New-TestB1Context 'isopc-b1gone' 1 $false @((New-TestRuntimeProc 874 'gone-iso.exe' $null ((Get-Date).AddHours(-2))))
        $x = New-IsoRun 'isopc-b1gone' $ctx
        if (-not $x) { return }
        $pcProcs = $ctx.Procs
        $op = New-TestCleanOperator -Answers @{ confirm = { param($ph) $i = -1; for ($j = 0; $j -lt $pcProcs.Count; $j++) { if ($pcProcs[$j].ProcessId -eq 874) { $i = $j } }; if ($i -ge 0) { $pcProcs.RemoveAt($i) }; $null }.GetNewClosure() }
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op @{ AcceptB1ResidualRisk = $true; BeforeMoveHook = { param($part) [IO.File]::WriteAllText((Join-Path $part.Path 'pc-hook.txt'), 'x') } })
        $pc = & $pcOf $x.Log
        Assert-True (@($pcProcs | Where-Object { $_.ProcessId -eq 874 }).Count -eq 0 -and $res.Aborted -ceq 'REVALIDATION_REFUSED' -and $pc.Rec.matched -eq $true -and @($pc.Rec.reasons).Count -eq 0) "processo que saiu: nao recusa na conferencia ($($res.Aborted); $($pc.Line))"
        & $private $pc $x.Root 'processo que saiu'
        Assert-Eq (Get-IsoEntryCount) $n0 'nenhuma entrada criada'
    }
    Test-Case 'Isolamento P3a' 'Desfechos do mover (costura -MoveTreeImpl e mover real): intencao gravada no log e no manifesto ANTES da chamada; recusa, excecao, arquivo em uso (mover real recusa) e mudanca na janela (movido e nao verificado) param a execucao com o manifesto registrando o desfecho' {
        $cases = @(
            @{ Name = 'refused'; Want = 'REFUSED'; Impl = { param($c, $e, $n) $script:isoSeen = @((Get-IsoLiveLastType $script:isoLog), (Get-IsoLiveLastType (Join-Path $e.ParentPath 'manifest.jsonl'))); [pscustomobject]@{ Moved = $false; Verified = $false; RenameStatus = $null; AbortReason = 'SYNTHETIC_REFUSED'; FilesAfter = -1; DirsAfter = -1; BytesAfter = -1; DigestPlanned = $null; DigestAfter = $null } } },
            @{ Name = 'exception'; Want = 'EXCEPTION'; Impl = { param($c, $e, $n) throw (New-Object IO.IOException 'synthetic') } },
            @{ Name = 'inuse'; Want = 'REFUSED'; Impl = { param($c, $e, $n) $fs = [IO.File]::Open((Join-Path $c.Path 'a.txt'), 'Open', 'ReadWrite', 'None'); try { [AgentTempManager.AtmMover]::MoveTree($c.Path, $c.Files, $c.Dirs, $c.Bytes, $c.NewestWriteTimeUtc.Ticks, $e, $n, $null) } finally { $fs.Dispose() } } },
            @{ Name = 'window'; Want = 'INTEGRITY_FAILED'; Impl = { param($c, $e, $n) [AgentTempManager.AtmMover]::MoveTree($c.Path, $c.Files, $c.Dirs, $c.Bytes, $c.NewestWriteTimeUtc.Ticks, $e, $n, [Action[string]]{ param($p) [IO.File]::WriteAllText((Join-Path $p 'na-janela.txt'), 'x') }) } }
        )
        foreach ($k in $cases) {
            $x = New-IsoRun ('isoout-' + $k.Name)
            if (-not $x) { return }
            $script:isoLog = $x.Log; $script:isoSeen = $null
            $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator) @{ MoveTreeImpl = $k.Impl })
            Assert-True (@($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq $k.Want -and $res.StoppedBy -ceq ('STOPPED_AFTER_' + $k.Want) -and -not $res.Aborted) "$($k.Name): $($res.StoppedBy) $($res.Aborted) $(@($res.Results | ForEach-Object { $_.AbortReason }) -join ';')"
            $mf = Read-TestCleanLogFile (Join-Path $res.EntryPath 'manifest.jsonl')
            Assert-True ((@($mf.Records | ForEach-Object { $_.type }) -join ',') -ceq 'entry,move-intent,move-result' -and $mf.Records[2].outcome -ceq $k.Want) "$($k.Name): manifesto registra o desfecho"
            Assert-True ((@((Read-TestCleanLogFile $x.Log).Records | ForEach-Object { $_.type }) -join ',') -ceq 'run-start,plan,confirmation,plan-check,move-intent,move-result,run-end') "$($k.Name): log completo"
            if ($k.Want -ceq 'INTEGRITY_FAILED') { Assert-True ($res.Results[0].Moved -and -not $res.Results[0].Verified -and -not [IO.Directory]::Exists($x.Root)) 'janela: movido, nao verificado' }
            else { Assert-True ([IO.Directory]::Exists($x.Root) -and [IO.File]::Exists((Join-Path $x.Root 'a.txt'))) "$($k.Name): raiz intacta no lugar" }
            if ($k.Name -ceq 'refused') { Assert-Eq ($script:isoSeen -join ',') 'move-intent,move-intent' 'na chamada ao mover: intencao ja no log e no manifesto' }
            if ($k.Name -ceq 'inuse') { Assert-True ($res.Results[0].AbortReason -ceq 'MOVE_ACCESS_DENIED') "mover real recusa com arquivo aberto ($($res.Results[0].AbortReason))" }
        }
    }
    Test-Case 'Isolamento P3a' 'Excecao B1 por raiz alem da trava (J-ISO-2 b): com -AcceptB1ResidualRisk a frase de risco da raiz e a confirmacao sao pedidas e a raiz e isolada; o log registra o risco aceito; sem a chave, nada' {
        $ctx = New-TestB1Context 'isob1full'
        $x = New-IsoRun 'isob1full' $ctx
        if (-not $x) { return }
        $op = New-TestCleanOperator
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op @{ AcceptB1ResidualRisk = $true })
        Assert-True (-not $res.Aborted -and -not $res.StoppedBy -and $res.Results[0].Outcome -ceq 'COMPLETE') "isolado sob B1 ($($res.Aborted)$($res.StoppedBy))"
        Assert-Eq ($op.Calls -join ',') ("risk|$($x.Root),confirm|") 'risco da raiz, depois a confirmacao'
        $lg = Read-TestCleanLogFile $x.Log
        Assert-True (@($lg.Records | Where-Object { $_.type -ceq 'plan' })[0].category -ceq 'ELIGIBLE_WITH_DECLARED_RISK' -and @($lg.Records | Where-Object { $_.type -ceq 'confirmation' })[0].b1ResidualRiskAccepted) 'risco declarado no log'
        $ctx2 = New-TestB1Context 'isob1nokey'
        $x2 = New-IsoRun 'isob1nokey' $ctx2
        $res = Invoke-IsoOpen (Get-IsoArgs $x2 (New-TestCleanOperator))
        Assert-True ($res.Aborted -ceq 'NENHUM_CAMINHO_ISOLAVEL' -and [IO.Directory]::Exists($x2.Root)) "sem -AcceptB1ResidualRisk: recusado ($($res.Aborted))"
    }
    Test-Case 'Isolamento P3a' 'Quarentena: criada nova com DACL protegida quando ausente; existente e aceitavel usada sem nenhuma alteracao; juncao no lugar da quarentena recusada sem mover nada' {
        $x = New-IsoRun 'isoquar'
        if (-not $x) { return }
        $saved = $script:AtmIsolationQuarantineRoot
        try {
            # Existing, acceptable (made by this process, no other writer): used as it is, its ACL unchanged.
            $q = Join-Path $sandbox 'iso-quar-existente\Q'; [void][IO.Directory]::CreateDirectory($q)
            $sd = (Get-Acl -LiteralPath $q).Sddl
            $script:AtmIsolationQuarantineRoot = $q
            $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator))
            if ($res.Aborted -like 'QUARANTINE_*' -and -not $script:sandboxAclAdjusted) { $script:caseSkipped = $true; $script:caseNote = "quarentena existente recusada pela politica de pasta neste sandbox ($($res.Aborted))"; return }
            Assert-True ($res.Results[0].Outcome -ceq 'COMPLETE' -and $res.EntryPath.StartsWith($q + '\')) "existente usada ($($res.Aborted))"
            Assert-Eq (Get-Acl -LiteralPath $q).Sddl $sd 'ACL da quarentena existente inalterada'
            # A junction where the quarantine should be: refused, nothing moved, nothing in its target.
            $y = New-IsoRun 'isoquarj'
            $tgt = Join-Path $sandbox 'iso-quar-alvo'; [void][IO.Directory]::CreateDirectory($tgt)
            $jq = Join-Path $sandbox 'iso-quar-juncao\Q'; New-Junction $jq $tgt
            $script:AtmIsolationQuarantineRoot = $jq
            $res = Invoke-IsoOpen (Get-IsoArgs $y (New-TestCleanOperator))
            Assert-True ([string]$res.Aborted -like 'QUARANTINE_*' -and @($res.Results).Count -eq 0 -and [IO.Directory]::Exists($y.Root)) "juncao recusada ($($res.Aborted))"
            Assert-Eq @(Get-ChildItem -LiteralPath $tgt -Force).Count 0 'nada criado no alvo da juncao'
        } finally { $script:AtmIsolationQuarantineRoot = $saved }
    }
    Test-Case 'Isolamento P3a' 'Outro volume (contrato 4.2 e 5): raiz em outro volume que a quarentena recusada no plano com MOVE_OTHER_VOLUME, com a trava fechada e alem dela (nada perguntado, nenhum log, nenhuma entrada, lock livre depois), tambem sob a excecao B1; regra comum aos dois planos, por raiz de caminho sem caixa, valida antes de a quarentena existir' {
        # The common rule (Get-AtmOtherVolumeRefusal): path roots as text, ignoring case.
        Assert-Eq (@(Get-AtmOtherVolumeRefusal -Path 'C:\a\b' -QuarantinePath 'c:\u\AgentTempManager\Q') -join ',') '' 'mesmo volume (caixa diferente)'
        Assert-Eq (@(Get-AtmOtherVolumeRefusal -Path 'D:\a\b' -QuarantinePath 'C:\u\AgentTempManager\Q') -join ',') 'MOVE_OTHER_VOLUME' 'outra letra de unidade'
        Assert-Eq (@(Get-AtmOtherVolumeRefusal -Path '\\srv\share\a' -QuarantinePath 'C:\u\AgentTempManager\Q') -join ',') 'MOVE_OTHER_VOLUME' 'compartilhamento de rede'
        Assert-Eq (@(Get-AtmOtherVolumeRefusal -Path 'C:\a\b' -QuarantinePath '') -join ',') '' 'sem quarentena: nada aqui (QUARANTINE_PATH_INVALID cobre alem da trava)'
        # The quarantine seam on a drive letter that does not exist on this machine: the rule holds before the quarantine
        # exists, and even a regression could create nothing there.
        $used = @([IO.DriveInfo]::GetDrives() | ForEach-Object { $_.Name.Substring(0, 1).ToUpperInvariant() })
        $free = @([char[]]'ZYXWVUTSRQPONMLKJIHGFE' | ForEach-Object { [string]$_ } | Where-Object { $used -notcontains $_ -and -not [IO.Directory]::Exists($_ + ':\') } | Select-Object -First 1)
        if ($free.Count -eq 0) { $script:caseSkipped = $true; $script:caseNote = 'nenhuma letra de unidade livre nesta maquina para a quarentena simulada em outro volume'; return }
        $qOther = $free[0] + ':\atm-iso-other-volume\AgentTempManager\Q'
        $x = New-IsoRun 'isovol'
        if (-not $x) { return }
        $before = Get-IsoRelativeListing $x.Root
        $n0 = Get-IsoEntryCount
        $saved = $script:AtmIsolationQuarantineRoot
        try {
            $script:AtmIsolationQuarantineRoot = $qOther
            # Gate closed: the plan only. The lock is held by another process (a run that took it would refuse BUSY).
            $rec = New-IsoPlanRecorder
            $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
            try {
                Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
                $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $x.Root; Fingerprint = $null }) -PlanPresenter $rec.Presenter -InventoryArgs $x.IA
            } finally { $null = Stop-TestLockHolderByGo $h }
            Assert-True ($res.Aborted -ceq 'NENHUM_CAMINHO_ISOLAVEL' -and (Get-IsoRejectedReason $res $x.Root) -ceq 'MOVE_OTHER_VOLUME' -and $rec.Calls.Count -eq 0) "trava fechada: recusada no plano, sem tentar o lock ($($res.Aborted): $(Get-IsoRejectedReason $res $x.Root))"
            # Past the gate (in this process only; not through Invoke-IsoOpen, whose guard keeps the quarantine in the sandbox).
            $op = New-TestCleanOperator
            $script:AtmIsolationEnabled = $true
            try { $a = Get-IsoArgs $x $op; $res = Invoke-AtmIsolate @a } finally { $script:AtmIsolationEnabled = $false }
            Assert-True ($res.Aborted -ceq 'NENHUM_CAMINHO_ISOLAVEL' -and (Get-IsoRejectedReason $res $x.Root) -ceq 'MOVE_OTHER_VOLUME') "alem da trava: recusada no plano ($($res.Aborted): $(Get-IsoRejectedReason $res $x.Root))"
            Assert-True ($op.Calls.Count -eq 0 -and -not $res.LogCreated -and -not (Test-Path -LiteralPath $x.Log) -and -not $res.EntryId -and @($res.Results).Count -eq 0) 'nada perguntado, nenhum log, nenhuma entrada, mover nunca chamado'
            $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
            try { Assert-Eq $h.Status 'ACQUIRED' 'lock livre depois da recusa' } finally { $null = Stop-TestLockHolderByGo $h }
            # Under the B1 exception (-AcceptB1ResidualRisk past the gate): refused all the same, before the risk phrase.
            $y = New-IsoRun 'isovolb1' (New-TestB1Context 'isovolb1')
            if ($y) {
                $opb = New-TestCleanOperator
                $script:AtmIsolationEnabled = $true
                try { $a = Get-IsoArgs $y $opb @{ AcceptB1ResidualRisk = $true }; $res = Invoke-AtmIsolate @a } finally { $script:AtmIsolationEnabled = $false }
                Assert-True ($res.Aborted -ceq 'NENHUM_CAMINHO_ISOLAVEL' -and (Get-IsoRejectedReason $res $y.Root) -ceq 'MOVE_OTHER_VOLUME' -and $opb.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $y.Log)) "sob B1: recusada no plano ($($res.Aborted): $(Get-IsoRejectedReason $res $y.Root))"
                # Without the switch the gates refuse the root; the volume code is reported with them.
                $res = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $y.Root; Fingerprint = $null }) -PlanPresenter (New-IsoPlanRecorder).Presenter -InventoryArgs $y.IA
                Assert-True ((Get-IsoRejectedReason $res $y.Root) -like '*MOVE_OTHER_VOLUME*') "com os gates recusando, o codigo do volume tambem ($(Get-IsoRejectedReason $res $y.Root))"
                Assert-True ([IO.Directory]::Exists($y.Root)) 'raiz B1 no lugar'
            }
        } finally { $script:AtmIsolationQuarantineRoot = $saved }
        Assert-Eq (Get-IsoRelativeListing $x.Root) $before 'raiz identica'
        Assert-Eq (Get-IsoEntryCount) $n0 'nenhuma entrada na quarentena do sandbox'
        Assert-True (-not [IO.Directory]::Exists($free[0] + ':\')) 'nada criado na unidade simulada'
        # Static: one literal of the code, in the common rule, called by both plans; in the isolate plan before the capacity
        # rules and before the stop of the gate (so before any question, log or entry).
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        Assert-Eq ([regex]::Matches($iso, "'MOVE_OTHER_VOLUME'").Count) 1 'um unico literal MOVE_OTHER_VOLUME, na regra comum'
        $core = $iso.Substring($iso.IndexOf('function Invoke-AtmIsolateCore'), $iso.IndexOf('function Read-AtmQuarantineManifest') - $iso.IndexOf('function Invoke-AtmIsolateCore'))
        $iVol = $core.IndexOf('Get-AtmOtherVolumeRefusal -Path $p.Path -QuarantinePath (Get-AtmQuarantineRootPath)')
        Assert-True ($iVol -gt 0 -and $iVol -lt $core.IndexOf('Get-AtmQuarantineCapacityRefusal') -and $iVol -lt $core.IndexOf("'ISOLAMENTO_REAL_DESABILITADO'")) 'plano do isolamento: regra comum antes da capacidade e da parada da trava'
        $rp = $iso.Substring($iso.IndexOf('function Get-AtmRestorePlan {'), $iso.IndexOf('function Invoke-AtmRestore {') - $iso.IndexOf('function Get-AtmRestorePlan {'))
        Assert-True ($rp.Contains('Get-AtmOtherVolumeRefusal -Path $parent -QuarantinePath $e.Path')) 'plano da restauracao: a mesma regra comum'
        Assert-True (-not $iso.Contains('GetPathRoot($parent)')) 'nenhuma comparacao de volume fora da regra comum'
    }
    Test-Case 'Isolamento P3a' 'Interrupcao entre a intencao e o resultado: processo filho que sai sozinho dentro do mover simulado deixa move-intent sem move-result no log e no manifesto (entrada INCOMPLETE); raiz intacta' {
        $dir = New-TestCleanLogDir 'iso-interrupt'
        if (-not $dir) { return }
        $f = New-TestT1Fixture 'isointr' 1
        $path = Join-Path $dir 'intr.jsonl'
        $q = Join-Path $sandbox 'iso-interrupt-home\AgentTempManager\Q'; [void][IO.Directory]::CreateDirectory((Join-Path $sandbox 'iso-interrupt-home'))
        $child = Join-Path $sandbox 'iso-interrupt-child.ps1'
        [IO.File]::WriteAllText($child, @'
param([string]$Src, [string]$ProfileRoot, [string]$Temp, [string]$Sid, [string]$Name, [string]$IsAdmin, [string]$Root, [string]$LogFile, [string]$NowTicks, [string]$LockName, [string]$Quarantine)
# A fresh process: the product files as shipped, the isolation gate opened in THIS process only (as the suite does), and a
# stand-in mover that moves nothing and ends the process itself (Environment.Exit) after the intent was written.
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0
. (Join-Path $Src 'lib\Engine.Audit.ps1')
Initialize-AtmNative -LibDir (Join-Path $Src 'lib')
foreach ($f in @(Get-ChildItem -LiteralPath (Join-Path $Src 'providers') -Filter '*.ps1' -File | Sort-Object Name)) { . $f.FullName }
. (Join-Path $Src 'lib\Engine.Clean.ps1')
. (Join-Path $Src 'lib\Engine.Isolate.ps1')
. (Join-Path $Src 'lib\Engine.Diagnose.ps1')
$script:AtmIsolationEnabled = $true
$script:AtmIsolationQuarantineRoot = $Quarantine
$script:AtmCleanLockName = $LockName
$script:AtmRuntimeEvidenceSources = @{ ServiceSource = { param($Names) @() }; VirtualizationSource = { param($Op) @() } }
$script:AtmCleanConsoleSource = { $true }
$prof = [pscustomobject]@{ Sid = $Sid; UserName = 'TEST\isointr'; ProfilePath = $ProfileRoot; Loaded = $true; Special = $false; Origin = 'Test'; EnvStatus = 'OK'
    TempCandidates = @([pscustomobject]@{ TempPath = $Temp; Source = 'test' }); EnvValues = @{}; EnvKnown = $true; Notes = @() }
$ia = @{ ProfilesOverride = @($prof); ProcessesOverride = @([pscustomobject]@{ ProcessId = 1; Name = 'idle.exe'; ParentProcessId = 0; CommandLine = 'idle.exe'; CreationDate = (Get-Date).AddHours(-1) })
    IdentityOverride = [pscustomobject]@{ Sid = $Sid; Name = $Name; IsAdmin = ($IsAdmin -ceq 'True') }; NowUtc = (New-Object DateTime ([long]$NowTicks), ([DateTimeKind]::Utc)); NoProgress = $true; ConfigDir = (Join-Path $Src 'config') }
$c = Invoke-AtmIsolate -Entries @([pscustomobject]@{ Source = 't'; Path = $Root; Fingerprint = $null }) -PlanPresenter { param($v, $r, $i, $p) } -ConfirmationReader { param($x) $x } -InventoryArgs $ia -LogFile $LogFile -MoveTreeImpl { param($c, $e, $n) [Environment]::Exit(7) }
[Console]::Out.WriteLine('NOT_EXITED ' + $c.Aborted + ' ' + $c.StoppedBy)
exit 0
'@, (New-Object Text.UTF8Encoding $true))
        $shell = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $tp = $f.Profile.TempCandidates[0].TempPath
        $r = Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$child`" -Src `"$srcDir`" -ProfileRoot `"$($f.Profile.ProfilePath)`" -Temp `"$tp`" -Sid `"$($testIdentity.Sid)`" -Name `"$($testIdentity.Name)`" -IsAdmin `"$($testIdentity.IsAdmin)`" -Root `"$($f.Roots[0])`" -LogFile `"$path`" -NowTicks `"$($nowFuture.Ticks)`" -LockName `"$(New-TestLockName)`" -Quarantine `"$q`"") -TimeoutSec 300
        Assert-True ($r.Exit -eq 7 -and -not $r.TimedOut) "o filho saiu sozinho dentro do mover simulado (saida $($r.Exit) $($r.Text))"
        Assert-Eq (@((Read-TestCleanLogFile $path).Records | ForEach-Object { $_.type }) -join ',') 'run-start,plan,confirmation,plan-check,move-intent' 'o log termina na intencao'
        $entries = @(Get-ChildItem -LiteralPath $q -Directory)
        Assert-Eq $entries.Count 1 'uma entrada criada'
        Assert-Eq (@((Read-TestCleanLogFile (Join-Path $entries[0].FullName 'manifest.jsonl')).Records | ForEach-Object { $_.type }) -join ',') 'entry,move-intent' 'manifesto termina na intencao: entrada INCOMPLETE'
        Assert-True ([IO.File]::Exists((Join-Path $f.Roots[0] 'a.txt')) -and -not [IO.Directory]::Exists((Join-Path $entries[0].FullName 'payload'))) 'raiz intacta, nada na entrada'
    }
    Test-Case 'Isolamento P3a' 'Escala: 200.000 arquivos isolados e verificados (pesado; NAO_TESTADO com -SkipHeavy)' {
        if ($SkipHeavy) { $script:caseSkipped = $true; $script:caseNote = 'pesado: rodado sem -SkipHeavy (a CI usa -SkipHeavy)'; return }
        $x = New-IsoRun 'isoscale'
        if (-not $x) { return }
        $big = Join-Path $x.Root 'big'
        for ($d = 0; $d -lt 200; $d++) { $sub = Join-Path $big ('d{0:000}' -f $d); [void][IO.Directory]::CreateDirectory($sub); for ($i = 0; $i -lt ($HeavyFiles / 200); $i++) { [IO.File]::WriteAllBytes((Join-Path $sub ('f{0:0000}.bin' -f $i)), [byte[]]@(1)) } }
        $sw = [Diagnostics.Stopwatch]::StartNew()
        $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator))
        Assert-True ($res.Results[0].Outcome -ceq 'COMPLETE') "isolado ($($res.Aborted)$($res.StoppedBy))"
        $script:caseNote = "$HeavyFiles arquivos em $([int]$sw.Elapsed.TotalSeconds) s"
    }
    Test-Case 'Isolamento P3a' 'Estatico: uma unica chamada ao mover, so alem da trava e depois da intencao no log e no manifesto; costuras -MoveTreeImpl e quarentena so no motor (atribuicao unica $null), nunca na CLI; lock e console pelos helpers compartilhados do clean' {
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        Assert-Eq $shippedQuarantineRoot $null 'quarentena distribuida: %LOCALAPPDATA%\AgentTempManager\Q (costura $null)'
        Assert-Eq ([regex]::Matches($iso, '\$script:AtmIsolationQuarantineRoot\s*=').Count) 1 'uma unica atribuicao da costura'
        Assert-True ($iso.Contains("Join-Path `$la 'AgentTempManager\Q'")) 'quarentena padrao em %LOCALAPPDATA%\AgentTempManager\Q'
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Isolate.ps1' })) {
            $t = [IO.File]::ReadAllText($fi.FullName)
            foreach ($seam in @('MoveTreeImpl', 'AtmIsolationQuarantineRoot', 'BeforeMoveHook', 'PurgeTreeImpl', 'BeforePurgeHook', 'AtmQuarantineClock')) { Assert-True (-not $t.Contains($seam)) "$($fi.Name) usa a costura $seam" }
        }
        $iIntent = $iso.IndexOf("-Type 'move-intent'"); $iMove = $iso.IndexOf('[AgentTempManager.AtmMover]::MoveTree('); $iGate = $iso.IndexOf("'ISOLAMENTO_REAL_DESABILITADO'"); $iLog = $iso.IndexOf("'LOG_REQUIRED'")
        Assert-True ($iGate -gt 0 -and $iLog -gt $iGate -and $iIntent -gt $iLog -and $iMove -gt $iIntent -and $iso.IndexOf("-Type 'move-intent'", $iIntent + 1) -lt $iMove) "ordem: trava $iGate < LOG_REQUIRED $iLog < intencao (log e manifesto) $iIntent < mover $iMove"
        Assert-True ($iso.Contains('Invoke-AtmUnderSharedLock -Body') -and $iso.Contains('Get-AtmEngineConsoleObservation') -and $iso.Contains("'atm-isolate-plan/1;'") -and -not $iso.Contains('atm-clean-plan')) 'lock e console compartilhados; prefixo proprio do plan id'
        $clean = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        $hl = $clean.Substring($clean.IndexOf('function Invoke-AtmUnderSharedLock'), $clean.IndexOf('function Invoke-AtmClean {') - $clean.IndexOf('function Invoke-AtmUnderSharedLock'))
        Assert-True ($hl.Contains('[AgentTempManager.AtmCleanLock]::TryAcquire($script:AtmCleanLockName)') -and $hl.Contains('try { $out = & $Body } finally { $rc = $lock.Release() }') -and $hl.IndexOf('Initialize-AtmNative') -lt $hl.IndexOf('TryAcquire')) 'lock compartilhado: mesmo nome, liberado no finally, biblioteca carregada antes'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.Contains("if (`$script:AtmIsolationEnabled -and -not (Test-AtmTuiInteractive)) { Write-Host (Get-AtmText 'cli.isolateNeedsConsole')") -and $cli.Contains('-ConfirmationReader $isoReader')) 'CLI: console exigido alem da trava; leitor do console'
    }

    # ------------------------------------------------------------------ 0.3.x isolation, phase P3b: quarantine management and restore (ISO-P3b)
    # Entries come from real isolations in the sandbox (New-IsoRun + Invoke-IsoOpen). The engine judges them by the identity
    # of the inventory (the test identity here; the process user in the CLI). The isolation gate opens only around each
    # call (Invoke-IsoOpen, Invoke-RstOpen) and is restored.
    function New-RstEntry {
        # One isolated entry: the run, the isolation result, the entry id and path, and the relative listing of the root.
        param([string]$Name, [hashtable]$Extra = @{})
        $x = New-IsoRun $Name
        if (-not $x) { return $null }
        $before = Get-IsoRelativeListing $x.Root
        $res = Invoke-IsoOpen (Get-IsoArgs $x (New-TestCleanOperator) $Extra)
        return [pscustomobject]@{ Run = $x; Iso = $res; Id = $res.EntryId; Path = $res.EntryPath; Before = $before; Manifest = $(if ($res.EntryPath) { Join-Path $res.EntryPath 'manifest.jsonl' } else { $null })
            Id8 = $(if ($res.EntryId) { $res.EntryId.Substring($res.EntryId.Length - 8) } else { $null }) }
    }
    function Invoke-RstOpen {
        param([hashtable]$Arguments)
        Assert-True ([string]$script:AtmIsolationQuarantineRoot -and ([string]$script:AtmIsolationQuarantineRoot).StartsWith($sandbox + '\', [StringComparison]::OrdinalIgnoreCase)) "quarentena dentro do sandbox ($($script:AtmIsolationQuarantineRoot))"
        $script:AtmIsolationEnabled = $true
        try { return (Invoke-AtmRestore @Arguments) } finally { $script:AtmIsolationEnabled = $false }
    }
    function New-RstPlanRecorder {
        $st = @{ Calls = (New-Object System.Collections.Generic.List[object]) }
        $st.Presenter = { param($plan, $inv, $planId) $st.Calls.Add([pscustomobject]@{ Plan = $plan; PlanId = $planId }) }.GetNewClosure()
        return $st
    }
    function Get-RstArgs {
        param($E, $Operator, [string]$Log, [hashtable]$Extra = @{})
        $a = @{ Id = $E.Id; PlanPresenter = (New-RstPlanRecorder).Presenter; ConfirmationReader = $Operator.Reader; InventoryArgs = $E.Run.IA; LogFile = $Log }
        foreach ($k in $Extra.Keys) { $a[$k] = $Extra[$k] }
        return $a
    }
    function Get-RstSnapshot {
        # Bytes and times of everything under a folder: names, creation and write times, attributes, SHA-256 of each file.
        # NTFS updates directory times lazily after recent creations (the fixtures write just before): the snapshot is
        # taken again until two in a row agree, as Get-StableTreeListing does.
        param([string]$Path)
        $take = {
            $out = New-Object System.Collections.Generic.List[string]
            $sha = [Security.Cryptography.SHA256]::Create()
            try {
                foreach ($i in @(Get-ChildItem -LiteralPath $Path -Recurse -Force)) {
                    $h = $(if ($i.PSIsContainer) { '' } else { [BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($i.FullName))) })
                    $out.Add(('{0}|{1}|{2}|{3}|{4}' -f $i.FullName, $i.CreationTimeUtc.Ticks, $i.LastWriteTimeUtc.Ticks, [int]$i.Attributes, $h))
                }
            } finally { $sha.Dispose() }
            return (($out | Sort-Object) -join "`n")
        }
        $a = & $take
        for ($w = 0; $w -lt 20; $w++) { Start-Sleep -Milliseconds 500; $b = & $take; if ($b -ceq $a) { break }; $a = $b }
        return $a
    }
    function Get-RstTypes { param([string]$Path) return (@((Read-TestCleanLogFile $Path).Records | ForEach-Object { $_.type }) -join ',') }
    function Set-RstManifestLines {
        # Test fixture only: keeps the first -Keep lines of a manifest and appends records, as the writer would have left them
        # (an interruption between an intent and its result).
        param([string]$Path, [int]$Keep, [object[]]$Append = @())
        $lines = @(([IO.File]::ReadAllText($Path)).Split([char]10) | Where-Object { $_ -ne '' })
        $new = @(@($lines | Select-Object -First $Keep) + @($Append | ForEach-Object { ConvertTo-Json -InputObject $_ -Compress -Depth 5 }))
        [IO.File]::WriteAllText($Path, (($new -join "`n") + "`n"), (New-Object Text.UTF8Encoding($false)))
    }
    function Get-RstHost {
        # The text a report function writes to the host (information stream), for assertions.
        param([scriptblock]$Block)
        return ((& $Block 6>&1 | ForEach-Object { [string]$_ }) -join "`n")
    }
    $rstRefused = { param($plan, $dest, $n) [pscustomobject]@{ Moved = $false; Verified = $false; RenameStatus = $null; AbortReason = 'SYNTHETIC_REFUSED'; FilesAfter = -1; DirsAfter = -1; BytesAfter = -1; DigestPlanned = $null; DigestAfter = $null } }
    $isoRefused = { param($c, $e, $n) [pscustomobject]@{ Moved = $false; Verified = $false; RenameStatus = $null; AbortReason = 'SYNTHETIC_REFUSED'; FilesAfter = -1; DirsAfter = -1; BytesAfter = -1; DigestPlanned = $null; DigestAfter = $null } }

    Test-Case 'Isolamento P3b' 'Gestao so leitura com a trava fechada: list, inspect e verify de uma entrada ISOLATED (estado, medicao, resumo dos metadados, registros); bytes e horarios identicos antes e depois, manifesto incluido; quarentena ausente nunca criada; id que nao e de entrada nunca vira caminho' {
        $e = New-RstEntry 'rstro'
        if (-not $e) { return }
        Assert-True ($e.Iso.Results[0].Outcome -ceq 'COMPLETE') "isolado ($($e.Iso.Aborted)$($e.Iso.StoppedBy))"
        Assert-Eq $script:AtmIsolationEnabled $false 'trava fechada durante a gestao'
        $q = $script:AtmIsolationQuarantineRoot
        $snap = Get-RstSnapshot $q
        $list = Get-AtmQuarantineList -OwnSid $testIdentity.Sid
        $mine = @($list.Entries | Where-Object { $_.Id -ceq $e.Id })
        Assert-True ($list.Exists -and $mine.Count -eq 1 -and $mine[0].State -ceq 'ISOLATED' -and $mine[0].OriginalPath -eq $e.Run.Root -and $mine[0].TargetKind -ceq 'SessionRoot' -and $mine[0].PayloadPresent) "list: ISOLATED ($(@($mine | ForEach-Object { Format-AtmQuarantineState $_ }) -join ','))"
        $one = Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
        Assert-True ($one.Files -eq 2 -and $one.Dirs -eq 1 -and $one.Verified.Files -eq 2 -and $one.Verified.Digest -cmatch '^[0-9A-F]{64}$' -and (@($one.Records | ForEach-Object { $_.Type }) -join ',') -ceq 'entry,move-intent,move-result') 'inspect: medicao, conferencia e registros'
        $v = Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
        Assert-True ($v.Result -ceq 'OK' -and $v.State -ceq 'ISOLATED' -and $null -eq $v.Reconcilable) "verify: OK ($($v.Result) $($v.Reason))"
        $old = Get-AtmLanguage
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $t = Get-RstHost { Show-AtmQuarantineList -List $list; Show-AtmQuarantineEntry -Entry $one; Show-AtmQuarantineVerify -Results @($v) }
                Assert-True ($t.Contains($e.Id) -and $t.Contains((Get-AtmText 'q.readOnly')) -and $t.Contains((Get-AtmText 'q.cliOnly' $e.Id)) -and $t.Contains('ISOLATED')) "$lang`: textos de list, inspect e verify"
            }
        } finally { Set-AtmLanguage -Requested $old }
        Assert-Eq (Get-RstSnapshot $q) $snap 'bytes e horarios identicos (manifesto incluido)'
        $missing = Join-Path $sandbox 'rst-sem-quarentena\AgentTempManager\Q'
        $l2 = Get-AtmQuarantineList -Root $missing -OwnSid $testIdentity.Sid
        Assert-True (-not $l2.Exists -and @($l2.Entries).Count -eq 0 -and -not (Test-Path -LiteralPath (Join-Path $sandbox 'rst-sem-quarentena'))) 'quarentena ausente: listada como ausente, nada criado'
        Assert-Eq (Test-AtmQuarantineEntry -Id '20260101T000000Z-0badf00d' -OwnSid $testIdentity.Sid).Result 'ENTRY_NOT_FOUND' 'entrada inexistente'
        foreach ($bad in @('..\x', $e.Path, ($e.Id + '\payload'), ('x' + $e.Id))) { Assert-True ($null -eq (Get-AtmQuarantineEntry -Id $bad -OwnSid $testIdentity.Sid)) "id invalido nao e aceito: $bad" }
    }
    Test-Case 'Isolamento P3b' 'Estados derivados (secao 7.4): a entrada que o mover deixa ao recusar aparece FAILED; intencao sem resultado INCOMPLETE; outra identidade ABANDONED; manifesto ausente, recSeq fora de ordem, id divergente, primeiro registro errado e payload depois de RESTORED dao ENTRY_MANIFEST_INVALID; pasta que nao e entrada e juncao UNRECOGNIZED, nunca abertas' {
        $f = New-RstEntry 'rstfail' @{ MoveTreeImpl = $isoRefused }
        if (-not $f) { return }
        Assert-Eq $f.Iso.StoppedBy 'STOPPED_AFTER_REFUSED' 'isolamento recusado pelo mover'
        $s = Get-AtmQuarantineEntry -Id $f.Id -OwnSid $testIdentity.Sid
        Assert-True ($s.State -ceq 'FAILED' -and $s.LastOutcome -ceq 'REFUSED' -and -not $s.PayloadPresent) "entrada da recusa: FAILED ($(Format-AtmQuarantineState $s))"
        Assert-Eq (Test-AtmQuarantineEntry -Id $f.Id -OwnSid $testIdentity.Sid).Result 'NOT_VERIFIABLE' 'FAILED: nada a conferir'
        $other = Get-AtmQuarantineEntry -Id $f.Id -OwnSid 'S-1-5-21-1-2-3-4444'
        Assert-Eq $other.State 'ABANDONED' 'manifesto de outra identidade: ABANDONED'
        Set-RstManifestLines -Path $f.Manifest -Keep 2
        $s = Get-AtmQuarantineEntry -Id $f.Id -OwnSid $testIdentity.Sid
        Assert-True ($s.State -ceq 'INCOMPLETE' -and $s.Pending -ceq 'move') "intencao sem resultado: INCOMPLETE ($(Format-AtmQuarantineState $s))"
        # Hand-made folders in a quarantine of their own.
        $qc = Join-Path $sandbox 'rst-states\Q'
        [void][IO.Directory]::CreateDirectory((Join-Path $qc 'nao-e-entrada'))
        $mk = {
            param([string]$Id, [object[]]$Recs, [switch]$Payload)
            $d = Join-Path $qc $Id; [void][IO.Directory]::CreateDirectory($d)
            if ($Payload) { [void][IO.Directory]::CreateDirectory((Join-Path $d 'payload')) }
            if ($null -ne $Recs) { [IO.File]::WriteAllText((Join-Path $d 'manifest.jsonl'), ((@($Recs | ForEach-Object { ConvertTo-Json -InputObject $_ -Compress -Depth 5 }) -join "`n") + "`n"), (New-Object Text.UTF8Encoding($false))) }
        }
        $rec = { param([string]$Id, [int]$Seq, [string]$Type, [hashtable]$More = @{}) $o = [ordered]@{ schema = 'atm.quarantine/1'; type = $Type; id = $Id; recSeq = $Seq; utc = '2026-01-01T00:00:00.0000000Z' }; foreach ($k in $More.Keys) { $o[$k] = $More[$k] }; $o }
        $act = @{ actor = [ordered]@{ sid = $testIdentity.Sid; elevated = $false }; targetKind = 'SessionRoot'; originalPath = 'C:\x\y'; provider = 'claude-code' }
        $i1 = '20260101T000000Z-00000001'; & $mk $i1 $null
        $i2 = '20260101T000000Z-00000002'; & $mk $i2 @((& $rec $i2 1 'entry' $act), (& $rec $i2 3 'move-intent'))
        $i3 = '20260101T000000Z-00000003'; & $mk $i3 @((& $rec '20260101T000000Z-0000000f' 1 'entry' $act))
        $i4 = '20260101T000000Z-00000004'; & $mk $i4 @((& $rec $i4 1 'move-intent'))
        $i5 = '20260101T000000Z-00000005'; & $mk $i5 @((& $rec $i5 1 'entry' $act), (& $rec $i5 2 'move-intent' @{ files = 0; dirs = 0; bytes = 0 }), (& $rec $i5 3 'move-result' @{ outcome = 'COMPLETE' }), (& $rec $i5 4 'restore-intent'), (& $rec $i5 5 'restore-result' @{ outcome = 'COMPLETE'; moved = $true })) -Payload
        $tgt = Join-Path $sandbox 'rst-states-alvo'; [void][IO.Directory]::CreateDirectory($tgt); [IO.File]::WriteAllText((Join-Path $tgt 'manifest.jsonl'), 'x')
        $i6 = '20260101T000000Z-00000006'; New-Junction (Join-Path $qc $i6) $tgt
        $snap = Get-RstSnapshot $qc
        $l = Get-AtmQuarantineList -Root $qc -OwnSid $testIdentity.Sid
        $by = @{}; foreach ($x in @($l.Entries)) { $by[$x.Id] = (Format-AtmQuarantineState $x) }
        Assert-Eq $by['nao-e-entrada'] 'UNRECOGNIZED (NOT_AN_ENTRY)' 'pasta que nao e entrada'
        Assert-Eq $by[$i1] 'ENTRY_MANIFEST_INVALID (MANIFEST_MISSING)' 'manifesto ausente'
        Assert-Eq $by[$i2] 'ENTRY_MANIFEST_INVALID (MANIFEST_INVALID)' 'recSeq fora de ordem'
        Assert-Eq $by[$i3] 'ENTRY_MANIFEST_INVALID (MANIFEST_INVALID)' 'id divergente do nome da pasta'
        Assert-Eq $by[$i4] 'ENTRY_MANIFEST_INVALID (MANIFEST_INVALID)' 'primeiro registro nao e entry'
        Assert-Eq $by[$i5] 'ENTRY_MANIFEST_INVALID (PAYLOAD_AFTER_RESTORE)' 'payload depois de RESTORED'
        Assert-Eq $by[$i6] 'UNRECOGNIZED (REPARSE_POINT)' 'juncao no lugar de uma entrada'
        Assert-Eq (Get-RstSnapshot $qc) $snap 'nada alterado'
        $saved = $script:AtmIsolationQuarantineRoot
        $script:AtmIsolationQuarantineRoot = $qc
        try {
            $v = Test-AtmQuarantineEntry -Id $i2 -OwnSid $testIdentity.Sid
            Assert-True ($v.Result -ceq 'ENTRY_MANIFEST_INVALID' -and $v.Reason -ceq 'MANIFEST_INVALID') "verify: ENTRY_MANIFEST_INVALID ($($v.Result))"
            Assert-Eq (Test-AtmQuarantineEntry -Id $i6 -OwnSid $testIdentity.Sid).Result 'ENTRY_NOT_FOUND' 'juncao nunca aberta como entrada'
            $rr = Invoke-AtmRestore -Id $i2 -PlanPresenter (New-RstPlanRecorder).Presenter -InventoryArgs $f.Run.IA
            Assert-True ($rr.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($rr.Plan.Reasons) -join ';') -like 'ENTRY_MANIFEST_INVALID*') "restauracao recusa manifesto invalido ($(@($rr.Plan.Reasons) -join ';'))"
        } finally { $script:AtmIsolationQuarantineRoot = $saved }
        Assert-Eq @(Get-ChildItem -LiteralPath $tgt -Force).Count 1 'nada criado no alvo da juncao'
    }
    Test-Case 'Isolamento P3b' 'Verificacao: arquivo acrescentado ao payload da DIFFERS (com o motivo); payload ausente da PAYLOAD_MISSING; nenhuma das duas grava nada; a restauracao recusa a entrada divergente antes de qualquer pergunta ou log' {
        $e = New-RstEntry 'rstdiff'
        if (-not $e) { return }
        [IO.File]::WriteAllText((Join-Path $e.Path 'payload\depois.txt'), 'x')
        $h0 = Get-RstSnapshot $e.Path
        $v = Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
        Assert-True ($v.Result -ceq 'DIFFERS' -and $v.Reason.Contains('FILES 3/2') -and $v.Reason.Contains('META_DIGEST')) "DIFFERS ($($v.Result) $($v.Reason))"
        Assert-Eq (Get-RstSnapshot $e.Path) $h0 'verify nao grava nada'
        $dir = New-TestCleanLogDir 'rst-diff'
        if (-not $dir) { return }
        $op = New-TestCleanOperator
        $res = Invoke-RstOpen (Get-RstArgs $e $op (Join-Path $dir 'r.jsonl'))
        Assert-True ($res.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($res.Plan.Reasons) -join ';') -like '*ENTRY_VERIFY_DIFFERS*' -and $op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath (Join-Path $dir 'r.jsonl'))) "restauracao recusada ($($res.Aborted) $(@($res.Plan.Reasons) -join ';'))"
        [IO.Directory]::Move((Join-Path $e.Path 'payload'), (Join-Path $e.Path 'payload-fora'))
        Assert-Eq (Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).Result 'PAYLOAD_MISSING' 'payload ausente'
        Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).State 'ISOLATED' 'o estado continua derivado do manifesto'
    }
    Test-Case 'Isolamento P3b' 'Restauracao com a trava fechada: so o plano (plan id com prefixo proprio, frase RESTAURAR <id8>); nada perguntado, nenhum lock, nenhum log, nada movido; quarentena e manifesto identicos' {
        $e = New-RstEntry 'rstclosed'
        if (-not $e) { return }
        $snap = Get-RstSnapshot $script:AtmIsolationQuarantineRoot
        $rec = New-RstPlanRecorder
        $log = Join-Path $sandbox 'rst-closed.jsonl'
        $script:rstReaderCalls = 0
        $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
        try {
            Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
            $res = Invoke-AtmRestore -Id $e.Id -PlanPresenter $rec.Presenter -ConfirmationReader { param($x) $script:rstReaderCalls++; $x } -InventoryArgs $e.Run.IA -LogFile $log -MoveTreeImpl { param($a, $b, $c) throw 'nunca' }
        } finally { $null = Stop-TestLockHolderByGo $h }
        Assert-Eq $res.Aborted 'RESTAURACAO_REAL_DESABILITADA' 'parado pela trava, sem tentar o lock'
        Assert-True ($rec.Calls.Count -eq 1 -and $rec.Calls[0].PlanId -match '^[0-9a-f]{64}$' -and $rec.Calls[0].PlanId -ceq $res.PlanId -and $rec.Calls[0].Plan.Destination -eq $e.Run.Root -and -not $rec.Calls[0].Plan.Conflict) 'plano apresentado uma vez, com o plan id e o destino original'
        Assert-Eq (@($res.Phrases) -join ',') ('RESTAURAR ' + $e.Id8.ToUpperInvariant()) 'frase ligada a entrada'
        Assert-True ($script:rstReaderCalls -eq 0 -and -not (Test-Path -LiteralPath $log) -and @($res.Results).Count -eq 0 -and -not [IO.Directory]::Exists($e.Run.Root)) 'nada perguntado; nenhum log; nada movido'
        Assert-Eq (Get-RstSnapshot $script:AtmIsolationQuarantineRoot) $snap 'quarentena e manifesto identicos'
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        $w = $iso.Substring($iso.IndexOf('function Invoke-AtmRestore {'), $iso.IndexOf('function Invoke-AtmRestoreCore') - $iso.IndexOf('function Invoke-AtmRestore {'))
        Assert-True ($w.IndexOf('if (-not $script:AtmIsolationEnabled) { return (Invoke-AtmRestoreCore @PSBoundParameters) }') -gt 0 -and $w.IndexOf('if (-not $script:AtmIsolationEnabled)') -lt $w.IndexOf('Invoke-AtmUnderSharedLock') -and -not $w.Contains('Invoke-AtmInventory')) 'trava antes do lock'
        $core = $iso.Substring($iso.IndexOf('function Invoke-AtmRestoreCore'))
        $iStop = $core.IndexOf("if (-not `$script:AtmIsolationEnabled) { `$state.Aborted = 'RESTAURACAO_REAL_DESABILITADA'; return (& `$finish) }")
        Assert-True ($iStop -gt 0) 'parada da trava no nucleo da restauracao'
        foreach ($act in @('& $ConfirmationReader', 'Open-AtmCleanLog', '::PinForMove(', '[AgentTempManager.AtmMover]::MoveTree(', '& $MoveTreeImpl', 'Get-AtmEngineConsoleObservation', "& `$writeManifest 'reconcile'", "& `$writeManifest 'restore-intent'")) { Assert-True ($core.IndexOf($act) -gt $iStop) "'$act' so depois da parada da trava" }
        $iMi = $core.IndexOf("& `$writeManifest 'restore-intent'"); $iLi = $core.IndexOf("-Type 'restore-intent'"); $iMv = $core.IndexOf('[AgentTempManager.AtmMover]::MoveTree(')
        Assert-True ($iMi -gt 0 -and $iLi -gt $iMi -and $iMv -gt $iLi) "intencao no manifesto ($iMi) e no log ($iLi) antes do mover ($iMv)"
        Assert-True ($iso.Contains("'atm-restore-plan/1;'")) 'prefixo proprio do plan id da restauracao'
    }
    Test-Case 'Isolamento P3b' 'Restaurar alem da trava, destino livre: a raiz volta inteira ao caminho original (nomes, tamanhos, horarios e atributos), pelo mesmo mover; frase RESTAURAR <id8>; manifesto (OpenExisting) e log completos e sem nomes de arquivo; entrada RESTORED com o manifesto como trilha; restaurar de novo e recusado' {
        $e = New-RstEntry 'rstfull'
        if (-not $e) { return }
        $dir = New-TestCleanLogDir 'rst-full'
        if (-not $dir) { return }
        $log = Join-Path $dir 'restore.jsonl'
        $op = New-TestCleanOperator
        $res = Invoke-RstOpen (Get-RstArgs $e $op $log)
        Assert-True (-not $res.Aborted -and -not $res.StoppedBy -and @($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'COMPLETE' -and $res.Results[0].Moved -and $res.Results[0].Verified) "restaurado ($($res.Aborted)$($res.StoppedBy) $(@($res.Results | ForEach-Object { $_.AbortReason; $_.ExceptionType }) -join ';'))"
        Assert-Eq ($op.Calls -join ',') ("restore|" + $e.Run.Root) 'uma frase, ligada a entrada e ao destino'
        Assert-Eq (@($op.Phrases) -join ',') ('RESTAURAR ' + $e.Id8.ToUpperInvariant()) 'frase RESTAURAR <id8>'
        Assert-Eq (Get-IsoRelativeListing $e.Run.Root) $e.Before 'raiz de volta intacta: nomes, tamanhos, horarios e atributos'
        Assert-True (-not [IO.Directory]::Exists((Join-Path $e.Path 'payload')) -and [IO.File]::Exists($e.Manifest)) 'payload saiu; a entrada e o manifesto ficam'
        $mf = Read-TestCleanLogFile $e.Manifest
        Assert-Eq (@($mf.Records | ForEach-Object { $_.type }) -join ',') 'entry,move-intent,move-result,restore-intent,restore-result' 'registros do manifesto'
        $rr = $mf.Records[4]
        Assert-True ($rr.outcome -ceq 'COMPLETE' -and $rr.verified -and $rr.destination -eq $e.Run.Root -and $rr.digestAfter -ceq $mf.Records[2].digestAfter -and @($mf.Records | Where-Object { $_.schema -cne 'atm.quarantine/1' -or $_.id -cne $e.Id }).Count -eq 0 -and -not $mf.Bom -and $mf.EndsLf) 'restore-result verificado, mesmo resumo dos metadados do isolamento'
        $lg = Read-TestCleanLogFile $log
        Assert-Eq (@($lg.Records | ForEach-Object { $_.type }) -join ',') 'run-start,confirmation,plan-check,restore-intent,restore-result,run-end' 'registros do log'
        Assert-True ($lg.Records[0].operation -ceq 'restore' -and $lg.Records[0].entryId -ceq $e.Id -and @($lg.Records | Where-Object { $_.schema -cne 'atm.isolatelog/1' }).Count -eq 0) 'log atm.isolatelog/1 da restauracao'
        foreach ($t in @([IO.File]::ReadAllText($e.Manifest), [IO.File]::ReadAllText($log))) { foreach ($leaf in @('a.txt', 'b.bin')) { Assert-True (-not $t.Contains($leaf)) "sem nome de arquivo ($leaf)" } }
        $s = Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
        Assert-True ($s.State -ceq 'RESTORED' -and (Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).Result -ceq 'NOT_VERIFIABLE') "entrada RESTORED ($(Format-AtmQuarantineState $s))"
        $again = Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) ($log + '.2'))
        Assert-True ($again.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($again.Plan.Reasons) -join ';') -ceq 'ENTRY_ALREADY_RESTORED' -and -not (Test-Path -LiteralPath ($log + '.2'))) "restaurar de novo: recusado ($(@($again.Plan.Reasons) -join ';'))"
    }
    Test-Case 'Isolamento P3b' 'Conflito (T-ISO-8): o original recriado nunca e sobrescrito nem mesclado; RESTORE_CONFLICT com contagens e o destino alternativo <nome>.restored-<id8> gerado pelo motor, com frase propria (errada: nada movido); alternativo ocupado: recusado' {
        $e = New-RstEntry 'rstconf'
        if (-not $e) { return }
        $dir = New-TestCleanLogDir 'rst-conf'
        if (-not $dir) { return }
        [void][IO.Directory]::CreateDirectory($e.Run.Root); [IO.File]::WriteAllText((Join-Path $e.Run.Root 'novo.txt'), 'novo')
        $orig = Get-IsoRelativeListing $e.Run.Root
        $alt = $e.Run.Root + '.restored-' + $e.Id8
        $rec = New-RstPlanRecorder
        $res = Invoke-AtmRestore -Id $e.Id -PlanPresenter $rec.Presenter -InventoryArgs $e.Run.IA
        $pl = $rec.Calls[0].Plan
        Assert-True ($res.Aborted -ceq 'RESTAURACAO_REAL_DESABILITADA' -and $pl.Conflict -and $pl.ConflictFiles -eq 1 -and $pl.Destination -eq $alt -and @($pl.Reasons).Count -eq 0) "plano: conflito com o alternativo gerado ($($pl.Destination) $(@($pl.Reasons) -join ';'))"
        Assert-Eq (@($res.Phrases) -join ',') ("RESTAURAR {0},RESTAURAR {0} EM DESTINO ALTERNATIVO" -f $e.Id8.ToUpperInvariant()) 'frase propria para o destino alternativo'
        $t = Get-RstHost { Show-AtmRestorePlan -Plan $pl -Inventory $null -PlanId $res.PlanId }
        Assert-True ($t.Contains('RESTORE_CONFLICT') -and $t.Contains($alt) -and -not $t.Contains('novo.txt')) 'relatorio: RESTORE_CONFLICT, contagens e alternativo, sem nomes'
        $op = New-TestCleanOperator -Answers @{ 'alternative#1' = 'RESTAURAR ERRADO' }
        $res = Invoke-RstOpen (Get-RstArgs $e $op (Join-Path $dir 'wrong.jsonl'))
        Assert-True ($res.Aborted -ceq 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' -and $res.RefusedAt.Step -ceq 'alternative' -and @($res.Results).Count -eq 0 -and -not [IO.Directory]::Exists($alt) -and [IO.Directory]::Exists((Join-Path $e.Path 'payload'))) "frase errada do alternativo: nada movido ($($res.Aborted))"
        $op = New-TestCleanOperator
        $res = Invoke-RstOpen (Get-RstArgs $e $op (Join-Path $dir 'ok.jsonl'))
        Assert-True ($res.Results[0].Outcome -ceq 'COMPLETE' -and $res.Results[0].Destination -eq $alt) "restaurado no alternativo ($($res.Aborted)$($res.StoppedBy))"
        Assert-Eq ($op.Calls -join ',') ("restore|$alt,alternative|$alt") 'duas frases, ambas com o destino'
        Assert-Eq (Get-IsoRelativeListing $alt) $e.Before 'alternativo com a raiz intacta'
        Assert-Eq (Get-IsoRelativeListing $e.Run.Root) $orig 'original recriado intocado: sem mescla nem sobrescrita'
        # The alternative already taken: refused.
        $e2 = New-RstEntry 'rstconf2'
        [void][IO.Directory]::CreateDirectory($e2.Run.Root); [void][IO.Directory]::CreateDirectory($e2.Run.Root + '.restored-' + $e2.Id8)
        $rec = New-RstPlanRecorder
        $res = Invoke-AtmRestore -Id $e2.Id -PlanPresenter $rec.Presenter -InventoryArgs $e2.Run.IA
        Assert-True ($res.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($rec.Calls[0].Plan.Reasons) -join ';') -like '*RESTORE_CONFLICT (ALTERNATIVE_EXISTS)*') "alternativo ocupado: recusado ($(@($rec.Calls[0].Plan.Reasons) -join ';'))"
    }
    Test-Case 'Isolamento P3b' 'Interrupcao e reconciliacao (T-ISO-5): move-intent sem resultado com payload integro e origem ausente e reconciliado pela propria restauracao (verify so informa); restore-intent sem resultado tambem; INCOMPLETE sem payload ou com a origem presente: a restauracao recusa sem reconciliar' {
        $dir = New-TestCleanLogDir 'rst-rec'
        if (-not $dir) { return }
        $a = New-RstEntry 'rstreca'
        if (-not $a) { return }
        Set-RstManifestLines -Path $a.Manifest -Keep 2
        $h0 = [IO.File]::ReadAllText($a.Manifest)
        $v = Test-AtmQuarantineEntry -Id $a.Id -OwnSid $testIdentity.Sid
        Assert-True ($v.State -ceq 'INCOMPLETE' -and $v.Result -ceq 'OK' -and $v.Reconcilable -eq $true) "verify: INCOMPLETE reconciliavel ($($v.State) $($v.Result) $($v.Reconcilable))"
        Assert-Eq ([IO.File]::ReadAllText($a.Manifest)) $h0 'verify nao grava a reconciliacao (T-ISO-4)'
        $res = Invoke-RstOpen (Get-RstArgs $a (New-TestCleanOperator) (Join-Path $dir 'a.jsonl'))
        Assert-True ($res.Results[0].Outcome -ceq 'COMPLETE') "restaurado ($($res.Aborted)$($res.StoppedBy))"
        Assert-Eq (Get-RstTypes $a.Manifest) 'entry,move-intent,reconcile,restore-intent,restore-result' 'reconcile gravado pela restauracao antes da intencao'
        Assert-True ((Get-RstTypes (Join-Path $dir 'a.jsonl')).Contains('plan-check,reconcile,restore-intent') -and (Get-IsoRelativeListing $a.Run.Root) -eq $a.Before) 'reconciliacao no log; raiz de volta intacta'
        $b = New-RstEntry 'rstrecb'
        Set-RstManifestLines -Path $b.Manifest -Keep 3 -Append @([ordered]@{ schema = 'atm.quarantine/1'; type = 'restore-intent'; id = $b.Id; recSeq = 4; utc = [datetime]::UtcNow.ToString('o'); opId = 'interrompido:1'; destination = $b.Run.Root; alternative = $false })
        Assert-True ((Get-AtmQuarantineEntry -Id $b.Id -OwnSid $testIdentity.Sid).Pending -ceq 'restore') 'restore-intent sem resultado: INCOMPLETE (restore)'
        $res = Invoke-RstOpen (Get-RstArgs $b (New-TestCleanOperator) (Join-Path $dir 'b.jsonl'))
        Assert-True ($res.Results[0].Outcome -ceq 'COMPLETE' -and (Get-RstTypes $b.Manifest) -ceq 'entry,move-intent,move-result,restore-intent,reconcile,restore-intent,restore-result') "restauracao interrompida reconciliada ($(Get-RstTypes $b.Manifest))"
        $c = New-RstEntry 'rstrecc' @{ MoveTreeImpl = $isoRefused }
        Set-RstManifestLines -Path $c.Manifest -Keep 2
        $h0 = [IO.File]::ReadAllText($c.Manifest)
        $v = Test-AtmQuarantineEntry -Id $c.Id -OwnSid $testIdentity.Sid
        Assert-True ($v.Result -ceq 'PAYLOAD_MISSING' -and $v.Reconcilable -eq $false) "sem payload: nao reconciliavel ($($v.Result) $($v.Reconcilable))"
        $op = New-TestCleanOperator
        $res = Invoke-RstOpen (Get-RstArgs $c $op (Join-Path $dir 'c.jsonl'))
        Assert-True ($res.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($res.Plan.Reasons) -join ';') -like 'ENTRY_INCOMPLETE*' -and $op.Calls.Count -eq 0 -and [IO.File]::ReadAllText($c.Manifest) -ceq $h0 -and [IO.Directory]::Exists($c.Run.Root)) "sem payload: recusado sem reconciliar ($(@($res.Plan.Reasons) -join ';'))"
        $d = New-RstEntry 'rstrecd'
        Set-RstManifestLines -Path $d.Manifest -Keep 2
        [void][IO.Directory]::CreateDirectory($d.Run.Root)
        $res = Invoke-RstOpen (Get-RstArgs $d (New-TestCleanOperator) (Join-Path $dir 'd.jsonl'))
        Assert-True ($res.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($res.Plan.Reasons) -join ';') -like '*ENTRY_INCOMPLETE (ORIGINAL_PRESENT)*') "origem presente: recusado sem reconciliar ($(@($res.Plan.Reasons) -join ';'))"
    }
    Test-Case 'Isolamento P3b' 'Desfechos do mover na restauracao (costura -MoveTreeImpl e mover real): intencao no manifesto e no log ANTES da chamada, com o pai fixado; recusa, excecao e arquivo em uso deixam a entrada ISOLATED; mudanca na janela: RESTORED_INTEGRITY_FAILED e entrada FAILED; nada desfeito' {
        $dir = New-TestCleanLogDir 'rst-out'
        if (-not $dir) { return }
        $cases = @(
            @{ Name = 'refused'; Want = 'REFUSED'; Stop = 'STOPPED_AFTER_REFUSED'; State = 'ISOLATED'; Impl = { param($plan, $dest, $n) $script:rstSeen = @((Get-IsoLiveLastType $script:rstLog), (Get-IsoLiveLastType (Join-Path $plan.Entry.Path 'manifest.jsonl')), [string]$dest.IsPinned, $dest.ParentPath); & $rstRefused $plan $dest $n } },
            @{ Name = 'exception'; Want = 'EXCEPTION'; Stop = 'STOPPED_AFTER_EXCEPTION'; State = 'ISOLATED'; Impl = { param($plan, $dest, $n) throw (New-Object IO.IOException 'synthetic') } },
            @{ Name = 'inuse'; Want = 'REFUSED'; Stop = 'STOPPED_AFTER_REFUSED'; State = 'ISOLATED'; Impl = { param($plan, $dest, $n) $pp = Join-Path $plan.Entry.Path 'payload'; $fs = [IO.File]::Open((Join-Path $pp 'a.txt'), 'Open', 'ReadWrite', 'None'); try { [AgentTempManager.AtmMover]::MoveTree($pp, $plan.Entry.Files, $plan.Entry.Dirs, $plan.Entry.Bytes, (ConvertTo-AtmUtcTicks $plan.Entry.NewestWriteUtc), $dest, $n, $null) } finally { $fs.Dispose() } } },
            @{ Name = 'window'; Want = 'INTEGRITY_FAILED'; Stop = 'RESTORED_INTEGRITY_FAILED'; State = 'FAILED'; Impl = { param($plan, $dest, $n) [AgentTempManager.AtmMover]::MoveTree((Join-Path $plan.Entry.Path 'payload'), $plan.Entry.Files, $plan.Entry.Dirs, $plan.Entry.Bytes, (ConvertTo-AtmUtcTicks $plan.Entry.NewestWriteUtc), $dest, $n, [Action[string]]{ param($p) [IO.File]::WriteAllText((Join-Path $p 'na-janela.txt'), 'x') }) } },
            # PinForMove: a name created by someone else after the plan, between the measurement and the rename. The rename
            # keeps ReplaceIfExists = FALSE: it fails closed and the other folder is never overwritten or merged.
            @{ Name = 'collision'; Want = 'REFUSED'; Stop = 'STOPPED_AFTER_REFUSED'; State = 'ISOLATED'; Impl = { param($plan, $dest, $n) $script:rstTaken = Join-Path $dest.ParentPath $n; [AgentTempManager.AtmMover]::MoveTree((Join-Path $plan.Entry.Path 'payload'), $plan.Entry.Files, $plan.Entry.Dirs, $plan.Entry.Bytes, (ConvertTo-AtmUtcTicks $plan.Entry.NewestWriteUtc), $dest, $n, [Action[string]]{ param($p) [void][IO.Directory]::CreateDirectory($script:rstTaken); [IO.File]::WriteAllText((Join-Path $script:rstTaken 'outro.txt'), 'outro') }) } }
        )
        foreach ($k in $cases) {
            $e = New-RstEntry ('rstout-' + $k.Name)
            if (-not $e) { return }
            $script:rstLog = Join-Path $dir ($k.Name + '.jsonl'); $script:rstSeen = $null
            $res = Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) $script:rstLog @{ MoveTreeImpl = $k.Impl })
            Assert-True (@($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq $k.Want -and $res.StoppedBy -ceq $k.Stop -and -not $res.Aborted) "$($k.Name): $($res.StoppedBy) $($res.Aborted) $(@($res.Results | ForEach-Object { $_.AbortReason; $_.ExceptionType }) -join ';')"
            Assert-Eq (Get-RstTypes $e.Manifest) 'entry,move-intent,move-result,restore-intent,restore-result' "$($k.Name): manifesto registra o desfecho"
            Assert-Eq (Get-RstTypes $script:rstLog) 'run-start,confirmation,plan-check,restore-intent,restore-result,run-end' "$($k.Name): log completo"
            Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).State $k.State "$($k.Name): estado derivado"
            if ($k.Name -ceq 'collision') {
                Assert-True ($res.Results[0].AbortReason -ceq 'MOVE_DEST_EXISTS' -and [IO.Directory]::Exists((Join-Path $e.Path 'payload'))) "nome criado na janela: rename recusado ($($res.Results[0].AbortReason))"
                Assert-True ((@(Get-ChildItem -LiteralPath $e.Run.Root -Force | ForEach-Object { $_.Name }) -join ',') -ceq 'outro.txt' -and [IO.File]::ReadAllText((Join-Path $e.Run.Root 'outro.txt')) -ceq 'outro') 'a pasta do outro processo ficou como estava: nada sobrescrito nem mesclado'
            }
            elseif ($k.State -ceq 'ISOLATED') { Assert-True ([IO.Directory]::Exists((Join-Path $e.Path 'payload')) -and -not [IO.Directory]::Exists($e.Run.Root)) "$($k.Name): payload continua na entrada" }
            else { Assert-True ($res.Results[0].Moved -and -not $res.Results[0].Verified -and [IO.Directory]::Exists($e.Run.Root)) 'janela: movido, nao verificado, nada desfeito' }
            if ($k.Name -ceq 'refused') { Assert-Eq ($script:rstSeen -join ',') ('restore-intent,restore-intent,True,' + [IO.Path]::GetDirectoryName($e.Run.Root)) 'na chamada ao mover: intencao no log e no manifesto (fechado), pai do destino fixado' }
            if ($k.Name -ceq 'inuse') { Assert-True ($res.Results[0].AbortReason -ceq 'MOVE_ACCESS_DENIED') "mover real recusa com arquivo aberto ($($res.Results[0].AbortReason))" }
        }
    }
    Test-Case 'Isolamento P3b' 'Recusas antes do mover na restauracao (manifesto intacto): id invalido, frase errada, sem log, log dentro da quarentena, sem console, lock ocupado (o mesmo do clean), outra identidade; mudanca no payload depois das perguntas: revalidacao recusada' {
        $e = New-RstEntry 'rstrefuse'
        if (-not $e) { return }
        $dir = New-TestCleanLogDir 'rst-refuse'
        if (-not $dir) { return }
        $h0 = [IO.File]::ReadAllText($e.Manifest)
        $n = 0
        $check = { param($Res, [string]$Code, [string]$Label) Assert-True ($Res.Aborted -ceq $Code -and @($Res.Results).Count -eq 0) "${Label}: $($Res.Aborted) (esperado $Code)"; Assert-Eq ([IO.File]::ReadAllText($e.Manifest)) $h0 "${Label}: manifesto intacto"; Assert-True ([IO.Directory]::Exists((Join-Path $e.Path 'payload')) -and -not [IO.Directory]::Exists($e.Run.Root)) "${Label}: nada movido" }
        $next = { $script:rstN++; Join-Path $dir ('r' + $script:rstN + '.jsonl') }
        $script:rstN = 0
        & $check (Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) (& $next) @{ Id = '..\x' })) 'ENTRY_ID_INVALID' 'id invalido'
        & $check (Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator -Answers @{ 'restore#1' = 'RESTAURAR ERRADO' }) (& $next))) 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' 'frase errada'
        $a = Get-RstArgs $e (New-TestCleanOperator) $null; $a.Remove('LogFile')
        & $check (Invoke-RstOpen $a) 'LOG_REQUIRED' 'sem log'
        & $check (Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) (Join-Path $script:AtmIsolationQuarantineRoot 'x.jsonl'))) 'LOG_DESTINATION_NOT_ALLOWED' 'log dentro da quarentena'
        $script:AtmCleanConsoleSource = { $false }
        try { $res = Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) (& $next)) } finally { $script:AtmCleanConsoleSource = { $true } }
        & $check $res 'CONSOLE_NOT_OBSERVED' 'sem console'
        $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
        try { $op = New-TestCleanOperator; $lg = & $next; $res = Invoke-RstOpen (Get-RstArgs $e $op $lg) } finally { $null = Stop-TestLockHolderByGo $h }
        & $check $res 'CLEAN_LOCK_BUSY' 'lock ocupado'
        Assert-True ($op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $lg)) 'lock ocupado: nada perguntado, nenhum log'
        $otherIa = Get-InvArgs -Profiles @($e.Run.Profile) -Identity ([pscustomobject]@{ Sid = 'S-1-5-21-1-2-3-4444'; Name = 'outro'; IsAdmin = $false })
        $res = Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) (& $next) @{ InventoryArgs = $otherIa })
        & $check $res 'RESTAURACAO_RECUSADA' 'outra identidade'
        Assert-True ((@($res.Plan.Reasons) -join ';') -like ('*' + $script:AtmIsolationOwnProfileOnly + '*')) "outra identidade: so o proprio perfil ($(@($res.Plan.Reasons) -join ';'))"
        $hook = { param($plan) [IO.File]::WriteAllText((Join-Path $plan.Entry.Path 'payload\antes-do-mover.txt'), 'novo') }
        $lg = & $next
        $res = Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) $lg @{ BeforeMoveHook = $hook })
        Assert-True ($res.Aborted -ceq 'REVALIDATION_REFUSED' -and @($res.Results).Count -eq 0 -and [IO.File]::ReadAllText($e.Manifest) -ceq $h0) "revalidacao recusada ($($res.Aborted))"
        Assert-True ((Get-RstTypes $lg) -ceq 'run-start,confirmation,plan-check,run-end' -and -not (Read-TestCleanLogFile $lg).Records[2].matched) 'plan-check nao confere, registrado'
    }
    Test-Case 'Isolamento P3b' 'CLI quarantine (processo filho, origem; trava fechada): sem subcomando ou sem -Entry sai com 2; -Entry com caminho sai com 2; entrada inexistente: inspect sai com 3 e restore mostra a recusa e sai com 3; list e verify -All so leem (nada criado); help lista os comandos' {
        $shell = (Get-Process -Id $PID).Path
        $cli = Join-Path $srcDir 'agent-temp.ps1'
        $run = { param([string]$ArgLine, [int]$T = 180) Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$cli`" $ArgLine -Lang en-US -NoProgress") -TimeoutSec $T }
        $usage = 'quarantine requires: list'
        $r = & $run 'quarantine'; Assert-True ($r.Exit -eq 2 -and $r.Text.Contains($usage)) "sem subcomando: exit $($r.Exit)"
        $r = & $run 'quarantine inspect'; Assert-True ($r.Exit -eq 2 -and $r.Text.Contains($usage)) "inspect sem -Entry: exit $($r.Exit)"
        $r = & $run 'quarantine restore'; Assert-True ($r.Exit -eq 2 -and $r.Text.Contains($usage)) "restore sem -Entry: exit $($r.Exit)"
        $r = & $run 'quarantine verify'; Assert-True ($r.Exit -eq 2 -and $r.Text.Contains($usage)) "verify sem -Entry nem -All: exit $($r.Exit)"
        $r = & $run ("quarantine restore -Entry `"$sandbox\x`""); Assert-True ($r.Exit -eq 2 -and $r.Text.Contains('never a path')) "-Entry com caminho: exit $($r.Exit)"
        $la = [Environment]::GetFolderPath('LocalApplicationData'); $home0 = [IO.Directory]::Exists((Join-Path $la 'AgentTempManager'))
        $r = & $run 'quarantine inspect -Entry 20260101T000000Z-0badf00d'; Assert-True ($r.Exit -eq 3 -and $r.Text.Contains('There is no quarantine entry 20260101T000000Z-0badf00d')) "inspect inexistente: exit $($r.Exit)"
        $r = & $run 'quarantine restore -Entry 20260101T000000Z-0badf00d' 300
        Assert-True ($r.Exit -eq 3 -and $r.Text.Contains('ENTRY_NOT_FOUND') -and $r.Text.Contains('RESTAURACAO_RECUSADA') -and $r.Text.Contains('Nothing was moved')) "restore inexistente: exit $($r.Exit)"
        $r = & $run 'quarantine list'; Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('QUARANTINE: ENTRIES') -and $r.Text.Contains('Read only')) "list: exit $($r.Exit)"
        $r = & $run 'quarantine verify -All'; Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('QUARANTINE: VERIFY')) "verify -All: exit $($r.Exit)"
        Assert-Eq ([IO.Directory]::Exists((Join-Path $la 'AgentTempManager'))) $home0 'list e verify nunca criam a quarentena'
        $r = & $run 'help'; Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('agent-temp quarantine list')) "help: exit $($r.Exit)"
    }
    Test-Case 'Isolamento P3b' 'Camadas e estatico: duas chamadas de produto ao mover (isolar e restaurar, so no motor) e OpenExisting so para os manifestos; funcoes de gestao sem escrita; TUI so chama o isolamento e as funcoes de leitura, nunca restaura (T-ISO-6); um unico ponto de restauracao, no lancador; console exigido alem da trava' {
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        $ro = $iso.Substring($iso.IndexOf('function Read-AtmQuarantineManifest'), $iso.IndexOf('function Get-AtmRestorePlanId') - $iso.IndexOf('function Read-AtmQuarantineManifest'))
        foreach ($pat in @('AtmCleanLog', 'OpenExisting', 'AtmSafeCreate', 'AtmMover', 'MoveTree(', 'WriteAll', 'AppendAll', 'File]::Create(', 'CreateDirectory', 'FileAccess]::Write', 'FileAccess]::ReadWrite', '::Move(', 'SetAttributes', 'Set-Content', 'Out-File', 'Write-AtmIsolationRecord')) { Assert-True (-not $ro.Contains($pat)) "list/inspect/verify sem escrita ('$pat')" }
        $tui = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Tui.ps1'))
        foreach ($pat in @('Invoke-AtmRestore', 'PinForMove', 'restore -Entry', 'Read-AtmQuarantineManifest', 'Get-AtmRestorePlan', 'Invoke-AtmPurge', 'Get-AtmPurgePlan', 'purge -Entry', 'AtmQuarantinePurgeEnabled')) { Assert-True (-not $tui.Contains($pat)) "TUI nao restaura nem expurga ('$pat')" }
        Assert-True ($tui.Contains('Get-AtmQuarantineList -OwnSid') -and $tui.Contains('Test-AtmQuarantineEntry -Id') -and [regex]::Matches($tui, 'Invoke-AtmIsolate ').Count -eq 1) 'TUI: leitura pela engine; um unico ponto de isolamento'
        $rep = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Report.ps1'))
        Assert-True (-not $rep.Contains('Invoke-AtmRestore') -and -not $rep.Contains('Invoke-AtmIsolate')) 'relatorio so apresenta'
        $calls = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd') -and $_.Name -ne 'Engine.Isolate.ps1' })) { if ([IO.File]::ReadAllText($fi.FullName).Contains('Invoke-AtmRestore')) { $calls += $fi.Name } }
        Assert-Eq ($calls -join ',') 'agent-temp.ps1' 'so o lancador chama a restauracao'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ([regex]::Matches($cli, 'Invoke-AtmRestore ').Count -eq 1 -and $cli.Contains("if (`$script:AtmIsolationEnabled -and -not (Test-AtmTuiInteractive)) { Write-Host (Get-AtmText 'cli.restoreNeedsConsole')") -and $cli.Contains('-ConfirmationReader $rstReader')) 'CLI: uma chamada; console exigido alem da trava'
        foreach ($l in @('en-US', 'pt-BR')) { foreach ($k in @('help.quarantine', 'cli.quarantineUsage', 'q.cliOnly', 'rst.planOnly', 'rst.conflict', 'menu.isolate', 'menu.quarantine', 'tuiiso.askLog', 'tui.q.cliOnly', 'foot.qdetail')) { Assert-True $script:AtmMessages[$l].ContainsKey($k) "$k ($l)" } }
    }
    Test-Case 'Isolamento P3b' 'PinForMove (Native.cs): a mesma validacao do Pin, so o compartilhamento do pai difere (leitura e escrita, nunca exclusao); Pin inalterado; um unico chamador, como destino do mover na restauracao; no sandbox: renomear para dentro de uma pasta fixada por Pin falha, por PinForMove passa e e conferido; a pasta fixada nao pode ser renomeada' {
        $ncs = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Native.cs'))
        $cut = { param([string]$Sig) $t = $ncs.Substring($ncs.IndexOf($Sig)); return $t.Substring($t.IndexOf('{'), $t.IndexOf('catch (Exception ex) { s.Error = "PIN_"') - $t.IndexOf('{')) }
        $pin = & $cut 'public static AtmSafeCreateSession Pin(string parentDir)'
        $pfm = & $cut 'public static AtmSafeCreateSession PinForMove(string parentDir)'
        $parentOpen = 'SafeFileHandle p = AtmDeleter.OpenChecked(full, true, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | SYNCHRONIZE, '
        Assert-True ($pin.Contains($parentOpen + 'FILE_SHARE_READ, out why, out info);')) 'Pin: pai compartilhado so para leitura (inalterado)'
        Assert-True ($pfm.Contains($parentOpen + 'FILE_SHARE_READ | FILE_SHARE_WRITE, out why, out info);')) 'PinForMove: pai compartilhado para leitura e escrita'
        Assert-True (-not $pfm.Contains('SHARE_DELETE') -and -not $pin.Contains('SHARE_DELETE') -and -not $pfm.Contains('DELETE |')) 'nunca compartilhado nem aberto para exclusao'
        Assert-Eq $pfm.Replace('FILE_SHARE_READ | FILE_SHARE_WRITE, out why, out info);', 'FILE_SHARE_READ, out why, out info);') $pin 'mesma validacao do Pin (unidade fixa, sem subst, canonico, ancestrais fixados, sem reparse, caminho final)'
        $hits = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd', '.cs') })) { $n = [regex]::Matches([IO.File]::ReadAllText($fi.FullName), 'PinForMove\(').Count; if ($n -gt 0) { $hits += ('{0}:{1}' -f $fi.Name, $n) } }
        Assert-Eq (($hits | Sort-Object) -join ',') 'Engine.Isolate.ps1:1,Native.cs:1' 'uma definicao e um unico chamador'
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        $core = $iso.Substring($iso.IndexOf('function Invoke-AtmRestoreCore'))
        Assert-True ($core.IndexOf('::PinForMove(') -gt 0 -and $core.IndexOf('::PinForMove(') -lt $core.IndexOf('[AgentTempManager.AtmMover]::MoveTree(') -and $iso.IndexOf('::PinForMove(') -gt $iso.IndexOf('function Invoke-AtmRestoreCore')) 'so como destino do mover, na restauracao'
        $base = Join-Path $sandbox 'pinformove'; $dst = Join-Path $base 'dest'; [void][IO.Directory]::CreateDirectory($dst)
        $t = Join-Path $base 'src'; [void][IO.Directory]::CreateDirectory((Join-Path $t 'sub')); [IO.File]::WriteAllText((Join-Path $t 'a.txt'), 'a'); [IO.File]::WriteAllText((Join-Path $t 'sub\b.txt'), 'bb')
        $null = Get-StableTreeListing $base
        $s = [AgentTempManager.AtmScanner]::ScanTree($t, 3, 4096)
        $pin = [AgentTempManager.AtmSafeCreate]::Pin($dst)
        try { $r = [AgentTempManager.AtmMover]::MoveTree($t, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $pin, 'com-pin', $null) } finally { $pin.Dispose() }
        Assert-True (-not $r.Moved -and $r.AbortReason -ceq 'MOVE_REFUSED_IN_USE' -and [IO.File]::Exists((Join-Path $t 'a.txt'))) "Pin: renomear para dentro da pasta recusado ($($r.AbortReason))"
        $pm = [AgentTempManager.AtmSafeCreate]::PinForMove($dst)
        try {
            Assert-True ($pm.IsPinned) "PinForMove fixou a pasta ($($pm.Error))"
            $renamed = $true
            try { [IO.Directory]::Move($dst, $dst + '-x') } catch { $renamed = $false }
            Assert-True (-not $renamed -and [IO.Directory]::Exists($dst)) 'a pasta fixada nao pode ser renomeada'
            $r = [AgentTempManager.AtmMover]::MoveTree($t, $s.Files, $s.Dirs, $s.Bytes, $s.NewestWriteTimeUtc.Ticks, $pm, 'restaurado', $null)
            Assert-True ($r.Moved -and $r.Verified -and [IO.File]::Exists((Join-Path $dst 'restaurado\sub\b.txt'))) "PinForMove: movido e conferido ($($r.AbortReason))"
        } finally { $pm.Dispose() }
        foreach ($bad in @('relativo\x', ($dst + '\..\dest'), 'C:\')) {
            $x = [AgentTempManager.AtmSafeCreate]::PinForMove($bad)
            try { Assert-True (-not $x.IsPinned -and $x.Error) "recusado: $bad ($($x.Error))" } finally { $x.Dispose() }
        }
    }

    # ------------------------------------------------------------------ 0.3.x isolation, phase P4: purge, retention, quota and policy (ISO-P4)
    # Entries come from real isolations in the sandbox (New-RstEntry). The purge gate opens only around each call
    # (Invoke-PurOpen) and is restored: the real deleter runs only here, on payloads in the sandbox's quarantine. A policy
    # is written only in a config folder of the sandbox (New-PurConfig), never in the source's.
    function Invoke-PurOpen {
        param([hashtable]$Arguments)
        Assert-True ([string]$script:AtmIsolationQuarantineRoot -and ([string]$script:AtmIsolationQuarantineRoot).StartsWith($sandbox + '\', [StringComparison]::OrdinalIgnoreCase)) "quarentena dentro do sandbox ($($script:AtmIsolationQuarantineRoot))"
        $script:AtmQuarantinePurgeEnabled = $true
        try { return (Invoke-AtmPurge @Arguments) } finally { $script:AtmQuarantinePurgeEnabled = $false }
    }
    function New-PurPlanRecorder {
        $st = @{ Calls = (New-Object System.Collections.Generic.List[object]) }
        $st.Presenter = { param($plan, $inv, $planId, $phrase) $st.Calls.Add([pscustomobject]@{ Plan = $plan; PlanId = $planId; Phrase = $phrase }) }.GetNewClosure()
        return $st
    }
    function Get-PurArgs {
        param($E, $Operator, [string]$Log, [hashtable]$Extra = @{})
        $a = @{ Id = $E.Id; PlanPresenter = (New-PurPlanRecorder).Presenter; ConfirmationReader = $Operator.Reader; InventoryArgs = $E.Run.IA; LogFile = $Log }
        foreach ($k in $Extra.Keys) { $a[$k] = $Extra[$k] }
        return $a
    }
    function New-PurConfig {
        # A config folder of the sandbox: the source's files and, when given, a quarantine.policy.json.
        param([string]$Name, [string]$Policy)
        $d = Join-Path $sandbox ('cfg-' + $Name)
        [void][IO.Directory]::CreateDirectory($d)
        foreach ($f in @(Get-ChildItem -LiteralPath $cfgDir -File)) { [IO.File]::Copy($f.FullName, (Join-Path $d $f.Name), $true) }
        if ($Policy) { [IO.File]::WriteAllText((Join-Path $d 'quarantine.policy.json'), $Policy, (New-Object Text.UTF8Encoding($false))) }
        return $d
    }

    Test-Case 'Isolamento P4' 'Nove travas: cada uma com uma unica atribuicao a $false no seu arquivo; a do expurgo (sexta) so no motor, conferida pelo build, pelo e2e da instalacao e mostrada em version; leitura independente: o expurgo so le a sua, isolar, restaurar, a gestao e os outros motores nunca a leem' {
        foreach ($g in @(@('lib\Engine.Clean.ps1', 'AtmRealDeletionEnabled'), @('lib\Engine.Diagnose.ps1', 'AtmWorktreeDiagnosticsEnabled'), @('lib\Engine.Diagnose.ps1', 'AtmHandleDiagnosticsEnabled'), @('lib\Report.ps1', 'AtmDiagnoseExportEnabled'), @('lib\Engine.Isolate.ps1', 'AtmIsolationEnabled'), @('lib\Engine.Isolate.ps1', 'AtmQuarantinePurgeEnabled'), @('lib\Gui.ps1', 'AtmGuiEnabled'), @('lib\Engine.Recover.ps1', 'AtmRecoveryEnabled'), @('lib\Engine.Monitor.ps1', 'AtmMonitoringEnabled'))) {
            $t = [IO.File]::ReadAllText((Join-Path $srcDir $g[0]))
            Assert-True ([regex]::Matches($t, '\$script:' + $g[1] + '\s*=').Count -eq 1 -and $t -match ('(?m)^\$script:' + $g[1] + ' = \$false\r?$')) "$($g[1]): uma unica atribuicao, a `$false ($($g[0]))"
        }
        Assert-Eq $script:AtmQuarantinePurgeEnabled $false 'trava do expurgo fechada neste processo'
        foreach ($f in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Name -ne 'Engine.Isolate.ps1' })) {
            Assert-True (-not ([regex]::IsMatch([IO.File]::ReadAllText($f.FullName), 'AtmQuarantinePurgeEnabled\s*='))) "$($f.Name) nao pode alterar a trava do expurgo"
        }
        $root = Split-Path -Parent $testsDir
        $br = [IO.File]::ReadAllText((Join-Path $root 'tools\Build-Release.ps1'))
        Assert-True ($br.Contains("@(`$isoTxt, 'AtmQuarantinePurgeEnabled')") -and $br.Contains("@(`$isoTxt, 'AtmIsolationEnabled')") -and $br.Contains("@(`$repTxt, 'AtmDiagnoseExportEnabled')")) 'build recusa o pacote sem as travas fechadas, a do expurgo inclusive'
        $e2e = [IO.File]::ReadAllText((Join-Path $testsDir 'e2e\Invoke-InstallE2E.ps1'))
        Assert-True ($e2e.Contains("AtmQuarantinePurgeEnabled = 'lib\Engine.Isolate.ps1'") -and $e2e.Contains("Step 'shipped-purge-gate'") -and $e2e.Contains('nine installed gates')) 'e2e confere as travas instaladas (seis ate a 0.3.x; sete desde a V0.2.1 P1, com a da GUI; oito desde a V0.4 R1, com a da recuperacao; nove desde a V0.5 M1, com a do monitoramento)'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.Contains("Get-AtmText 'cli.purge' `$(if (`$script:AtmQuarantinePurgeEnabled)") -and $cli.Contains('Get-AtmQuarantinePolicyLines -Policy (Get-AtmQuarantinePolicy')) 'version mostra a trava do expurgo e a politica efetiva'
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        $iP = $iso.IndexOf('function Invoke-AtmPurge {')
        $pur = $iso.Substring($iP)
        Assert-True ($iP -gt 0 -and -not $pur.Contains('AtmIsolationEnabled') -and -not $pur.Contains('AtmRealDeletionEnabled')) 'o expurgo so le a propria trava'
        Assert-Eq ([regex]::Matches($iso.Substring(0, $iP), '\$script:AtmQuarantinePurgeEnabled').Count) 1 'isolar, restaurar e a gestao nunca leem a trava do expurgo (so a atribuicao)'
        foreach ($n in @('lib\Engine.Clean.ps1', 'lib\Engine.Audit.ps1', 'lib\Engine.Diagnose.ps1', 'lib\Tui.ps1')) { Assert-True (-not [IO.File]::ReadAllText((Join-Path $srcDir $n)).Contains('AtmQuarantinePurgeEnabled')) "$n nunca le a trava do expurgo" }
    }
    Test-Case 'Isolamento P4' 'Travas independentes nos dois sentidos: com a do isolamento aberta (e a de exclusao do clean, aberta pela suite) o expurgo para em EXPURGO_REAL_DESABILITADO sem perguntar; com a do expurgo aberta, isolar e restaurar param nas suas e o clean com a sua fechada para na dele; o expurgo alem da sua trava funciona com as outras fechadas' {
        $e = New-RstEntry 'purindep'
        if (-not $e) { return }
        $dir = New-TestCleanLogDir 'pur-indep'
        if (-not $dir) { return }
        $snap = Get-RstSnapshot $e.Path
        $op = New-TestCleanOperator
        $a1 = Get-PurArgs $e $op (Join-Path $dir 'iso-aberta.jsonl')
        $script:AtmIsolationEnabled = $true
        try { $r1 = Invoke-AtmPurge @a1 } finally { $script:AtmIsolationEnabled = $false }
        Assert-True ($r1.Aborted -ceq 'EXPURGO_REAL_DESABILITADO' -and $op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath (Join-Path $dir 'iso-aberta.jsonl')) -and $script:AtmRealDeletionEnabled) "isolamento e exclusao abertos nao abrem o expurgo ($($r1.Aborted))"
        $x = New-IsoRun 'purindepx'
        if (-not $x) { return }
        $before = Get-IsoRelativeListing $x.Root
        $ai = Get-IsoArgs $x (New-TestCleanOperator)
        $ar = Get-RstArgs $e (New-TestCleanOperator) (Join-Path $dir 'rst.jsonl')
        $script:AtmQuarantinePurgeEnabled = $true
        try {
            $ri = Invoke-AtmIsolate @ai
            $rr = Invoke-AtmRestore @ar
            $script:AtmRealDeletionEnabled = $false
            try { $rc = Invoke-AtmClean -Entries @([pscustomobject]@{ Source = 't'; Path = $x.Root; Fingerprint = $null }) -PlanPresenter { param($v, $r, $i) } -ConfirmationReader { param($p) $p } -InventoryArgs $x.IA -LogWriter (New-TestCleanLogWriter) }
            finally { $script:AtmRealDeletionEnabled = $true }
        } finally { $script:AtmQuarantinePurgeEnabled = $false }
        Assert-True ($ri.Aborted -ceq 'ISOLAMENTO_REAL_DESABILITADO' -and $rr.Aborted -ceq 'RESTAURACAO_REAL_DESABILITADA' -and $rc.Aborted -ceq 'EXCLUSAO_REAL_DESABILITADA_V0_1') "expurgo aberto: isolar $($ri.Aborted), restaurar $($rr.Aborted), clean $($rc.Aborted)"
        Assert-Eq (Get-IsoRelativeListing $x.Root) $before 'nada isolado nem apagado'
        Assert-Eq (Get-RstSnapshot $e.Path) $snap 'entrada identica: nada restaurado nem expurgado'
        $script:AtmRealDeletionEnabled = $false
        try { $rp = Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) (Join-Path $dir 'purge.jsonl')) } finally { $script:AtmRealDeletionEnabled = $true }
        Assert-True (@($rp.Results).Count -eq 1 -and $rp.Results[0].Outcome -ceq 'COMPLETE' -and $script:AtmIsolationEnabled -eq $false) "so a trava do expurgo aberta: expurgado ($($rp.Aborted)$($rp.StoppedBy))"
    }
    Test-Case 'Isolamento P4' 'Expurgo com a trava fechada: so o plano (plan id com prefixo proprio, frase EXPURGAR <id8> <arquivos> ARQUIVOS) e EXPURGO_REAL_DESABILITADO; nada perguntado, nenhum lock, nenhum log, nada expurgado; o relatorio diz que nenhum espaco foi liberado; quarentena e manifesto identicos (bytes e horarios)' {
        $e = New-RstEntry 'purclosed'
        if (-not $e) { return }
        $snap = Get-RstSnapshot $script:AtmIsolationQuarantineRoot
        $rec = New-PurPlanRecorder
        $log = Join-Path $sandbox 'pur-closed.jsonl'
        $script:purReaderCalls = 0
        $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
        try {
            Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
            $res = Invoke-AtmPurge -Id $e.Id -PlanPresenter $rec.Presenter -ConfirmationReader { param($x) $script:purReaderCalls++; $x } -InventoryArgs $e.Run.IA -LogFile $log -PurgeTreeImpl { param($p) throw 'nunca' }
        } finally { $null = Stop-TestLockHolderByGo $h }
        Assert-Eq $res.Aborted 'EXPURGO_REAL_DESABILITADO' 'parado pela trava, sem tentar o lock'
        $phrase = 'EXPURGAR {0} 2 ARQUIVOS' -f $e.Id8.ToUpperInvariant()
        $pl = $rec.Calls[0].Plan
        Assert-True ($rec.Calls.Count -eq 1 -and $rec.Calls[0].PlanId -match '^[0-9a-f]{64}$' -and $rec.Calls[0].PlanId -ceq $res.PlanId -and $rec.Calls[0].Phrase -ceq $phrase -and $res.Phrase -ceq $phrase) 'plano apresentado uma vez, com o plan id e a frase'
        Assert-True (@($pl.Reasons).Count -eq 0 -and $pl.Files -eq 2 -and $pl.Dirs -eq 1 -and $pl.Bytes -eq 2148 -and $pl.Uninspectable -eq 0 -and $pl.PayloadPath -eq (Join-Path $e.Path 'payload')) "plano sem recusas, com a medicao do manifesto ($(@($pl.Reasons) -join ';'))"
        Assert-True ($script:purReaderCalls -eq 0 -and -not (Test-Path -LiteralPath $log) -and @($res.Results).Count -eq 0 -and [IO.File]::Exists((Join-Path $e.Path 'payload\a.txt'))) 'nada perguntado; nenhum log; nada expurgado'
        $old = Get-AtmLanguage
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $t = Get-RstHost { Show-AtmPurgePlan -Plan $pl -PlanId $res.PlanId -Phrase $res.Phrase; Show-AtmPurgeResult -Result $res }
                Assert-True ($t.Contains((Get-AtmText 'pur.planOnly')) -and $t.Contains((Get-AtmText 'pur.gateMsg')) -and $t.Contains($phrase) -and $t.Contains($e.Id) -and -not $t.Contains('a.txt') -and -not $t.Contains('b.bin')) "$lang`: so o plano, nenhum espaco liberado, sem nomes de arquivo"
            }
        } finally { Set-AtmLanguage -Requested $old }
        Assert-Eq (Get-RstSnapshot $script:AtmIsolationQuarantineRoot) $snap 'quarentena e manifesto identicos'
        Assert-True ([IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1')).Contains("'atm-purge-plan/1;'")) 'prefixo proprio do plan id do expurgo'
    }
    Test-Case 'Isolamento P4' 'Expurgar alem da trava (no processo da suite, quarentena do sandbox): declaracoes AUT-2 do proprio expurgo e a frase EXPURGAR <id8> <arquivos> ARQUIVOS; intencao no manifesto e no log; uma chamada ao deleter real com a medicao do manifesto; payload ausente, entrada e manifesto ficam como trilha (PURGED); log completo sem nomes de arquivo; restaurar ou expurgar de novo e recusado' {
        $e = New-RstEntry 'purfull'
        if (-not $e) { return }
        $dir = New-TestCleanLogDir 'pur-full'
        if (-not $dir) { return }
        $log = Join-Path $dir 'purge.jsonl'
        $op = New-TestCleanOperator
        $res = Invoke-PurOpen (Get-PurArgs $e $op $log @{ Interaction = @{ Caller = 'CLI'; ConsoleRequired = $true } })
        Assert-True (-not $res.Aborted -and -not $res.StoppedBy -and @($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'COMPLETE' -and $res.Results[0].Verified -and $res.Results[0].FilesDeleted -eq 2) "expurgado ($($res.Aborted)$($res.StoppedBy) $(@($res.Results | ForEach-Object { $_.AbortReason; $_.ExceptionType }) -join ';'))"
        Assert-Eq ($op.Calls -join ',') ('task|{0},results|{0},purge|{1}' -f $e.Run.Root, $e.Id) 'declaracoes do proprio expurgo (as do isolamento nao contam), depois a frase ligada a entrada'
        Assert-Eq $op.Phrases[2] ('EXPURGAR {0} 2 ARQUIVOS' -f $e.Id8.ToUpperInvariant()) 'frase EXPURGAR <id8> <arquivos> ARQUIVOS'
        Assert-True ($res.Declaration.TaskCompleted -and $res.Declaration.ContentDecision) 'declaracao registrada no resultado'
        Assert-True (-not [IO.Directory]::Exists((Join-Path $e.Path 'payload')) -and [IO.File]::Exists($e.Manifest) -and -not [IO.Directory]::Exists($e.Run.Root)) 'payload expurgado; entrada e manifesto ficam; nada restaurado'
        $mf = Read-TestCleanLogFile $e.Manifest
        Assert-Eq (@($mf.Records | ForEach-Object { $_.type }) -join ',') 'entry,move-intent,move-result,purge-intent,purge-result' 'registros do manifesto'
        $pi = $mf.Records[3]; $pr = $mf.Records[4]
        Assert-True ($pi.automatic -eq $false -and $pi.declaredBy -ceq 'OPERATOR' -and $pi.files -eq 2 -and $pr.outcome -ceq 'COMPLETE' -and $pr.automatic -eq $false -and $pr.verifiedGone -eq $true -and $pi.opId -ceq $pr.opId) 'purge-intent e purge-result (automatic false), a mesma operacao'
        Assert-True (@($mf.Records | Where-Object { $_.schema -cne 'atm.quarantine/1' -or $_.id -cne $e.Id }).Count -eq 0 -and -not $mf.Bom -and $mf.EndsLf) 'manifesto atm.quarantine/1 da entrada'
        $lg = Read-TestCleanLogFile $log
        Assert-Eq (@($lg.Records | ForEach-Object { $_.type }) -join ',') 'run-start,declaration,confirmation,plan-check,purge-intent,purge-result,run-end' 'registros do log'
        Assert-True ($lg.Records[0].operation -ceq 'purge' -and $lg.Records[0].entryId -ceq $e.Id -and $lg.Records[1].declaredBy -ceq 'OPERATOR' -and $lg.Records[2].accepted -and $lg.Records[2].interaction.caller -ceq 'CLI' -and $lg.Records[3].matched) 'run-start, declaracao, confirmacao e plan-check'
        Assert-True ($lg.Records[5].outcome -ceq 'COMPLETE' -and $lg.Records[5].automatic -eq $false -and @($lg.Records | Where-Object { $_.schema -cne 'atm.purgelog/1' }).Count -eq 0 -and -not $lg.Bom -and $lg.EndsLf) 'log atm.purgelog/1 do expurgo'
        foreach ($t in @([IO.File]::ReadAllText($e.Manifest), [IO.File]::ReadAllText($log))) { foreach ($leaf in @('a.txt', 'b.bin')) { Assert-True (-not $t.Contains($leaf)) "sem nome de arquivo ($leaf)" } }
        $s = Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
        Assert-True ($s.State -ceq 'PURGED' -and -not $s.PayloadPresent -and (Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).Result -ceq 'NOT_VERIFIABLE') "entrada PURGED ($(Format-AtmQuarantineState $s))"
        $old = Get-AtmLanguage
        try { foreach ($lang in @('en-US', 'pt-BR')) { Set-AtmLanguage -Requested $lang; $t = Get-RstHost { Show-AtmPurgeResult -Result $res }; Assert-True ($t.Contains('COMPLETE') -and $t.Contains($e.Id) -and -not $t.Contains('a.txt')) "$lang`: resultado do expurgo" } } finally { Set-AtmLanguage -Requested $old }
        $rr = Invoke-RstOpen (Get-RstArgs $e (New-TestCleanOperator) (Join-Path $dir 'rst.jsonl'))
        Assert-True ($rr.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($rr.Plan.Reasons) -join ';') -ceq 'ENTRY_PURGED') "restaurar entrada expurgada: recusado ($(@($rr.Plan.Reasons) -join ';'))"
        $op2 = New-TestCleanOperator
        $again = Invoke-PurOpen (Get-PurArgs $e $op2 (Join-Path $dir 'again.jsonl'))
        Assert-True ($again.Aborted -ceq 'EXPURGO_RECUSADO' -and (@($again.Plan.Reasons) -join ';') -ceq 'PURGE_REFUSED_PURGED' -and $op2.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath (Join-Path $dir 'again.jsonl'))) "expurgar de novo: recusado ($(@($again.Plan.Reasons) -join ';'))"
    }
    Test-Case 'Isolamento P4' 'Recusas por estado (gate aberto, antes de qualquer pergunta ou log; manifesto intacto; nunca uma nova tentativa com verificacao mais fraca): ABANDONED, DIFFERS, PAYLOAD_MISSING, PURGED, payload depois de PURGED (PAYLOAD_AFTER_PURGE), expurgo interrompido (INCOMPLETE purge: restauracao tambem recusa, nunca reconciliavel, nada excluido), INCOMPLETE, FAILED, RESTORED, UNRECOGNIZED, ENTRY_MANIFEST_INVALID e entrada inexistente' {
        $dir = New-TestCleanLogDir 'pur-states'
        if (-not $dir) { return }
        $script:purN = 0
        $refuse = {
            param($E, [string]$Want, [string]$Label, [hashtable]$Extra = @{})
            $op = New-TestCleanOperator; $script:purN++; $lg = Join-Path $dir ('s' + $script:purN + '.jsonl')
            $h0 = $(if ($E.Manifest -and [IO.File]::Exists($E.Manifest)) { [IO.File]::ReadAllText($E.Manifest) } else { $null })
            $res = Invoke-PurOpen (Get-PurArgs $E $op $lg $Extra)
            $why = @($res.Plan.Reasons) -join ';'
            Assert-True ($res.Aborted -ceq 'EXPURGO_RECUSADO' -and $why -like $Want -and @($res.Results).Count -eq 0 -and $op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $lg)) "${Label}: $($res.Aborted) $why (esperado $Want)"
            if ($null -ne $h0) { Assert-Eq ([IO.File]::ReadAllText($E.Manifest)) $h0 "${Label}: manifesto intacto" }
        }
        $a = New-RstEntry 'purstate'
        if (-not $a) { return }
        $otherIa = Get-InvArgs -Profiles @($a.Run.Profile) -Identity ([pscustomobject]@{ Sid = 'S-1-5-21-1-2-3-4444'; Name = 'outro'; IsAdmin = $false })
        & $refuse $a 'PURGE_REFUSED_ABANDONED' 'outra identidade' @{ InventoryArgs = $otherIa }
        [IO.File]::WriteAllText((Join-Path $a.Path 'payload\depois.txt'), 'x')
        & $refuse $a 'PURGE_REFUSED_DIFFERS (*FILES 3/2*' 'payload divergente'
        [IO.Directory]::Move((Join-Path $a.Path 'payload'), (Join-Path $a.Path 'payload-fora'))
        & $refuse $a 'PURGE_REFUSED_PAYLOAD_MISSING*' 'payload ausente'
        $u = [datetime]::UtcNow.ToString('o')
        Set-RstManifestLines -Path $a.Manifest -Keep 3 -Append @([ordered]@{ schema = 'atm.quarantine/1'; type = 'purge-intent'; id = $a.Id; recSeq = 4; utc = $u; opId = 'x:1'; files = 2; dirs = 1; bytes = 2148; automatic = $false }, [ordered]@{ schema = 'atm.quarantine/1'; type = 'purge-result'; id = $a.Id; recSeq = 5; utc = $u; opId = 'x:1'; outcome = 'COMPLETE'; automatic = $false })
        Assert-Eq (Get-AtmQuarantineEntry -Id $a.Id -OwnSid $testIdentity.Sid).State 'PURGED' 'purge-result COMPLETE sem payload: PURGED'
        & $refuse $a 'PURGE_REFUSED_PURGED' 'ja expurgada'
        # A payload present while the manifest says PURGED: an invalid entry, never purged.
        [IO.Directory]::Move((Join-Path $a.Path 'payload-fora'), (Join-Path $a.Path 'payload'))
        & $refuse $a 'PURGE_REFUSED_ENTRY_MANIFEST_INVALID (PAYLOAD_AFTER_PURGE)' 'payload depois de PURGED'
        # purge-intent without purge-result (an interrupted purge): INCOMPLETE, refused by purge and restore, not reconcilable.
        Set-RstManifestLines -Path $a.Manifest -Keep 3 -Append @([ordered]@{ schema = 'atm.quarantine/1'; type = 'purge-intent'; id = $a.Id; recSeq = 4; utc = $u; opId = 'x:2'; files = 2; dirs = 1; bytes = 2148; automatic = $false })
        $s = Get-AtmQuarantineEntry -Id $a.Id -OwnSid $testIdentity.Sid
        Assert-True ($s.State -ceq 'INCOMPLETE' -and $s.Pending -ceq 'purge') "purge-intent sem resultado: INCOMPLETE (purge) ($(Format-AtmQuarantineState $s))"
        & $refuse $a 'PURGE_REFUSED_INCOMPLETE (purge)' 'expurgo interrompido'
        $rr = Invoke-AtmRestore -Id $a.Id -PlanPresenter (New-RstPlanRecorder).Presenter -InventoryArgs $a.Run.IA
        Assert-True ($rr.Aborted -ceq 'RESTAURACAO_RECUSADA' -and (@($rr.Plan.Reasons) -join ';') -like '*ENTRY_INCOMPLETE (PURGE_PENDING)*') "expurgo interrompido: restauracao recusada ($(@($rr.Plan.Reasons) -join ';'))"
        Assert-True ((Test-AtmQuarantineEntry -Id $a.Id -OwnSid $testIdentity.Sid).Reconcilable -eq $false) 'expurgo interrompido: nunca reconciliavel'
        Assert-True ([IO.File]::Exists((Join-Path $a.Path 'payload\a.txt')) -and [IO.File]::Exists((Join-Path $a.Path 'payload\sub\b.bin'))) 'expurgo interrompido: nada excluido'
        Set-RstManifestLines -Path $a.Manifest -Keep 2
        & $refuse $a 'PURGE_REFUSED_INCOMPLETE (move)' 'intencao sem resultado'
        $b = New-RstEntry 'purstatef' @{ MoveTreeImpl = $isoRefused }
        & $refuse $b 'PURGE_REFUSED_FAILED' 'isolamento recusado (FAILED)'
        $c = New-RstEntry 'purstater'
        $rr = Invoke-RstOpen (Get-RstArgs $c (New-TestCleanOperator) (Join-Path $dir 'rst.jsonl'))
        Assert-True (@($rr.Results).Count -eq 1 -and $rr.Results[0].Outcome -ceq 'COMPLETE') "restaurada ($($rr.Aborted)$($rr.StoppedBy))"
        & $refuse $c 'PURGE_REFUSED_RESTORED' 'restaurada (RESTORED)'
        Assert-True ([IO.Directory]::Exists($c.Run.Root)) 'a raiz restaurada nunca e tocada pelo expurgo'
        & $refuse ([pscustomobject]@{ Id = '20260101T000000Z-0badf00d'; Run = $c.Run; Manifest = $null }) 'PURGE_REFUSED_ENTRY_NOT_FOUND' 'entrada inexistente'
        # Hand-made folders in a quarantine of their own.
        $qc = Join-Path $sandbox 'pur-states\Q'
        $i1 = '20260101T000000Z-0000a001'; [void][IO.Directory]::CreateDirectory((Join-Path $qc ($i1 + '\payload')))
        $tgt = Join-Path $sandbox 'pur-states-alvo'; [void][IO.Directory]::CreateDirectory((Join-Path $tgt 'payload')); [IO.File]::WriteAllText((Join-Path $tgt 'payload\x.txt'), 'x')
        $i2 = '20260101T000000Z-0000a002'; New-Junction (Join-Path $qc $i2) $tgt
        $saved = $script:AtmIsolationQuarantineRoot
        $script:AtmIsolationQuarantineRoot = $qc
        try {
            & $refuse ([pscustomobject]@{ Id = $i1; Run = $c.Run; Manifest = $null }) 'PURGE_REFUSED_ENTRY_MANIFEST_INVALID (MANIFEST_MISSING)' 'manifesto ausente'
            & $refuse ([pscustomobject]@{ Id = $i2; Run = $c.Run; Manifest = $null }) 'PURGE_REFUSED_UNRECOGNIZED' 'juncao no lugar de uma entrada'
        } finally { $script:AtmIsolationQuarantineRoot = $saved }
        Assert-True ([IO.File]::Exists((Join-Path $tgt 'payload\x.txt')) -and [IO.Directory]::Exists((Join-Path $qc ($i1 + '\payload')))) 'nada expurgado no alvo da juncao nem na pasta sem manifesto'
    }
    Test-Case 'Isolamento P4' 'Recusas antes do deleter (gate aberto; manifesto e payload intactos): id invalido, sem apresentacao, sem leitor, frase errada, declaracao da tarefa ou do conteudo recusada, sem log, log dentro da quarentena, sem console, lock ocupado (o mesmo do clean); linha de comando que cita a quarentena (B2-1 estendido) recusa no plano; mudanca no payload depois das perguntas: revalidacao recusada' {
        $e = New-RstEntry 'purrefuse'
        if (-not $e) { return }
        $dir = New-TestCleanLogDir 'pur-refuse'
        if (-not $dir) { return }
        $h0 = [IO.File]::ReadAllText($e.Manifest)
        $intact = { [IO.File]::Exists((Join-Path $e.Path 'payload\a.txt')) -and [IO.File]::Exists((Join-Path $e.Path 'payload\sub\b.bin')) -and [IO.File]::ReadAllText($e.Manifest) -ceq $h0 }
        $check = { param($Res, [string]$Code, [string]$Label) Assert-True ($Res.Aborted -ceq $Code -and @($Res.Results).Count -eq 0) "${Label}: $($Res.Aborted) (esperado $Code)"; Assert-True (& $intact) "${Label}: manifesto e payload intactos" }
        $script:purN = 0
        $next = { $script:purN++; Join-Path $dir ('r' + $script:purN + '.jsonl') }
        & $check (Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) (& $next) @{ Id = '..\x' })) 'ENTRY_ID_INVALID' 'id invalido'
        $a = Get-PurArgs $e (New-TestCleanOperator) (& $next); $a.Remove('PlanPresenter')
        & $check (Invoke-PurOpen $a) 'SEM_APRESENTACAO' 'sem apresentacao'
        $a = Get-PurArgs $e (New-TestCleanOperator) (& $next); $a.Remove('ConfirmationReader')
        & $check (Invoke-PurOpen $a) 'SEM_APRESENTACAO_OU_CONFIRMACAO' 'sem leitor'
        $op = New-TestCleanOperator -Answers @{ 'purge#1' = 'EXPURGAR ERRADO' }; $lg = & $next
        $res = Invoke-PurOpen (Get-PurArgs $e $op $lg)
        & $check $res 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' 'frase errada'
        Assert-True ($res.RefusedAt.Step -ceq 'purge' -and (Get-RstTypes $lg) -ceq 'run-start,confirmation,run-end' -and -not (Read-TestCleanLogFile $lg).Records[1].accepted) 'frase errada: recusa registrada no log, sem declaracao'
        $op = New-TestCleanOperator -Answers @{ 'task#1' = 'NAO TERMINEI' }
        $res = Invoke-PurOpen (Get-PurArgs $e $op (& $next))
        Assert-True ($res.Aborted -like 'DECLARATION_*' -and $res.RefusedAt.Step -ceq 'task' -and $op.Calls.Count -eq 1 -and (& $intact)) "declaracao da tarefa recusada ($($res.Aborted))"
        $op = New-TestCleanOperator -Answers @{ 'results#1' = 'TALVEZ' }
        $res = Invoke-PurOpen (Get-PurArgs $e $op (& $next))
        Assert-True ($res.Aborted -like 'DECLARATION_*' -and $res.RefusedAt.Step -ceq 'results' -and $op.Calls.Count -eq 2 -and (& $intact)) "declaracao do conteudo recusada ($($res.Aborted))"
        $a = Get-PurArgs $e (New-TestCleanOperator) $null; $a.Remove('LogFile')
        & $check (Invoke-PurOpen $a) 'LOG_REQUIRED' 'sem log'
        & $check (Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) (Join-Path $script:AtmIsolationQuarantineRoot 'x.jsonl'))) 'LOG_DESTINATION_NOT_ALLOWED' 'log dentro da quarentena'
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $script:AtmIsolationQuarantineRoot 'x.jsonl'))) 'nada criado na quarentena'
        $script:AtmCleanConsoleSource = { $false }
        try { $res = Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) (& $next)) } finally { $script:AtmCleanConsoleSource = { $true } }
        & $check $res 'CONSOLE_NOT_OBSERVED' 'sem console'
        $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
        try { $op = New-TestCleanOperator; $lg = & $next; $res = Invoke-PurOpen (Get-PurArgs $e $op $lg) } finally { $null = Stop-TestLockHolderByGo $h }
        & $check $res 'CLEAN_LOCK_BUSY' 'lock ocupado'
        Assert-True ($op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $lg)) 'lock ocupado: nada perguntado, nenhum log'
        # B2-1 extended to the quarantine: a command line that names it (any slash form) refuses; one that only starts like it does not.
        $q = $script:AtmIsolationQuarantineRoot
        $proc = { param([string]$Cmd) [pscustomobject]@{ ProcessId = 4321; Name = 'tool.exe'; ParentProcessId = 0; CommandLine = $Cmd; CreationDate = (Get-Date).AddHours(-1) } }
        $iaRef = Get-InvArgs -Profiles @($e.Run.Profile) -Procs (New-Procs -Extra @((& $proc ('tool.exe --dir "' + $q.Replace('\', '/') + '/' + $e.Id + '"'))))
        $op = New-TestCleanOperator; $lg = & $next
        $res = Invoke-PurOpen (Get-PurArgs $e $op $lg @{ InventoryArgs = $iaRef })
        & $check $res 'EXPURGO_RECUSADO' 'linha de comando cita a quarentena'
        Assert-True ((@($res.Plan.Reasons) -join ';') -ceq 'RUNTIME_QUARANTINE_REFERENCED (1)' -and $op.Calls.Count -eq 0 -and -not (Test-Path -LiteralPath $lg)) "B2-1 estendido a quarentena, so a contagem ($(@($res.Plan.Reasons) -join ';'))"
        $iaNear = Get-InvArgs -Profiles @($e.Run.Profile) -Procs (New-Procs -Extra @((& $proc ('tool.exe ' + $q + 'X'))))
        $res = Invoke-AtmPurge -Id $e.Id -PlanPresenter (New-PurPlanRecorder).Presenter -InventoryArgs $iaNear
        Assert-True ($res.Aborted -ceq 'EXPURGO_REAL_DESABILITADO' -and @($res.Plan.Reasons).Count -eq 0) "nome que so comeca como a quarentena nao conta ($(@($res.Plan.Reasons) -join ';'))"
        # Last: a change in the payload after the questions.
        $hook = { param($plan) [IO.File]::WriteAllText((Join-Path $plan.PayloadPath 'depois.txt'), 'novo') }
        $lg = & $next
        $res = Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) $lg @{ BeforePurgeHook = $hook; PurgeTreeImpl = { param($p) throw 'nunca' } })
        Assert-True ($res.Aborted -ceq 'REVALIDATION_REFUSED' -and @($res.Results).Count -eq 0 -and [IO.File]::ReadAllText($e.Manifest) -ceq $h0 -and [IO.File]::Exists((Join-Path $e.Path 'payload\a.txt')) -and [IO.File]::Exists((Join-Path $e.Path 'payload\depois.txt'))) "revalidacao recusada, nada expurgado ($($res.Aborted))"
        Assert-True ((Get-RstTypes $lg) -ceq 'run-start,declaration,confirmation,plan-check,run-end' -and -not (Read-TestCleanLogFile $lg).Records[3].matched) 'plan-check nao confere, registrado'
    }
    Test-Case 'Isolamento P4' 'Desfechos do deleter no expurgo (deleter real e costura -PurgeTreeImpl): intencao no manifesto e no log ANTES da chamada; medicao divergente: o deleter recusa antes da primeira exclusao (so o codigo do motivo) e a entrada fica ISOLATED, depois expurgavel; excecao: FAILED; arquivo em uso: recusado no plano pela sonda (gate 8) e, aberto depois da revalidacao, nunca apagado; nada repetido' {
        $dir = New-TestCleanLogDir 'pur-out'
        if (-not $dir) { return }
        $e = New-RstEntry 'purout-differs'
        if (-not $e) { return }
        $before = Get-IsoRelativeListing (Join-Path $e.Path 'payload')
        $script:purLog = Join-Path $dir 'differs.jsonl'; $script:purSeen = $null
        $impl = { param($plan) $script:purSeen = @((Get-IsoLiveLastType $script:purLog), (Get-IsoLiveLastType (Join-Path $plan.Entry.Path 'manifest.jsonl'))); [AgentTempManager.AtmDeleter]::DeleteTree($plan.PayloadPath, $plan.Files + 1, $plan.Dirs, $plan.Bytes, $plan.NewestTicks, $null) }
        $res = Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) $script:purLog @{ PurgeTreeImpl = $impl })
        Assert-True (@($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'REFUSED' -and $res.StoppedBy -ceq 'STOPPED_AFTER_REFUSED' -and $res.Results[0].AbortReason -ceq 'PLAN_DIFFERS_FROM_VALIDATED_MEASUREMENT' -and $res.Results[0].FilesDeleted -eq 0 -and $res.Results[0].Attempted -eq $false) "medicao divergente: recusado antes da primeira exclusao ($($res.StoppedBy) $(@($res.Results | ForEach-Object { $_.AbortReason }) -join ';'))"
        Assert-Eq ($script:purSeen -join ',') 'purge-intent,purge-intent' 'na chamada ao deleter: intencao no log e no manifesto'
        Assert-Eq (Get-IsoRelativeListing (Join-Path $e.Path 'payload')) $before 'payload intacto'
        Assert-Eq (Get-RstTypes $e.Manifest) 'entry,move-intent,move-result,purge-intent,purge-result' 'manifesto registra o desfecho'
        Assert-Eq (Get-RstTypes $script:purLog) 'run-start,declaration,confirmation,plan-check,purge-intent,purge-result,run-end' 'log completo'
        $mr = (Read-TestCleanLogFile $e.Manifest).Records[4]
        Assert-True ($mr.outcome -ceq 'REFUSED' -and $mr.abortReason -ceq 'PLAN_DIFFERS_FROM_VALIDATED_MEASUREMENT' -and -not ([IO.File]::ReadAllText($e.Manifest)).Contains($e.Path)) 'so o codigo do motivo, sem caminho'
        Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).State 'ISOLATED' 'recusa do deleter: entrada continua ISOLATED'
        $res = Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) (Join-Path $dir 'differs-2.jsonl'))
        Assert-True (@($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'COMPLETE' -and (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).State -ceq 'PURGED') "nova execucao confirmada pelo operador: expurgada ($($res.Aborted)$($res.StoppedBy))"
        $x = New-RstEntry 'purout-exc'
        $res = Invoke-PurOpen (Get-PurArgs $x (New-TestCleanOperator) (Join-Path $dir 'exc.jsonl') @{ PurgeTreeImpl = { param($plan) throw (New-Object IO.IOException 'synthetic') } })
        Assert-True (@($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'EXCEPTION' -and $res.StoppedBy -ceq 'STOPPED_AFTER_EXCEPTION' -and $res.Results[0].ExceptionType -ceq 'IOException') "excecao ($($res.StoppedBy))"
        Assert-Eq (Get-AtmQuarantineEntry -Id $x.Id -OwnSid $testIdentity.Sid).State 'FAILED' 'excecao: estado do payload desconhecido, entrada FAILED'
        $u = New-RstEntry 'purout-inuse'
        $op = New-TestCleanOperator
        $fs = [IO.File]::Open((Join-Path $u.Path 'payload\a.txt'), 'Open', 'ReadWrite', 'None')
        try { $res = Invoke-PurOpen (Get-PurArgs $u $op (Join-Path $dir 'inuse-plan.jsonl')) } finally { $fs.Dispose() }
        Assert-True ($res.Aborted -ceq 'EXPURGO_RECUSADO' -and @($res.Plan.Reasons).Count -gt 0 -and $op.Calls.Count -eq 0 -and [IO.File]::Exists((Join-Path $u.Path 'payload\a.txt'))) "em uso no plano: recusado pela sonda ($(@($res.Plan.Reasons).Count) motivo(s))"
        $impl = { param($plan) $h = [IO.File]::Open((Join-Path $plan.PayloadPath 'a.txt'), 'Open', 'ReadWrite', 'None'); try { [AgentTempManager.AtmDeleter]::DeleteTree($plan.PayloadPath, $plan.Files, $plan.Dirs, $plan.Bytes, $plan.NewestTicks, $null) } finally { $h.Dispose() } }
        $res = Invoke-PurOpen (Get-PurArgs $u (New-TestCleanOperator) (Join-Path $dir 'inuse.jsonl') @{ PurgeTreeImpl = $impl })
        $o = @($res.Results)[0]
        Assert-True (@($res.Results).Count -eq 1 -and @('REFUSED', 'PARTIAL') -ccontains $o.Outcome -and $res.StoppedBy -ceq ('STOPPED_AFTER_' + $o.Outcome) -and [IO.File]::Exists((Join-Path $u.Path 'payload\a.txt'))) "arquivo em uso no deleter: nunca apagado ($($o.Outcome) $($o.AbortReason))"
        Assert-Eq (Get-AtmQuarantineEntry -Id $u.Id -OwnSid $testIdentity.Sid).State $(if ($o.Outcome -ceq 'REFUSED') { 'ISOLATED' } else { 'FAILED' }) 'estado derivado do desfecho'
        $script:caseNote = "arquivo em uso no deleter: $($o.Outcome) $($o.AbortReason)"
    }
    Test-Case 'Isolamento P4' 'Retencao (relogio injetavel, so na suite): padrao de 30 dias marca EXPIRED a entrada ISOLATED, com a data, em list, inspect e verify; politica valida de 60 dias substitui o padrao; so ISOLATED vira EXPIRED (FAILED continua FAILED); EXPIRED so marca, nada gravado nem expurgado; a entrada EXPIRED so sai pelo comando confirmado' {
        $e = New-RstEntry 'purexp'
        $f = New-RstEntry 'purexpf' @{ MoveTreeImpl = $isoRefused }
        if (-not $e -or -not $f) { return }
        $dir = New-TestCleanLogDir 'pur-exp'
        if (-not $dir) { return }
        $snap = Get-RstSnapshot $e.Path
        $p60 = Get-AtmQuarantinePolicy -ConfigDir (New-PurConfig 'ret60' '{"schema":"atm.quarantine-policy/1","retentionDays":60}')
        Assert-True ($p60.Source -ceq 'FILE' -and $p60.RetentionDays -eq 60) 'politica de 60 dias'
        $old = Get-AtmLanguage
        try {
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(29) }
            $s = Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
            Assert-True ($s.State -ceq 'ISOLATED' -and $s.ExpiresUtc -gt [datetime]::UtcNow.AddDays(29) -and $s.ExpiresUtc -le [datetime]::UtcNow.AddDays(30)) "29 dias: ISOLATED, marca em 30 dias ($($s.ExpiresUtc.ToString('o')))"
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(31) }
            $s = Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
            $l = Get-AtmQuarantineList -OwnSid $testIdentity.Sid
            $le = @($l.Entries | Where-Object { $_.Id -ceq $e.Id })[0]
            $v = Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid
            Assert-True ($s.State -ceq 'EXPIRED' -and $le.State -ceq 'EXPIRED' -and $le.ExpiresUtc -eq $s.ExpiresUtc -and $v.Result -ceq 'OK' -and $v.State -ceq 'EXPIRED') "31 dias, padrao: EXPIRED em inspect, list e verify ($($s.State) $($le.State) $($v.Result))"
            Assert-Eq (@($l.Entries | Where-Object { $_.Id -ceq $f.Id })[0].State) 'FAILED' 'so ISOLATED vira EXPIRED'
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $t = Get-RstHost { Show-AtmQuarantineList -List $l; Show-AtmQuarantineEntry -Entry $s }
                Assert-True ($t.Contains('EXPIRED') -and $t.Contains((Get-AtmText 'q.expired' (Format-AtmTime $s.ExpiresUtc))) -and $t.Contains((Get-AtmText 'q.cliPurge' $e.Id)) -and $t.Contains((Format-AtmQuarantinePolicy $l.Policy))) "$lang`: EXPIRED com a data, comando de expurgo e politica"
            }
            Set-AtmLanguage -Requested $old
            Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid -Policy $p60).State 'ISOLATED' 'politica de 60 dias: ainda ISOLATED aos 31'
            Assert-Eq (@((Get-AtmQuarantineList -OwnSid $testIdentity.Sid -Policy $p60).Entries | Where-Object { $_.Id -ceq $e.Id })[0].State) 'ISOLATED' 'list com a politica: ISOLATED'
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(61) }
            Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid -Policy $p60).State 'EXPIRED' 'politica de 60 dias: EXPIRED aos 61'
            Assert-Eq (Get-RstSnapshot $e.Path) $snap 'EXPIRED so marca: payload e manifesto identicos'
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(31) }
            $rec = New-PurPlanRecorder
            $res = Invoke-PurOpen (Get-PurArgs $e (New-TestCleanOperator) (Join-Path $dir 'purge.jsonl') @{ PlanPresenter = $rec.Presenter })
            Assert-True ($rec.Calls[0].Plan.Entry.State -ceq 'EXPIRED' -and @($res.Results).Count -eq 1 -and $res.Results[0].Outcome -ceq 'COMPLETE') "EXPIRED expurgada pelo comando confirmado ($($res.Aborted)$($res.StoppedBy))"
            Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).State 'PURGED' 'PURGED nunca volta a EXPIRED'
        } finally { $script:AtmQuarantineClock = $null; Set-AtmLanguage -Requested $old }
    }
    Test-Case 'Isolamento P4' 'Quota: com quotaBytes da politica atingida, list avisa (QUARANTINE_QUOTA_REACHED, uso e quota) e um novo isolamento e recusado antes de qualquer pergunta ou log; a quota nunca expurga: quarentena identica e a raiz no lugar; sem quota (padrao) o uso nem e medido' {
        $x = New-IsoRun 'purquota'
        if (-not $x) { return }
        $cfg = New-PurConfig 'quota' '{"schema":"atm.quarantine-policy/1","quotaBytes":1}'
        $x.IA['ConfigDir'] = $cfg
        $q = $script:AtmIsolationQuarantineRoot
        Assert-True ([IO.Directory]::Exists($q)) 'quarentena do sandbox com entradas'
        $snap = Get-RstSnapshot $q
        $before = Get-IsoRelativeListing $x.Root
        $op = New-TestCleanOperator
        $res = Invoke-IsoOpen (Get-IsoArgs $x $op)
        Assert-True ($res.Aborted -ceq 'NENHUM_CAMINHO_ISOLAVEL' -and (Get-IsoRejectedReason $res $x.Root) -like '*QUARANTINE_QUOTA_REACHED*' -and $op.Calls.Count -eq 0 -and -not $res.EntryId -and -not (Test-Path -LiteralPath $x.Log)) "isolamento recusado pela quota ($($res.Aborted): $(Get-IsoRejectedReason $res $x.Root))"
        Assert-Eq (Get-IsoRelativeListing $x.Root) $before 'raiz no lugar'
        Assert-Eq (Get-RstSnapshot $q) $snap 'a quota nunca expurga: quarentena identica'
        $pol = Get-AtmQuarantinePolicy -ConfigDir $cfg
        $l = Get-AtmQuarantineList -OwnSid $testIdentity.Sid -Policy $pol
        Assert-True ($pol.QuotaBytes -eq 1 -and $l.QuotaReached -and $l.UsedBytes -gt 0) "list: quota atingida ($($l.UsedBytes))"
        $t = Get-RstHost { Show-AtmQuarantineList -List $l }
        Assert-True ($t.Contains((Get-AtmText 'q.quotaReached')) -and $t.Contains((Get-AtmText 'q.usage' (Format-AtmMB $l.UsedBytes) (Format-AtmMB 1)))) 'aviso da quota e uso no list'
        $l0 = Get-AtmQuarantineList -OwnSid $testIdentity.Sid -Policy (Get-AtmQuarantinePolicy -ConfigDir $cfgDir)
        Assert-True ($null -eq $l0.UsedBytes -and -not $l0.QuotaReached) 'sem quota: uso nao medido'
        Assert-Eq (Get-RstSnapshot $q) $snap 'list so leu'
    }
    Test-Case 'Isolamento P4' 'Politica config\quarantine.policy.json (esquema estrito atm.quarantine-policy/1): ausente = padrao; valida substitui (com ou sem BOM); invalida (campo extra, outro esquema, sem esquema, tipos, limites, nao JSON, vazia, grande demais) vale como DESLIGADA com aviso; autoPurge = true e lido, mostrado e avisado (ligado: so o ponto de entrada da P6a age), e list, inspect e verify nao expurgam; capacidade: quota e espaco livre minimo fixo no codigo so recusam' {
        $cfgP = New-PurConfig 'policy' $null
        $pf = Join-Path $cfgP 'quarantine.policy.json'
        $set = { param([string]$T, [bool]$Bom = $false) [IO.File]::WriteAllText($pf, $T, (New-Object Text.UTF8Encoding($Bom))) }
        $off = { param($P) $P.RetentionDays -eq 30 -and $null -eq $P.QuotaBytes -and -not $P.AutoPurge }
        $p0 = Get-AtmQuarantinePolicy -ConfigDir $cfgP
        Assert-True ($p0.Source -ceq 'DEFAULT' -and (& $off $p0) -and @($p0.Warnings).Count -eq 0) 'ausente: padrao (30 dias, sem quota, autoPurge false)'
        foreach ($bom in @($false, $true)) {
            & $set '{"schema":"atm.quarantine-policy/1","retentionDays":7,"quotaBytes":1048576,"autoPurge":false}' $bom
            $p1 = Get-AtmQuarantinePolicy -ConfigDir $cfgP
            Assert-True ($p1.Source -ceq 'FILE' -and $p1.RetentionDays -eq 7 -and $p1.QuotaBytes -eq 1048576 -and -not $p1.AutoPurge -and @($p1.Warnings).Count -eq 0) "valida (BOM $bom): $($p1.Source) $($p1.RetentionDays) $($p1.QuotaBytes)"
        }
        $bads = @('{"schema":"atm.quarantine-policy/1","retentionDays":7,"extra":1}', '{"schema":"atm.quarantine-policy/2"}', '{"retentionDays":7}', '{"Schema":"atm.quarantine-policy/1"}',
            '{"schema":"atm.quarantine-policy/1","retentionDays":"7"}', '{"schema":"atm.quarantine-policy/1","retentionDays":7.5}', '{"schema":"atm.quarantine-policy/1","retentionDays":0}', '{"schema":"atm.quarantine-policy/1","retentionDays":3651}',
            '{"schema":"atm.quarantine-policy/1","quotaBytes":0}', '{"schema":"atm.quarantine-policy/1","quotaBytes":-1}', '{"schema":"atm.quarantine-policy/1","autoPurge":"yes"}', '{"schema":"atm.quarantine-policy/1","autoPurge":1}',
            '[1,2]', 'nao e json', '', ('{"schema":"atm.quarantine-policy/1"}' + (' ' * 70000)))
        foreach ($bad in $bads) {
            & $set $bad
            $pb = Get-AtmQuarantinePolicy -ConfigDir $cfgP
            Assert-True ($pb.Source -ceq 'INVALID' -and (& $off $pb) -and (@($pb.Warnings) -join ',') -ceq 'QUARANTINE_POLICY_INVALID') "invalida vale como desligada: $(if ($bad.Length -gt 80) { $bad.Substring(0, 40) + '...' } else { $bad })"
        }
        & $set '{"schema":"atm.quarantine-policy/1","autoPurge":true}'
        $pa = Get-AtmQuarantinePolicy -ConfigDir $cfgP
        Assert-True ($pa.Source -ceq 'FILE' -and $pa.AutoPurge -and $pa.RetentionDays -eq 30 -and (@($pa.Warnings) -join ',') -ceq 'AUTOPURGE_ON') 'autoPurge true: lido e avisado (ligado)'
        $old = Get-AtmLanguage
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $t = (@(Get-AtmQuarantinePolicyLines -Policy $pa) | ForEach-Object { $_.Text }) -join "`n"
                Assert-True ($t.Contains((Format-AtmQuarantinePolicy $pa)) -and $t.Contains((Get-AtmText 'q.policyWarn.AUTOPURGE_ON')) -and $t.Contains((Get-AtmText 'q.policySource.FILE'))) "$lang`: autoPurge mostrado com o aviso"
                $t = (@(Get-AtmQuarantinePolicyLines -Policy $pb) | ForEach-Object { $_.Text }) -join "`n"
                Assert-True ($t.Contains((Get-AtmText 'q.policyWarn.QUARANTINE_POLICY_INVALID')) -and $t.Contains((Get-AtmText 'q.policySource.INVALID'))) "$lang`: politica invalida avisada"
            }
        } finally { Set-AtmLanguage -Requested $old }
        # autoPurge = true acts only through bin\agent-temp-autopurge.ps1 (P6a): an EXPIRED entry stays as it is through
        # list, inspect and verify.
        $e = New-RstEntry 'purauto'
        if (-not $e) { return }
        $snap = Get-RstSnapshot $e.Path
        $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(31) }
        try {
            $l = Get-AtmQuarantineList -OwnSid $testIdentity.Sid -Policy $pa
            $null = Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid -Policy $pa
            $v = Test-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid -Policy $pa
        } finally { $script:AtmQuarantineClock = $null }
        Assert-True (@($l.Entries | Where-Object { $_.Id -ceq $e.Id })[0].State -ceq 'EXPIRED' -and $v.Result -ceq 'OK' -and $l.Policy.AutoPurge) 'EXPIRED com autoPurge true'
        Assert-Eq (Get-RstSnapshot $e.Path) $snap 'autoPurge nao fez nada: payload e manifesto identicos'
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        $pol = $iso.Substring($iso.IndexOf('function Get-AtmQuarantinePolicy'), $iso.IndexOf('function Get-AtmQuarantineUsage') - $iso.IndexOf('function Get-AtmQuarantinePolicy'))
        # P6a: the policy's autoPurge is read in the policy function and, outside it, only by the automatic pass; P6b: and
        # once by schedule-autopurge, only to warn that nothing happens while it is off.
        $apw = $iso.Substring($iso.IndexOf('function Invoke-AtmAutoPurge {'), $iso.IndexOf('function Invoke-AtmAutoPurgeCore') - $iso.IndexOf('function Invoke-AtmAutoPurge {'))
        $aps = $iso.Substring($iso.IndexOf('function Invoke-AtmAutoPurgeSchedule {'), $iso.IndexOf('function Invoke-AtmAutoPurgeUnschedule {') - $iso.IndexOf('function Invoke-AtmAutoPurgeSchedule {'))
        Assert-Eq ([regex]::Matches($iso, '\.AutoPurge\b').Count) ([regex]::Matches($pol, '\.AutoPurge\b').Count + [regex]::Matches($apw, '\.AutoPurge\b').Count + [regex]::Matches($aps, '\.AutoPurge\b').Count) 'autoPurge so lido na politica, na passada automatica e no aviso do agendamento (motor)'
        Assert-Eq ([regex]::Matches($apw, '\.AutoPurge\b').Count) 1 'a passada automatica le autoPurge uma vez'
        Assert-Eq ([regex]::Matches($aps, '\.AutoPurge\b').Count) 1 'o agendamento le autoPurge uma vez (so para avisar)'
        # The policy field, not the TUI's own state keys (AutoPurgeNotice, AutoPurgeTask: display only, P6b).
        foreach ($n in @('agent-temp.ps1', 'lib\Tui.ps1', 'lib\Engine.Clean.ps1', 'lib\Engine.Audit.ps1', 'lib\Engine.Diagnose.ps1')) { Assert-True (-not [regex]::IsMatch([IO.File]::ReadAllText((Join-Path $srcDir $n)), '\.AutoPurge\b')) "$n nao usa autoPurge" }
        Assert-Eq ([regex]::Matches([IO.File]::ReadAllText((Join-Path $srcDir 'lib\Report.ps1')), '\.AutoPurge').Count) 2 'relatorio so mostra autoPurge (linha da politica e aviso de ligado)'
        # Capacity: refusals only (QUARANTINE_QUOTA_REACHED, LOW_DISK_SPACE with the minimum fixed in code); nothing purged.
        $q = $script:AtmIsolationQuarantineRoot
        $pq = [pscustomobject]@{ RetentionDays = 30; QuotaBytes = 1000L; AutoPurge = $false; Source = 'FILE'; Warnings = @() }
        Assert-Eq (@(Get-AtmQuarantineCapacityRefusal -QuarantineRoot $q -Bytes 10 -Policy $pq -UsedBytes 100 -FreeBytes 1GB) -join ',') '' 'quota nao atingida'
        Assert-Eq (@(Get-AtmQuarantineCapacityRefusal -QuarantineRoot $q -Bytes 950 -Policy $pq -UsedBytes 100 -FreeBytes 1GB) -join ',') 'QUARANTINE_QUOTA_REACHED' 'a quota seria ultrapassada'
        Assert-Eq (@(Get-AtmQuarantineCapacityRefusal -QuarantineRoot $q -Bytes 0 -Policy $pq -UsedBytes 1000 -FreeBytes 1GB) -join ',') 'QUARANTINE_QUOTA_REACHED' 'quota atingida'
        Assert-Eq (@(Get-AtmQuarantineCapacityRefusal -QuarantineRoot $q -Bytes 0 -Policy $p0 -FreeBytes ($script:AtmQuarantineMinFreeBytes - 1)) -join ',') 'LOW_DISK_SPACE' 'espaco livre abaixo do minimo fixo'
        Assert-True ([regex]::Matches($iso, '\$script:AtmQuarantineMinFreeBytes\s*=').Count -eq 1 -and -not $iso.Contains('minFreeBytes')) 'minimo fixo no codigo, sem chave nova de politica'
    }
    Test-Case 'Isolamento P4' 'Politica preservada na atualizacao: instalada sem politica; a do administrador sobrevive ao -Update byte a byte e fica no manifesto da nova copia (verify passa); version da copia instalada mostra a politica efetiva; uma politica invalida tambem e preservada e vale como desligada' {
        $inst = Join-Path $sandbox 'PFP4\AgentTempManager'
        [void][IO.Directory]::CreateDirectory((Split-Path -Parent $inst))
        $inArgs = @{ SourceDir = $srcDir; InstallDir = $inst; TrustSid = $me.Sid; SkipPath = $true; SourceWithoutManifest = $true }
        $null = Install-AtmProduct @inArgs
        $pf = Join-Path $inst 'config\quarantine.policy.json'
        Assert-True (-not (Test-Path -LiteralPath $pf)) 'instalado sem politica'
        $cmd = Join-Path $inst 'bin\agent-temp.cmd'
        $r = Invoke-AtmTestChild -CommandLine ("`"$cmd`" version -Lang en-US") -TimeoutSec 180
        Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('quarantine purge: DISABLED') -and $r.Text.Contains('retention 30 day(s)') -and $r.Text.Contains('default: no policy file')) "version sem politica ($($r.Exit))"
        $text = '{"schema":"atm.quarantine-policy/1","retentionDays":7,"quotaBytes":1048576,"autoPurge":false}'
        [IO.File]::WriteAllText($pf, $text, (New-Object Text.UTF8Encoding($false)))
        $null = Install-AtmProduct @inArgs -Update
        Assert-Eq ([IO.File]::ReadAllText($pf)) $text 'politica preservada byte a byte'
        $man = Get-Content -LiteralPath (Join-Path $inst 'manifest.json') -Raw
        Assert-True ($man.Contains('quarantine.policy.json')) 'politica no manifesto da nova copia'
        $r = Invoke-AtmTestChild -CommandLine ("`"$cmd`" verify") -TimeoutSec 180
        Assert-Eq $r.Exit 0 "verify da copia atualizada ($($r.Text))"
        $r = Invoke-AtmTestChild -CommandLine ("`"$cmd`" version -Lang en-US") -TimeoutSec 180
        Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('retention 7 day(s)') -and $r.Text.Contains('config\quarantine.policy.json') -and $r.Text.Contains('quarantine purge: DISABLED')) "version mostra a politica instalada ($($r.Exit))"
        $bad = '{"schema":"atm.quarantine-policy/1","retentionDays":0}'
        [IO.File]::WriteAllText($pf, $bad, (New-Object Text.UTF8Encoding($false)))
        $null = Install-AtmProduct @inArgs -Update
        Assert-Eq ([IO.File]::ReadAllText($pf)) $bad 'politica invalida tambem preservada'
        $r = Invoke-AtmTestChild -CommandLine ("`"$cmd`" version -Lang en-US") -TimeoutSec 180
        Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('QUARANTINE_POLICY_INVALID') -and $r.Text.Contains('retention 30 day(s)')) "invalida vale como desligada na copia instalada ($($r.Exit))"
        Uninstall-AtmProduct -InstallDir $inst | Out-Null
        Assert-True (-not (Test-Path -LiteralPath $inst)) 'desinstalado'
    }
    Test-Case 'Isolamento P4' 'CLI quarantine purge (processo filho, origem; trava fechada): sem -Entry sai com 2; -Entry com caminho sai com 2; entrada inexistente: o plano recusa (PURGE_REFUSED_ENTRY_NOT_FOUND, EXPURGO_RECUSADO), sai com 3 e nada e criado; version mostra a trava do expurgo DESABILITADA e a politica efetiva; help lista o comando' {
        $shell = (Get-Process -Id $PID).Path
        $cli = Join-Path $srcDir 'agent-temp.ps1'
        $run = { param([string]$ArgLine, [int]$T = 180) Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$cli`" $ArgLine -Lang en-US -NoProgress") -TimeoutSec $T }
        $r = & $run 'quarantine purge'; Assert-True ($r.Exit -eq 2 -and $r.Text.Contains('quarantine requires: list')) "purge sem -Entry: exit $($r.Exit)"
        $r = & $run ("quarantine purge -Entry `"$sandbox\x`""); Assert-True ($r.Exit -eq 2 -and $r.Text.Contains('never a path')) "-Entry com caminho: exit $($r.Exit)"
        $la = [Environment]::GetFolderPath('LocalApplicationData'); $home0 = [IO.Directory]::Exists((Join-Path $la 'AgentTempManager'))
        $r = & $run 'quarantine purge -Entry 20260101T000000Z-0badf00d' 300
        Assert-True ($r.Exit -eq 3 -and $r.Text.Contains('PURGE_REFUSED_ENTRY_NOT_FOUND') -and $r.Text.Contains('EXPURGO_RECUSADO') -and -not $r.Text.Contains('EXPURGAR ')) "purge inexistente: exit $($r.Exit)"
        Assert-Eq ([IO.Directory]::Exists((Join-Path $la 'AgentTempManager'))) $home0 'purge com a trava fechada nunca cria a quarentena'
        $r = & $run 'version'
        Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('quarantine purge: DISABLED') -and $r.Text.Contains('no space is freed') -and $r.Text.Contains('retention 30 day(s)') -and $r.Text.Contains('default: no policy file')) "version: trava do expurgo e politica ($($r.Exit))"
        $r = & $run 'help'; Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('purge -Entry <id>')) "help: exit $($r.Exit)"
    }
    Test-Case 'Isolamento P4' 'Camadas e estatico: uma chamada de produto ao deleter no clean e uma no expurgo (so alem da trava, depois da intencao no manifesto e no log); duas ao mover (isolar e restaurar); relatorio, TUI e lancador nunca chamam o deleter; so o lancador chama o expurgo, uma vez; costura do relogio com atribuicao unica; textos nos dois idiomas' {
        $hits = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd') })) { $n = [regex]::Matches([IO.File]::ReadAllText($fi.FullName), 'AtmDeleter\]::DeleteTree\(').Count; if ($n -gt 0) { $hits += ('{0}:{1}' -f $fi.Name, $n) } }
        Assert-Eq (($hits | Sort-Object) -join ',') 'Engine.Clean.ps1:1,Engine.Isolate.ps1:1' 'deleter: uma chamada de produto no clean e uma no expurgo'
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        Assert-Eq ([regex]::Matches($iso, 'AtmMover\]::MoveTree\(').Count) 2 'mover: isolar e restaurar'
        $core = $iso.Substring($iso.IndexOf('function Invoke-AtmPurgeCore'))
        $iGate = $core.IndexOf("`$state.Aborted = 'EXPURGO_REAL_DESABILITADO'")
        $iMi = $core.IndexOf("& `$writeManifest 'purge-intent'"); $iLi = $core.IndexOf("-Type 'purge-intent'"); $iDel = $core.IndexOf('[AgentTempManager.AtmDeleter]::DeleteTree(')
        Assert-True ($iGate -gt 0 -and $iMi -gt $iGate -and $iLi -gt $iMi -and $iDel -gt $iLi -and $iso.IndexOf('[AgentTempManager.AtmDeleter]::DeleteTree(') -gt $iso.IndexOf('function Invoke-AtmPurgeCore')) "ordem: trava $iGate < intencao no manifesto $iMi < no log $iLi < deleter $iDel"
        foreach ($act in @('& $ConfirmationReader', 'Open-AtmCleanLog', 'Get-AtmEngineConsoleObservation', '& $PurgeTreeImpl', '& $BeforePurgeHook', "& `$writeManifest")) { Assert-True ($core.IndexOf($act) -gt $iGate) "'$act' so depois da parada da trava" }
        $w = $iso.Substring($iso.IndexOf('function Invoke-AtmPurge {'), $iso.IndexOf('function Invoke-AtmPurgeCore') - $iso.IndexOf('function Invoke-AtmPurge {'))
        Assert-True ($w.IndexOf('if (-not $script:AtmQuarantinePurgeEnabled) { return (Invoke-AtmPurgeCore @PSBoundParameters) }') -gt 0 -and $w.IndexOf('if (-not $script:AtmQuarantinePurgeEnabled)') -lt $w.IndexOf('Invoke-AtmUnderSharedLock') -and -not $w.Contains('Invoke-AtmInventory')) 'trava antes do lock'
        $calls = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd') -and $_.Name -ne 'Engine.Isolate.ps1' })) { if ([IO.File]::ReadAllText($fi.FullName).Contains('Invoke-AtmPurge')) { $calls += $fi.Name } }
        Assert-Eq ($calls -join ',') 'agent-temp.ps1' 'so o lancador chama o expurgo'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ([regex]::Matches($cli, 'Invoke-AtmPurge ').Count -eq 1 -and $cli.Contains("if (`$script:AtmQuarantinePurgeEnabled -and -not (Test-AtmTuiInteractive)) { Write-Host (Get-AtmText 'cli.purgeNeedsConsole')") -and $cli.Contains('-ConfirmationReader $purReader')) 'CLI: uma chamada; console exigido alem da trava'
        foreach ($n in @('lib\Report.ps1', 'lib\Tui.ps1', 'agent-temp.ps1')) { $t = [IO.File]::ReadAllText((Join-Path $srcDir $n)); Assert-True (-not $t.Contains('AtmDeleter') -and -not $t.Contains('DeleteTree')) "$n nunca chama o deleter" }
        Assert-True ([regex]::Matches($iso, '\$script:AtmQuarantineClock\s*=').Count -eq 1 -and $iso -match '(?m)^\$script:AtmQuarantineClock = \$null\r?$') 'costura do relogio: atribuicao unica $null no motor'
        foreach ($l in @('en-US', 'pt-BR')) {
            foreach ($k in @('cli.purge', 'cli.purgeDisabled', 'cli.purgeNeedsConsole', 'col.expires', 'q.expires', 'q.expired', 'q.cliPurge', 'q.policy', 'q.quotaOff', 'q.quotaBytes', 'q.usage', 'q.usageUnmeasured', 'q.quotaReached', 'q.policySource.DEFAULT', 'q.policySource.FILE', 'q.policySource.INVALID', 'q.policyWarn.QUARANTINE_POLICY_INVALID', 'q.policyWarn.AUTOPURGE_ON', 'pur.planOnly', 'pur.gateMsg', 'pur.phraseEntry', 'pur.purged', 'pur.nothingPurged', 'pur.resultRow')) { Assert-True $script:AtmMessages[$l].ContainsKey($k) "$k ($l)" }
        }
        foreach ($k in @($script:AtmMessages['en-US'].Keys | Where-Object { $_ -like 'pur.*' })) { Assert-True $script:AtmMessages['pt-BR'].ContainsKey($k) "$k tambem em pt-BR" }
    }

    # ------------------------------------------------------------------ 0.3.x isolation, phase P6a: the automatic purge entry point (ISO-P6a)
    # The pass reads every entry of the quarantine it is given, so each case uses a quarantine of its own in the sandbox
    # (Enter-ApQuarantine, restored in finally), the clock seam for EXPIRED and a config folder of the sandbox for the
    # policy. The purge gate opens only around each call (Invoke-ApOpen) and is restored. The entry point itself runs only
    # in child processes on a staged copy, never where it would read the runner's own quarantine.
    function Enter-ApQuarantine {
        param([string]$Name)
        [void][IO.Directory]::CreateDirectory((Join-Path $sandbox $Name))
        $script:AtmIsolationQuarantineRoot = Join-Path $sandbox ($Name + '\AgentTempManager\Q')
    }
    function Invoke-ApOpen {
        param([hashtable]$Arguments)
        Assert-True ([string]$script:AtmIsolationQuarantineRoot -and ([string]$script:AtmIsolationQuarantineRoot).StartsWith($sandbox + '\', [StringComparison]::OrdinalIgnoreCase)) "quarentena dentro do sandbox ($($script:AtmIsolationQuarantineRoot))"
        $script:AtmQuarantinePurgeEnabled = $true
        try { return (Invoke-AtmAutoPurge @Arguments) } finally { $script:AtmQuarantinePurgeEnabled = $false }
    }
    function Get-ApLogDir { return (Join-Path (Split-Path -Parent $script:AtmIsolationQuarantineRoot) 'AutoPurgeLog') }
    function Get-ApDecisions {
        # Id -> 'DECISION:reason;reason' of every entry of a pass.
        param($Result)
        $by = @{}
        foreach ($x in @($Result.Entries)) { $by[$x.Id] = $x.Decision + ':' + (@($x.Reasons) -join ';') }
        return $by
    }

    Test-Case 'Isolamento P6a' 'Politica ausente, invalida ou desligada (trava aberta, entrada EXPIRED, lock segurado por outro processo): AUTOPURGE_OFF; nada lido alem da politica, nenhum lock, nenhum log, pasta AutoPurgeLog nao criada, nada expurgado; uma linha de estado' {
        $saved = $script:AtmIsolationQuarantineRoot
        Enter-ApQuarantine 'ap-off'
        try {
            $e = New-RstEntry 'apoff'
            if (-not $e) { return }
            $snap = Get-RstSnapshot $script:AtmIsolationQuarantineRoot
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(31) }
            Assert-Eq (Get-AtmQuarantineEntry -Id $e.Id -OwnSid $testIdentity.Sid).State 'EXPIRED' 'entrada EXPIRED'
            $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
            try {
                Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
                foreach ($c in @(@('ausente', ''), @('invalida', '{"schema":"atm.quarantine-policy/1","autoPurge":"yes"}'), @('desligada', '{"schema":"atm.quarantine-policy/1","retentionDays":7,"autoPurge":false}'))) {
                    $ia = @{} + $e.Run.IA
                    $ia['ConfigDir'] = New-PurConfig ('apoff-' + $c[0]) $c[1]
                    $r = Invoke-ApOpen @{ InventoryArgs = $ia; BeforePurgeHook = { param($p) throw 'nunca' }; PurgeTreeImpl = { param($p) throw 'nunca' } }
                    Assert-True ($r.Aborted -ceq 'AUTOPURGE_OFF' -and @($r.Entries).Count -eq 0 -and @($r.Results).Count -eq 0 -and -not $r.LogFile -and -not $r.LogCreated -and $null -eq $r.RunId) "$($c[0]): AUTOPURGE_OFF ($($r.Aborted))"
                    $t = Get-RstHost { Show-AtmAutoPurgeResult -Result $r }
                    Assert-Eq $t.Trim() (Get-AtmText 'ap.off') "$($c[0]): uma linha de estado"
                }
            } finally { $null = Stop-TestLockHolderByGo $h }
            Assert-True (-not (Test-Path -LiteralPath (Get-ApLogDir))) 'nenhuma pasta de log criada'
            Assert-Eq (Get-RstSnapshot $script:AtmIsolationQuarantineRoot) $snap 'entrada EXPIRED identica'
        } finally { $script:AtmQuarantineClock = $null; $script:AtmIsolationQuarantineRoot = $saved }
    }
    Test-Case 'Isolamento P6a' 'Passada ligada alem da trava (so no processo da suite, quarentena propria): antes de expirar nada e expurgado (STATE_ISOLATED); expirada, so a EXPIRED com verify OK e expurgada pelo deleter real; DIFFERS, FAILED, INCOMPLETE, ABANDONED, UNRECOGNIZED e FUTURE_DATE (registro e id) pulados com o motivo e intactos; manifesto e log atm.autopurgelog/1 com automatic=true e declaredBy=AUTOMATIC_POLICY, o log fora de Q e sem nomes de arquivo; retencao de 7 dias (o minimo) aceita' {
        $saved = $script:AtmIsolationQuarantineRoot
        Enter-ApQuarantine 'ap-on'
        try {
            $ok = New-RstEntry 'apok'
            $dif = New-RstEntry 'apdif'
            $fail = New-RstEntry 'apfail' @{ MoveTreeImpl = $isoRefused }
            $inc = New-RstEntry 'apinc'
            $ab = New-RstEntry 'apab'
            $fut = New-RstEntry 'apfut'
            if (-not $ok -or -not $dif -or -not $fail -or -not $inc -or -not $ab -or -not $fut) { return }
            $q = $script:AtmIsolationQuarantineRoot
            # The fixtures: a payload that differs, an intent without its result, another identity's manifest, a record
            # dated after the clock, a folder that is not an entry and an entry id dated after the clock.
            [IO.File]::WriteAllText((Join-Path $dif.Path 'payload\depois.txt'), 'x')
            Set-RstManifestLines -Path $inc.Manifest -Keep 2
            [IO.File]::WriteAllText($ab.Manifest, ([IO.File]::ReadAllText($ab.Manifest)).Replace(('"' + $testIdentity.Sid + '"'), '"S-1-5-21-1-2-3-4444"'), (New-Object Text.UTF8Encoding($false)))
            $fl = @(([IO.File]::ReadAllText($fut.Manifest)).Split([char]10) | Where-Object { $_ -ne '' })
            $fl[$fl.Count - 1] = [regex]::Replace($fl[$fl.Count - 1], '"utc":"[^"]*"', ('"utc":"' + [datetime]::UtcNow.AddDays(400).ToString('o') + '"'))
            [IO.File]::WriteAllText($fut.Manifest, (($fl -join "`n") + "`n"), (New-Object Text.UTF8Encoding($false)))
            [void][IO.Directory]::CreateDirectory((Join-Path $q 'nao-e-entrada'))
            $fid = '20990101T000000Z-0000f00d'
            [void][IO.Directory]::CreateDirectory((Join-Path $q ($fid + '\payload')))
            $ia = Get-InvArgs -Profiles @($ok.Run.Profile, $dif.Run.Profile, $fail.Run.Profile, $inc.Run.Profile, $ab.Run.Profile, $fut.Run.Profile)
            $ia['ConfigDir'] = New-PurConfig 'ap-on' '{"schema":"atm.quarantine-policy/1","retentionDays":7,"autoPurge":true}'
            $snaps = @{}
            foreach ($x in @($dif, $fail, $inc, $ab, $fut)) { $snaps[$x.Id] = Get-RstSnapshot $x.Path }
            # Five days with a retention of seven: nothing has expired, nothing is purged.
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(5) }
            $r0 = Invoke-ApOpen @{ InventoryArgs = $ia }
            $by0 = Get-ApDecisions $r0
            Assert-True (-not $r0.Aborted -and -not $r0.StoppedBy -and @($r0.Results).Count -eq 0 -and $by0[$ok.Id] -ceq 'SKIPPED:STATE_ISOLATED' -and [IO.File]::Exists((Join-Path $ok.Path 'payload\a.txt'))) "antes de expirar: nada expurgado ($($r0.Aborted)$($r0.StoppedBy) $($by0[$ok.Id]))"
            # Eight days: the entry expired.
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(8) }
            $r = Invoke-ApOpen @{ InventoryArgs = $ia }
            $by = Get-ApDecisions $r
            $all = ($by.Keys | Sort-Object | ForEach-Object { $_ + '=' + $by[$_] }) -join ' | '
            Assert-True (-not $r.Aborted -and -not $r.StoppedBy -and @($r.Results).Count -eq 1 -and $r.Results[0].Id -ceq $ok.Id -and $r.Results[0].Outcome -ceq 'COMPLETE' -and $r.Results[0].Verified) "so a EXPIRED com verify OK expurgada ($($r.Aborted)$($r.StoppedBy) $all)"
            Assert-Eq $by[$ok.Id] 'PURGED:' 'EXPIRED com verify OK: PURGED'
            Assert-True ($by[$dif.Id] -like 'SKIPPED:PURGE_REFUSED_DIFFERS*') "DIFFERS pulada ($($by[$dif.Id]))"
            Assert-Eq $by[$fail.Id] 'SKIPPED:STATE_FAILED' 'FAILED pulada'
            Assert-Eq $by[$inc.Id] 'SKIPPED:STATE_INCOMPLETE (move)' 'INCOMPLETE pulada'
            Assert-Eq $by[$ab.Id] 'SKIPPED:STATE_ABANDONED' 'ABANDONED pulada'
            Assert-Eq $by['nao-e-entrada'] 'SKIPPED:STATE_UNRECOGNIZED (NOT_AN_ENTRY)' 'UNRECOGNIZED pulada'
            Assert-Eq $by[$fut.Id] 'SKIPPED:FUTURE_DATE' 'registro com data depois do relogio: pulada'
            Assert-Eq $by[$fid] 'SKIPPED:FUTURE_DATE' 'id com data depois do relogio: pulado'
            foreach ($x in @($dif, $fail, $inc, $ab, $fut)) { Assert-Eq (Get-RstSnapshot $x.Path) $snaps[$x.Id] "pulada e intacta: $($by[$x.Id])" }
            Assert-True ([IO.Directory]::Exists((Join-Path $q ($fid + '\payload')))) 'pasta com id futuro intacta'
            $s = Get-AtmQuarantineEntry -Id $ok.Id -OwnSid $testIdentity.Sid
            Assert-True ($s.State -ceq 'PURGED' -and -not [IO.Directory]::Exists((Join-Path $ok.Path 'payload')) -and [IO.File]::Exists($ok.Manifest)) "payload ausente; entrada e manifesto ficam como trilha ($($s.State))"
            $mr = @((Read-TestCleanLogFile $ok.Manifest).Records)
            $mi = @($mr | Where-Object { $_.type -ceq 'purge-intent' })
            $mo = @($mr | Where-Object { $_.type -ceq 'purge-result' })
            Assert-True ($mi.Count -eq 1 -and $mo.Count -eq 1 -and $mi[0].automatic -eq $true -and $mi[0].declaredBy -ceq 'AUTOMATIC_POLICY' -and $mo[0].automatic -eq $true -and $mo[0].declaredBy -ceq 'AUTOMATIC_POLICY' -and $mo[0].outcome -ceq 'COMPLETE') 'manifesto: purge-intent e purge-result com automatic=true e declaredBy=AUTOMATIC_POLICY'
            $logDir = Get-ApLogDir
            Assert-True ($r.LogCreated -and $r.LogFile.StartsWith($logDir + '\', [StringComparison]::OrdinalIgnoreCase) -and -not $r.LogFile.StartsWith($q + '\', [StringComparison]::OrdinalIgnoreCase) -and [IO.File]::Exists($r.LogFile) -and $r.LogFile -cne $r0.LogFile) "log novo da passada em AutoPurgeLog, ao lado da quarentena e fora dela ($($r.LogFile))"
            $lf = Read-TestCleanLogFile $r.LogFile
            $types = @($lf.Records | ForEach-Object { [string]$_.type })
            Assert-True (-not $lf.Bom -and -not $lf.Cr -and $lf.EndsLf -and @($lf.Records | Where-Object { $_.schema -cne 'atm.autopurgelog/1' -or $_.id -cne $r.RunId }).Count -eq 0) 'log T1: UTF-8 sem BOM, LF, schema atm.autopurgelog/1 e o id da passada em todo registro'
            Assert-True ($types[0] -ceq 'run-start' -and $types[$types.Count - 1] -ceq 'run-end' -and @($types | Where-Object { $_ -ceq 'skip' }).Count -eq 7 -and (@($types | Where-Object { $_ -cmatch '^(plan-check|purge-intent|purge-result)$' }) -join ',') -ceq 'plan-check,purge-intent,purge-result') "registros: $($types -join ',')"
            $rs = $lf.Records[0]
            Assert-True ($rs.operation -ceq 'autopurge' -and $rs.declaredBy -ceq 'AUTOMATIC_POLICY' -and $rs.retentionDays -eq 7 -and $rs.minRetentionDays -eq 7 -and $rs.entries -eq 8 -and $rs.candidates -eq 1) 'run-start: a politica, o minimo e as contagens'
            $li = @($lf.Records | Where-Object { $_.type -ceq 'purge-intent' })[0]
            $lo = @($lf.Records | Where-Object { $_.type -ceq 'purge-result' })[0]
            Assert-True ($li.automatic -eq $true -and $li.declaredBy -ceq 'AUTOMATIC_POLICY' -and $li.entryId -ceq $ok.Id -and $lo.automatic -eq $true -and $lo.declaredBy -ceq 'AUTOMATIC_POLICY' -and $lo.outcome -ceq 'COMPLETE') 'log: purge-intent e purge-result com automatic=true e declaredBy=AUTOMATIC_POLICY'
            $raw = [IO.File]::ReadAllText($r.LogFile)
            Assert-True (-not $raw.Contains('a.txt') -and -not $raw.Contains('b.bin') -and -not $raw.Contains('depois.txt') -and -not $raw.Contains($ok.Run.Root)) 'log sem nomes de arquivo nem a raiz original'
            $old = Get-AtmLanguage
            try {
                foreach ($lang in @('en-US', 'pt-BR')) {
                    Set-AtmLanguage -Requested $lang
                    $t = Get-RstHost { Show-AtmAutoPurgeResult -Result $r }
                    Assert-True ($t.Contains((Get-AtmText 'ap.done' 1 (Format-AtmMB $r.Results[0].Bytes) 7)) -and $t.Contains((Get-AtmText 'q.policyWarn.AUTOPURGE_ON')) -and $t.Contains($ok.Id) -and $t.Contains('FUTURE_DATE') -and $t.Contains('STATE_ABANDONED') -and -not $t.Contains('a.txt')) "$lang`: resultado por entrada, com os motivos"
                }
            } finally { Set-AtmLanguage -Requested $old }
        } finally { $script:AtmQuarantineClock = $null; $script:AtmIsolationQuarantineRoot = $saved }
    }
    Test-Case 'Isolamento P6a' 'Trava do expurgo fechada (toda copia distribuida): a passada ligada so relata (WOULD_PURGE e os motivos) e para em EXPURGO_REAL_DESABILITADO; nenhum lock (outro processo o segura), nenhum log, pasta AutoPurgeLog nao criada, deleter nunca chamado; quarentena identica' {
        $saved = $script:AtmIsolationQuarantineRoot
        Enter-ApQuarantine 'ap-closed'
        try {
            $e = New-RstEntry 'apclosed'
            $f = New-RstEntry 'apclosedf' @{ MoveTreeImpl = $isoRefused }
            if (-not $e -or -not $f) { return }
            $q = $script:AtmIsolationQuarantineRoot
            $ia = Get-InvArgs -Profiles @($e.Run.Profile, $f.Run.Profile)
            $ia['ConfigDir'] = New-PurConfig 'ap-closed' '{"schema":"atm.quarantine-policy/1","retentionDays":7,"autoPurge":true}'
            $snap = Get-RstSnapshot $q
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(8) }
            $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
            try {
                Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
                Assert-Eq $script:AtmQuarantinePurgeEnabled $false 'trava do expurgo fechada'
                $r = Invoke-AtmAutoPurge -InventoryArgs $ia -BeforePurgeHook { param($p) throw 'nunca' } -PurgeTreeImpl { param($p) throw 'nunca' }
            } finally { $null = Stop-TestLockHolderByGo $h }
            $by = Get-ApDecisions $r
            Assert-True ($r.Aborted -ceq 'EXPURGO_REAL_DESABILITADO' -and -not $r.StoppedBy -and @($r.Results).Count -eq 0 -and -not $r.LogFile -and -not $r.LogCreated -and $by[$e.Id] -ceq 'WOULD_PURGE:' -and $by[$f.Id] -ceq 'SKIPPED:STATE_FAILED') "so o relato ($($r.Aborted) $($by[$e.Id]) $($by[$f.Id]))"
            Assert-True (-not (Test-Path -LiteralPath (Get-ApLogDir))) 'nenhuma pasta de log'
            Assert-Eq (Get-RstSnapshot $q) $snap 'quarentena identica'
            $old = Get-AtmLanguage
            try {
                foreach ($lang in @('en-US', 'pt-BR')) {
                    Set-AtmLanguage -Requested $lang
                    $t = Get-RstHost { Show-AtmAutoPurgeResult -Result $r }
                    Assert-True ($t.Contains((Get-AtmText 'ap.gateClosed' 1)) -and $t.Contains('WOULD_PURGE') -and -not $t.Contains((Get-AtmText 'ap.done' 0 0 1))) "$lang`: so relato, nada expurgado"
                }
            } finally { Set-AtmLanguage -Requested $old }
        } finally { $script:AtmQuarantineClock = $null; $script:AtmIsolationQuarantineRoot = $saved }
    }
    Test-Case 'Isolamento P6a' 'Limites (trava aberta so na suite): retencao de 5 dias abaixo do minimo recusada antes de ler a quarentena (AUTOPURGE_RETENTION_BELOW_MINIMUM); lock ocupado por outro processo: CLEAN_LOCK_BUSY, nada expurgado, nenhum log; revalidacao recusada pula a entrada sem nova tentativa (REVALIDATION_REFUSED); deleter que recusa antes de apagar pula a entrada e a passada segue; excecao no deleter para a passada (o resto NOT_REACHED); lock livre depois' {
        $saved = $script:AtmIsolationQuarantineRoot
        Enter-ApQuarantine 'ap-lim'
        try {
            $made = @((New-RstEntry 'aplima'), (New-RstEntry 'aplimb'), (New-RstEntry 'aplimc'), (New-RstEntry 'aplimd'))
            if (@($made | Where-Object { -not $_ }).Count -gt 0) { return }
            # The pass takes the entries in the order of their names: the roles follow that order.
            $s = @($made | Sort-Object Id)
            $q = $script:AtmIsolationQuarantineRoot
            $ia = Get-InvArgs -Profiles @($s | ForEach-Object { $_.Run.Profile })
            $snap = Get-RstSnapshot $q
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(31) }
            $ia5 = @{} + $ia
            $ia5['ConfigDir'] = New-PurConfig 'ap-ret5' '{"schema":"atm.quarantine-policy/1","retentionDays":5,"autoPurge":true}'
            $r5 = Invoke-ApOpen @{ InventoryArgs = $ia5; PurgeTreeImpl = { param($p) throw 'nunca' } }
            Assert-True ($r5.Aborted -ceq 'AUTOPURGE_RETENTION_BELOW_MINIMUM' -and @($r5.Entries).Count -eq 0 -and @($r5.Results).Count -eq 0 -and -not $r5.LogFile) "retencao de 5 dias recusada ($($r5.Aborted))"
            Assert-Eq (Get-RstHost { Show-AtmAutoPurgeResult -Result $r5 }).Trim() (Get-AtmText 'ap.retentionMin' 5 7) 'uma linha de estado com a retencao e o minimo'
            $ia['ConfigDir'] = New-PurConfig 'ap-lim' '{"schema":"atm.quarantine-policy/1","retentionDays":7,"autoPurge":true}'
            $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
            try {
                Assert-Eq $h.Status 'ACQUIRED' 'lock ocupado por outro processo'
                $rb = Invoke-ApOpen @{ InventoryArgs = $ia; BeforePurgeHook = { param($p) throw 'nunca' }; PurgeTreeImpl = { param($p) throw 'nunca' } }
            } finally { $null = Stop-TestLockHolderByGo $h }
            Assert-True ($rb.Aborted -ceq 'CLEAN_LOCK_BUSY' -and @($rb.Entries).Count -eq 0 -and @($rb.Results).Count -eq 0 -and -not $rb.LogFile) "lock ocupado: a passada termina sem expurgar ($($rb.Aborted))"
            Assert-True ((Get-RstHost { Show-AtmAutoPurgeResult -Result $rb }).Contains((Get-AtmText 'ap.busy' 'CLEAN_LOCK_BUSY'))) 'mensagem de lock indisponivel'
            Assert-True (-not (Test-Path -LiteralPath (Get-ApLogDir))) 'nenhum log'
            Assert-Eq (Get-RstSnapshot $q) $snap 'quarentena identica'
            $script:apRe = $s[0].Id; $script:apRef = $s[1].Id; $script:apExc = $s[2].Id
            $hook = { param($p) if ($p.Entry.Id -ceq $script:apRe) { [IO.File]::WriteAllText((Join-Path $p.PayloadPath 'novo.txt'), 'x') } }
            $impl = {
                param($p)
                if ($p.Entry.Id -ceq $script:apRef) { return [pscustomobject]@{ Attempted = $true; Completed = $false; FilesDeleted = 0; DirsDeleted = 0; FilesPlanned = $p.Files; DirsPlanned = $p.Dirs; AbortReason = 'SYNTHETIC_REFUSED' } }
                if ($p.Entry.Id -ceq $script:apExc) { throw (New-Object IO.IOException 'synthetic') }
                throw 'nunca'
            }
            $r = Invoke-ApOpen @{ InventoryArgs = $ia; BeforePurgeHook = $hook; PurgeTreeImpl = $impl }
            $by = Get-ApDecisions $r
            Assert-True ($by[$s[0].Id] -like 'SKIPPED:REVALIDATION_REFUSED;PURGE_REFUSED_DIFFERS*') "revalidacao recusada: pulada sem nova tentativa ($($by[$s[0].Id]))"
            Assert-Eq $by[$s[1].Id] 'SKIPPED:DELETER_REFUSED (SYNTHETIC_REFUSED)' 'deleter recusou antes de apagar: pulada, a passada segue'
            Assert-Eq $by[$s[2].Id] 'STOPPED:STOPPED_AFTER_EXCEPTION' 'excecao no deleter: a passada para'
            Assert-Eq $by[$s[3].Id] 'NOT_REACHED:' 'depois da parada: nao alcancada'
            Assert-True ($r.StoppedBy -ceq 'STOPPED_AFTER_EXCEPTION' -and (@($r.Results | ForEach-Object { $_.Outcome }) -join ',') -ceq 'REFUSED,EXCEPTION') "resultados ($($r.StoppedBy): $(@($r.Results | ForEach-Object { $_.Outcome }) -join ',')))"
            $st = @($s | ForEach-Object { (Get-AtmQuarantineEntry -Id $_.Id -OwnSid $testIdentity.Sid).State })
            Assert-Eq ($st -join ',') 'EXPIRED,EXPIRED,FAILED,EXPIRED' 'estados: revalidada e recusada continuam EXPIRED; a excecao deixa FAILED'
            foreach ($i in @(0, 1, 3)) { Assert-True ([IO.File]::Exists((Join-Path $s[$i].Path 'payload\a.txt'))) "nada apagado na entrada $i" }
            $types = @((Read-TestCleanLogFile $r.LogFile).Records | ForEach-Object { [string]$_.type })
            Assert-True ($types[0] -ceq 'run-start' -and $types[$types.Count - 1] -ceq 'run-end' -and @($types | Where-Object { $_ -ceq 'plan-check' }).Count -eq 3 -and @($types | Where-Object { $_ -ceq 'purge-intent' }).Count -eq 2) "log da passada: $($types -join ',')"
            $h = Start-TestLockHolder -Name $script:AtmCleanLockName -Mode release
            try { Assert-Eq $h.Status 'ACQUIRED' 'lock livre depois da passada' } finally { $null = Stop-TestLockHolderByGo $h }
        } finally { $script:AtmQuarantineClock = $null; $script:AtmIsolationQuarantineRoot = $saved }
    }
    Test-Case 'Isolamento P6a' 'Aviso de expurgo automatico ligado (en-US e pt-BR): com autoPurge = true na politica, as linhas da politica (version, quarantine list, TUI) e o aviso de todo relatorio dizem EXPURGO AUTOMATICO LIGADO e que so a execucao manual de bin\agent-temp-autopurge.ps1 age; sem politica, invalida ou desligada nada e mostrado' {
        $on = New-PurConfig 'ap-notice-on' '{"schema":"atm.quarantine-policy/1","autoPurge":true}'
        $offs = @((New-PurConfig 'ap-notice-off' '{"schema":"atm.quarantine-policy/1","autoPurge":false}'), (New-PurConfig 'ap-notice-bad' '{"schema":"atm.quarantine-policy/1","autoPurge":1}'), $cfgDir)
        $old = Get-AtmLanguage
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $w = Get-AtmText 'q.policyWarn.AUTOPURGE_ON'
                Assert-True ($w.Contains('bin\agent-temp-autopurge.ps1') -and $w.Contains('EXPIRED') -and $w.Contains('autoPurge = true')) "$lang`: o texto nomeia o ponto de entrada e o alcance"
                Assert-Eq (@(Get-AtmAutoPurgeNoticeLines -ConfigDir $on) -join '|') $w "$lang`: aviso com autoPurge = true"
                foreach ($c in $offs) { Assert-Eq @(Get-AtmAutoPurgeNoticeLines -ConfigDir $c).Count 0 "$lang`: sem aviso ($c)" }
                $t = (@(Get-AtmQuarantinePolicyLines -Policy (Get-AtmQuarantinePolicy -ConfigDir $on)) | ForEach-Object { $_.Text }) -join "`n"
                Assert-True ($t.Contains($w)) "$lang`: linhas da politica com o aviso"
            }
        } finally { Set-AtmLanguage -Requested $old }
        # The source has no policy: the reports of this suite show no notice.
        Assert-Eq @(Get-AtmAutoPurgeNoticeLines).Count 0 'origem sem politica: nenhum aviso'
        Assert-True (-not [IO.File]::Exists((Join-Path $cfgDir 'quarantine.policy.json'))) 'a suite nunca escreve politica na origem'
    }
    Test-Case 'Isolamento P6a' 'Estatico: so bin\agent-temp-autopurge.ps1 chama a passada (a CLI interativa e a TUI nunca, e nenhuma tem parametro de expurgo automatico); o ponto de entrada nao tem bloco de parametros, recusa argumentos antes de tudo, confere o manifesto antes de carregar, so em ASCII, nunca chama o deleter, nem pergunta, nem abre a trava; a passada nao tem leitor, apresentador nem frase; uma referencia ao deleter no motor; minimo de 7 dias fixo; todo relatorio mostra o aviso; textos nos dois idiomas; instalador e build exigem o ponto de entrada' {
        $calls = @()
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd') -and $_.Name -ne 'Engine.Isolate.ps1' })) { if ([regex]::IsMatch([IO.File]::ReadAllText($fi.FullName), 'Invoke-AtmAutoPurge\b')) { $calls += $fi.Name } }
        Assert-Eq ($calls -join ',') 'agent-temp-autopurge.ps1' 'so o ponto de entrada chama a passada'
        # P6b: the CLI reaches only the task's two commands and its state; the TUI only the notice and the task's state.
        $apCmds = { param($n) $t = [Management.Automation.Language.Parser]::ParseFile((Join-Path $srcDir $n), [ref]$null, [ref]$null)
            @($t.FindAll({ param($a) $a -is [Management.Automation.Language.CommandAst] }, $true) | ForEach-Object { $_.GetCommandName() } | Where-Object { $_ -match 'autopurge' } | Sort-Object -Unique) }
        Assert-Eq ((& $apCmds 'agent-temp.ps1') -join ',') 'Get-AtmAutoPurgeTaskLines,Get-AtmAutoPurgeTaskState,Invoke-AtmAutoPurgeSchedule,Invoke-AtmAutoPurgeUnschedule,Show-AtmAutoPurgeTaskPlan,Show-AtmAutoPurgeTaskResult' 'a CLI so chama os comandos da tarefa e o seu estado'
        Assert-Eq ((& $apCmds 'lib\Tui.ps1') -join ',') 'Get-AtmAutoPurgeNoticeLines,Get-AtmAutoPurgeTaskLines,Get-AtmAutoPurgeTaskState,Get-AtmTuiAutoPurgeNotice' 'a TUI so mostra o aviso e o estado da tarefa'
        $epPath = Join-Path $srcDir 'bin\agent-temp-autopurge.ps1'
        $ep = [IO.File]::ReadAllText($epPath)
        $tk = $null; $er = $null
        $ast = [Management.Automation.Language.Parser]::ParseInput($ep, [ref]$tk, [ref]$er)
        Assert-True (@($er).Count -eq 0 -and $null -eq $ast.ParamBlock -and -not $ep.Contains('[CmdletBinding()]')) 'sem bloco de parametros nem CmdletBinding'
        $iArgs = $ep.IndexOf('if ($args.Count -gt 0) {'); $iChk = $ep.IndexOf('$integrity = Test-AtmAutoPurgeIntegrity'); $iBad = $ep.IndexOf('if ($integrity.Problems.Count -gt 0) {'); $iLoad = $ep.IndexOf(". (Join-Path `$here 'lib\Engine.Audit.ps1')")
        Assert-True ($iArgs -gt 0 -and $iArgs -lt $iChk -and $iChk -lt $iBad -and $iBad -lt $iLoad) "argumentos recusados antes de tudo; manifesto conferido antes de carregar ($iArgs < $iChk < $iBad < $iLoad)"
        Assert-True ($ep.Contains("'lib\Engine.Audit.ps1', 'lib\I18n.ps1', 'lib\Engine.Clean.ps1', 'lib\Engine.Isolate.ps1', 'lib\Engine.Diagnose.ps1', 'lib\Report.ps1', 'bin\agent-temp-autopurge.ps1'") -and $ep.Contains("-Filter '*.ps1' -File -Force")) 'toda biblioteca carregada e o proprio ponto de entrada precisam estar no manifesto; providers com -Force'
        # The entry point's check is a copy of the launcher's rules (agent-temp.ps1 is not changed in this phase): every
        # rule line must stay identical in both, so the two checks cannot drift apart.
        $launcher = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        $rules = @'
try { $p = [string]$e.path; $h = [string]$e.sha256 } catch { $p = ''; $h = '' }
$segments = @($p -split '\\')
if ($p -notmatch '^[A-Za-z0-9_. -]+(\\[A-Za-z0-9_. -]+)*$' -or $segments -contains '.' -or $segments -contains '..' -or
$h -notmatch '^[0-9A-Fa-f]{64}$' -or $r.Listed.ContainsKey($k)) {
try { $found = @(Get-ChildItem -LiteralPath $providersDir -Filter '*.ps1' -File -Force -ErrorAction Stop | Sort-Object Name) } catch { $found = $null }
$r.Providers = @($found | Where-Object { $r.Listed.ContainsKey(('providers\' + $_.Name).ToLowerInvariant()) })
$loadedKeys = @($r.Providers | ForEach-Object { ('providers\' + $_.Name).ToLowerInvariant() })
foreach ($k in @($r.Listed.Keys | Where-Object { $_ -match '^providers\\[^\\]+\.ps1$' })) {
'@
        foreach ($rl in @($rules -split "`r?`n" | Where-Object { $_.Trim() })) { Assert-True ($launcher.Contains($rl.Trim()) -and $ep.Contains($rl.Trim())) "regra identica no lancador e no ponto de entrada: $($rl.Trim().Substring(0, [Math]::Min(60, $rl.Trim().Length)))" }
        Assert-True ($launcher.Contains('if ($loadedKeys -notcontains $k -and (Test-Path -LiteralPath (Join-Path $here $k) -PathType Leaf)) {') -and $ep.Contains('if ($loadedKeys -notcontains $k -and (Test-Path -LiteralPath (Join-Path $here $k) -PathType Leaf)) {')) 'provider listado e nao enumerado recusado nos dois'
        Assert-Eq ([regex]::Matches($ep, 'Invoke-AtmAutoPurge ').Count) 1 'uma chamada da passada'
        foreach ($pat in @('AtmDeleter', 'DeleteTree', 'ConfirmationReader', 'Read-Host', 'AtmQuarantinePurgeEnabled', 'PurgeTreeImpl', 'BeforePurgeHook', 'Invoke-AtmPurge ')) { Assert-True (-not $ep.Contains($pat)) "ponto de entrada sem '$pat'" }
        Assert-Eq @([IO.File]::ReadAllBytes($epPath) | Where-Object { $_ -gt 127 }).Count 0 'ponto de entrada so em ASCII'
        $iso = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Isolate.ps1'))
        # The pass, up to the scheduled task's section (P6b), which has its own presenter and phrases.
        $apEnd = $iso.IndexOf('# ------------------------------------------------------------------ the scheduled task of the automatic purge (P6b)')
        $ap = $iso.Substring($iso.IndexOf('function Invoke-AtmAutoPurge {'), $apEnd - $iso.IndexOf('function Invoke-AtmAutoPurge {'))
        foreach ($pat in @('ConfirmationReader', 'PlanPresenter', 'Test-AtmTypedPhrase', 'Get-AtmEngineConsoleObservation', 'Read-Host')) { Assert-True (-not $ap.Contains($pat)) "passada sem '$pat'" }
        Assert-Eq ([regex]::Matches($iso, 'AtmDeleter').Count) 1 'uma referencia ao deleter no motor (o caminho comum dos dois expurgos)'
        Assert-True ($iso.IndexOf('AtmDeleter') -gt $iso.IndexOf('function Invoke-AtmPurgeDeletion') -and $iso.IndexOf('function Invoke-AtmPurgeDeletion') -gt $iso.IndexOf('function Invoke-AtmPurgeCore')) 'o deleter so no caminho comum, depois do expurgo manual'
        Assert-True ([regex]::Matches($iso, '\$script:AtmAutoPurgeMinRetentionDays\s*=').Count -eq 1 -and $iso -match '(?m)^\$script:AtmAutoPurgeMinRetentionDays = 7\r?$') 'minimo de 7 dias fixo no codigo, atribuicao unica'
        $w = $ap.Substring(0, $ap.IndexOf('function Invoke-AtmAutoPurgeCore'))
        $iOff = $w.IndexOf("'AUTOPURGE_OFF'"); $iMin = $w.IndexOf("'AUTOPURGE_RETENTION_BELOW_MINIMUM'"); $iGate = $w.IndexOf('if (-not $script:AtmQuarantinePurgeEnabled) { return (Invoke-AtmAutoPurgeCore'); $iLock = $w.IndexOf('Invoke-AtmUnderSharedLock')
        Assert-True ($iOff -gt 0 -and $iOff -lt $iMin -and $iMin -lt $iGate -and $iGate -lt $iLock -and -not $w.Contains('Invoke-AtmInventory')) "politica, minimo e trava antes do lock e do inventario ($iOff < $iMin < $iGate < $iLock)"
        $core = $ap.Substring($ap.IndexOf('function Invoke-AtmAutoPurgeCore'))
        $iStop = $core.IndexOf("`$state.Aborted = 'EXPURGO_REAL_DESABILITADO'")
        foreach ($act in @('Open-AtmAutoPurgeLog -', 'Invoke-AtmPurgeDeletion -', '& $BeforePurgeHook')) { Assert-True ($core.IndexOf($act) -gt $iStop -and $iStop -gt 0) "'$act' so depois da parada da trava" }
        Assert-True ($core.IndexOf("'FUTURE_DATE'") -lt $core.IndexOf("[string]`$en.State -cne 'EXPIRED'") -and $core.Contains('-Automatic')) 'data futura antes do estado; registros automaticos'
        $rep = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Report.ps1'))
        $tk = $null; $er = $null
        $rast = [Management.Automation.Language.Parser]::ParseInput($rep, [ref]$tk, [ref]$er)
        $fns = @($rast.FindAll({ param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] }, $false))
        foreach ($fn in @('Show-AtmAudit', 'Show-AtmPathDetail', 'Show-AtmPreview', 'Show-AtmCleanPlan', 'Show-AtmIsolatePlan', 'Show-AtmIsolateResult', 'Show-AtmQuarantineEntry', 'Show-AtmQuarantineVerify', 'Show-AtmRestorePlan', 'Show-AtmRestoreResult', 'Show-AtmPurgePlan', 'Show-AtmPurgeResult', 'Show-AtmDiscardPresentation', 'Show-AtmDiscardResult', 'Show-AtmCleanResult', 'Show-AtmDiagnose')) {
            $d = @($fns | Where-Object { $_.Name -ceq $fn })
            Assert-True ($d.Count -eq 1 -and $d[0].Body.Extent.Text.Contains('Show-AtmAutoPurgeNotice')) "$fn mostra o aviso"
        }
        $ql = @($fns | Where-Object { $_.Name -ceq 'Show-AtmQuarantineList' })[0].Body.Extent.Text
        Assert-True ($ql.Contains('Get-AtmQuarantinePolicyLines')) 'quarantine list mostra o aviso pelas linhas da politica'
        foreach ($l in @('en-US', 'pt-BR')) {
            foreach ($k in @('q.policyWarn.AUTOPURGE_ON', 'ap.header', 'ap.off', 'ap.retentionMin', 'ap.gateClosed', 'ap.busy', 'ap.aborted', 'ap.stopped', 'ap.row', 'ap.done', 'ap.logFile', 'ap.failed')) { Assert-True $script:AtmMessages[$l].ContainsKey($k) "$k ($l)" }
            Assert-True (-not $script:AtmMessages[$l].ContainsKey('q.policyWarn.AUTOPURGE_NOT_AVAILABLE')) "aviso antigo removido ($l)"
        }
        Assert-True ($script:AtmRequiredFiles -contains 'bin\agent-temp-autopurge.ps1') 'instalador exige o ponto de entrada'
        $br = [IO.File]::ReadAllText((Join-Path (Split-Path -Parent $testsDir) 'tools\Build-Release.ps1'))
        Assert-True ($br.Contains("& `$read 'src/bin/agent-temp-autopurge.ps1'") -and $br.Contains("'bin\agent-temp-autopurge.ps1'")) 'build confere o ponto de entrada no pacote e no manifesto'
    }
    Test-Case 'Isolamento P6a' 'Ponto de entrada em processo filho (copia preparada com manifesto; nunca le a quarentena do executor): argumento recusado com 2; sem manifesto (origem), biblioteca ou o proprio ponto de entrada alterado e provider fora do manifesto: 5, nada carregado; politica ausente, invalida ou desligada: 0 e uma linha de estado, nenhuma pasta criada; retencao abaixo do minimo: 3; version e diagnose da copia com autoPurge = true mostram o aviso' {
        $shell = (Get-Process -Id $PID).Path
        $inst = Join-Path $sandbox 'ap-stage\AgentTempManager'
        [void][IO.Directory]::CreateDirectory($inst)
        Copy-AtmTree -From $srcDir -To $inst
        Write-AtmManifest -Root $inst -Version (Get-AtmSourceVersion -SourceDir $srcDir)
        $ep = Join-Path $inst 'bin\agent-temp-autopurge.ps1'
        $pf = Join-Path $inst 'config\quarantine.policy.json'
        $run = { param([string]$File, [string]$ArgLine = '') Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$File`" $ArgLine") -TimeoutSec 300 }
        $setPolicy = { param([string]$T) [IO.File]::WriteAllText($pf, $T, (New-Object Text.UTF8Encoding($false))) }
        $home0 = Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'AgentTempManager'
        $seen0 = @([IO.Directory]::Exists($home0), [IO.Directory]::Exists((Join-Path $home0 'AutoPurgeLog')), [IO.Directory]::Exists((Join-Path $home0 'Q')))
        foreach ($al in @('x', '-Verbose', 'quarantine purge')) {
            $r = & $run $ep $al
            Assert-True ($r.Exit -eq 2 -and $r.Text.Contains('takes no arguments') -and $r.Text.Contains('nao aceita argumentos')) "argumento '$al' recusado: exit $($r.Exit)"
        }
        $r = & $run (Join-Path $srcDir 'bin\agent-temp-autopurge.ps1')
        Assert-True ($r.Exit -eq 5 -and $r.Text.Contains('manifest missing / manifesto ausente: manifest.json')) "origem sem manifesto recusada: exit $($r.Exit)"
        foreach ($c in @(@('ausente', $null), @('invalida', '{"schema":"atm.quarantine-policy/1","retentionDays":0,"autoPurge":true}'), @('desligada', '{"schema":"atm.quarantine-policy/1","autoPurge":false}'))) {
            if ($c[1]) { & $setPolicy $c[1] }
            $r = & $run $ep
            Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('autoPurge = true') -and @($r.Text.Trim() -split "`n").Count -eq 1) "$($c[0]): exit 0 e uma linha de estado (exit $($r.Exit): $($r.Text.Trim()))"
        }
        & $setPolicy '{"schema":"atm.quarantine-policy/1","retentionDays":5,"autoPurge":true}'
        $r = & $run $ep
        Assert-True ($r.Exit -eq 3 -and $r.Text.Contains('retentionDays') -and $r.Text.Contains(' 5,') -and $r.Text.Contains(' 7 ')) "retencao de 5 dias recusada: exit $($r.Exit) ($($r.Text.Trim()))"
        $seen1 = @([IO.Directory]::Exists($home0), [IO.Directory]::Exists((Join-Path $home0 'AutoPurgeLog')), [IO.Directory]::Exists((Join-Path $home0 'Q')))
        Assert-Eq ($seen1 -join ',') ($seen0 -join ',') 'nenhuma pasta criada no perfil do executor'
        # The copy with autoPurge on: version and a report show the notice (the entry point is not run with it: it would
        # read the runner's own quarantine).
        & $setPolicy '{"schema":"atm.quarantine-policy/1","autoPurge":true}'
        $cli = Join-Path $inst 'agent-temp.ps1'
        $r = & $run $cli 'version -Lang en-US'
        Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('AUTOMATIC PURGE ON') -and $r.Text.Contains('bin\agent-temp-autopurge.ps1')) "version mostra o expurgo automatico ligado: exit $($r.Exit)"
        $r = & $run $cli 'diagnose -DeadlineSeconds 0 -Lang en-US -NoProgress'
        Assert-True ($r.Exit -ne 5 -and $r.Text.Contains('AUTOMATIC PURGE ON')) "relatorio (diagnose) mostra o aviso: exit $($r.Exit)"
        & $setPolicy '{"schema":"atm.quarantine-policy/1","autoPurge":false}'
        # Integrity: a library, the entry point itself and an unlisted provider refuse before anything is loaded.
        foreach ($rel in @('lib\Report.ps1', 'bin\agent-temp-autopurge.ps1')) {
            $fp = Join-Path $inst $rel
            $orig = [IO.File]::ReadAllBytes($fp)
            [IO.File]::AppendAllText($fp, "`r`n# alterado`r`n")
            try { $r = & $run $ep } finally { [IO.File]::WriteAllBytes($fp, $orig) }
            Assert-True ($r.Exit -eq 5 -and $r.Text.Contains('modified/alterado: ' + $rel.ToLowerInvariant()) -and -not $r.Text.Contains('autoPurge = true')) "$rel alterado: exit $($r.Exit)"
        }
        $extra = Join-Path $inst 'providers\Extra.ps1'
        [IO.File]::WriteAllText($extra, '# x')
        try { $r = & $run $ep } finally { [IO.File]::Delete($extra) }
        Assert-True ($r.Exit -eq 5 -and $r.Text.Contains('provider not in manifest / provider fora do manifesto: Extra.ps1')) "provider fora do manifesto: exit $($r.Exit)"
        $r = & $run $ep
        Assert-Eq $r.Exit 0 "copia restaurada volta a passar ($($r.Text.Trim()))"
    }

    # ------------------------------------------------------------------ the scheduled task of the automatic purge (ISO-P6b)
    # J-ISO-7, complement of 2026-11-03. A real task is created only on the CI's disposable runner, always with a name marked
    # as a test (AutoPurgeTest-<8 hex>), and removed by the case; anywhere else those cases are NAO_TESTADO.
    function Get-ApFnBody {
        # The text of one function of a file (AST), for the static checks.
        param([string]$File, [string]$Name)
        $t = [Management.Automation.Language.Parser]::ParseFile($File, [ref]$null, [ref]$null)
        $d = @($t.FindAll({ param($a) $a -is [Management.Automation.Language.FunctionDefinitionAst] -and $a.Name -ceq $Name }, $true))
        if ($d.Count -ne 1) { return '' }
        return $d[0].Extent.Text
    }
    function Get-ApCallers {
        # Where a command is called in src, as <file>:<function> (script: the top level).
        param([string]$Command)
        $out = New-Object System.Collections.Generic.List[string]
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File -Filter '*.ps1' | Sort-Object FullName)) {
            $t = [Management.Automation.Language.Parser]::ParseFile($fi.FullName, [ref]$null, [ref]$null)
            foreach ($c in @($t.FindAll({ param($a) $a -is [Management.Automation.Language.CommandAst] -and $a.GetCommandName() -ceq $Command }, $true))) {
                $p = $c.Parent
                while ($null -ne $p -and -not ($p -is [Management.Automation.Language.FunctionDefinitionAst])) { $p = $p.Parent }
                $out.Add($fi.Name + ':' + $(if ($null -ne $p) { $p.Name } else { 'script' }))
            }
        }
        return $out.ToArray()
    }
    function New-ApTestName { return ('AutoPurgeTest-' + [guid]::NewGuid().ToString('N').Substring(0, 8)) }
    function Clear-ApTestTask {
        # Test code only: a task of the suite (test name) left by a case is removed here; never any other task.
        param([string]$Name)
        if ($Name -cnotmatch '^AutoPurgeTest-[0-9a-f]{8}$') { throw "nao e um nome de tarefa de teste: $Name" }
        try { (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager').DeleteTask($Name, 0) } catch { $null = $_ }
    }
    # The engine's own seams of P6b back to $null; the console seam is the suite's (set for the whole run), so each case
    # that changes it gives back the value it found.
    function Reset-ApSeams { param($Console) $script:AtmAutoPurgeTaskNameOverride = $null; $script:AtmAutoPurgeElevationSource = $null; $script:AtmCleanConsoleSource = $Console }
    $apStd = { [pscustomobject]@{ IsElevatedAdministrator = $false; ElevationType = 'DEFAULT'; IntegrityLevel = 'MEDIUM' } }

    Test-Case 'Isolamento P6b' 'Estatico: o agendador so por Connect-AtmTaskScheduler; RegisterTaskDefinition, CreateFolder e NewTask uma vez cada por motor, so nas suas funcoes; DeleteTask exatamente duas vezes (as duas remocoes, cada uma depois da conferencia exata) e DeleteFolder exatamente uma (a pasta vazia, a constante do produto, depois da contagem; V0.5 M4a); registrar so pelo agendar e remover so pelo desagendar, os dois so pela CLI nos dois subcomandos; a pasta vazia so pelos dois comandos de desagendar, depois da releitura ABSENT; a mesma constante de pasta no expurgo e no monitoramento; TUI, relatorio, ponto de entrada e desinstalador nunca mudam o agendador; principal interativo e limitado, TASK_CREATE, sem senha; ordem das recusas; costuras de atribuicao unica; mesmo nome e pasta no motor e no desinstalador; textos nos dois idiomas; excecao de Write-Host do ponto de entrada' {
        $root = Split-Path -Parent $testsDir
        $isoFile = Join-Path $srcDir 'lib\Engine.Isolate.ps1'
        $iso = [IO.File]::ReadAllText($isoFile)
        $all = @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1', '.cmd', '.cs') })
        $count = { param([string]$Pat) $n = 0; $where = @(); foreach ($fi in $all) { $m = [regex]::Matches([IO.File]::ReadAllText($fi.FullName), $Pat).Count; if ($m -gt 0) { $n += $m; $where += $fi.Name } }; [pscustomobject]@{ N = $n; Where = ($where -join ',') } }
        $r = & $count 'Schedule\.Service'
        Assert-True ($r.N -eq 1 -and $r.Where -ceq 'Engine.Isolate.ps1' -and [regex]::IsMatch((Get-ApFnBody $isoFile 'Connect-AtmTaskScheduler'), 'Schedule\.Service')) "Schedule.Service: uma vez, so em Connect-AtmTaskScheduler ($($r.N) em $($r.Where))"
        # V0.5 M3a: the collection task of the monitoring registers too, once, in its own functions of Engine.Monitor; the
        # purge's stay once each in Engine.Isolate. V0.5 M4a: DeleteTask exactly twice, once in each removal, each after
        # its exact-task check in the same read; DeleteFolder exactly once, in the empty-folder helper, after the counts.
        $monFile = Join-Path $srcDir 'lib\Engine.Monitor.ps1'
        $r = & $count '\.DeleteTask\('
        $unA = Get-ApFnBody $isoFile 'Unregister-AtmAutoPurgeTask'; $unM = Get-ApFnBody $monFile 'Unregister-AtmMonitorTask'
        Assert-True ($r.N -eq 2 -and $r.Where -ceq 'Engine.Isolate.ps1,Engine.Monitor.ps1' -and [regex]::Matches($unA, '\.DeleteTask\(').Count -eq 1 -and [regex]::Matches($unM, '\.DeleteTask\(').Count -eq 1) "DeleteTask: exatamente duas vezes, uma em Unregister-AtmAutoPurgeTask e uma em Unregister-AtmMonitorTask ($($r.N) em $($r.Where))"
        Assert-True ($unM.IndexOf('Test-AtmMonitorTaskMatch') -gt 0 -and $unM.IndexOf('Test-AtmMonitorTaskMatch') -lt $unM.IndexOf('.DeleteTask($name, 0)') -and $unM.IndexOf('if (-not $script:AtmMonitoringEnabled)') -ge 0 -and $unM.IndexOf('if (-not $script:AtmMonitoringEnabled)') -lt $unM.IndexOf('Connect-AtmTaskScheduler')) 'remocao do monitoramento: a trava antes do agendador, e so depois de conferir a tarefa exata, na mesma leitura'
        $r = & $count '\.DeleteFolder\('
        $hlp = Get-ApFnBody $isoFile 'Remove-AtmEmptyTaskFolder'
        Assert-True ($r.N -eq 1 -and $r.Where -ceq 'Engine.Isolate.ps1' -and [regex]::Matches($hlp, '\.DeleteFolder\(').Count -eq 1) "DeleteFolder: exatamente uma vez, so em Remove-AtmEmptyTaskFolder ($($r.N) em $($r.Where))"
        Assert-Eq (& $count 'DeleteFolder').Where 'Engine.Isolate.ps1' 'DeleteFolder so e citado no Engine.Isolate'
        $ix = @(@('$svc.GetFolder($script:AtmAutoPurgeTaskFolder)', 'Test-AtmTaskNotFound', '.GetTasks(1).Count', '.GetFolders(0).Count', "'NOT_EMPTY'", ".DeleteFolder(`$script:AtmAutoPurgeTaskFolder.TrimStart('\'), 0)", "'REMOVED'") | ForEach-Object { $hlp.IndexOf($_) })
        Assert-True (@($ix | Where-Object { $_ -lt 0 }).Count -eq 0 -and ((@($ix | Sort-Object) -join ',') -ceq ($ix -join ','))) "pasta vazia: a constante do produto, ausente, contagem de tarefas (inclusive ocultas) e subpastas, nao vazia, e so entao DeleteFolder nessa ordem ($($ix -join ','))"
        Assert-True (-not $hlp.Contains('param(') -and -not $hlp.Contains('DeleteTask') -and -not $hlp.Contains('RegisterTaskDefinition') -and -not $hlp.Contains('Set-Acl') -and -not $hlp.Contains('SetSecurityDescriptor') -and [regex]::Matches($hlp, 'GetFolder\(').Count -eq 2) 'pasta vazia: sem parametro (so a constante), sem remover tarefa, sem ACL, sem segunda tentativa'
        foreach ($u in @($unA, $unM)) { Assert-True (-not $u.Contains('DeleteFolder') -and -not $u.Contains('Remove-AtmEmptyTaskFolder')) 'as remocoes de tarefa nao tocam a pasta' }
        $isoT = [IO.File]::ReadAllText($isoFile); $monT = [IO.File]::ReadAllText($monFile)
        $fA = [regex]::Match($isoT, "(?m)^\`$script:AtmAutoPurgeTaskFolder = '([^']+)'\r?$"); $fM = [regex]::Match($monT, "(?m)^\`$script:AtmMonitorTaskFolder = '([^']+)'\r?$")
        Assert-True ($fA.Success -and $fM.Success -and $fA.Groups[1].Value -ceq $fM.Groups[1].Value -and $fA.Groups[1].Value -ceq '\AgentTempManager' -and [regex]::Matches($isoT, '\$script:AtmAutoPurgeTaskFolder\s*=').Count -eq 1 -and [regex]::Matches($monT, '\$script:AtmMonitorTaskFolder\s*=').Count -eq 1) "a pasta do helper (expurgo) e a do monitoramento: a mesma constante, atribuida uma vez cada ($($fA.Groups[1].Value) / $($fM.Groups[1].Value))"
        foreach ($c in @(@('\.RegisterTaskDefinition\(', 'Register-AtmAutoPurgeTask', 'Register-AtmMonitorTask'), @('\.CreateFolder\(', 'Register-AtmAutoPurgeTask', 'Register-AtmMonitorTask'), @('\.NewTask\(', 'New-AtmAutoPurgeTaskDefinition', 'New-AtmMonitorTaskDefinition'))) {
            $r = & $count $c[0]
            Assert-True ($r.N -eq 2 -and $r.Where -ceq 'Engine.Isolate.ps1,Engine.Monitor.ps1' -and [regex]::Matches((Get-ApFnBody $isoFile $c[1]), $c[0]).Count -eq 1 -and [regex]::Matches((Get-ApFnBody $monFile $c[2]), $c[0]).Count -eq 1) "$($c[0]): uma vez em $($c[1]) e uma em $($c[2]) ($($r.N) em $($r.Where))"
        }
        foreach ($pat in @('Register-ScheduledTask', 'Unregister-ScheduledTask', 'Set-ScheduledTask', 'New-ScheduledTask', 'schtasks', 'Get-Credential', 'SecureString', 'savecred')) { Assert-Eq (& $count ([regex]::Escape($pat))).N 0 "nenhum '$pat' em src" }
        Assert-Eq ((Get-ApCallers 'Connect-AtmTaskScheduler') -join ',') 'Engine.Isolate.ps1:Get-AtmAutoPurgeTaskState,Engine.Isolate.ps1:Register-AtmAutoPurgeTask,Engine.Isolate.ps1:Unregister-AtmAutoPurgeTask,Engine.Isolate.ps1:Remove-AtmEmptyTaskFolder,Engine.Monitor.ps1:Get-AtmMonitorTaskState,Engine.Monitor.ps1:Register-AtmMonitorTask,Engine.Monitor.ps1:Unregister-AtmMonitorTask' 'o agendador so e alcancado pelos estados (leitura) e pelas funcoes que o mudam (purga e monitoramento: registrar e remover; a pasta vazia)'
        Assert-Eq ((Get-ApCallers 'Register-AtmAutoPurgeTask') -join ',') 'Engine.Isolate.ps1:Invoke-AtmAutoPurgeSchedule' 'registrar so pelo agendar'
        Assert-Eq ((Get-ApCallers 'Unregister-AtmAutoPurgeTask') -join ',') 'Engine.Isolate.ps1:Invoke-AtmAutoPurgeUnschedule' 'remover so pelo desagendar'
        Assert-Eq ((Get-ApCallers 'Unregister-AtmMonitorTask') -join ',') 'Engine.Monitor.ps1:Invoke-AtmMonitorDisable' 'remover a tarefa de coleta so pelo disable'
        Assert-Eq ((Get-ApCallers 'Remove-AtmEmptyTaskFolder') -join ',') 'Engine.Isolate.ps1:Invoke-AtmAutoPurgeUnschedule,Engine.Monitor.ps1:Invoke-AtmMonitorDisable' 'a pasta vazia so pelos dois comandos de desagendar'
        Assert-Eq ((Get-ApCallers 'Invoke-AtmMonitorDisable') -join ',') 'agent-temp.ps1:script' 'o disable so pela CLI'
        Assert-Eq ((Get-ApCallers 'Invoke-AtmAutoPurgeSchedule') -join ',') 'agent-temp.ps1:script' 'agendar so pela CLI'
        Assert-Eq ((Get-ApCallers 'Invoke-AtmAutoPurgeUnschedule') -join ',') 'agent-temp.ps1:script' 'desagendar so pela CLI'
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        $iCase = $cli.IndexOf("{ `$_ -in @('schedule-autopurge', 'unschedule-autopurge') } {"); $iDef = $cli.IndexOf("default { Write-Host (Get-AtmText 'cli.quarantineUsage')")
        foreach ($fn in @('Invoke-AtmAutoPurgeSchedule -', 'Invoke-AtmAutoPurgeUnschedule -')) { $i = $cli.IndexOf($fn); Assert-True ($iCase -gt 0 -and $i -gt $iCase -and $i -lt $iDef) "$fn so no caso dos dois subcomandos de quarantine" }
        foreach ($n in @('lib\Tui.ps1', 'lib\Report.ps1', 'bin\agent-temp-autopurge.ps1', 'bin\agent-temp-monitor.ps1', 'agent-temp.ps1')) {
            $t = [IO.File]::ReadAllText((Join-Path $srcDir $n))
            foreach ($pat in @('Register-AtmAutoPurgeTask', 'Connect-AtmTaskScheduler', 'RegisterTaskDefinition', 'DeleteTask', 'CreateFolder', 'DeleteFolder', 'Schedule.Service', 'AtmAutoPurgeTaskNameOverride', 'AtmAutoPurgeElevationSource', 'Register-AtmMonitorTask', 'New-AtmMonitorTaskDefinition', 'AtmMonitorTaskNameOverride', 'AtmMonitorElevationSource', 'Unregister-AtmMonitorTask', 'Remove-AtmEmptyTaskFolder')) { Assert-True (-not $t.Contains($pat)) "$n sem '$pat'" }
        }
        foreach ($n in @('lib\Tui.ps1', 'lib\Report.ps1', 'bin\agent-temp-autopurge.ps1')) { foreach ($pat in @('Invoke-AtmAutoPurgeSchedule', 'Invoke-AtmAutoPurgeUnschedule')) { Assert-True (-not ([IO.File]::ReadAllText((Join-Path $srcDir $n))).Contains($pat)) "$n sem '$pat' (a TUI so mostra, T-ISO-6)" } }
        $ic = [IO.File]::ReadAllText((Join-Path $root 'install\InstallCommon.ps1'))
        foreach ($pat in @('RegisterTaskDefinition', 'DeleteTask', 'CreateFolder', 'DeleteFolder', 'Register-ScheduledTask', 'Unregister-ScheduledTask', 'schtasks')) { Assert-True (-not $ic.Contains($pat)) "desinstalador sem '$pat'" }
        Assert-True ($ic.Contains("`$script:AtmInstallAutoPurgeTaskFolder = '\AgentTempManager'") -and $iso.Contains("`$script:AtmAutoPurgeTaskFolder = '\AgentTempManager'") -and $iso.Contains("`$script:AtmAutoPurgeTaskPrefix = 'AutoPurge-'")) 'mesma pasta e prefixo no motor e no desinstalador'
        $i = 0
        foreach ($s in @('S-1-5-80-1000-2000-3000-4000-5000', 'S-1-5-18', 'S-1-5-32-545', 'S-1-12-1-1-2-3-4')) { $i++; Assert-Eq (Get-AtmInstallAutoPurgeTaskName -Sid $s) (Get-AtmAutoPurgeTaskName -Sid $s) "mesmo nome no motor e no desinstalador (SID sintetico $i)" }
        # V0.5 M4b (V05-D9 (a)): the monitoring's constants repeated in the installer, equal to the engine's; the notice
