        Assert-True ($ic.Contains("`$script:AtmInstallMonitorTaskFolder = '\AgentTempManager'") -and $ic.Contains("`$script:AtmInstallMonitorTaskPrefix = 'Monitor-'") -and $ic.Contains("`$script:AtmInstallMonitorFolderName = 'Monitor'") -and $ic.Contains("`$script:AtmInstallMonitorFolderLiteral = '%LOCALAPPDATA%\AgentTempManager\Monitor'")) 'monitoramento: constantes repetidas no desinstalador'
        Assert-True ($script:AtmInstallMonitorTaskFolder -ceq $script:AtmMonitorTaskFolder -and $script:AtmInstallMonitorTaskPrefix -ceq $script:AtmMonitorTaskPrefix -and $script:AtmInstallMonitorFolderName -ceq $script:AtmMonitorFolderName -and $script:AtmInstallMonitorFolderLiteral -ceq ('%LOCALAPPDATA%\AgentTempManager\' + $script:AtmMonitorFolderName)) 'monitoramento: mesma pasta de tarefas, prefixo e pasta do historico no motor e no desinstalador'
        $oldOverride = $script:AtmMonitorTaskNameOverride
        try {
            $script:AtmMonitorTaskNameOverride = $null
            $i = 0
            foreach ($s in @('S-1-5-80-1000-2000-3000-4000-5000', 'S-1-5-18', 'S-1-5-32-545', 'S-1-12-1-1-2-3-4')) { $i++; Assert-Eq (Get-AtmInstallMonitorTaskName -Sid $s) (Get-AtmMonitorTaskName -Sid $s) "monitoramento: mesmo nome no motor e no desinstalador (SID sintetico $i)" }
        } finally { $script:AtmMonitorTaskNameOverride = $oldOverride }
        $mn = [regex]::Replace((Get-ApFnBody (Join-Path $root 'install\InstallCommon.ps1') 'Get-AtmUninstallMonitorNotice'), '(?m)#.*$', '')
        Assert-True ($mn.Contains('GetTasks(1)') -and $mn.Contains('GetAttributes(')) 'aviso do monitoramento lido (controle positivo)'
        foreach ($pat in @('Delete', 'Remove-', 'Move', 'Rename', 'Write', 'Create', 'Set-', 'New-Item', 'Out-File', 'Register', 'Unregister', 'schtasks', 'AtmDeleter', 'Remove-AtmOwnTree', 'Invoke-AtmMonitor')) { Assert-True ($mn.IndexOf($pat, [StringComparison]::OrdinalIgnoreCase) -lt 0) "aviso do monitoramento so le: sem '$pat'" }
        Assert-True ($ic.Contains('foreach ($wl in @(Get-AtmUninstallMonitorNotice)) { Write-Warning $wl }')) 'o desinstalar chama o aviso do monitoramento'
        $def = Get-ApFnBody $isoFile 'New-AtmAutoPurgeTaskDefinition'
        foreach ($s in @('$td.Principal.UserId = $Sid', '$td.Principal.LogonType = 3', '$td.Principal.RunLevel = 0', '$td.Triggers.Create(2)', '$tr.DaysInterval = 1', '$tr.RandomDelay = $script:AtmAutoPurgeTaskRandomDelay', '$s.StartWhenAvailable = $true', '$s.DisallowStartIfOnBatteries = $false', '$s.StopIfGoingOnBatteries = $false', '$s.MultipleInstances = 2', '$td.Actions.Create(0)')) { Assert-True $def.Contains($s) "definicao: $s" }
        Assert-Eq ([regex]::Matches($def, '\.Actions\.Create\(').Count) 1 'uma acao'
        Assert-True ((Get-ApFnBody $isoFile 'Register-AtmAutoPurgeTask').Contains('.RegisterTaskDefinition($name, $td, 2, $Sid, $null, 3, $null)')) 'registro com TASK_CREATE (2), o SID, senha nula e logon interativo (3)'
        foreach ($rx in @('(?m)^\$script:AtmAutoPurgeTaskHour = 12\r?$', "(?m)^\`$script:AtmAutoPurgeTaskRandomDelay = 'PT1H'\r?$", "(?m)^\`$script:AtmAutoPurgeTaskTimeLimit = 'PT2H'\r?$", "(?m)^\`$script:AtmAutoPurgeSchedulePhrase = 'AGENDAR EXPURGO AUTOMATICO'\r?$", "(?m)^\`$script:AtmAutoPurgeUnschedulePhrase = 'DESAGENDAR EXPURGO AUTOMATICO'\r?$")) { Assert-True ($iso -match $rx) "fixo no codigo: $rx" }
        foreach ($seam in @('AtmAutoPurgeTaskNameOverride', 'AtmAutoPurgeElevationSource')) {
            Assert-True ([regex]::Matches($iso, '\$script:' + $seam + '\s*=').Count -eq 1 -and $iso -match ('(?m)^\$script:' + $seam + ' = \$null\r?$')) "costura $seam`: atribuicao unica `$null no motor"
            foreach ($fi in $all) { if ($fi.Name -ne 'Engine.Isolate.ps1') { Assert-True (-not ([IO.File]::ReadAllText($fi.FullName)).Contains($seam)) "$($fi.Name) usa a costura $seam" } }
        }
        Assert-True ((Get-ApFnBody $isoFile 'Get-AtmAutoPurgeTaskName').Contains("-cnotmatch '^AutoPurgeTest-[0-9a-f]{8}$'")) 'o nome de teste so na forma de teste'
        $sch = Get-ApFnBody $isoFile 'Invoke-AtmAutoPurgeSchedule'
        $ix = @(@("'AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN'", "'AUTOPURGE_TASK_NOT_INSTALLED'", "'CONSOLE_NOT_OBSERVED'", "'AUTOPURGE_TASK_EXISTS'", '& $PlanPresenter', "'autopurge-off'", "'autopurge-schedule'", 'Register-AtmAutoPurgeTask -') | ForEach-Object { $sch.IndexOf($_) })
        Assert-True (@($ix | Where-Object { $_ -lt 0 }).Count -eq 0 -and ((@($ix | Sort-Object) -join ',') -ceq ($ix -join ','))) "agendar: token, instalacao, console, existente, plano, frases e registro nessa ordem ($($ix -join ','))"
        $uns = Get-ApFnBody $isoFile 'Invoke-AtmAutoPurgeUnschedule'
        $ix = @(@("'CONSOLE_NOT_OBSERVED'", 'Get-AtmAutoPurgeTaskState', "'AUTOPURGE_TASK_DIVERGENT'", '& $PlanPresenter', "'autopurge-unschedule'", 'Unregister-AtmAutoPurgeTask -', "'AUTOPURGE_TASK_NOT_VERIFIED'", '$st.Done = $true', '$st.Folder = Remove-AtmEmptyTaskFolder') | ForEach-Object { $uns.IndexOf($_) })
        Assert-True (@($ix | Where-Object { $_ -lt 0 }).Count -eq 0 -and ((@($ix | Sort-Object) -join ',') -ceq ($ix -join ',')) -and [regex]::Matches($uns, 'Remove-AtmEmptyTaskFolder').Count -eq 1) "desagendar: console, estado, divergente, plano, frase, remocao, releitura ABSENT e so entao a pasta vazia, uma vez, nessa ordem ($($ix -join ','))"
        $un = Get-ApFnBody $isoFile 'Unregister-AtmAutoPurgeTask'
        Assert-True ($un.IndexOf('Test-AtmAutoPurgeTaskMatch') -gt 0 -and $un.IndexOf('Test-AtmAutoPurgeTaskMatch') -lt $un.IndexOf('.DeleteTask(')) 'remocao so depois de conferir a tarefa exata, na mesma leitura'
        Assert-True ((Get-ApFnBody $isoFile 'Get-AtmAutoPurgeTaskObject') -notmatch 'CreateFolder|RegisterTaskDefinition|DeleteTask') 'a leitura do estado nunca cria a pasta'
        foreach ($l in @('en-US', 'pt-BR')) {
            foreach ($k in @('help.quarantine3', 'ap.task.absent', 'ap.task.present', 'ap.task.enabled', 'ap.task.disabled', 'ap.task.never', 'ap.task.lastResult', 'ap.task.divergent', 'ap.task.unreadable', 'ap.plan.header', 'ap.plan.task', 'ap.plan.trigger', 'ap.plan.action', 'ap.plan.principal', 'ap.plan.policyOn', 'ap.plan.policyOff',
                    'ap.plan.unschedule', 'ap.plan.unscheduleTask', 'ap.task.created', 'ap.task.removed', 'ap.task.notScheduled', 'ap.task.notRemoved', 'ap.task.notVerified', 'inst.apTaskWarn', 'inst.apTaskOthers', 'inst.apTaskUnreadable', 'tf.removed', 'tf.absent', 'tf.notEmpty', 'tf.kept',
                    'ap.task.why.AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN', 'ap.task.why.AUTOPURGE_TASK_NOT_INSTALLED', 'ap.task.why.AUTOPURGE_TASK_EXISTS', 'ap.task.why.AUTOPURGE_TASK_DIVERGENT', 'ap.task.why.AUTOPURGE_TASK_ABSENT', 'ap.task.why.AUTOPURGE_TASK_NOT_CONFIRMED', 'ap.task.why.CONSOLE_NOT_OBSERVED')) { Assert-True $script:AtmMessages[$l].ContainsKey($k) "$k ($l)" }
            Assert-True (-not $script:AtmMessages[$l]['q.policyWarn.AUTOPURGE_ON'].Contains('No scheduled task') -and -not $script:AtmMessages[$l]['q.policyWarn.AUTOPURGE_ON'].Contains('existe tarefa agendada'))"aviso de ligado sem 'nenhuma tarefa' ($l)"
        }
        Assert-True ($cli.Contains("'help.quarantine2', 'help.quarantine3'")) 'a ajuda lista os dois subcomandos'
        $sa = Import-PowerShellDataFile -LiteralPath (Join-Path $root 'tools\static-analysis-exceptions.psd1')
        $wh = @($sa.Exceptions | Where-Object { $_['Rule'] -eq 'PSAvoidUsingWriteHost' -and @($_['Files']) -contains 'src/bin/agent-temp-autopurge.ps1' })
        Assert-True ($wh.Count -eq 1 -and ([string]$wh[0]['Justification']).Contains('Console entry point')) 'excecao de Write-Host do ponto de entrada de console, justificada'
    }

    Test-Case 'Isolamento P6b' 'Definicao montada e nunca registrada (XML): o SID como usuario, logon interativo, nivel limitado, sem senha; diario as 12:00 locais com atraso de ate 1 h, primeira execucao no futuro sem fuso, perdida roda na proxima oportunidade, tambem na bateria, uma instancia, limite de 2 h, uma acao exata; nome por hash do SID (nunca o SID; o de teste so na forma de teste); regra do token; conferencia exata (usuario por nome resolvido; cada divergencia com o seu motivo)' {
        $me = Get-AtmCurrentIdentity
        $ep = Join-Path $sandbox 'ap6b dir\bin\agent-temp-autopurge.ps1'
        $svc = Connect-AtmTaskScheduler
        $td = New-AtmAutoPurgeTaskDefinition -Service $svc -Sid $me.Sid -EntryPoint $ep -Now ([datetime]'2026-11-03T09:00:00')
        $x = [xml]$td.XmlText
        $ns = New-Object Xml.XmlNamespaceManager($x.NameTable); $ns.AddNamespace('t', 'http://schemas.microsoft.com/windows/2004/02/mit/task')
        $v = { param($p) $n = $x.SelectSingleNode($p, $ns); if ($null -ne $n) { $n.InnerText } else { '<none>' } }
        Assert-True ((& $v '//t:Principal/t:UserId') -ceq $me.Sid -and (& $v '//t:Principal/t:LogonType') -ceq 'InteractiveToken' -and (& $v '//t:Principal/t:RunLevel') -ceq 'LeastPrivilege') 'principal: o SID do processo, InteractiveToken, LeastPrivilege'
        Assert-True ($null -eq $x.SelectSingleNode('//t:Password', $ns) -and -not $td.XmlText.Contains('Password')) 'nenhuma senha na definicao'
        Assert-Eq (& $v '//t:CalendarTrigger/t:StartBoundary') '2026-11-03T12:00:00' 'primeira execucao: as 12:00 locais, sem fuso'
        Assert-True ((& $v '//t:CalendarTrigger/t:RandomDelay') -ceq 'PT1H' -and (& $v '//t:CalendarTrigger/t:ScheduleByDay/t:DaysInterval') -ceq '1' -and @($x.SelectNodes('//t:Triggers/*', $ns)).Count -eq 1) 'um gatilho diario com atraso de ate 1 h'
        foreach ($k in @(@('StartWhenAvailable', 'true'), @('DisallowStartIfOnBatteries', 'false'), @('StopIfGoingOnBatteries', 'false'), @('MultipleInstancesPolicy', 'IgnoreNew'), @('ExecutionTimeLimit', 'PT2H'))) { Assert-Eq (& $v ('//t:Settings/t:' + $k[0])) $k[1] "configuracao $($k[0])" }
        $want = Get-AtmAutoPurgeTaskAction -EntryPoint $ep
        Assert-True (@($x.SelectNodes('//t:Actions/*', $ns)).Count -eq 1 -and (& $v '//t:Exec/t:Command') -ceq (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -and (& $v '//t:Exec/t:Arguments') -ceq ('-NoLogo -NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + $ep + '"') -and $want.Arguments -ceq (& $v '//t:Exec/t:Arguments')) 'uma acao exata: o PowerShell 5.1 absoluto e o ponto de entrada, sem argumentos proprios'
        Assert-Eq (& $v '//t:RegistrationInfo/t:Author') 'Agent Temp Manager' 'autor: o produto (nunca a conta)'
        Assert-True ((Get-AtmAutoPurgeTaskStart -Now ([datetime]'2026-11-03T11:59:30')) -ceq '2026-11-04T12:00:00' -and (Get-AtmAutoPurgeTaskStart -Now ([datetime]'2026-11-03T13:00:00')) -ceq '2026-11-04T12:00:00' -and (Get-AtmAutoPurgeTaskStart -Now ([datetime]'2026-12-31T12:30:00')) -ceq '2027-01-01T12:00:00') 'registrar nunca dispara: a primeira execucao e sempre a proxima, ao menos 1 min adiante'
        $nm = Get-AtmAutoPurgeTaskName -Sid $me.Sid
        Assert-True ($nm -cmatch '^AutoPurge-[0-9a-f]{16}$' -and -not $nm.Contains($me.Sid) -and (Get-AtmAutoPurgeTaskName -Sid $me.Sid) -ceq $nm -and (Get-AtmAutoPurgeTaskName -Sid 'S-1-5-18') -cne $nm) 'nome: prefixo e 16 hex do SHA-256 do SID, estavel, nunca o SID'
        try {
            foreach ($bad in @('AutoPurge-0123456789abcdef', 'AutoPurgeTest-ABCDEF12', 'AutoPurgeTest-1234567', 'x')) {
                $script:AtmAutoPurgeTaskNameOverride = $bad
                $thrown = ''; try { $null = Get-AtmAutoPurgeTaskName -Sid $me.Sid } catch { $thrown = $_.Exception.Message }
                Assert-Eq $thrown 'AUTOPURGE_TASK_TEST_NAME_INVALID' "nome de teste fora da forma recusado: $bad"
            }
            $script:AtmAutoPurgeTaskNameOverride = 'AutoPurgeTest-0a1b2c3d'
            Assert-Eq (Get-AtmAutoPurgeTaskName -Sid $me.Sid) 'AutoPurgeTest-0a1b2c3d' 'nome de teste na forma de teste'
            $script:AtmAutoPurgeTaskNameOverride = $null
            foreach ($c in @(@($true, 'FULL', 'HIGH', $false), @($false, 'FULL', 'MEDIUM', $false), @($false, 'DEFAULT', 'HIGH', $false), @($false, 'DEFAULT', 'SYSTEM', $false), @($null, 'UNKNOWN', 'UNKNOWN', $false),
                    @($false, 'DEFAULT', 'LOW', $false), @($false, 'DEFAULT', 'UNTRUSTED', $false), @($false, 'DEFAULT', 'MEDIUM', $true), @($false, 'LIMITED', 'MEDIUM', $true), @($false, 'DEFAULT', 'MEDIUM_PLUS', $true))) {
                $script:apTok = [pscustomobject]@{ IsElevatedAdministrator = $c[0]; ElevationType = $c[1]; IntegrityLevel = $c[2] }
                $script:AtmAutoPurgeElevationSource = { $script:apTok }
                Assert-Eq (Test-AtmAutoPurgeStandardToken) $c[3] "token admin=$($c[0]) $($c[1]) $($c[2])"
            }
        } finally { Reset-ApSeams $script:AtmCleanConsoleSource }
        # The exact match, on tasks built in memory (no scheduler).
        $mkTask = { param($Path, $User, $Logon, $Run, $Acts)
            $col = [pscustomobject]@{ Count = @($Acts).Count; Items = @($Acts) }
            $col | Add-Member -MemberType ScriptMethod -Name Item -Value { param($i) $this.Items[$i - 1] }
            [pscustomobject]@{ Path = $Path; Definition = [pscustomobject]@{ Principal = [pscustomobject]@{ UserId = $User; LogonType = $Logon; RunLevel = $Run }; Actions = $col } } }
        $mkAct = { param($Type, $P, $A, $D) [pscustomobject]@{ Type = $Type; Path = $P; Arguments = $A; WorkingDirectory = $D } }
        $tp = '\AgentTempManager\' + $nm
        $ok = & $mkAct 0 $want.Path $want.Arguments ''
        $cases = @(
            @('exata', (& $mkTask $tp $me.Sid 3 0 @($ok)), ''),
            @('usuario por nome', (& $mkTask $tp $me.Name 3 0 @($ok)), ''),
            @('caminho em maiusculas', (& $mkTask $tp.ToUpperInvariant() $me.Sid 3 0 @(& $mkAct 0 $want.Path.ToUpperInvariant() $want.Arguments '')), ''),
            @('outra pasta', (& $mkTask ('\Other\' + $nm) $me.Sid 3 0 @($ok)), 'TASK_PATH'),
            @('outro usuario', (& $mkTask $tp 'S-1-5-18' 3 0 @($ok)), 'TASK_USER'),
            @('usuario que nao resolve', (& $mkTask $tp 'NOSUCHDOMAIN\no-such-account' 3 0 @($ok)), 'TASK_USER'),
            @('logon com senha', (& $mkTask $tp $me.Sid 1 0 @($ok)), 'TASK_LOGON_TYPE'),
            @('nivel elevado', (& $mkTask $tp $me.Sid 3 1 @($ok)), 'TASK_RUN_LEVEL'),
            @('duas acoes', (& $mkTask $tp $me.Sid 3 0 @($ok, $ok)), 'TASK_ACTION_COUNT'),
            @('acao que nao e programa', (& $mkTask $tp $me.Sid 3 0 @(& $mkAct 5 $want.Path $want.Arguments '')), 'TASK_ACTION_TYPE'),
            @('outro programa', (& $mkTask $tp $me.Sid 3 0 @(& $mkAct 0 'C:\Windows\System32\cmd.exe' $want.Arguments '')), 'TASK_ACTION_PATH'),
            @('argumentos a mais', (& $mkTask $tp $me.Sid 3 0 @(& $mkAct 0 $want.Path ($want.Arguments + ' x') '')), 'TASK_ACTION_ARGUMENTS'),
            @('pasta de trabalho', (& $mkTask $tp $me.Sid 3 0 @(& $mkAct 0 $want.Path $want.Arguments 'C:\')), 'TASK_ACTION_DIRECTORY'))
        foreach ($c in $cases) { Assert-Eq (@(Test-AtmAutoPurgeTaskMatch -Task $c[1] -Sid $me.Sid -Name $nm -EntryPoint $ep) -join ',') $c[2] "conferencia: $($c[0])" }
    }

    Test-Case 'Isolamento P6b' 'Recusas antes de qualquer pergunta ou registro (nome de teste): processo elevado (o token real da CI e as variantes pela costura) AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN; copia nao instalada; sem apresentador; console nao observado; frase do aviso ou principal errada nao cria nada; desagendar sem tarefa (AUTOPURGE_TASK_ABSENT) ou sem console; o resultado diz o codigo e o porque nos dois idiomas; a CLI em processo filho (agendar: exit 3 sem perguntar; desagendar sem console: exit 6; version e quarantine list mostram o estado)' {
        $name = New-ApTestName
        $asked = New-Object System.Collections.Generic.List[string]
        $pres = { param($p) $asked.Add('plan') }
        $rd = { param($ph, $k) $asked.Add($k); 'nao' }
        $cfgOff = New-PurConfig 'ap6b-off' $null
        $cfgOn = New-PurConfig 'ap6b-on' '{"schema":"atm.quarantine-policy/1","autoPurge":true}'
        $old = Get-AtmLanguage
        $prevConsole = $script:AtmCleanConsoleSource
        try {
            $script:AtmAutoPurgeTaskNameOverride = $name
            if ([bool](Get-AtmIdentityState).IsElevatedAdministrator) {
                $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
                Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN' -and -not $r.Registered -and $null -eq $r.Plan -and $asked.Count -eq 0) "processo elevado (token real) recusado sem perguntar ($($r.Aborted))"
            } else { $script:caseNote = 'o processo nao e elevado aqui: a recusa com o token real e verificada na CI (elevada); as variantes pela costura rodam aqui' }
            foreach ($tok in @(@($true, 'FULL', 'HIGH'), @($false, 'DEFAULT', 'HIGH'), @($null, 'UNKNOWN', 'UNKNOWN'))) {
                $script:apTok = [pscustomobject]@{ IsElevatedAdministrator = $tok[0]; ElevationType = $tok[1]; IntegrityLevel = $tok[2] }
                $script:AtmAutoPurgeElevationSource = { $script:apTok }
                $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
                Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN' -and $asked.Count -eq 0) "token $($tok -join ' ') recusado ($($r.Aborted))"
            }
            $script:AtmAutoPurgeElevationSource = $apStd
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_NOT_INSTALLED' -and $asked.Count -eq 0) "copia nao instalada ($($r.Aborted))"
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'SEM_APRESENTACAO_OU_CONFIRMACAO' -and $asked.Count -eq 0) "sem apresentador ($($r.Aborted))"
            $script:AtmCleanConsoleSource = { $false }
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'CONSOLE_NOT_OBSERVED' -and $asked.Count -eq 0) "agendar sem console ($($r.Aborted))"
            $r = Invoke-AtmAutoPurgeUnschedule -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'CONSOLE_NOT_OBSERVED' -and $asked.Count -eq 0) "desagendar sem console ($($r.Aborted))"
            $script:AtmCleanConsoleSource = { $true }
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOff -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_NOT_CONFIRMED' -and ($asked -join ',') -ceq 'plan,autopurge-off' -and -not $r.Plan.PolicyOn -and $r.Plan.OffPhrase -ceq 'AGENDAR COM EXPURGO DESLIGADO' -and -not $r.Registered) "politica desligada, frase do aviso errada: nada criado ($($r.Aborted) $($asked -join ','))"
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_NOT_CONFIRMED' -and ($asked -join ',') -ceq 'plan,autopurge-schedule' -and $r.Plan.PolicyOn -and $null -eq $r.Plan.OffPhrase -and $r.Plan.TaskPath -ceq ('\AgentTempManager\' + $name)) "politica ligada, frase errada: nada criado ($($r.Aborted) $($asked -join ','))"
            Assert-Eq (Get-AtmAutoPurgeTaskState).State 'ABSENT' 'nenhuma tarefa criada'
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeUnschedule -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_ABSENT' -and $asked.Count -eq 0) "desagendar sem tarefa ($($r.Aborted))"
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                foreach ($c in @(@('schedule', 'AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN'), @('schedule', 'AUTOPURGE_TASK_EXISTS'), @('unschedule', 'AUTOPURGE_TASK_DIVERGENT'), @('unschedule', 'AUTOPURGE_TASK_ABSENT'), @('schedule', 'TASK_SCHEDULER_0x80070005'))) {
                    $t = Get-RstHost { Show-AtmAutoPurgeTaskResult -Result ([pscustomobject]@{ Operation = $c[0]; Aborted = $c[1]; Plan = $null; Registered = $false; Done = $false; Task = $null }) }
                    $why = 'ap.task.why.' + $c[1]
                    Assert-True ($t.Contains($c[1]) -and $t.Contains((Get-AtmText $(if ($c[0] -ceq 'schedule') { 'ap.task.notScheduled' } else { 'ap.task.notRemoved' }) $c[1])) -and (-not $script:AtmMessages['en-US'].ContainsKey($why) -or $t.Contains((Get-AtmText $why)))) "$lang`: resultado $($c[1])"
                }
                $plan = [pscustomobject]@{ TaskPath = '\AgentTempManager\' + $name; Hour = 12; RandomDelay = 'PT1H'; FirstRun = '2026-11-04T12:00:00'; TimeLimit = 'PT2H'; ActionPath = 'P.exe'; ActionArguments = '-File "x"'; PolicyOn = $false; Phrase = 'A'; OffPhrase = 'B' }
                $t = Get-RstHost { Show-AtmAutoPurgeTaskPlan -Plan $plan -Operation 'schedule' }
                Assert-True ($t.Contains($plan.TaskPath) -and $t.Contains((Get-AtmText 'ap.plan.trigger' 12 60 '2026-11-04 12:00:00' 120)) -and $t.Contains((Get-AtmText 'ap.plan.principal')) -and $t.Contains((Get-AtmText 'ap.plan.policyOff'))) "$lang`: plano (tarefa, gatilho, quem roda, aviso de desligada)"
            }
        } finally { Reset-ApSeams $prevConsole; Set-AtmLanguage -Requested $old; Clear-ApTestTask $name }
        # The CLI of the source in child processes: no question is asked and no task is created.
        $shell = (Get-Process -Id $PID).Path
        $cliRun = { param([string]$ArgLine) Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -ExecutionPolicy Bypass -File `"$(Join-Path $srcDir 'agent-temp.ps1')`" $ArgLine") -TimeoutSec 300 }
        $r = & $cliRun 'quarantine schedule-autopurge -Lang en-US'
        Assert-True ($r.Exit -eq 3 -and ($r.Text.Contains('AUTOPURGE_TASK_REQUIRES_STANDARD_TOKEN') -or $r.Text.Contains('AUTOPURGE_TASK_NOT_INSTALLED')) -and -not $r.Text.Contains('AGENDAR EXPURGO AUTOMATICO')) "agendar pela CLI (elevado ou origem): exit 3 sem perguntar (exit $($r.Exit))"
        $r = & $cliRun 'quarantine unschedule-autopurge -Lang en-US'
        Assert-True ($r.Exit -eq 6 -and $r.Text.Contains('CONSOLE_NOT_OBSERVED')) "desagendar sem console: exit 6 (exit $($r.Exit))"
        $r = & $cliRun 'version -Lang en-US'
        Assert-True ($r.Exit -eq 0 -and $r.Text.Contains('Scheduled task of the automatic purge:')) "version mostra o estado da tarefa (exit $($r.Exit))"
        $r = & $cliRun 'help -Lang en-US'
        Assert-True ($r.Text.Contains('schedule-autopurge | unschedule-autopurge')) 'a ajuda mostra os dois subcomandos'
    }

    Test-Case 'Isolamento P6b' 'Tarefa real (so na CI, runner descartavel, nomes de teste): agendar com a politica ligada pede so a frase principal, cria e rele PRESENT (usuario = o SID do processo, logon interativo, nivel limitado, sem senha, uma acao exata, primeira execucao no futuro, nunca executada); agendar de novo recusa sem perguntar nem mudar nada (AUTOPURGE_TASK_EXISTS) e TASK_CREATE recusa sobrescrever; desagendar com frase errada nao remove; desagendar remove so ela e depois a pasta, vazia (REMOVED, a pasta nao existe mais; V0.5 M4a); com a politica desligada pede a frase do aviso e a principal; acao divergente: estado DIVERGENT e desagendar recusa sem perguntar nem tocar; com outra tarefa de teste na pasta, desagendar remove a propria e a pasta fica (NOT_EMPTY, so a contagem)' {
        if ($env:GITHUB_ACTIONS -ne 'true') { $script:caseSkipped = $true; $script:caseNote = 'cria tarefas agendadas reais: so na CI (runner descartavel), nunca local'; return }
        $n1 = New-ApTestName; $n2 = New-ApTestName; $n3 = New-ApTestName
        $me = Get-AtmCurrentIdentity
        $ep = Get-AtmAutoPurgeEntryPoint
        $want = Get-AtmAutoPurgeTaskAction -EntryPoint $ep
        $asked = New-Object System.Collections.Generic.List[string]
        $pres = { param($p) $script:apPlan = $p; $asked.Add('plan') }
        $rd = { param($ph, $k) $asked.Add($k); $ph }
        $cfgOff = New-PurConfig 'ap6b-real-off' '{"schema":"atm.quarantine-policy/1","autoPurge":false}'
        $cfgOn = New-PurConfig 'ap6b-real-on' '{"schema":"atm.quarantine-policy/1","retentionDays":30,"autoPurge":true}'
        $getTask = { param($n) (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager').GetTask($n) }
        $prevConsole = $script:AtmCleanConsoleSource
        try {
            $script:AtmAutoPurgeElevationSource = $apStd
            $script:AtmCleanConsoleSource = { $true }
            $script:AtmAutoPurgeTaskNameOverride = $n1
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Done -and $r.Registered -and -not $r.Aborted -and $r.Task.State -ceq 'PRESENT' -and ($asked -join ',') -ceq 'plan,autopurge-schedule') "agendar com a politica ligada ($($r.Aborted) $($asked -join ','))"
            Assert-True ($script:apPlan.PolicyOn -and $null -eq $script:apPlan.OffPhrase -and $script:apPlan.TaskPath -ceq ('\AgentTempManager\' + $n1) -and $script:apPlan.ActionArguments -ceq $want.Arguments) 'o plano mostrado: tarefa, acao, politica ligada'
            $t = & $getTask $n1
            $td = $t.Definition
            Assert-True ((Resolve-AtmTaskUserSid ([string]$td.Principal.UserId)) -ceq $me.Sid) 'usuario da tarefa: o SID deste processo'
            Assert-True ([int]$td.Principal.LogonType -eq 3 -and [int]$td.Principal.RunLevel -eq 0) 'logon interativo (InteractiveToken) e nivel limitado (LUA)'
            $x = [xml]$t.Xml
            $ns = New-Object Xml.XmlNamespaceManager($x.NameTable); $ns.AddNamespace('t', 'http://schemas.microsoft.com/windows/2004/02/mit/task')
            # The scheduler stores a registered task without the elements that hold their default value (RunLevel
            # LeastPrivilege, for one): absent or that value, with the definition's own properties checked above.
            $xn = { param($p, $default) $n = $x.SelectSingleNode($p, $ns); ($null -eq $n) -or ($n.InnerText -ceq $default) }
            Assert-True ($null -eq $x.SelectSingleNode('//t:Password', $ns) -and -not ([string]$t.Xml).Contains('<Password') -and (& $xn '//t:Principal/t:LogonType' 'InteractiveToken') -and (& $xn '//t:Principal/t:RunLevel' 'LeastPrivilege')) 'tarefa registrada: sem senha, InteractiveToken, LeastPrivilege'
            Assert-True ([int]$td.Actions.Count -eq 1 -and [int]$td.Actions.Item(1).Type -eq 0 -and [string]$td.Actions.Item(1).Path -ceq $want.Path -and [string]$td.Actions.Item(1).Arguments -ceq $want.Arguments) 'uma acao exata: o ponto de entrada'
            Assert-True ([datetime]$t.NextRunTime -gt [datetime]::Now -and [int]$t.LastTaskResult -eq 267011 -and $null -eq $r.Task.LastRunTime) 'primeira execucao no futuro; nunca executada (SCHED_S_TASK_HAS_NOT_RUN; o estado nao mostra ultima execucao)'
            Assert-True ([bool]$td.Settings.StartWhenAvailable -and -not [bool]$td.Settings.DisallowStartIfOnBatteries -and [string]$td.Triggers.Item(1).RandomDelay -ceq 'PT1H') 'perdida roda na proxima oportunidade, tambem na bateria, com atraso'
            $xml0 = [string]$t.Xml
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_EXISTS' -and $asked.Count -eq 0 -and -not $r.Registered) "duplicada recusada sem perguntar ($($r.Aborted))"
            Assert-Eq (Register-AtmAutoPurgeTask -Sid $me.Sid -EntryPoint $ep) 'AUTOPURGE_TASK_EXISTS' 'registro direto: AUTOPURGE_TASK_EXISTS'
            $hr = 0
            try { $svc = Connect-AtmTaskScheduler; $null = $svc.GetFolder('\AgentTempManager').RegisterTaskDefinition($n1, (New-AtmAutoPurgeTaskDefinition -Service $svc -Sid $me.Sid -EntryPoint $ep -Now ([datetime]::Now.AddDays(3))), 2, $me.Sid, $null, 3, $null) } catch { $hr = [int](Get-AtmInnerException $_.Exception).HResult }
            Assert-True (@(-2147024713, -2147024816) -contains $hr) "TASK_CREATE (a flag do produto) recusa sobrescrever: ERROR_ALREADY_EXISTS ou ERROR_FILE_EXISTS (0x$('{0:X8}' -f $hr))"
            Assert-Eq ([string](& $getTask $n1).Xml) $xml0 'a tarefa ficou intacta'
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeUnschedule -PlanPresenter $pres -ConfirmationReader { param($ph, $k) $asked.Add($k); 'nao' }
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_NOT_CONFIRMED' -and ($asked -join ',') -ceq 'plan,autopurge-unschedule' -and (Get-AtmAutoPurgeTaskState).State -ceq 'PRESENT') "desagendar com frase errada nao remove ($($r.Aborted))"
            # V0.5 M4a (V05-D9 (c)): with only this task in the product's folder, the command removes the task and then the
            # folder, now empty.
            $pf = (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager')
            $pre = @([int]$pf.GetTasks(1).Count, [int]$pf.GetFolders(0).Count)
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeUnschedule -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Done -and -not $r.Aborted -and $r.Task.State -ceq 'ABSENT' -and ($asked -join ',') -ceq 'plan,autopurge-unschedule' -and $script:apPlan.TaskPath -ceq ('\AgentTempManager\' + $n1)) "desagendar remove ($($r.Aborted))"
            $folderGone = $false; try { $null = (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager') } catch { $folderGone = [bool](Test-AtmTaskNotFound $_.Exception) }
            Assert-True ($pre[0] -eq 1 -and $pre[1] -eq 0 -and [string]$r.Folder.State -ceq 'REMOVED' -and $null -eq $r.Folder.Code -and $folderGone) "pasta vazia depois da tarefa: REMOVED, a pasta nao existe mais (antes: $($pre[0]) tarefa(s), $($pre[1]) subpasta(s); $($r.Folder.State) $($r.Folder.Code))"
            $t = Get-RstHost { Show-AtmAutoPurgeTaskResult -Result $r }
            Assert-True ($t.Contains((Get-AtmText 'ap.task.removed' ('\AgentTempManager\' + $n1))) -and $t.Contains((Get-AtmText 'tf.removed' '\AgentTempManager'))) 'o resultado mostra a tarefa e a pasta removidas'
            $script:AtmAutoPurgeTaskNameOverride = $n2
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOff -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Done -and ($asked -join ',') -ceq 'plan,autopurge-off,autopurge-schedule' -and -not $script:apPlan.PolicyOn) "politica desligada: frase do aviso e a principal ($($r.Aborted) $($asked -join ','))"
            # A divergent task: the test changes the arguments (TASK_UPDATE); the product refuses to touch it.
            $svc = Connect-AtmTaskScheduler; $f = $svc.GetFolder('\AgentTempManager'); $d2 = $f.GetTask($n2).Definition
            $d2.Actions.Item(1).Arguments = $want.Arguments + ' -Extra'
            $null = $f.RegisterTaskDefinition($n2, $d2, 4, $me.Sid, $null, 3, $null)
            $st = Get-AtmAutoPurgeTaskState
            Assert-True ($st.State -ceq 'DIVERGENT' -and (@($st.Reasons) -join ',') -ceq 'TASK_ACTION_ARGUMENTS') "estado DIVERGENT com o motivo ($($st.State) $(@($st.Reasons) -join ','))"
            $xml2 = [string](& $getTask $n2).Xml
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeUnschedule -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Aborted -ceq 'AUTOPURGE_TASK_DIVERGENT' -and $asked.Count -eq 0 -and -not $r.Done) "desagendar recusa a divergente sem perguntar ($($r.Aborted))"
            Assert-Eq (Unregister-AtmAutoPurgeTask -Sid $me.Sid -EntryPoint $ep) 'AUTOPURGE_TASK_DIVERGENT' 'remocao direta recusa a divergente'
            Assert-Eq ([string](& $getTask $n2).Xml) $xml2 'a divergente ficou intacta'
            $t = Get-RstHost { Show-AtmAutoPurgeTaskResult -Result $r }
            Assert-True ($t.Contains('AUTOPURGE_TASK_DIVERGENT') -and $t.Contains('TASK_ACTION_ARGUMENTS')) 'o resultado mostra o codigo e o motivo'
            # V0.5 M4a: another task in the folder (the divergent test task n2): the command removes its own task n3, and
            # the folder stays NOT_EMPTY, with nothing tried and nothing named.
            $script:AtmAutoPurgeTaskNameOverride = $n3
            $asked.Clear()
            $r = Invoke-AtmAutoPurgeSchedule -ConfigDir $cfgOn -Installed -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Done) "terceira tarefa de teste criada ($($r.Aborted))"
            $r = Invoke-AtmAutoPurgeUnschedule -PlanPresenter $pres -ConfirmationReader $rd
            $pf = (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager')
            Assert-True ($r.Done -and $r.Task.State -ceq 'ABSENT' -and [string]$r.Folder.State -ceq 'NOT_EMPTY' -and $r.Folder.Tasks -eq 1 -and $r.Folder.Folders -eq 0 -and $null -eq $r.Folder.Code) "outra tarefa na pasta: a propria removida, a pasta NOT_EMPTY ($($r.Folder.State), $($r.Folder.Tasks) tarefa(s))"
            Assert-True ([int]$pf.GetTasks(1).Count -eq 1 -and [string](& $getTask $n2).Xml -ceq $xml2) 'a pasta fica com a outra tarefa, intacta'
            $t = Get-RstHost { Show-AtmAutoPurgeTaskResult -Result $r }
            Assert-True ($t.Contains((Get-AtmText 'tf.notEmpty' '\AgentTempManager' 1 0)) -and -not $t.Contains($n2)) 'o resultado diz que a pasta fica, so com a contagem (sem nomear a outra tarefa)'
        } finally { Reset-ApSeams $prevConsole; Clear-ApTestTask $n1; Clear-ApTestTask $n2; Clear-ApTestTask $n3 }
    }

    Test-Case 'Isolamento P6b' 'Limite final do agendador (so na CI, runner descartavel, nomes de teste; V0.5 M4a): uma pasta de teste \AtmTest-<8 hex> com uma tarefa de teste; DeleteFolder direto (codigo de teste) sobre ela e recusado pelo proprio agendador, com o codigo, e a pasta e a tarefa ficam; depois a tarefa e a pasta de teste saem pelos nomes exatos' {
        if ($env:GITHUB_ACTIONS -ne 'true') { $script:caseSkipped = $true; $script:caseNote = 'cria uma pasta e uma tarefa agendadas reais: so na CI (runner descartavel), nunca local'; return }
        # Test code only: this folder and this task are the suite's (test names), and are removed here by those names.
        $fName = 'AtmTest-' + [guid]::NewGuid().ToString('N').Substring(0, 8)
        $tName = New-ApTestName
        if ($fName -cnotmatch '^AtmTest-[0-9a-f]{8}$' -or $tName -cnotmatch '^AutoPurgeTest-[0-9a-f]{8}$') { throw 'nomes de teste fora da forma' }
        $me = Get-AtmCurrentIdentity
        $svc = Connect-AtmTaskScheduler
        $rootF = $svc.GetFolder('\')
        $made = $false
        try {
            $tf = $rootF.CreateFolder($fName, $null); $made = $true
            $null = $tf.RegisterTaskDefinition($tName, (New-AtmAutoPurgeTaskDefinition -Service $svc -Sid $me.Sid -EntryPoint (Get-AtmAutoPurgeEntryPoint) -Now ([datetime]::Now.AddDays(3))), 2, $me.Sid, $null, 3, $null)
            $hr = 0
            try { $rootF.DeleteFolder($fName, 0) } catch { $hr = [int](Get-AtmInnerException $_.Exception).HResult }
            $still = $true; try { $null = $svc.GetFolder('\' + $fName).GetTask($tName) } catch { $still = $false }
            Assert-True ($hr -ne 0 -and $still) ("DeleteFolder de uma pasta com tarefa: recusado pelo agendador (0x{0:X8}), a pasta e a tarefa ficam ({1})" -f $hr, $still)
            # The code reaches the CI log and the report through the case's note (the host output of a case is discarded).
            $script:caseNote = ('limite final: DeleteFolder recusado pelo agendador com 0x{0:X8}; a pasta e a tarefa de teste ficaram' -f $hr)
        } finally {
            if ($made) {
                try { $svc.GetFolder('\' + $fName).DeleteTask($tName, 0) } catch { $null = $_ }
                try { $rootF.DeleteFolder($fName, 0) } catch { $null = $_ }
            }
        }
    }

    Test-Case 'V0.5 M4a' 'M4a real (so na CI, runner descartavel, nome de teste MonitorTest-<8 hex>, trava aberta so na memoria da suite): monitor disable no agendador real - a tarefa de coleta de teste (a definicao do produto, registrada pelo teste) relida PRESENT; frase errada nao remove nada; com outra tarefa de teste na pasta, o disable remove so a propria e a pasta fica (NOT_EMPTY, so a contagem, a outra intacta e nao nomeada); sozinha na pasta, o disable remove a tarefa e depois a pasta (REMOVED, a pasta nao existe mais); o token elevado do runner chega a pergunta' {
        if ($env:GITHUB_ACTIONS -ne 'true') { $script:caseSkipped = $true; $script:caseNote = 'registra e remove tarefas agendadas reais: so na CI (runner descartavel), nunca local; local, o disable so com o agendador falso (area V0.5 M4a)'; return }
        # Test code registers the monitoring test task (the product's definition, the test name) only so the product's
        # monitor disable can remove it; the gate is opened in this process only and closed in the finally.
        $mName = 'MonitorTest-' + [guid]::NewGuid().ToString('N').Substring(0, 8)
        $aName = New-ApTestName
        if ($mName -cnotmatch '^MonitorTest-[0-9a-f]{8}$' -or $aName -cnotmatch '^AutoPurgeTest-[0-9a-f]{8}$') { throw 'nomes de teste fora da forma' }
        $me = Get-AtmCurrentIdentity
        $mEp = Get-AtmMonitorEntryPoint
        $asked = New-Object System.Collections.Generic.List[string]
        $pres = { param($p) $script:m4realPlan = $p; $asked.Add('plan') }
        $rd = { param($ph, $k) $asked.Add($k); $ph }
        $folderOf = { (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager') }
        $regMon = { $svc = Connect-AtmTaskScheduler; $null = $svc.GetFolder('\AgentTempManager').RegisterTaskDefinition($mName, (New-AtmMonitorTaskDefinition -Service $svc -Sid $me.Sid -EntryPoint $mEp -IntervalHours 6), 2, $me.Sid, $null, 3, $null) }
        $prevConsole = $script:AtmCleanConsoleSource
        $notes = New-Object System.Collections.Generic.List[string]
        try {
            $script:AtmCleanConsoleSource = { $true }
            $script:AtmAutoPurgeTaskNameOverride = $aName
            $script:AtmMonitorTaskNameOverride = $mName
            $script:AtmMonitoringEnabled = $true
            # The other test task first: the product's own registration creates the folder when it is missing.
            Assert-Eq (Register-AtmAutoPurgeTask -Sid $me.Sid -EntryPoint (Get-AtmAutoPurgeEntryPoint)) $null 'a outra tarefa de teste (purga) registrada pelo produto'
            & $regMon
            Assert-Eq (Get-AtmMonitorTaskState).State 'PRESENT' 'a tarefa de coleta de teste relida PRESENT (a definicao exata do produto)'
            $r = Invoke-AtmMonitorDisable -PlanPresenter $pres -ConfirmationReader { param($ph, $k) $asked.Add($k); 'nao' }
            Assert-True ($r.Aborted -ceq 'MONITOR_TASK_NOT_CONFIRMED' -and ($asked -join ',') -ceq 'plan,monitor-disable' -and $null -eq $r.Folder -and (Get-AtmMonitorTaskState).State -ceq 'PRESENT') "frase errada nao remove nada; o token elevado do runner chegou a pergunta ($($r.Aborted) $($asked -join ','))"
            Assert-True ($script:m4realPlan.TaskPath -ceq ('\AgentTempManager\' + $mName) -and $script:m4realPlan.IntervalHours -eq 6 -and $script:m4realPlan.Folder -ceq '\AgentTempManager') 'o plano: a tarefa de teste, o intervalo e a pasta'
            $pre = [int](& $folderOf).GetTasks(1).Count
            $asked.Clear()
            $r = Invoke-AtmMonitorDisable -PlanPresenter $pres -ConfirmationReader $rd
            Assert-True ($r.Done -and -not $r.Aborted -and $r.Task.State -ceq 'ABSENT' -and [string]$r.Folder.State -ceq 'NOT_EMPTY' -and $r.Folder.Tasks -eq ($pre - 1) -and $r.Folder.Folders -eq 0 -and $null -eq $r.Folder.Code) "outra tarefa na pasta: a propria removida, a pasta NOT_EMPTY ($($r.Aborted) $($r.Folder.State), $($r.Folder.Tasks) de $pre)"
            $other = $null; try { $other = (& $folderOf).GetTask($aName) } catch { $null = $_ }
            Assert-True ($null -ne $other) 'a outra tarefa de teste ficou'
            $t = Get-RstHost { Show-AtmMonitorDisableResult -Result $r }
            Assert-True ($t.Contains((Get-AtmText 'tf.notEmpty' '\AgentTempManager' $r.Folder.Tasks 0)) -and -not $t.Contains($aName)) 'o resultado diz que a pasta fica, so com a contagem'
            $notes.Add("com outra tarefa: NOT_EMPTY ($($r.Folder.Tasks) tarefa(s))")
            Clear-ApTestTask $aName
            $others = [int](& $folderOf).GetTasks(1).Count
            & $regMon
            $asked.Clear()
            $r = Invoke-AtmMonitorDisable -PlanPresenter $pres -ConfirmationReader $rd
            $gone = $false; try { $null = (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager') } catch { $gone = [bool](Test-AtmTaskNotFound $_.Exception) }
            if ($others -eq 0) {
                Assert-True ($r.Done -and $r.Task.State -ceq 'ABSENT' -and [string]$r.Folder.State -ceq 'REMOVED' -and $null -eq $r.Folder.Code -and $gone) "sozinha na pasta: a tarefa e depois a pasta (REMOVED, a pasta nao existe mais; $($r.Folder.State) $($r.Folder.Code))"
                $t = Get-RstHost { Show-AtmMonitorDisableResult -Result $r }
                Assert-True ($t.Contains((Get-AtmText 'mon.task.removed' ('\AgentTempManager\' + $mName))) -and $t.Contains((Get-AtmText 'tf.removed' '\AgentTempManager'))) 'o resultado mostra a tarefa e a pasta removidas'
                $notes.Add('sozinha: REMOVED')
            } else {
                Assert-True ($r.Done -and $r.Task.State -ceq 'ABSENT' -and [string]$r.Folder.State -ceq 'NOT_EMPTY' -and -not $gone) "o runner ja tinha $others tarefa(s) na pasta: NOT_EMPTY ($($r.Folder.State))"
                $notes.Add("REMOVED nao observavel: o runner ja tinha $others tarefa(s) na pasta (NOT_EMPTY)")
            }
            $script:caseNote = 'disable real: ' + ($notes -join '; ')
        } finally {
            $script:AtmMonitoringEnabled = $false
            $script:AtmMonitorTaskNameOverride = $null
            Reset-ApSeams $prevConsole
            try { (Connect-AtmTaskScheduler).GetFolder('\AgentTempManager').DeleteTask($mName, 0) } catch { $null = $_ }
            Clear-ApTestTask $aName
        }
        Assert-Eq $script:AtmMonitoringEnabled $false 'trava fechada de novo'
    }

    # ------------------------------------------------------------------ trusted accounts per engine (FIX-TRUSTED-SIDS)
    Test-Case 'Contas confiaveis' 'Cada motor com a sua lista: com Clean, Isolate e Diagnose carregados na ordem do lancador, o gate 4 usa a lista declarada no Engine.Clean (com OWNER RIGHTS) e a regra de local do Git a sua propria (sem OWNER RIGHTS); nenhum arquivo atribui a lista de outro motor' {
        $declared = @('S-1-5-18', 'S-1-5-32-544', 'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464', 'S-1-3-0', 'S-1-3-4')
        $git = @('S-1-5-18', 'S-1-5-32-544', 'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464', 'S-1-3-0')
        # The suite loads the engines in the launcher's order (Clean, Isolate, Diagnose), as the launcher itself does.
        $cli = [IO.File]::ReadAllText((Join-Path $srcDir 'agent-temp.ps1'))
        Assert-True ($cli.IndexOf(". (Join-Path `$here 'lib\Engine.Clean.ps1')") -lt $cli.IndexOf(". (Join-Path `$here 'lib\Engine.Diagnose.ps1')")) 'lancador: Clean antes de Diagnose'
        Assert-Eq (@($script:AtmTrustedWriterSids) -join ',') ($declared -join ',') 'lista efetiva do gate 4 = a declarada no Engine.Clean'
        Assert-Eq (@($script:AtmGitTrustedWriterSids) -join ',') ($git -join ',') 'lista da regra de local do Git inalterada'
        $assign = @{}
        foreach ($fi in @(Get-ChildItem -LiteralPath $srcDir -Recurse -File | Where-Object { $_.Extension -in @('.ps1', '.psm1') })) {
            $t = [IO.File]::ReadAllText($fi.FullName)
            foreach ($n in @('AtmTrustedWriterSids', 'AtmGitTrustedWriterSids')) { foreach ($m in [regex]::Matches($t, '\$script:' + $n + '\s*=')) { $assign[$n] = @($assign[$n]) + @($fi.Name) } }
            if ($fi.Name -ne 'Engine.Clean.ps1') { Assert-True (-not [regex]::IsMatch($t, '\$script:AtmTrustedWriterSids\b')) "$($fi.Name) nao usa a lista do gate 4" }
            if ($fi.Name -ne 'Engine.Diagnose.ps1') { Assert-True (-not $t.Contains('$script:AtmGitTrustedWriterSids')) "$($fi.Name) nao usa a lista do Git" }
        }
        Assert-Eq (@($assign['AtmTrustedWriterSids'] | Where-Object { $_ }) -join ',') 'Engine.Clean.ps1' 'lista do gate 4 atribuida uma vez, so no Engine.Clean'
        Assert-Eq (@($assign['AtmGitTrustedWriterSids'] | Where-Object { $_ }) -join ',') 'Engine.Diagnose.ps1' 'lista do Git atribuida uma vez, so no Engine.Diagnose'
    }
    Test-Case 'Contas confiaveis' 'Gate 4: uma ACE OWNER RIGHTS numa pasta cujo dono e o SID do perfil nao gera ESCRITA_CONCEDIDA_A_TERCEIROS; uma ACE de escrita de outro SID continua gerando; a regra de local do Git continua recusando OWNER RIGHTS' {
        $mk = {
            param([string]$Name, [string[]]$Extra)
            # A new folder created WITH its security (no existing ACL changed): the owner, SYSTEM, Administrators, plus -Extra.
            $sec = New-Object Security.AccessControl.DirectorySecurity
            $sec.SetAccessRuleProtection($true, $false)
            foreach ($s in @(@($testOwnerSid, 'S-1-5-18', 'S-1-5-32-544') + @($Extra) | Select-Object -Unique)) { $sec.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($s)), 'Modify', 'ContainerInherit, ObjectInherit', 'None', 'Allow'))) }
            $d = Join-Path $sandbox ('trusted-sids\' + $Name)
            [void][IO.Directory]::CreateDirectory((Split-Path -Parent $d))
            # Created with its security: Directory.CreateDirectory(path, security) on .NET Framework (PowerShell 5.1),
            # FileSystemAclExtensions.Create(DirectoryInfo, security) on .NET (PowerShell 7).
            if ($PSVersionTable.PSEdition -eq 'Core') { [IO.FileSystemAclExtensions]::Create((New-Object IO.DirectoryInfo $d), $sec) }
            else { [void][IO.Directory]::CreateDirectory($d, $sec) }
            return $d
        }
        $ow = & $mk 'owner-rights' @('S-1-3-4')
        Assert-Eq ((Get-Acl -LiteralPath $ow).GetOwner([Security.Principal.SecurityIdentifier]).Value) $testOwnerSid 'dono = SID do perfil de teste'
        $pb = @(Get-AtmAclProblems -Path $ow -OwnerSid $testOwnerSid)
        Assert-Eq $pb.Count 0 "OWNER RIGHTS aceito no gate 4 ($($pb -join ' ; '))"
        $other = & $mk 'authenticated-users' @('S-1-5-11')
        $pb = @(Get-AtmAclProblems -Path $other -OwnerSid $testOwnerSid)
        Assert-True ($pb.Count -eq 1 -and $pb[0] -eq (Get-AtmText 'reason.thirdPartyWrite' 'S-1-5-11' $other)) "outro SID com escrita: recusado ($($pb -join ' ; '))"
        # The Git location rule is unchanged: OWNER RIGHTS with write is not trusted there. Its owner rule asks for SYSTEM,
        # Administrators, TrustedInstaller or CREATOR OWNER, so the ACE is reached only when the test owner is one of them.
        if ($testOwnerSid -ceq 'S-1-5-32-544') {
            $clean = & $mk 'git-clean' @()
            Assert-True (Test-AtmTrustedLocationAcl -Path $clean) 'Git: so contas confiaveis -> confiavel'
            Assert-True (-not (Test-AtmTrustedLocationAcl -Path $ow)) 'Git: OWNER RIGHTS com escrita -> nao confiavel (como antes)'
        } else {
            Assert-True (-not (Test-AtmTrustedLocationAcl -Path $ow)) 'Git: dono que nao e conta confiavel -> nao confiavel (como antes)'
            $script:caseNote = 'regra do Git com ACE OWNER RIGHTS so alcancavel com dono Administradores (CI elevada); aqui o dono e o usuario'
        }
    }

    # ------------------------------------------------------------------ TUI (headless) and layering
    function New-Key { param([string]$Key, [char]$Char = [char]0) return New-Object ConsoleKeyInfo($Char, [ConsoleKey]$Key, $false, $false, $false) }
    function Invoke-HeadlessTui {
        param([object[]]$Keys, [hashtable]$InvArgs, [string[]]$Lines = @(), [switch]$Ascii, [int]$W = 120, [int]$H = 30, [scriptblock]$DiagRunner = $null, [scriptblock]$ApTaskReader = $null)
        $script:tuiKeys = New-Object System.Collections.Generic.Queue[object]; foreach ($k in $Keys) { $script:tuiKeys.Enqueue($k) }
        $script:tuiLines = New-Object System.Collections.Generic.Queue[string]; foreach ($l in $Lines) { $script:tuiLines.Enqueue($l) }
        $script:tuiFrames = New-Object System.Collections.Generic.List[string]
        $script:tuiPrompts = New-Object System.Collections.Generic.List[string]
        $ks = { if ($script:tuiKeys.Count -gt 0) { $script:tuiKeys.Dequeue() } else { $null } }
        # '@PHRASE' answers with the phrase the clean flow has just shown (AUT-2: the final phrase carries the plan id).
        $lr = { param($p, $shown) $script:tuiPrompts.Add([string]$p); $v = $(if ($script:tuiLines.Count -gt 0) { $script:tuiLines.Dequeue() } else { '' }); if ($v -ceq '@PHRASE') { [string]$shown } else { $v } }
        $rd = { param($frame) $script:tuiFrames.Add((($frame | ForEach-Object { ($_ | ForEach-Object { $_.Text }) -join '' }) -join "`n")) }
        $tuiArgs = @{ InventoryArgs = $InvArgs; KeySource = $ks; Renderer = $rd; LineReader = $lr; Ascii = $Ascii; Width = $W; Height = $H }
        if ($null -ne $DiagRunner) { $tuiArgs['DiagnoseRunner'] = $DiagRunner; $tuiArgs['DiagnoseArgs'] = @{} }
        if ($null -ne $ApTaskReader) { $tuiArgs['AutoPurgeTaskReader'] = $ApTaskReader }
        $st = Start-AtmTui @tuiArgs
        return [pscustomobject]@{ State = $st; Frames = $script:tuiFrames.ToArray(); Prompts = $script:tuiPrompts.ToArray() }
    }
    Test-Case 'TUI' 'Isolamento 0.3.x headless (en-US e pt-BR): I sobre a raiz selecionada mostra so o plano com a trava fechada (sem pergunta de log, nada movido); area Quarentena (Z) so leitura: lista, inspect e V verify sem gravar nada; mostra o comando da CLI e nunca restaura (T-ISO-6)' {
        $saved = $script:AtmIsolationQuarantineRoot
        [void][IO.Directory]::CreateDirectory((Join-Path $sandbox 'tuiq-home'))
        $script:AtmIsolationQuarantineRoot = Join-Path $sandbox 'tuiq-home\AgentTempManager\Q'
        $old = Get-AtmLanguage
        try {
            $e = New-RstEntry 'tuiq'
            if (-not $e) { return }
            Assert-True ($e.Iso.Results[0].Outcome -ceq 'COMPLETE') "entrada para a area ($($e.Iso.Aborted)$($e.Iso.StoppedBy))"
            $p = New-TestProfile 'tuiiso'; $r = New-TestRoot -ProfileInfo $p
            $before = Get-IsoRelativeListing $r
            $snap = Get-RstSnapshot $script:AtmIsolationQuarantineRoot
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                # The quarantine area judges entries by the inventory's identity: the run's profile is in this inventory.
                $ia = Get-InvArgs -Profiles @($p, $e.Run.Profile)
                $keys = @((New-Key 'Z' 'z'), (New-Key 'Enter'), (New-Key 'V' 'v'), (New-Key 'Escape'), (New-Key 'Escape'), (New-Key 'D4' '4'), (New-Key 'I' 'i'), (New-Key 'Escape'), (New-Key 'Q' 'q'))
                $o = Invoke-HeadlessTui -Keys $keys -InvArgs $ia -Lines @('') -H 40
                $all = $o.Frames -join "`n=====`n"
                # Without Unicode output the frames fall back to ASCII: either form of a text counts.
                $has = { param([string]$T) $all.Contains($T) -or $all.Contains((ConvertTo-AtmAscii $T)) }
                Assert-True ((& $has ('[I] ' + (Get-AtmText 'menu.isolate'))) -and (& $has ('[Z] ' + (Get-AtmText 'menu.quarantine')))) "$lang`: menu com I e Z"
                Assert-True ($all.Contains($e.Id) -and $all.Contains('ISOLATED')) "$lang`: entrada listada com o estado"
                Assert-True ((& $has (Get-AtmText 'q.cliOnly' $e.Id)) -and (& $has (Get-AtmText 'tui.q.cliOnly'))) "$lang`: comando da CLI mostrado, sem restaurar"
                Assert-True (& $has ((Get-AtmText 'tui.q.verifyResult' 'OK' '').Trim())) "$lang`: V verificou (OK)"
                Assert-True ($o.Prompts -contains (Get-AtmText 'tuiclean.enterPanel') -and -not ($o.Prompts -contains (Get-AtmText 'tuiiso.askLog'))) "$lang`: isolar com a trava fechada: nenhuma pergunta de log ($($o.Prompts -join ' | '))"
                foreach ($fr in $o.Frames) { foreach ($ln in ($fr -split "`n")) { Assert-True ($ln.Length -le 120) "$lang`: linha excede a largura: $($ln.Length)" } }
            }
            Assert-Eq (Get-IsoRelativeListing $r) $before 'raiz intacta: so o plano'
            Assert-Eq (Get-RstSnapshot $script:AtmIsolationQuarantineRoot) $snap 'quarentena e manifesto identicos: a TUI so leu'
            Assert-Eq (Get-IsoEntryCount) 1 'nenhuma entrada nova'
        } finally { $script:AtmIsolationQuarantineRoot = $saved; Set-AtmLanguage -Requested $old }
    }
    Test-Case 'TUI' 'Quarentena 0.3.x P4 headless (en-US e pt-BR): EXPIRED (relogio injetavel da suite) e PURGED listados com o estado; o detalhe mostra o comando da CLI de expurgo e a politica efetiva; a TUI nunca expurga nem restaura: quarentena e manifestos identicos' {
        $saved = $script:AtmIsolationQuarantineRoot
        [void][IO.Directory]::CreateDirectory((Join-Path $sandbox 'tuip4-home'))
        $script:AtmIsolationQuarantineRoot = Join-Path $sandbox 'tuip4-home\AgentTempManager\Q'
        $old = Get-AtmLanguage
        try {
            $a = New-RstEntry 'tuip4a'
            $b = New-RstEntry 'tuip4b'
            if (-not $a -or -not $b) { return }
            $dir = New-TestCleanLogDir 'tuip4'
            if (-not $dir) { return }
            $pr = Invoke-PurOpen (Get-PurArgs $b (New-TestCleanOperator) (Join-Path $dir 'purge.jsonl'))
            Assert-True (@($pr.Results).Count -eq 1 -and $pr.Results[0].Outcome -ceq 'COMPLETE') "entrada expurgada para a area ($($pr.Aborted)$($pr.StoppedBy))"
            $snap = Get-RstSnapshot $script:AtmIsolationQuarantineRoot
            $script:AtmQuarantineClock = { [datetime]::UtcNow.AddDays(31) }
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $ia = Get-InvArgs -Profiles @($a.Run.Profile, $b.Run.Profile)
                $keys = @((New-Key 'Z' 'z'), (New-Key 'Enter'), (New-Key 'Escape'), (New-Key 'Escape'), (New-Key 'Q' 'q'))
                $o = Invoke-HeadlessTui -Keys $keys -InvArgs $ia -H 40
                $all = $o.Frames -join "`n=====`n"
                $has = { param([string]$T) $all.Contains($T) -or $all.Contains((ConvertTo-AtmAscii $T)) }
                # The state of each entry is on its own row of the list (the policy line also says EXPIRED: never counted).
                $lines = @($all -split "`n")
                $rowA = @($lines | Where-Object { $_.Contains($a.Id) -and $_ -cmatch '\bEXPIRED\b' -and -not $_.Contains('ISOLATED') })
                $rowB = @($lines | Where-Object { $_.Contains($b.Id) -and $_ -cmatch '\bPURGED\b' })
                Assert-True ($rowA.Count -ge 1 -and $rowB.Count -ge 1) "$lang`: a linha da entrada isolada diz EXPIRED e a da expurgada diz PURGED"
                Assert-True ((& $has (Get-AtmText 'q.cliPurge' $a.Id)) -or (& $has (Get-AtmText 'q.cliPurge' $b.Id))) "$lang`: comando da CLI de expurgo no detalhe"
                # At 120 columns the policy line wraps (hard, by characters): its first 40 characters are on one line.
                $polHead = (Format-AtmQuarantinePolicy (Get-AtmQuarantinePolicy -ConfigDir $cfgDir)).Substring(0, 40)
                Assert-True ((& $has $polHead) -and $polHead.Contains('30') -and (& $has (Get-AtmText 'tui.q.cliOnly'))) "$lang`: politica efetiva (retencao de 30 dias); a TUI nao restaura nem expurga"
                foreach ($fr in $o.Frames) { foreach ($ln in ($fr -split "`n")) { Assert-True ($ln.Length -le 120) "$lang`: linha excede a largura: $($ln.Length)" } }
            }
        } finally { $script:AtmQuarantineClock = $null; $script:AtmIsolationQuarantineRoot = $saved; Set-AtmLanguage -Requested $old }
        Assert-Eq (Get-RstSnapshot (Join-Path $sandbox 'tuip4-home\AgentTempManager\Q')) $snap 'quarentena e manifestos identicos: a TUI so leu'
    }
    Test-Case 'Isolamento P6b' 'TUI headless (en-US e pt-BR; so exibicao, T-ISO-6): com autoPurge = true o aviso de expurgo automatico ligado fica sob o cabecalho de toda tela (menu, painel, ajuda, quarentena, ocupada); a area Quarentena mostra o estado da tarefa do usuario (lido ao abrir a area, nunca agendado nem desagendado); sem a politica, nenhum aviso; linhas dentro da largura' {
        $saved = $script:AtmIsolationQuarantineRoot
        $script:AtmIsolationQuarantineRoot = Join-Path $sandbox 'tuip6b-home\AgentTempManager\Q'
        $old = Get-AtmLanguage
        try {
            $p = New-TestProfile 'tuip6b'; $null = New-TestRoot -ProfileInfo $p
            $script:apReads = 0
            $reader = { $script:apReads++; [pscustomobject]@{ State = 'PRESENT'; TaskPath = '\AgentTempManager\AutoPurge-0123456789abcdef'; Enabled = $true; NextRunTime = [datetime]'2026-11-04T12:31:00'; LastRunTime = $null; LastResult = $null; Reasons = @() } }
            $keys = @((New-Key 'D1' '1'), (New-Key 'Escape'), (New-Key 'H' 'h'), (New-Key 'Escape'), (New-Key 'Z' 'z'), (New-Key 'Escape'), (New-Key 'Q' 'q'))
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $ia = Get-InvArgs -Profiles @($p)
                $ia['ConfigDir'] = New-PurConfig 'tuip6b-on' '{"schema":"atm.quarantine-policy/1","autoPurge":true}'
                $script:apReads = 0
                $o = Invoke-HeadlessTui -Keys $keys -InvArgs $ia -H 40 -ApTaskReader $reader
                # Headless frames are transliterated when the console has no Unicode output (ASCII fallback): both forms count.
                $head = (Get-AtmText 'q.policyWarn.AUTOPURGE_ON').Substring(0, 30)
                $bad = @($o.Frames | Where-Object { $r1 = ($_ -split "`n")[1]; $r1.IndexOf($head) -lt 0 -and $r1.IndexOf((ConvertTo-AtmAscii $head)) -lt 0 })
                Assert-True ($o.Frames.Count -ge 5 -and $bad.Count -eq 0) "$lang`: aviso sob o cabecalho em todos os $($o.Frames.Count) quadros (sem ele: $($bad.Count))"
                $q = @($o.Frames | Where-Object { $_.Contains('\AgentTempManager\AutoPurge-0123456789abcdef') })
                Assert-True ($q.Count -ge 1 -and $script:apReads -eq 1 -and $o.State.AutoPurgeTask.State -ceq 'PRESENT') "$lang`: area Quarentena mostra a tarefa (leituras: $($script:apReads))"
                foreach ($fr in $o.Frames) { foreach ($ln in ($fr -split "`n")) { Assert-True ($ln.Length -le 120) "$lang`: linha excede a largura: $($ln.Length)" } }
                $ia['ConfigDir'] = $cfgDir
                $o = Invoke-HeadlessTui -Keys $keys -InvArgs $ia -H 40 -ApTaskReader $reader
                $allOff = $o.Frames -join "`n"
                Assert-True (-not $allOff.Contains($head) -and -not $allOff.Contains((ConvertTo-AtmAscii $head))) "$lang`: sem a politica, nenhum aviso"
            }
        } finally { $script:AtmIsolationQuarantineRoot = $saved; Set-AtmLanguage -Requested $old }
    }
    Test-Case 'TUI' 'Navegacao headless: dashboard, usuarios, roots, detalhe, classes, erros, preview, ajuda' {
        $p = New-TestProfile 'tui'
        $r1 = New-TestRoot -ProfileInfo $p; $r2 = New-TestRoot -ProfileInfo $p
        [IO.File]::SetLastWriteTimeUtc((Join-Path $r2 'a.txt'), $nowFuture.AddHours(-1))
        $ia = Get-InvArgs -Profiles @($p)
        $keys = @((New-Key 'D1' '1'), (New-Key 'Escape'), (New-Key 'D2' '2'), (New-Key 'Enter'), (New-Key 'Enter'), (New-Key 'Escape'), (New-Key 'Escape'), (New-Key 'Escape'),
            (New-Key 'D6' '6'), (New-Key 'Escape'), (New-Key 'D8' '8'), (New-Key 'Escape'), (New-Key 'D9' '9'), (New-Key 'PageDown'), (New-Key 'Escape'), (New-Key 'P' 'p'), (New-Key 'DownArrow'), (New-Key 'Enter'), (New-Key 'Escape'), (New-Key 'Escape'),
            (New-Key 'H' 'h'), (New-Key 'Escape'), (New-Key 'D3' '3'), (New-Key 'Enter'), (New-Key 'Escape'), (New-Key 'Escape'), (New-Key 'Q' 'q'))
        $o = Invoke-HeadlessTui -Keys $keys -InvArgs $ia -H 40
        $all = $o.Frames -join "`n=====`n"
        foreach ($s in @((Get-AtmText 'menu.dashboard'), (Get-AtmText 'dash.profiles'), (Get-AtmText 'menu.users'), (Get-AtmText 'tui.detailOf' '').Trim(), 'RECENT', (Get-AtmText 'menu.blockedTitle'), (Get-AtmText 'menu.errorsTitle'), 'Preview', 'ELIGIBLE', (Get-AtmText 'menu.help'), (Get-AtmText 'menu.projects'), 'ORPHAN_SUSPECTED', (Get-AtmText 'det.fingerprint'))) { Assert-True ($all.Contains($s)) "tela contem '$s'" }
        Assert-True ($all.Contains((Split-Path $r1 -Leaf))) 'root listada'
        foreach ($f in $o.Frames) { foreach ($ln in ($f -split "`n")) { Assert-True ($ln.Length -le 120) "linha excede largura: $($ln.Length)" } }
        Assert-True ([IO.Directory]::Exists($r1) -and [IO.Directory]::Exists($r2)) 'TUI nao alterou nada'
    }
    Test-Case 'TUI' 'Dashboard em 120 e 160 colunas (en-US e pt-BR): os quatro cartoes inteiros dentro da largura (bordas fechadas), textos e numeros sem corte; 4 por linha so a partir de 130 colunas (inspecao do buffer)' {
        $p = New-TestProfile 'dash120'; $null = New-TestRoot -ProfileInfo $p
        $G = Get-AtmTuiGlyphs
        $old = Get-AtmLanguage
        $bad = New-Object System.Collections.Generic.List[string]
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                foreach ($w in @(120, 160)) {
                    $o = Invoke-HeadlessTui -Keys @((New-Key 'D1' '1'), (New-Key 'Escape'), (New-Key 'Q' 'q')) -InvArgs (Get-InvArgs -Profiles @($p)) -W $w -H 40
                    $fr = @($o.Frames | Where-Object { $_.Contains((Get-AtmText 'dash.errorsCoverage')) })
                    if ($fr.Count -eq 0) { $bad.Add("$lang $($w): dashboard nao desenhado"); continue }
                    $ls = @($fr[0] -split "`n")
                    $long = @($ls | Where-Object { $_.TrimEnd().Length -gt ($w - 1) }).Count
                    $cnt = { param($Glyph) @($ls | ForEach-Object { ([regex]::Matches($_, [regex]::Escape($Glyph))).Count } | Measure-Object -Sum).Sum }
                    $cut = @($ls | Where-Object { $_.Contains($G.V) -and $_.Contains($G.Ell) }).Count
                    $tops = @($ls | Where-Object { $_.Contains($G.TL) -and $_.Contains($G.TR) })
                    $perRow = ([regex]::Matches(([string]$tops[0]), [regex]::Escape($G.TR))).Count
                    $want = $(if ($w -ge 130) { 4 } else { 2 })
                    $text = $fr[0]
                    # Each label whole, with its number (any value) and unit, as the text table writes it.
                    $pat = { param([string]$Key, [string]$Num) [regex]::Escape((Get-AtmText $Key '@@N@@')).Replace('@@N@@', $Num) }
                    $full = @((& $pat 'dash.discovered' '\d+'), (& $pat 'dash.audited' '\d+'), (& $pat 'dash.incomplete' '\d+'), (& $pat 'dash.partitions' '\d+'), (& $pat 'dash.mbPhysical' '[\d.,]+'), (& $pat 'dash.readErrors' '\d+'), (& $pat 'dash.incompleteMeas' '\d+'), (& $pat 'dash.coverage' '\S+'))
                    $missing = @($full | Where-Object { $text -notmatch $_ })
                    if ($long -gt 0 -or (& $cnt $G.TR) -ne 4 -or (& $cnt $G.BR) -ne 4 -or (& $cnt $G.TL) -ne 4 -or (& $cnt $G.BL) -ne 4 -or $cut -gt 0 -or $perRow -ne $want -or $missing.Count -gt 0) {
                        $bad.Add("$lang $($w): linhas alem da largura $long; cantos TL/TR/BL/BR $(& $cnt $G.TL)/$(& $cnt $G.TR)/$(& $cnt $G.BL)/$(& $cnt $G.BR); linhas de cartao cortadas $cut; cartoes por linha $perRow (esperado $want); textos ausentes: $($missing -join ' | ')")
                    }
                }
            }
        } finally { Set-AtmLanguage -Requested $old }
        Assert-Eq ($bad -join ' || ') '' 'dashboard'
    }
    Test-Case 'TUI' 'Fallback ASCII e terminal estreito (60x20)' {
        $p = New-TestProfile 'tuiascii'
        $null = New-TestRoot -ProfileInfo $p
        $o = Invoke-HeadlessTui -Keys @((New-Key 'D1' '1'), (New-Key 'Escape'), (New-Key 'D4' '4'), (New-Key 'Q' 'q')) -InvArgs (Get-InvArgs -Profiles @($p)) -Ascii -W 60 -H 20
        $all = $o.Frames -join "`n"
        Assert-True ($all -match '^[\x09\x0A\x20-\x7E]*$') 'somente ASCII imprimivel'
        foreach ($f in $o.Frames) { foreach ($ln in ($f -split "`n")) { Assert-True ($ln.Length -le 60) 'largura' } }
    }
    Test-Case 'TUI' 'Excecao restrita de B1 na TUI: preview mostra a categoria nova como nao liberada; a limpeza pela TUI nunca usa a excecao (B1 identico, nenhuma pergunta de risco), nada apagado' {
        $logDir = New-TestCleanLogDir 'tuib1'
        if (-not $logDir) { return }
        $x = New-TestB1Context 'tuib1' 1
        $r = $x.F.Roots[0]
        $old = Get-AtmLanguage
        try {
            foreach ($lang in @('en-US', 'pt-BR')) {
                Set-AtmLanguage -Requested $lang
                $o = Invoke-HeadlessTui -Keys @((New-Key 'P' 'p'), (New-Key 'Escape'), (New-Key 'Q' 'q')) -InvArgs $x.IA -W 160 -H 40
                $all = $o.Frames -join "`n"
                Assert-True ($all.Contains((Get-AtmText 'tui.catDeclaredRisk')) -and $all.Contains('B1_EXCEPTION_RESIDUAL_RISK') -and -not ($all -match 'ELIGIBLE_\S*…')) "$($lang): preview da TUI com rotulo proprio (nunca ELIGIBLE cortado) e motivo de nao liberada"
            }
        } finally { Set-AtmLanguage -Requested $old }
        $o2 = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $x.IA -Lines @('', $r, (Join-Path $logDir 'tuib1.jsonl'), '@PHRASE', '@PHRASE', '@PHRASE', '@PHRASE', '')
        $rej = @(@($o2.State.LastClean.Rejected)[0].Reasons)
        Assert-True ($o2.State.LastClean.Aborted -ceq 'NENHUM_CAMINHO_ELEGIVEL' -and $rej.Count -eq 1 -and ([string]$rej[0]).StartsWith('COBERTURA_DE_PROCESSOS_INCOMPLETA')) "limpeza pela TUI: B1 identico ($($o2.State.LastClean.Aborted))"
        Assert-True (Test-TestT1RootsIntact $x.F) 'nada apagado'
    }
    Test-Case 'TUI' 'Limpeza pela TUI usa o motor: allowlist, plano, frase; cancelamentos nao apagam' {
        # Both prompt flows, whatever the session: an administrator is also asked whether to include other users
        # (answered with an empty line = no), which shifts every later answer by one line.
        # T1: with deletion enabled (this process only) the TUI also asks for a new log file right before the engine.
        $logDir = New-TestCleanLogDir 'tui'
        if (-not $logDir) { return }
        foreach ($asAdmin in @($false, $true)) {
            $p = New-TestProfile ('tuiclean' + [int]$asAdmin)
            $r = New-TestRoot -ProfileInfo $p
            $ia = Get-InvArgs -Profiles @($p) -Identity ([pscustomobject]@{ Sid = $testOwnerSid; Name = $me.Name; IsAdmin = $asAdmin })
            $others = @(if ($asAdmin) { '' })
            $log = { param([string]$Tag) Join-Path $logDir ("{0}-{1}.jsonl" -f $Tag, [int]$asAdmin) }
            $o = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $ia -Lines @('', '', '')
            Assert-True ([IO.Directory]::Exists($r)) "cancelado: preservado (admin=$asAdmin)"
            $o = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $ia -Lines (@('', $r) + $others + @((& $log 'wrong'), '@PHRASE', '@PHRASE', 'APAGAR 1 caminhos', ''))
            Assert-True ([IO.Directory]::Exists($r)) "frase errada: preservado (admin=$asAdmin)"
            Assert-Eq $o.State.LastClean.Aborted 'CONFIRMACAO_AUSENTE_OU_DIVERGENTE' "motor abortou (admin=$asAdmin)"
            Assert-True ([IO.File]::Exists((& $log 'wrong'))) "log da execucao rejeitada criado (admin=$asAdmin)"
            $o = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $ia -Lines (@('', $r) + $others + @('', ''))
            Assert-True ([IO.Directory]::Exists($r) -and $o.State.LastClean.Aborted -ceq 'LOG_REQUIRED') "sem log: recusado antes da confirmacao, preservado (admin=$asAdmin; $($o.State.LastClean.Aborted))"
            $o = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $ia -Lines (@('', "$(Get-Base $p)") + $others + @((& $log 'base'), ''))
            Assert-Eq $o.State.LastClean.Aborted 'NENHUM_CAMINHO_ELEGIVEL' "base recusada pelo motor (admin=$asAdmin)"
            $o = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $ia -Lines (@('', $r) + $others + @((& $log 'ok'), '@PHRASE', '@PHRASE', '@PHRASE', ''))
            Assert-True (-not [IO.Directory]::Exists($r)) "confirmado: excluido pelo motor (admin=$asAdmin)"
            Assert-True ($null -ne $o.State.LastClean.PostInventory) "auditoria posterior (admin=$asAdmin)"
            Assert-Eq (@((Read-TestCleanLogFile (& $log 'ok')).Records | ForEach-Object { $_.type }) -join ',') 'run-start,plan,declaration,confirmation,plan-check,intent,result,run-end' "log da exclusao pela TUI (admin=$asAdmin)"
            Assert-True ($o.Prompts -contains (Get-AtmText 'tuiclean.askLog')) "trava aberta: a TUI pergunta o log (admin=$asAdmin)"
        }
        # Gate closed (every distributed copy): the screen is as before - no log question, plan only, nothing deleted.
        $p = New-TestProfile 'tuicleangate'
        $r = New-TestRoot -ProfileInfo $p
        $ia = Get-InvArgs -Profiles @($p) -Identity ([pscustomobject]@{ Sid = $testOwnerSid; Name = $me.Name; IsAdmin = $false })
        $script:AtmRealDeletionEnabled = $false
        try { $o = Invoke-HeadlessTui -Keys @((New-Key 'L' 'l'), (New-Key 'Q' 'q')) -InvArgs $ia -Lines @('', $r, '') }
        finally { $script:AtmRealDeletionEnabled = $true }
        Assert-True ($o.State.LastClean.Aborted -ceq 'EXCLUSAO_REAL_DESABILITADA_V0_1' -and $null -eq $o.State.LastClean.RunId) "trava fechada: so o plano ($($o.State.LastClean.Aborted))"
        Assert-True (-not ($o.Prompts -contains (Get-AtmText 'tuiclean.askLog')) -and ($o.Prompts -contains (Get-AtmText 'tuiclean.askPath'))) "trava fechada: nenhuma pergunta de log ($($o.Prompts -join ' | '))"
        Assert-True ([IO.Directory]::Exists($r)) 'trava fechada: preservado'
    }
    Test-Case 'Camadas' 'TUI e relatorio nunca chamam APIs de exclusao; motor de auditoria nao exclui nem imprime' {
        $lib = Join-Path $srcDir 'lib'
        foreach ($f in @('Tui.ps1', 'Report.ps1')) {
            $txt = [IO.File]::ReadAllText((Join-Path $lib $f))
            foreach ($pat in @('AtmDeleter', 'DeleteTree', 'Remove-Item', '::Delete(', '.Delete(', 'rd /s', 'rmdir', 'del ')) { Assert-True (-not $txt.Contains($pat)) "$f contem '$pat'" }
        }
        $audit = [IO.File]::ReadAllText((Join-Path $lib 'Engine.Audit.ps1'))
        foreach ($pat in @('AtmDeleter', 'DeleteTree', 'Remove-Item', 'Write-Host', 'Write-Progress', 'Read-Host')) { Assert-True (-not $audit.Contains($pat)) "Engine.Audit contem '$pat'" }
        $clean = [IO.File]::ReadAllText((Join-Path $lib 'Engine.Clean.ps1'))
        foreach ($pat in @('Write-Host', 'Read-Host', 'Remove-Item', '-Force')) { Assert-True (-not $clean.Contains($pat)) "Engine.Clean contem '$pat'" }
        Assert-Eq ([regex]::Matches($clean, 'AtmDeleter\]::DeleteTree').Count) 1 'um unico ponto de exclusao, apos revalidacao'
    }
    Test-Case 'Gate V0.1' 'FINAL-B F-10: motor de exclusao contra arvore descartavel do harness - pasta vazia pinada convertida em juncao dentro da janela (FSCTL) recusada, alvo sentinela intacto; juncao presente antes do inicio, ancestral juncao e renomeacao de pasta pinada recusados sem nada apagado fora da arvore; trava distribuida fechada' {
        # Native engine only (AtmDeleter), on a tree the harness creates; every junction points to a sentinel folder INSIDE
        # the sandbox, so even a defect could only touch sandbox content. The distributed gate is never opened here.
        # The harness opens the gate in memory for its sandbox (top of this file); the distributed copy keeps it closed.
        $gateSrc = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        $gateClosed = { [regex]::Matches($gateSrc, '\$script:AtmRealDeletionEnabled\s*=').Count -eq 1 -and $gateSrc -match '(?m)^\$script:AtmRealDeletionEnabled = \$false\r?$' }
        Assert-True (& $gateClosed) 'trava distribuida fechada (atribuicao unica $false em Engine.Clean.ps1)'
        Initialize-AtmTestReparse
        $f10 = [AgentTempManager.AtmNative]::GetLongPath((New-Item -ItemType Directory -Path (Join-Path $sandbox 'f10')).FullName)
        $sent = Join-Path $f10 'sentinel'
        foreach ($d in @($sent, (Join-Path $sent 'deep'))) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $sent 'keep.txt'), 'keep'); [IO.File]::WriteAllText((Join-Path $sent 'deep\deep.txt'), 'deep')
        $snap = { @(Get-ChildItem -LiteralPath $sent -Recurse -Force | ForEach-Object { $_.FullName.Substring($sent.Length) + '|' + $(if ($_.PSIsContainer) { 'd' } else { [IO.File]::ReadAllText($_.FullName) }) } | Sort-Object) -join ';' }
        $before = & $snap
        $newTree = { param([string]$Name) $t = Join-Path $f10 $Name; foreach ($d in @($t, (Join-Path $t 'empty'), (Join-Path $t 'sub'))) { [void][IO.Directory]::CreateDirectory($d) }; [IO.File]::WriteAllText((Join-Path $t 'top.txt'), 't'); [IO.File]::WriteAllText((Join-Path $t 'sub\file.txt'), 'f'); $t }
        # 1. Inside the window: everything pinned and planned, then another handle turns the empty pinned folder into a
        #    junction (share modes do not stop it: M-1). The bottom-up re-check must refuse it; the target is never traversed.
        $t1 = & $newTree 'tree1'
        $st = @{ Set = $null }
        $hook = [Action[string]]({ param($root) $st.Set = [AtmTestReparse]::SetJunction((Join-Path $root 'empty'), $sent) }.GetNewClosure())
        $r1 = [AgentTempManager.AtmDeleter]::DeleteTree($t1, $hook)
        Assert-Eq $st.Set 'SET_OK' 'juncao gravada na pasta pinada por outro handle (limite documentado)'
        Assert-True (-not $r1.Completed -and [string]$r1.AbortReason -like 'PINNED_DIR_CHANGED*') "exclusao recusada na reverificacao ($($r1.AbortReason))"
        Assert-Eq (& $snap) $before 'alvo sentinela intacto (nada apagado nem atravessado)'
        $lnk = Join-Path $t1 'empty'
        if ((Test-Path -LiteralPath $lnk) -and (([IO.File]::GetAttributes($lnk) -band [IO.FileAttributes]::ReparsePoint) -ne 0)) { [IO.Directory]::Delete($lnk, $false) }
        # 2. A junction already in the tree when the deletion starts: refused while planning, nothing deleted.
        $t2 = & $newTree 'tree2'
        [IO.Directory]::Delete((Join-Path $t2 'empty'), $false)
        $o = & cmd.exe /c "mklink /J `"$(Join-Path $t2 'empty')`" `"$sent`"" 2>&1; Assert-Eq $LASTEXITCODE 0 "juncao de fixture criada ($o)"
        $r2 = [AgentTempManager.AtmDeleter]::DeleteTree($t2)
        Assert-True (-not $r2.Attempted -and $r2.FilesDeleted -eq 0 -and [string]$r2.AbortReason -like 'REPARSE_POINT_FOUND*') "juncao antes do inicio: recusada sem apagar ($($r2.AbortReason))"
        Assert-True ((Test-Path -LiteralPath (Join-Path $t2 'top.txt')) -and (& $snap) -eq $before) 'arvore e sentinela intactas'
        [IO.Directory]::Delete((Join-Path $t2 'empty'), $false)
        # 3. An ancestor that is a junction: refused before anything is pinned.
        $t3 = & $newTree 'tree3'
        $via = Join-Path $f10 'via'
        $o = & cmd.exe /c "mklink /J `"$via`" `"$t3`"" 2>&1; Assert-Eq $LASTEXITCODE 0 "juncao ancestral de fixture criada ($o)"
        $r3 = [AgentTempManager.AtmDeleter]::DeleteTree((Join-Path $via 'sub'))
        Assert-True (-not $r3.Attempted -and [string]$r3.AbortReason -like 'ANCESTOR_REPARSE_POINT*') "ancestral juncao: recusado ($($r3.AbortReason))"
        Assert-True (Test-Path -LiteralPath (Join-Path $t3 'sub\file.txt')) 'nada apagado pelo caminho com juncao'
        [IO.Directory]::Delete($via, $false)
        # 4. A pinned folder cannot be renamed during the window (its identity cannot change under the engine).
        $t4 = & $newTree 'tree4'
        $mv = @{ Threw = $false }
        $hook4 = [Action[string]]({ param($root) try { [IO.Directory]::Move((Join-Path $root 'sub'), (Join-Path $root 'sub-moved')) } catch { $mv.Threw = $true } }.GetNewClosure())
        $r4 = [AgentTempManager.AtmDeleter]::DeleteTree($t4, $hook4)
        Assert-True ($mv.Threw -and -not (Test-Path -LiteralPath (Join-Path $t4 'sub-moved'))) 'renomear pasta pinada durante a janela: recusado pelo sistema'
        Assert-True ($r4.Completed -and -not (Test-Path -LiteralPath $t4)) "arvore descartavel inteira apagada pelo motor depois da tentativa ($($r4.AbortReason))"
        Assert-Eq (& $snap) $before 'sentinela intacta ao final'
        $gateSrc = [IO.File]::ReadAllText((Join-Path $srcDir 'lib\Engine.Clean.ps1'))
        Assert-True (& $gateClosed) 'trava distribuida fechada ao final'
        $script:caseNote = "janela: $($r1.AbortReason -replace ':.*$', ''); antes do inicio: $($r2.AbortReason -replace ':.*$', ''); ancestral: $($r3.AbortReason -replace ':.*$', '')"
    }
    Test-Case 'Gate V0.1' 'FINAL-B F-10: verificacao do caminho final por handle - arvore alcancada por uma unidade subst recusada (PATH_REDIRECTED), nada apagado' {
        $real = Join-Path $sandbox 'f10-subst'
        foreach ($d in @($real, (Join-Path $real 'tree5\sub'))) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $real 'tree5\sub\file.txt'), 'f')
        $sl = $null; foreach ($l in [char[]]'QRSTUVWXYZ') { if (-not (Test-Path "$($l):\")) { $sl = $l; break } }
        if (-not $sl) { $script:caseSkipped = $true; $script:caseNote = 'nenhuma letra de unidade livre'; return }
        $null = cmd /c subst "$($sl):" "`"$real`"" 2>&1
        try {
            if (-not (Test-Path "$($sl):\tree5")) { $script:caseSkipped = $true; $script:caseNote = 'subst indisponivel'; return }
            $r = [AgentTempManager.AtmDeleter]::DeleteTree("$($sl):\tree5")
            Assert-True (-not $r.Attempted -and $r.FilesDeleted -eq 0 -and [string]$r.AbortReason -like '*PATH_REDIRECTED*') "caminho final diferente do pedido: recusado ($($r.AbortReason -replace ':.*$', ''))"
            Assert-True (Test-Path -LiteralPath (Join-Path $real 'tree5\sub\file.txt')) 'nada apagado'
            $script:caseNote = "unidade subst: $($r.AbortReason -replace ':.*$', '')"
        } finally { $null = cmd /c subst "$($sl):" /d 2>&1 }
    }
    Test-Case 'Gate V0.1' 'V0.3 V3a R13: pasta vazia pinada convertida em link simbolico de diretorio dentro da janela (FSCTL) recusada (PINNED_DIR_CHANGED), alvo sentinela intacto' {
        # Native engine only (AtmDeleter), on a tree the harness creates, as the F-10 case above but with a directory
        # symbolic link (needs the symbolic link privilege: without it, NAO_TESTADO). The full flow repeats it in the e2e.
        Initialize-AtmTestReparse
        $v3 = [AgentTempManager.AtmNative]::GetLongPath((New-Item -ItemType Directory -Path (Join-Path $sandbox 'v3a-r13')).FullName)
        $sent = Join-Path $v3 'sentinel'
        [void][IO.Directory]::CreateDirectory((Join-Path $sent 'deep'))
        [IO.File]::WriteAllText((Join-Path $sent 'keep.txt'), 'keep'); [IO.File]::WriteAllText((Join-Path $sent 'deep\deep.txt'), 'deep')
        $snap = { @(Get-ChildItem -LiteralPath $sent -Recurse -Force | ForEach-Object { $_.FullName.Substring($sent.Length) + '|' + $(if ($_.PSIsContainer) { 'd' } else { [IO.File]::ReadAllText($_.FullName) }) } | Sort-Object) -join ';' }
        $before = & $snap
        $t = Join-Path $v3 'tree'
        foreach ($d in @($t, (Join-Path $t 'empty'), (Join-Path $t 'sub'))) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $t 'top.txt'), 't'); [IO.File]::WriteAllText((Join-Path $t 'sub\file.txt'), 'f')
        $st = @{ Set = $null }
        $hook = [Action[string]]({ param($root) $st.Set = [AtmTestReparse]::SetSymlink((Join-Path $root 'empty'), $sent) }.GetNewClosure())
        $r = [AgentTempManager.AtmDeleter]::DeleteTree($t, $hook)
        $lnk = Join-Path $t 'empty'
        if ($st.Set -cne 'SET_OK') {
            Assert-True $r.Completed "sem link gravado ($($st.Set)) a exclusao segue normal ($($r.AbortReason))"
            $script:caseSkipped = $true; $script:caseNote = "link simbolico nao gravado nesta conta ($($st.Set -replace ' .*$', '')): sem privilegio"
            return
        }
        Assert-True (-not $r.Completed -and [string]$r.AbortReason -like 'PINNED_DIR_CHANGED*' -and [string]$r.FailedAt -ieq $lnk) "exclusao recusada na reverificacao ($($r.AbortReason -replace ':.*$', ''))"
        Assert-Eq (& $snap) $before 'alvo sentinela intacto (nada apagado nem atravessado)'
        if ((Test-Path -LiteralPath $lnk) -and (([IO.File]::GetAttributes($lnk) -band [IO.FileAttributes]::ReparsePoint) -ne 0)) { [IO.Directory]::Delete($lnk, $false) }
        $script:caseNote = "janela: $($r.AbortReason -replace ':.*$', ''), $($r.FilesDeleted) arquivo(s) antes"
    }
    Test-Case 'Privacidade' 'Scanner detecta dados pessoais plantados e aceita apenas os valores ficticios do projeto' {
        $scan = Join-Path (Split-Path -Parent $testsDir) 'tools\Test-AtmPrivacy.ps1'
        $d = Join-Path $sandbox 'privacy-probe'; [void][IO.Directory]::CreateDirectory($d)
        $fakeSid = 'S-1-5-21-' + '111111111-222222222-333333333-1001'
        $fakeMail = 'maria.silva' + '@' + 'exemplo-real.com.br'
        $fakePath = 'C:' + '\Users\' + 'MariaSilva\AppData'
        $fakeTok = 'sk-ant-' + 'api03-AbCdEfGhIjKlMnOp'
        $fakeHost = 'DESKTOP-' + 'Q1W2E3R'
        [IO.File]::WriteAllText((Join-Path $d 'vazamento.md'), "$fakeSid`n$fakeMail`n$fakePath`n$fakeTok`n$fakeHost`nSEGREDO-PRIVADO-XYZ`n")
        [IO.File]::WriteAllText((Join-Path $d 'ficticio.md'), "C:\Users\alice\AppData S-1-5-21-1-2-3-777 S-1-5-21-9-9-9-1000 C:\Users\EXAMPL~1\x noreply@anthropic.com")
        $f = @(& $scan -Path $d -ExtraNeedles @('SEGREDO-PRIVADO-XYZ'))
        foreach ($k in @('SID', 'EMAIL', 'USER_PATH', 'TOKEN', 'MACHINE', 'PRIVATE_IDENTIFIER')) { Assert-True (@($f | Where-Object { $_.Kind -eq $k -and $_.File -eq 'vazamento.md' }).Count -ge 1) "detecta $k" }
        Assert-Eq @($f | Where-Object { $_.File -eq 'ficticio.md' }).Count 0 'valores ficticios aceitos'
        Assert-True (@($f | Where-Object { $_.Excerpt -match 'MariaSilva|111111111|exemplo-real' }).Count -eq 0) 'achados nao reproduzem o dado'
    }
    Test-Case 'Privacidade' 'FINAL-A-S: identificador da maquina igual a uma palavra do produto nao e procurado (com aviso); nome que apenas contem a palavra e identificador explicito continuam detectados' {
        $scan = Join-Path (Split-Path -Parent $testsDir) 'tools\Test-AtmPrivacy.ps1'
        $d = Join-Path $sandbox 'privacy-words'; [void][IO.Directory]::CreateDirectory($d)
        [IO.File]::WriteAllText((Join-Path $d 'produto.md'), "The installer verifies the manifest; TrustedInstaller keeps its access.`n")
        $joined = 'installer' + '-maria-p'
        [IO.File]::WriteAllText((Join-Path $d 'nome.md'), "account $joined`n")
        $savedUser = $env:USERNAME
        try {
            # The same filter runs for every needle taken from the machine (environment, SID, ProfileList).
            $env:USERNAME = 'Installer'
            $wv = $null
            $f = @(& $scan -Path $d -WarningVariable wv -WarningAction SilentlyContinue)
            Assert-Eq @($f | Where-Object { $_.Kind -eq 'PRIVATE_IDENTIFIER' -and $_.File -eq 'produto.md' }).Count 0 'palavra do produto vinda da maquina: texto do produto aceito'
            Assert-True (@($wv | Where-Object { [string]$_ -match "from USERNAME equals the product word 'installer'" }).Count -eq 1) 'aviso visivel com a origem e a palavra (nunca silencioso)'
            $env:USERNAME = $joined
            $wv = $null
            $f = @(& $scan -Path $d -WarningVariable wv -WarningAction SilentlyContinue)
            Assert-True (@($f | Where-Object { $_.Kind -eq 'PRIVATE_IDENTIFIER' -and $_.File -eq 'nome.md' }).Count -ge 1 -and @($wv | Where-Object { [string]$_ -match 'from USERNAME equals the product word' }).Count -eq 0) 'nome que apenas contem a palavra: detectado, sem aviso dessa origem (outra origem desta maquina pode avisar)'
        } finally { $env:USERNAME = $savedUser }
        $f = @(& $scan -Path $d -ExtraNeedles @('installer') -WarningAction SilentlyContinue)
        Assert-True (@($f | Where-Object { $_.Kind -eq 'PRIVATE_IDENTIFIER' -and $_.File -eq 'produto.md' }).Count -ge 1) 'identificador explicito igual a palavra: sempre procurado'
        $src = [IO.File]::ReadAllText($scan)
        Assert-True ($src.Contains("`$machineNeedles.Add(@('ProfileList', `$leaf))") -and $src.Contains("`$productWords = @('installer')") -and -not $src.Contains("`$needles.Add(`$leaf)")) 'ProfileList passa pelo mesmo filtro; lista com uma unica palavra'
    }
    Test-Case 'Privacidade' 'FINAL-B: artefatos de CI - identificadores desta maquina trocados por marcadores antes do envio; varredura falha fechada (achado, scanner ausente); arquivo compactado varrido e nunca alterado; relatorio sem nome de conta' {
        $tool = Join-Path (Split-Path -Parent $testsDir) 'tools\Protect-AtmArtifact.ps1'
        $shell = (Get-Process -Id $PID).Path
        $run = { param([string]$ArgLine) Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$tool`" " + $ArgLine) -TimeoutSec 180 }
        $d = Join-Path $sandbox 'artifact-ok'; [void][IO.Directory]::CreateDirectory($d)
        $fakeSid = 'S-1-5-21-' + '111111111-222222222-333333333-1001'
        $rep = Join-Path $d 'report.json'
        $raw = '{ "detail": "' + ($sandbox + '\x.txt').Replace('\', '\\') + '", "who": "' + $env:USERNAME + '", "machine": "' + $env:COMPUTERNAME + '", "sid": "' + $fakeSid + '", "test": "S-1-5-21-1-2-3-777", "home": "' + $env:USERPROFILE + '" }'
        [IO.File]::WriteAllText($rep, $raw)
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $zsrc = Join-Path $sandbox 'artifact-zip-src'; [void][IO.Directory]::CreateDirectory($zsrc); [IO.File]::WriteAllText((Join-Path $zsrc 'a.txt'), 'clean')
        $zip = Join-Path $d 'pkg.zip'; [IO.Compression.ZipFile]::CreateFromDirectory($zsrc, $zip)
        $zh = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash
        $r = & $run ("-Path `"$d`"")
        Assert-Eq $r.Exit 0 "artefato limpo depois da troca: exit 0 ($($r.Text))"
        $after = [IO.File]::ReadAllText($rep)
        foreach ($x in @($env:USERNAME, $env:COMPUTERNAME, $fakeSid, $env:USERPROFILE, $env:USERPROFILE.Replace('\', '\\'))) { Assert-True ($after.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0) 'identificador desta maquina trocado no artefato' }
        # The account may also be a profile folder name of this machine: either placeholder replaces it.
        Assert-True ($after.Contains('<temp>') -and ($after.Contains('<account>') -or $after.Contains('<profile-name>')) -and $after.Contains('<sid>') -and $after.Contains('S-1-5-21-1-2-3-777') -and $after.Contains('<profile>')) "marcadores no lugar; SID ficticio do projeto mantido ($after)"
        Assert-Eq (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash $zh 'arquivo compactado nunca alterado'
        Assert-True ($r.Text -match '1 archive\(s\)') "arquivo compactado varrido ($($r.Text))"
        # A value the sanitizer does not know (an address) is still found by the scanner: exit 1, location only.
        $d2 = Join-Path $sandbox 'artifact-leak'; [void][IO.Directory]::CreateDirectory($d2)
        $mail = 'maria.silva' + '@' + 'exemplo-real.com.br'
        [IO.File]::WriteAllText((Join-Path $d2 'out.txt'), "contato $mail")
        $r = & $run ("-Path `"$d2`"")
        Assert-Eq $r.Exit 1 "achado: exit 1 ($($r.Text))"
        Assert-True ($r.Text -match 'FINDING out\.txt:1 EMAIL' -and $r.Text -notmatch 'maria|exemplo-real') 'achado por arquivo, linha e tipo, sem o valor'
        # The scan cannot be trusted: exit 2 (fail closed), never a silent pass.
        $r = & $run ("-Path `"$d`" -Scanner `"$(Join-Path $sandbox 'nao-existe.ps1')`"")
        Assert-Eq $r.Exit 2 "scanner ausente: exit 2 ($($r.Text))"
        # The suite's own details and report: placeholders, no account name.
        Assert-True ((ConvertTo-AtmArtifactSafeText -Text "$sandbox\y" -Identifiers $script:safeIds).StartsWith('<temp>')) 'detalhe dos casos: sandbox sob <temp>'
        $self = [IO.File]::ReadAllText((Join-Path $testsDir 'Run-Tests.ps1'))
        Assert-True ($self.Contains("accountKind = `$(if (`$me.IsAdmin)") -and -not $self.Contains('user = ' + '$me.Name')) 'relatorio: tipo de conta, sem nome'
    }
    Test-Case 'Privacidade' 'Identidade Git: autor, committer e trailers; noreply aceito; pessoal detectado sem expor o endereco' {
        if (-not (Get-Command git -ErrorAction SilentlyContinue)) { $script:caseSkipped = $true; $script:caseNote = 'git indisponivel'; return }
        $tool = Join-Path (Split-Path -Parent $testsDir) 'tools\Test-AtmCommitIdentity.ps1'
        $shell = (Get-Process -Id $PID).Path
        $g = Join-Path $sandbox 'identity-repo'; [void][IO.Directory]::CreateDirectory($g)
        # Fictitious addresses, assembled at run time so the privacy scanner never sees them in the source.
        $personal = 'maria.teste' + '@' + 'exemplo-pessoal.com.br'
        $other = 'joao.contrib' + '@' + 'exemplo-pessoal.com.br'
        $noreply = '1234567+alice-dev' + '@' + 'users.noreply.github.com'
        $botMail = '49699333+dependabot[bot]' + '@' + 'users.noreply.github.com'
        $webflow = 'noreply' + '@' + 'github.com'
        $ghSupport = 'support' + '@' + 'github.com'
        $assistant = 'noreply' + '@' + 'anthropic.com'
        $saved = @{}; foreach ($v in @('GIT_CONFIG_GLOBAL', 'GIT_CONFIG_NOSYSTEM', 'GIT_AUTHOR_NAME', 'GIT_AUTHOR_EMAIL', 'GIT_COMMITTER_NAME', 'GIT_COMMITTER_EMAIL')) { $saved[$v] = [Environment]::GetEnvironmentVariable($v) }
        $eap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
        try {
            # Isolated from the user's and the system's Git configuration (no hooks, signing or identity leak in).
            $env:GIT_CONFIG_GLOBAL = Join-Path $g 'empty.gitconfig'; [IO.File]::WriteAllText($env:GIT_CONFIG_GLOBAL, '')
            $env:GIT_CONFIG_NOSYSTEM = '1'
            & git -C $g init -q 2>&1 | Out-Null
            function New-IdCommit([string]$Author, [string]$Committer, [string[]]$Trailers = @()) {
                $env:GIT_AUTHOR_NAME = 'Autor'; $env:GIT_AUTHOR_EMAIL = $Author
                $env:GIT_COMMITTER_NAME = 'Committer'; $env:GIT_COMMITTER_EMAIL = $Committer
                $msg = @('-m', 'teste'); if ($Trailers.Count) { $msg += @('-m', ($Trailers -join "`n")) }
                & git -C $g commit -q --allow-empty @msg 2>&1 | Out-Null
                Assert-Eq $LASTEXITCODE 0 'commit de teste'
                return (& git -C $g rev-parse HEAD).Trim()
            }
            function Invoke-IdTool([string[]]$ToolArgs) {
                $out = @(& $shell -NoProfile -ExecutionPolicy Bypass -File $tool -RepoDir $g @ToolArgs 2>&1 | ForEach-Object { "$_" })
                return [pscustomobject]@{ Code = $LASTEXITCODE; Text = ($out -join "`n") }
            }
            $c0 = New-IdCommit $noreply $noreply @("Co-authored-by: Assistente <$assistant>")
            $c1 = New-IdCommit $botMail $webflow @("Signed-off-by: dependabot[bot] <$ghSupport>")
            $r = Invoke-IdTool @('-All')
            Assert-Eq $r.Code 0 "noreply, bot, web-flow e trailers organizacionais aceitos: $($r.Text)"

            $c2 = New-IdCommit $personal $noreply
            $c3 = New-IdCommit $noreply $personal                       # what a GitHub merge did in the incident
            $c4 = New-IdCommit $noreply $noreply @("Co-authored-by: Joao <$other>", "Signed-off-by: Maria <$personal>")
            $c5 = New-IdCommit $assistant $noreply                       # trailer-only address used as author
            $r = Invoke-IdTool @('-All')
            Assert-Eq $r.Code 1 'achados geram codigo 1'
            foreach ($exp in @("$($c2.Substring(0, 12)) author", "$($c3.Substring(0, 12)) committer", "$($c4.Substring(0, 12)) Co-authored-by", "$($c4.Substring(0, 12)) Signed-off-by", "$($c5.Substring(0, 12)) author")) {
                Assert-True ($r.Text -match [regex]::Escape($exp)) "detecta $exp"
            }
            Assert-True ($r.Text -match 'achados: 5') "cinco achados: $($r.Text)"
            foreach ($secret in @($personal, $other, 'maria.teste', 'joao.contrib', 'exemplo-pessoal')) { Assert-True (-not $r.Text.Contains($secret)) 'endereco nunca aparece completo' }
            Assert-True ($r.Text -match 'm\*\*\*@e\*\*\*') 'endereco mascarado'

            $r = Invoke-IdTool @('-Range', "$c1..$c2")
            Assert-Eq $r.Code 1 'faixa com um commit pessoal'
            Assert-True ($r.Text -match 'commits verificados: 1 ') 'a faixa limita os commits verificados'
            $r = Invoke-IdTool @('-Range', "$c0..$c1")
            Assert-Eq $r.Code 0 'faixa limpa'
            $r = Invoke-IdTool @('-Commit', $c3)
            Assert-Eq $r.Code 1 'commit unico (push) com committer pessoal'

            $al = Join-Path $sandbox 'identity-allowlist.txt'
            [IO.File]::WriteAllText($al, "# teste`nemail:$($personal.ToUpperInvariant())`nemail:$other`ncommit:$c5`n")
            $r = Invoke-IdTool @('-All', '-AllowListFile', $al)
            Assert-Eq $r.Code 0 "allow-list: e-mails publicados por decisao e commit aceito ($($r.Text))"
            Assert-True ($r.Text -match 'excecoes aceitas: 1') 'commit aceito contabilizado'
            [IO.File]::WriteAllText($al, "email:nao-e-um-endereco`n")
            $r = Invoke-IdTool @('-All', '-AllowListFile', $al)
            Assert-Eq $r.Code 2 'linha invalida na allow-list e erro (nao aceita tudo)'
            $r = Invoke-IdTool @('-All', '-Commit', $c0)
            Assert-Eq $r.Code 2 'parametros conflitantes'
            $r = Invoke-IdTool @('-Range', 'ref-inexistente..HEAD')
            Assert-Eq $r.Code 2 'faixa invalida e erro, nunca "limpo"'
        } finally {
            $ErrorActionPreference = $eap
            foreach ($v in $saved.Keys) { [Environment]::SetEnvironmentVariable($v, $saved[$v]) }
        }
    }
    Test-Case 'Privacidade' 'Repositorio (arquivos de trabalho e index Git) sem dados pessoais, da maquina ou privados' {
        $repo = Split-Path -Parent $testsDir
        $scan = Join-Path $repo 'tools\Test-AtmPrivacy.ps1'
        $copy = Join-Path $sandbox 'publishable'
        foreach ($rel in @('src', 'install', 'docs', 'tests', 'tools', '.github')) { if (Test-Path (Join-Path $repo $rel)) { Copy-AtmTree -From (Join-Path $repo $rel) -To (Join-Path $copy $rel) } }
        # '.git' is a file (pointer to the main repository) in a linked worktree; it is never published.
        foreach ($f in @(Get-ChildItem -LiteralPath $repo -File -Force | Where-Object { $_.Name -ne '.git' })) { Copy-Item -LiteralPath $f.FullName -Destination $copy }
        $pw = $null
        $hits = @(& $scan -Path $copy -NeedlesFile $env:ATM_PRIVATE_NEEDLES -WarningVariable pw -WarningAction SilentlyContinue)
        # A weaker scan stays visible in the result (source and product word only, never a name of this machine).
        if (@($pw).Count -gt 0) { $script:caseNote = 'avisos do scanner: ' + ((@($pw) | ForEach-Object { [string]$_ } | Sort-Object -Unique) -join ' | ') }
        Assert-Eq $hits.Count 0 (($hits | ForEach-Object { "$($_.File):$($_.Line) $($_.Kind)" }) -join '; ')
        if ((Get-Command git -ErrorAction SilentlyContinue) -and (Test-Path (Join-Path $repo '.git'))) {
            $idx = Join-Path $sandbox 'git-index'
            $ErrorActionPreference = 'Continue'
            foreach ($p in @(& git -C $repo ls-files 2>$null)) {
                $dst = Join-Path $idx ($p.Replace('/', '\'))
                [void][IO.Directory]::CreateDirectory((Split-Path -Parent $dst))
                $blob = (& git -C $repo show ":$p" 2>$null) -join "`n"
                [IO.File]::WriteAllText($dst, [string]$blob)
            }
            if (Test-Path $idx) {
                $h2 = @(& $scan -Path $idx -NeedlesFile $env:ATM_PRIVATE_NEEDLES)
                Assert-Eq $h2.Count 0 ('index Git: ' + (($h2 | ForEach-Object { "$($_.File):$($_.Line) $($_.Kind)" }) -join '; '))
            }
            $ignored = @(& git -C $repo status --short --ignored 2>$null | Where-Object { $_ -like '!!*' } | ForEach-Object { $_.Substring(3) })
            foreach ($i in $ignored) { Assert-True ($i -in @('dist/')) "arquivo ignorado inesperado: $i" }
        }
    }
    # --- V5 tools (V5-TOOLS) ---
    # The read-only evidence tools of the V5 pilot (tools\v5-pilot; ADR-0015, sections 6 to 8, decision V5-D7 (a)), on
    # synthetic folders of the sandbox only. Nothing here deletes anything: a "removal" is two snapshots compared in the
    # reverse order of their creation, or (V5-TOOLS-ISO, the isolation sequence) a folder moved inside the sandbox, out
    # of the snapshot's roots. The T1 logs are made by the engine's own Write-AtmCleanLogRecord (src\lib\Engine.Clean.ps1)
    # with the fields of the records of Invoke-AtmCleanCore; the isolate, restore and purge logs and the manifests by its
    # Write-AtmIsolationRecord (src\lib\Engine.Isolate.ps1) with the fields of the records of Invoke-AtmIsolateCore,
    # Invoke-AtmRestoreCore and Invoke-AtmPurgeCore. Only the writer is a stand-in. No isolation gate is touched.
    $v5Dir = Join-Path (Split-Path -Parent $testsDir) 'tools\v5-pilot'
    $v5Snap = Join-Path $v5Dir 'Get-AtmPilotSnapshot.ps1'
    $v5Cmp = Join-Path $v5Dir 'Compare-AtmPilotSnapshot.ps1'
    $v5Sum = Join-Path $v5Dir 'Get-AtmPilotSummary.ps1'
    function Invoke-V5Tool {
        # One tool in this process: its exit code and its console text (every stream).
        param([string]$Tool, [hashtable]$Arguments)
        $global:LASTEXITCODE = 0
        $txt = (@(& $Tool @Arguments *>&1) | ForEach-Object { [string]$_ }) -join "`n"
        return [pscustomobject]@{ Code = $LASTEXITCODE; Text = $txt }
    }
    function Read-V5Snapshot {
        # The entries of one snapshot file, by relative path (one root).
        param([string]$Path)
        $m = @{}
        foreach ($l in [IO.File]::ReadAllLines($Path)) {
            $f = $l.Split("`t")
            if ($f[0] -ceq 'E') { $m[$f[7]] = [pscustomobject]@{ Label = $f[1]; Type = $f[2]; Size = $f[3]; Write = $f[4]; Sha = $f[5]; Code = $f[6] } }
        }
        return $m
    }
    function Get-V5Times {
        # Last write and creation times of every item under a folder; reparse points listed, never followed.
        param([string]$Dir)
        $out = New-Object System.Collections.Generic.List[string]
        $stack = New-Object System.Collections.Generic.Stack[object]
        $stack.Push((New-Object IO.DirectoryInfo($Dir)))
        while ($stack.Count -gt 0) {
            foreach ($e in $stack.Pop().GetFileSystemInfos()) {
                # The item's own times (not the copy in the folder listing, which NTFS updates lazily).
                $e.Refresh()
                $out.Add($e.FullName + '|' + $e.LastWriteTimeUtc.Ticks + '|' + $e.CreationTimeUtc.Ticks)
                if (($e.Attributes -band [IO.FileAttributes]::Directory) -and -not ($e.Attributes -band [IO.FileAttributes]::ReparsePoint)) { $stack.Push($e) }
            }
        }
        return (($out | Sort-Object) -join "`n")
    }
    function New-V5Snap {
        param([string[]]$Roots, [string]$Out)
        $r = Invoke-V5Tool $v5Snap @{ Root = $Roots; Out = $Out }
        Assert-Eq $r.Code 0 "snapshot escrito ($($r.Text))"
        return $Out
    }
    function Get-V5Count {
        # One count of the compare output (console text or file).
        param([string]$Text, [string]$Key)
        $m = [regex]::Match($Text, '(?m)^' + [regex]::Escape($Key) + "`t([^\r\n]*)")
        if (-not $m.Success) { throw "ASSERT: chave $Key ausente na saida do compare" }
        return $m.Groups[1].Value
    }
    function New-V5T1Log {
        # A T1 log as the engine writes it: each line by Write-AtmCleanLogRecord, with a stand-in writer (AppendLine).
        param([string]$Path, [string]$RunId, [object[]]$Records)
        $w = [pscustomobject]@{ Lines = (New-Object System.Collections.Generic.List[string]) }
        $w | Add-Member -MemberType ScriptMethod -Name AppendLine -Value { param($l) $this.Lines.Add($l); return $null }
        $st = @{ RunId = $RunId; RecSeq = 0 }
        foreach ($rec in $Records) { $lc = Write-AtmCleanLogRecord -Log $w -State $st -Type $rec[0] -Fields $rec[1]; if ($null -ne $lc) { throw "registro de teste recusado: $lc" } }
        [IO.File]::WriteAllText($Path, (($w.Lines -join "`n") + "`n"), (New-Object System.Text.UTF8Encoding($false)))
    }
    function Get-V5Records {
        # The records of Invoke-AtmCleanCore (src\lib\Engine.Clean.ps1: run-start, plan, declaration, confirmation,
        # plan-check, then intent and result, or skip, then run-end) for one root under the B1 exception. Kind COMPLETE:
        # the deleting run. Kind FA: a revalidation refused by new processes not inspected (F-A), before any deletion.
        # -StoppedBy replaces the run-end code (a planted value).
        param([string]$RunId, [string]$Kind, $StoppedBy = '__default__')
        $op = $RunId + ':1'
        $path = 'C:\Users\alice\AppData\Local\Temp\claude\C--Users-alice-proj\' + [guid]::NewGuid().ToString()
        $planId = ('ab' * 32)
        $ia = [ordered]@{ caller = 'CLI'; consoleRequiredByCaller = $true; callerFieldsVerified = $false; interactiveConsoleObserved = $true; observedBy = 'ENGINE_CONSOLE_CHECK'; identifiesRespondent = $false }
        $recs = @(
            , @('run-start', [ordered]@{ tool = $script:AtmVersion; user = 'PILOTVM\alice'; sid = 'S-1-5-21-1-2-3-4444'; elevated = $false; planned = 1; planId = $planId; b1Exception = $true; uninspectableProcesses = 3 })
            , @('plan', [ordered]@{ opId = $op; path = $path; fingerprint = 'f1f2'; files = 2; dirs = 1; bytes = 4096; newestWriteUtc = '2026-11-10T08:00:00.0000000Z'; category = 'ELIGIBLE_WITH_DECLARED_RISK'; uninspectableProcesses = 3; uninspectableKeys = @('4@638000000000000000', '812@638000000000000001', '990@638000000000000002') })
            , @('declaration', [ordered]@{ opId = $op; path = $path; fingerprint = 'f1f2'; declaredBy = 'OPERATOR'; taskCompleted = $true; contentDecision = 'NOTHING_NEEDED'; preservation = [ordered]@{ basis = 'NOTHING_NEEDED_DISCARD_ACCEPTED'; verifiedByTool = $false }; b1ResidualRiskAccepted = $true; uninspectableProcesses = 3 })
            , @('confirmation', [ordered]@{ accepted = $true; planId = $planId; roots = 1; interaction = $ia; limitations = @($script:AtmCleanDeclarationLimitations) })
            , @('plan-check', [ordered]@{ planId = $planId; matched = $true; changed = @() })
        )
        if ($Kind -ceq 'COMPLETE') {
            $recs += , @('intent', [ordered]@{ opId = $op; path = $path; fingerprint = 'f1f2'; files = 2; dirs = 1; bytes = 4096 })
            $recs += , @('result', [ordered]@{ opId = $op; path = $path; outcome = 'COMPLETE'; attempted = $true; completed = $true; filesDeleted = 2; dirsDeleted = 2; filesPlanned = 2; dirsPlanned = 2; abortReason = $null; failedAt = $null; verifiedGone = $true; exceptionType = $null })
            $sb = $(if ($StoppedBy -ceq '__default__') { $null } else { $StoppedBy })
            $recs += , @('run-end', [ordered]@{ results = 1; complete = 1; skipped = 0; stoppedBy = $sb; stoppedAtOpId = $null; notAttempted = @() })
        } else {
            $recs += , @('skip', [ordered]@{ opId = $op; path = $path; reasons = @('B1_EXCEPTION_NEW_UNINSPECTABLE_PROCESS (2)') })
            $recs += , @('run-end', [ordered]@{ results = 0; complete = 0; skipped = 1; stoppedBy = 'REVALIDATION_REFUSED'; stoppedAtOpId = $op; notAttempted = @() })
        }
        return , $recs
    }
    function New-V5IsoLog {
        # An isolate, restore or purge log (or an entry's manifest) as the engine writes it: each line by
        # Write-AtmIsolationRecord (src\lib\Engine.Isolate.ps1), with a stand-in writer (AppendLine). -Seq: the records
        # already in the file; -Append adds to it (a manifest that grows).
        param([string]$Path, [string]$Id, [string]$Schema, [object[]]$Records, [int]$Seq = 0, [switch]$Append)
        $w = [pscustomobject]@{ Lines = (New-Object System.Collections.Generic.List[string]) }
        $w | Add-Member -MemberType ScriptMethod -Name AppendLine -Value { param($l) $this.Lines.Add($l); return $null }
        $st = @{ Id = $Id; Seq = $Seq }
        foreach ($rec in $Records) { $lc = Write-AtmIsolationRecord -Log $w -State $st -Schema $Schema -Type $rec[0] -Fields $rec[1]; if ($null -ne $lc) { throw "registro de teste recusado: $lc" } }
        $text = ($w.Lines -join "`n") + "`n"
        $enc = New-Object System.Text.UTF8Encoding($false)
        if ($Append) { [IO.File]::AppendAllText($Path, $text, $enc) } else { [IO.File]::WriteAllText($Path, $text, $enc) }
    }
    function Get-V5IsoRecords {
        # The records of Invoke-AtmIsolateCore, Invoke-AtmRestoreCore and Invoke-AtmPurgeCore (src\lib\Engine.Isolate.ps1)
        # for one root (isolate, under the B1 exception) or one entry (restore, purge) that ends COMPLETE. -Set replaces
        # one field of every record of a type ('<type>.<field>' = value: a planted value).
        param([string]$Kind, [string]$RunId, [string]$EntryId, [string]$PlanId, [string]$Path, [hashtable]$Set = @{})
        $op = $RunId + ':1'
        $ia = [ordered]@{ caller = 'CLI'; consoleRequiredByCaller = $true; callerFieldsVerified = $false; interactiveConsoleObserved = $true; observedBy = 'ENGINE_CONSOLE_CHECK'; identifiesRespondent = $false }
        $user = 'PILOTVM\alice'; $sid = 'S-1-5-21-1-2-3-4444'; $nw = '2026-11-10T08:00:00.0000000Z'; $dg = ('d1' * 32)
        $recs = $null
        switch -CaseSensitive ($Kind) {
            'isolate' {
                $recs = @(
                    , @('run-start', [ordered]@{ tool = $script:AtmVersion; user = $user; sid = $sid; elevated = $false; planned = 1; planId = $PlanId; b1Exception = $true; uninspectableProcesses = 2 })
                    , @('plan', [ordered]@{ opId = $op; path = $Path; fingerprint = 'f1f2'; files = 2; dirs = 1; bytes = 18; newestWriteUtc = $nw; category = 'ELIGIBLE_WITH_DECLARED_RISK'; uninspectableKeys = @('4@638000000000000000', '812@638000000000000001') })
                    , @('confirmation', [ordered]@{ accepted = $true; planId = $PlanId; roots = 1; b1ResidualRiskAccepted = $true; interaction = $ia })
                    , @('plan-check', [ordered]@{ planId = $PlanId; matched = $true; reasons = @() })
                    , @('move-intent', [ordered]@{ opId = $op; path = $Path; entryId = $EntryId; fingerprint = 'f1f2'; files = 2; dirs = 1; bytes = 18; newestWriteUtc = $nw })
                    , @('move-result', [ordered]@{ opId = $op; outcome = 'COMPLETE'; moved = $true; verified = $true; filesAfter = 2; dirsAfter = 1; bytesAfter = 18; digestPlanned = $dg; digestAfter = $dg; renameStatus = '0x00000000'; abortReason = $null; exceptionType = $null; path = $Path; entryId = $EntryId })
                    , @('run-end', [ordered]@{ results = 1; complete = 1; stoppedBy = $null; entryId = $EntryId })
                )
            }
            'restore' {
                $recs = @(
                    , @('run-start', [ordered]@{ tool = $script:AtmVersion; operation = 'restore'; user = $user; sid = $sid; elevated = $false; entryId = $EntryId; planId = $PlanId; destination = $Path; alternative = $false; reconcile = $false })
                    , @('confirmation', [ordered]@{ accepted = $true; planId = $PlanId; step = $null; interaction = $ia })
                    , @('plan-check', [ordered]@{ planId = $PlanId; matched = $true; reasons = @() })
                    , @('restore-intent', [ordered]@{ opId = $op; entryId = $EntryId; destination = $Path; files = 2; dirs = 1; bytes = 18 })
                    , @('restore-result', [ordered]@{ opId = $op; outcome = 'COMPLETE'; moved = $true; verified = $true; destination = $Path; filesAfter = 2; dirsAfter = 1; bytesAfter = 18; digestPlanned = $dg; digestAfter = $dg; renameStatus = '0x00000000'; abortReason = $null; exceptionType = $null; entryId = $EntryId })
                    , @('run-end', [ordered]@{ results = 1; complete = 1; stoppedBy = $null; entryId = $EntryId })
                )
            }
            'purge' {
                $recs = @(
                    , @('run-start', [ordered]@{ tool = $script:AtmVersion; operation = 'purge'; user = $user; sid = $sid; elevated = $false; entryId = $EntryId; planId = $PlanId; files = 2; dirs = 1; bytes = 18; uninspectableProcesses = 0 })
                    , @('declaration', [ordered]@{ entryId = $EntryId; declaredBy = 'OPERATOR'; taskCompleted = $true; contentDecision = 'RESULTS_PRESERVED'; preservation = [ordered]@{ basis = (Get-AtmPreservationBasis 'RESULTS_PRESERVED'); verifiedByTool = $false } })
                    , @('confirmation', [ordered]@{ accepted = $true; planId = $PlanId; entryId = $EntryId; interaction = $ia; limitations = @($script:AtmCleanDeclarationLimitations) })
                    , @('plan-check', [ordered]@{ planId = $PlanId; matched = $true; reasons = @() })
                    , @('purge-intent', [ordered]@{ opId = $op; entryId = $EntryId; files = 2; dirs = 1; bytes = 18; automatic = $false })
                    , @('purge-result', [ordered]@{ opId = $op; outcome = 'COMPLETE'; filesDeleted = 2; dirsDeleted = 2; automatic = $false; attempted = $true; completed = $true; filesPlanned = 2; dirsPlanned = 2; abortReason = $null; verifiedGone = $true; exceptionType = $null; entryId = $EntryId })
                    , @('run-end', [ordered]@{ results = 1; complete = 1; stoppedBy = $null; entryId = $EntryId })
                )
            }
            default { throw "tipo de log de teste desconhecido: $Kind" }
        }
        foreach ($k in $Set.Keys) {
            $t, $f = $k.Split('.', 2)
            foreach ($r in $recs) { if ($r[0] -ceq $t) { $r[1][$f] = $Set[$k] } }
        }
        return , $recs
    }
    $v5CmpKeys = @('onlyExpectedChange', 'roots', 'expectedRemovedGiven', 'expectedRemovedFound', 'expectedNewPatterns', 'expectedTouchedPatterns', 'removed.expected', 'removed.unexpected', 'new.expected',
        'new.unexpected', 'changed.expected', 'changed.unexpected', 'touched.expected', 'unchanged.expected', 'unchanged.unexpected', 'rootsChanged.expected', 'rootsChanged.unexpected')
    Test-Case 'V5 tools' 'Snapshot: arquivos, pastas aninhadas, arquivo vazio, nome com acento e com espaco; SHA-256 igual ao Get-FileHash; datas de escrita e de criacao inalteradas; juncao registrada e nunca seguida (o alvo fora da raiz nao aparece); arquivo em uso exclusivo registrado com codigo, sem conteudo; entradas e console sem caminho absoluto' {
        $base = Join-Path $sandbox 'v5-snap'
        $root = Join-Path $base 'root'
        $outside = Join-Path $base 'outside'
        foreach ($d in @((Join-Path $root 'a\b\c'), $outside)) { [void][IO.Directory]::CreateDirectory($d) }
        $accent = 'relat' + [char]0x00F3 + 'rio a' + [char]0x00E7 + [char]0x00E3 + 'o.txt'
        [IO.File]::WriteAllText((Join-Path $root 'top.txt'), 'top')
        [IO.File]::WriteAllText((Join-Path $root 'a\b\c\deep.bin'), ('x' * 70000))
        [IO.File]::WriteAllBytes((Join-Path $root 'a\vazio.txt'), [byte[]]@())
        [IO.File]::WriteAllText((Join-Path $root "a\$accent"), 'acento')
        [IO.File]::WriteAllText((Join-Path $root 'a\com espaco.txt'), 'espaco')
        [IO.File]::WriteAllText((Join-Path $outside 'alvo-fora-da-raiz.txt'), 'fora')
        New-Junction -Link (Join-Path $root 'a\juncao') -Target $outside
        $locked = Join-Path $root 'a\exclusivo.txt'
        [IO.File]::WriteAllText($locked, 'em uso')
        $before = Get-V5Times $root
        $out = Join-Path $base 'snap.txt'
        $fs = [IO.File]::Open($locked, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::None)
        try { $r = Invoke-V5Tool $v5Snap @{ Root = @($root); Out = $out } } finally { $fs.Dispose() }
        Assert-Eq $r.Code 0 "snapshot escrito ($($r.Text))"
        Assert-Eq (Get-V5Times $root) $before 'datas de escrita e de criacao inalteradas'
        $rows = Read-V5Snapshot $out
        foreach ($rel in @('top.txt', 'a\b\c\deep.bin', 'a\vazio.txt', "a\$accent", 'a\com espaco.txt')) {
            $e = $rows[$rel]
            Assert-True ($null -ne $e -and $e.Label -ceq 'R1' -and $e.Type -ceq 'FILE' -and $e.Code -ceq '-') "arquivo listado: $rel"
            Assert-Eq $e.Sha (Get-FileHash -LiteralPath (Join-Path $root $rel) -Algorithm SHA256).Hash "SHA-256 igual ao Get-FileHash: $rel"
            Assert-Eq $e.Size ([string](New-Object IO.FileInfo((Join-Path $root $rel))).Length) "tamanho: $rel"
        }
        Assert-Eq $rows['a\vazio.txt'].Size '0' 'arquivo vazio, tamanho 0'
        foreach ($rel in @('a', 'a\b', 'a\b\c')) { Assert-True ($null -ne $rows[$rel] -and $rows[$rel].Type -ceq 'DIR' -and $rows[$rel].Sha -ceq '-') "pasta aninhada: $rel" }
        Assert-True ($rows['a\juncao'].Type -ceq 'REPARSE_DIR' -and $rows['a\juncao'].Sha -ceq '-') 'juncao registrada como ponto de reparse'
        $txt = [IO.File]::ReadAllText($out, [Text.Encoding]::UTF8)
        Assert-True (@($rows.Keys | Where-Object { $_ -like 'a\juncao\*' }).Count -eq 0 -and -not $txt.Contains('alvo-fora-da-raiz')) 'juncao nunca seguida: o alvo fora da raiz nao aparece'
        Assert-True ($rows['a\exclusivo.txt'].Code -ceq 'SHARING_VIOLATION' -and $rows['a\exclusivo.txt'].Sha -ceq '-') "arquivo em uso exclusivo: codigo e nenhum conteudo ($($rows['a\exclusivo.txt'].Code))"
        Assert-Eq $rows.Count 10 'todas as entradas, nenhuma a mais'
        $lines = @($txt -split "`r?`n")
        Assert-True ($lines[0] -ceq "atm-pilot-snapshot`t1" -and @($lines | Where-Object { $_ -like "root`tR1`tPRESENT`t*" }).Count -eq 1 -and $lines -ccontains "end`t10") 'cabecalho, raiz R1 e fim com a contagem'
        Assert-True (@($lines | Where-Object { $_ -like "E`t*" -and $_ -match ':\\' }).Count -eq 0) 'entradas so com rotulo e caminho relativo'
        Assert-True ($r.Text -notmatch ':\\') "console sem caminho ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Snapshot: link simbolico de arquivo registrado como ponto de reparse e nunca lido (sem privilegio para criar o link: NAO_TESTADO)' {
        $base = Join-Path $sandbox 'v5-snap-link'
        $root = Join-Path $base 'root'
        $outside = Join-Path $base 'outside'
        foreach ($d in @($root, $outside)) { [void][IO.Directory]::CreateDirectory($d) }
        $target = Join-Path $outside 'alvo.txt'
        [IO.File]::WriteAllText($target, 'conteudo do alvo fora da raiz')
        try { $null = New-Item -ItemType SymbolicLink -Path (Join-Path $root 'link.txt') -Target $target -ErrorAction Stop }
        catch { $script:caseSkipped = $true; $script:caseNote = 'link simbolico de arquivo nao criado nesta conta (sem privilegio): NAO_TESTADO'; return }
        $out = New-V5Snap @($root) (Join-Path $base 'snap.txt')
        $rows = Read-V5Snapshot $out
        Assert-True ($rows['link.txt'].Type -ceq 'REPARSE_FILE' -and $rows['link.txt'].Sha -ceq '-' -and $rows['link.txt'].Size -ceq '-') 'link de arquivo: reparse, sem tamanho e sem SHA'
        Assert-True (-not ([IO.File]::ReadAllText($out)).Contains((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash)) 'o alvo nunca e lido'
    }
    Test-Case 'V5 tools' 'Snapshot: recusas sem escrever nada - -Out dentro de uma raiz (tambem com outra caixa e barra final), -Out que ja existe (conteudo intacto), ponto de reparse no caminho do -Out, raizes sobrepostas' {
        $base = Join-Path $sandbox 'v5-snap-ref'
        $root = Join-Path $base 'root'
        [void][IO.Directory]::CreateDirectory((Join-Path $root 'sub'))
        $in = Join-Path $root 'sub\snap.txt'
        $r = Invoke-V5Tool $v5Snap @{ Root = @($root); Out = $in }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'OUT_INSIDE_ROOT' -and -not [IO.File]::Exists($in)) "-Out dentro da raiz recusado ($($r.Text))"
        $r = Invoke-V5Tool $v5Snap @{ Root = @($root.ToUpperInvariant() + '\'); Out = $in }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'OUT_INSIDE_ROOT' -and -not [IO.File]::Exists($in)) "outra caixa e barra final: recusado ($($r.Text))"
        $exist = Join-Path $base 'ja-existe.txt'
        [IO.File]::WriteAllText($exist, 'original')
        $r = Invoke-V5Tool $v5Snap @{ Root = @($root); Out = $exist }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'OUT_EXISTS' -and [IO.File]::ReadAllText($exist) -ceq 'original') "-Out existente recusado, intacto ($($r.Text))"
        New-Junction -Link (Join-Path $base 'atalho') -Target (Join-Path $root 'sub')
        $r = Invoke-V5Tool $v5Snap @{ Root = @($root); Out = (Join-Path $base 'atalho\snap2.txt') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'OUT_PATH_REPARSE' -and -not [IO.File]::Exists((Join-Path $root 'sub\snap2.txt'))) "reparse no caminho do -Out recusado ($($r.Text))"
        $r = Invoke-V5Tool $v5Snap @{ Root = @($root, (Join-Path $root 'sub')); Out = (Join-Path $base 'snap3.txt') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'ROOTS_OVERLAP' -and -not [IO.File]::Exists((Join-Path $base 'snap3.txt'))) "raizes sobrepostas recusadas ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Compare: sem mudanca; so o removido esperado (a pasta pai pode mudar so a data); removido sem -ExpectedRemoved e remocao esperada que nao aconteceu; novos esperados por nome exato e por prefixo de pasta; um novo inesperado; um alterado; saida sem caminho; -Out existente recusado' {
        $base = Join-Path $sandbox 'v5-cmp'
        $r1 = Join-Path $base 'base'; $r2 = Join-Path $base 'evid'; $s = Join-Path $base 'snaps'
        foreach ($d in @((Join-Path $r1 'claude\C--Users-alice-proj'), $r2, $s)) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $r1 'claude\C--Users-alice-proj\outro.txt'), 'fica')
        [IO.File]::WriteAllText((Join-Path $r2 'antigo.log'), 'log antigo')
        $a = New-V5Snap @($r1, $r2) (Join-Path $s 'a.txt')
        $a2 = New-V5Snap @($r1, $r2) (Join-Path $s 'a2.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $a; After = $a2 }
        Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'onlyExpectedChange') -ceq 'true' -and (Get-V5Count $r.Text 'unchanged.expected') -ceq '4' -and (Get-V5Count $r.Text 'roots') -ceq 'R1,R2') "sem mudanca: so o esperado ($($r.Text))"
        $sess = 'claude\C--Users-alice-proj\0f0e0d0c-1111-2222-3333-444455556666'
        [void][IO.Directory]::CreateDirectory((Join-Path $r1 "$sess\tmp"))
        [IO.File]::WriteAllText((Join-Path $r1 "$sess\saida.txt"), 'sintetico')
        [IO.File]::WriteAllText((Join-Path $r1 "$sess\tmp\x.txt"), 'sintetico')
        $b = New-V5Snap @($r1, $r2) (Join-Path $s 'b.txt')
        # The root "removed": b (with it) before a2 (taken before it existed).
        $r = Invoke-V5Tool $v5Cmp @{ Before = $b; After = $a2; ExpectedRemoved = "R1:$sess" }
        Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'removed.expected') -ceq '4' -and (Get-V5Count $r.Text 'removed.unexpected') -ceq '0' -and (Get-V5Count $r.Text 'changed.unexpected') -ceq '0' -and (Get-V5Count $r.Text 'expectedRemovedFound') -ceq 'true') "so o removido esperado ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $b; After = $a2 }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'onlyExpectedChange') -ceq 'false' -and (Get-V5Count $r.Text 'removed.unexpected') -ceq '4') "removido sem -ExpectedRemoved: inesperado ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $a2; After = $b; ExpectedRemoved = "R1:$sess" }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'expectedRemovedFound') -ceq 'false') "remocao esperada que nao aconteceu ($($r.Text))"
        [IO.File]::WriteAllText((Join-Path $r2 'run6.log'), '{}')
        [void][IO.Directory]::CreateDirectory((Join-Path $r2 'transcripts'))
        [IO.File]::WriteAllText((Join-Path $r2 'transcripts\run6.txt'), 'transcricao')
        $c = New-V5Snap @($r1, $r2) (Join-Path $s 'c.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $b; After = $c; ExpectedNew = @('R2:run6.log', 'R2:transcripts\') }
        Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'new.expected') -ceq '3' -and (Get-V5Count $r.Text 'new.unexpected') -ceq '0' -and (Get-V5Count $r.Text 'expectedNewPatterns') -ceq '2') "novos esperados: nome exato e prefixo de pasta ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $b; After = $c; ExpectedNew = @('R2:\') }
        Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'new.expected') -ceq '3' -and (Get-V5Count $r.Text 'unchanged.expected') -ceq '8') "novo esperado em qualquer lugar de uma raiz ('R2:\') ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $b; After = $c; ExpectedNew = @('R2:run6.log') }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'new.unexpected') -ceq '2') "novo inesperado ($($r.Text))"
        [IO.File]::WriteAllText((Join-Path $r1 'claude\C--Users-alice-proj\outro.txt'), 'mudou')
        $d2 = New-V5Snap @($r1, $r2) (Join-Path $s 'd.txt')
        $cmpOut = Join-Path $s 'cmp-cd.txt'
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $d2; Out = $cmpOut }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'changed.unexpected') -ceq '1') "alterado: inesperado ($($r.Text))"
        $ct = [IO.File]::ReadAllText($cmpOut)
        $kl = @($ct -split "`r?`n" | Where-Object { $_ -ne '' } | ForEach-Object { $_.Split("`t")[0] })
        Assert-Eq ($kl -join ',') ((@('atm-pilot-compare') + $v5CmpKeys + @('end')) -join ',') 'saida: chaves conhecidas, na ordem'
        Assert-True ($ct -notmatch ':\\' -and $ct -notmatch 'alice|claude|outro|run6|transcri' -and $r.Text -notmatch ':\\|alice|outro') 'saida (arquivo e console) sem caminho absoluto nem relativo'
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $d2; Out = $cmpOut }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'OUT_EXISTS' -and [IO.File]::ReadAllText($cmpOut) -ceq $ct) "-Out existente recusado ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Compare: raiz que falta num dos snapshots (inesperada, salvo se for exatamente o -ExpectedRemoved); snapshots incompativeis (raizes, ordem dos rotulos), formato desconhecido, truncado e rotulo desconhecido recusados' {
        $base = Join-Path $sandbox 'v5-cmp-roots'
        $r1 = Join-Path $base 'base'; $r3 = Join-Path $base 'mais-tarde'; $s = Join-Path $base 'snaps'
        foreach ($d in @($r1, $s)) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $r1 'f.txt'), 'f')
        $r = Invoke-V5Tool $v5Snap @{ Root = @($r1, $r3); Out = (Join-Path $s 'e.txt') }
        Assert-True ($r.Code -eq 0 -and $r.Text -match 'R2=MISSING') "raiz inexistente registrada como MISSING ($($r.Text))"
        $e = Join-Path $s 'e.txt'
        [void][IO.Directory]::CreateDirectory($r3)
        [IO.File]::WriteAllText((Join-Path $r3 'g.txt'), 'g')
        $f = New-V5Snap @($r1, $r3) (Join-Path $s 'f.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $e; After = $f }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'rootsChanged.unexpected') -ceq '1') "raiz que aparece: inesperada ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $e }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'rootsChanged.unexpected') -ceq '1') "raiz que falta, sem -ExpectedRemoved: inesperada ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $e; ExpectedRemoved = 'R2:' }
        Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'rootsChanged.expected') -ceq '1' -and (Get-V5Count $r.Text 'removed.expected') -ceq '1') "raiz que falta, exatamente o -ExpectedRemoved: esperada ($($r.Text))"
        $g = New-V5Snap @($r1) (Join-Path $s 'g.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $g }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'SNAPSHOTS_INCOMPATIBLE') "raizes diferentes recusadas ($($r.Text))"
        $h = New-V5Snap @($r3, $r1) (Join-Path $s 'h.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $h }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'SNAPSHOTS_INCOMPATIBLE') "rotulos em outra ordem recusados ($($r.Text))"
        $u = Join-Path $s 'desconhecido.txt'; [IO.File]::WriteAllText($u, "outro-formato`t1`r`n")
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $u }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'FORMAT_UNKNOWN') "formato desconhecido recusado ($($r.Text))"
        $all = [IO.File]::ReadAllLines($f)
        $t = Join-Path $s 'truncado.txt'; [IO.File]::WriteAllText($t, (($all[0..($all.Count - 2)]) -join "`r`n") + "`r`n")
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $t }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'SNAPSHOT_TRUNCATED') "snapshot truncado recusado ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $f; After = $f; ExpectedRemoved = 'R9:x' }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'EXPECTED_LABEL_UNKNOWN') "rotulo desconhecido recusado ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Resumo: log T1 de COMPLETE (formato real do motor) mais o compare - tipos de registro na ordem, desfecho, consoleBy, contagens, booleanos da secao 6 (os que o log nao responde ficam null); nenhum caminho, SID, conta ou id; achado de outro arquivo da pasta nao conta' {
        $d = Join-Path $sandbox 'v5-sum-complete'; [void][IO.Directory]::CreateDirectory($d)
        $run = [guid]::NewGuid().ToString()
        $log = Join-Path $d 'run6.t1.jsonl'
        New-V5T1Log -Path $log -RunId $run -Records (Get-V5Records -RunId $run -Kind 'COMPLETE')
        # Another file of the folder with a SID: the scanner finds it, the summary ignores findings outside its own file.
        [IO.File]::WriteAllText((Join-Path $d 'outro.txt'), ('S-1-5-21-' + '111111111-222222222-333333333-1001'))
        $cmpFile = Join-Path $d 'cmp.txt'
        $cv = @{ onlyExpectedChange = 'true'; roots = 'R1,R2,R3,R4'; expectedRemovedGiven = 'true'; expectedRemovedFound = 'true'; expectedNewPatterns = '1'; 'removed.expected' = '4' }
        [IO.File]::WriteAllText($cmpFile, ("atm-pilot-compare`t2`r`n" +(($v5CmpKeys | ForEach-Object { "$_`t" + $(if ($cv.ContainsKey($_)) { $cv[$_] } else { '0' }) }) -join "`r`n") + "`r`nend`tcompare`r`n"))
        $out = Join-Path $d 'summary.json'
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Compare = $cmpFile; PinnedSha = ('0123456789abcdef' * 3).Substring(0, 40); Out = $out }
        Assert-True ($r.Code -eq 0 -and [IO.File]::Exists($out)) "resumo escrito ($($r.Text))"
        Assert-Eq @(Get-ChildItem -LiteralPath $d -Filter '*.REFUSED').Count 0 'nenhum arquivo REFUSED'
        $txt = [IO.File]::ReadAllText($out)
        $j = $txt | ConvertFrom-Json
        Assert-Eq (@($j.log.recordTypes) -join ',') 'run-start,plan,declaration,confirmation,plan-check,intent,result,run-end' 'tipos de registro, na ordem'
        Assert-True ($j.log.present -eq $true -and $j.log.deletingRunOrder -eq $true -and $j.log.recSeqContiguous -eq $true -and $j.log.singleRun -eq $true -and $null -eq $j.log.fileAbsent) 'log: presente, ordem, sequencia e uma execucao'
        Assert-True ($j.run.consoleBy -ceq 'ENGINE_CONSOLE_CHECK' -and $j.run.caller -ceq 'CLI' -and $j.run.confirmationAccepted -eq $true -and $j.run.elevated -eq $false -and $j.run.b1Exception -eq $true) 'consoleBy, caller, confirmacao, nao elevado, excecao B1'
        Assert-True ((@($j.run.outcomes) -join ',') -ceq 'COMPLETE' -and (@($j.run.verifiedGone) -join ',') -ceq 'GONE' -and $null -eq $j.run.stoppedBy -and (@($j.run.b1ResidualRiskAccepted) -join ',') -eq 'True' -and (@($j.run.contentDecisions) -join ',') -ceq 'NOTHING_NEEDED') 'desfecho COMPLETE, verificado, sem codigo de termino; risco B1 aceito'
        Assert-True ($j.counts.uninspectableProcesses -eq 3 -and $j.counts.filesDeleted -eq 2 -and $j.counts.dirsDeleted -eq 2 -and $j.counts.bytesDeleted -eq 4096 -and $null -eq $j.counts.newUninspectableIdentities -and $j.counts.complete -eq 1 -and $j.counts.planCheckChanged -eq 0) 'contagens'
        Assert-True ($j.compare.given -eq $true -and $j.compare.onlyExpectedChange -eq $true -and $j.compare.'removed.expected' -eq 4 -and $j.checks.changedOutsideRoot -eq $false -and $j.checks.consoleByEngineCheck -eq $true) 'compare e booleanos respondidos'
        Assert-True ($null -eq $j.checks.checkoutDiffersByGateLineOnly -and $null -eq $j.checks.guestClockWithinSecondsOfHost -and $null -eq $j.checks.networkDisconnectedAtDeletingRun) 'o que o log nao responde fica null, nunca inventado'
        Assert-True ($j.pinnedSha -ceq ('0123456789abcdef' * 3).Substring(0, 40) -and $j.schema -ceq 'atm-pilot-summary-2' -and $j.log.kind -ceq 'clean' -and $j.log.fullRunOrder -eq $true) 'SHA fixado, esquema e tipo do log'
        Assert-True ($null -eq $j.counts.filesMoved -and $null -eq $j.counts.filesPurged -and $null -eq $j.run.declaredBy -and $null -eq $j.run.automatic -and $null -eq $j.run.moved -and $j.compare.expectedTouchedPatterns -eq 0 -and $j.compare.'touched.expected' -eq 0) 'campos do isolamento e do expurgo null no clean; contagens novas do compare'
        foreach ($x in @('alice', 'PILOTVM', 'S-1-', '\', 'C--Users', $run, ('ab' * 32), 'f1f2', '638000000000000000', '@')) { Assert-True ($txt.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0) "resumo sem '$x'" }
    }
    Test-Case 'V5 tools' 'Resumo: log T1 de recusa por F-A (REVALIDATION_REFUSED com B1_EXCEPTION_NEW_UNINSPECTABLE_PROCESS) e execucoes sem log (CLEAN_LOCK_BUSY e exit 6: -NoLog, o codigo e o exit mostrados no console); log ausente sem -NoLog recusado' {
        $d = Join-Path $sandbox 'v5-sum-fa'; [void][IO.Directory]::CreateDirectory($d)
        $run = [guid]::NewGuid().ToString()
        $log = Join-Path $d 'run6b.t1.jsonl'
        New-V5T1Log -Path $log -RunId $run -Records (Get-V5Records -RunId $run -Kind 'FA')
        $out = Join-Path $d 'summary-fa.json'
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = $out; ExitCode = '3' }
        Assert-True ($r.Code -eq 0 -and [IO.File]::Exists($out)) "resumo da recusa por F-A ($($r.Text))"
        $j = [IO.File]::ReadAllText($out) | ConvertFrom-Json
        Assert-Eq (@($j.log.recordTypes) -join ',') 'run-start,plan,declaration,confirmation,plan-check,skip,run-end' 'tipos de registro'
        Assert-True ($j.run.stoppedBy -ceq 'REVALIDATION_REFUSED' -and (@($j.run.skipReasonCodes) -join ',') -ceq 'B1_EXCEPTION_NEW_UNINSPECTABLE_PROCESS' -and $j.counts.newUninspectableIdentities -eq 2 -and $j.log.deletingRunOrder -eq $false -and @($j.run.outcomes).Count -eq 0 -and $null -eq $j.counts.filesDeleted -and $j.run.exitCode -eq 3 -and $null -eq $j.compare.onlyExpectedChange -and $null -eq $j.checks.changedOutsideRoot) 'codigo de termino, motivo, identidades novas, nada apagado, sem compare'
        # CLEAN_LOCK_BUSY: the engine refuses the lock before any log is opened (src\lib\Engine.Clean.ps1, Invoke-AtmClean),
        # so the run is summarized from what the console showed, and the log path given to clean is checked absent.
        $busy = Join-Path $d 'summary-busy.json'
        $r = Invoke-V5Tool $v5Sum @{ NoLog = $true; LogFile = (Join-Path $d 'run5-console2.t1.jsonl'); ShownCode = 'CLEAN_LOCK_BUSY'; ExitCode = '3'; Out = $busy }
        Assert-True ($r.Code -eq 0) "resumo sem log ($($r.Text))"
        $j = [IO.File]::ReadAllText($busy) | ConvertFrom-Json
        Assert-True ($j.log.present -eq $false -and $j.log.fileAbsent -eq $true -and @($j.log.recordTypes).Count -eq 0 -and $j.run.shownCode -ceq 'CLEAN_LOCK_BUSY' -and $j.run.exitCode -eq 3 -and $null -eq $j.run.consoleBy -and $null -eq $j.log.deletingRunOrder) 'CLEAN_LOCK_BUSY: sem log, codigo e exit do console'
        $r = Invoke-V5Tool $v5Sum @{ NoLog = $true; ExitCode = '6'; Out = (Join-Path $d 'summary-exit6.json') }
        Assert-True ($r.Code -eq 0 -and ([IO.File]::ReadAllText((Join-Path $d 'summary-exit6.json')) | ConvertFrom-Json).run.exitCode -eq 6) "exit 6 sem log ($($r.Text))"
        $r = Invoke-V5Tool $v5Sum @{ LogFile = (Join-Path $d 'nao-existe.jsonl'); Out = (Join-Path $d 'summary-x.json') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'LOG_MISSING' -and -not [IO.File]::Exists((Join-Path $d 'summary-x.json'))) "log ausente sem -NoLog: recusado ($($r.Text))"
        $r = Invoke-V5Tool $v5Sum @{ NoLog = $true; Out = (Join-Path $d 'summary-y.json') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'NOLOG_NEEDS_CODE') "-NoLog sem codigo: recusado ($($r.Text))"
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = $out }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'OUT_EXISTS') "-Out existente recusado ($($r.Text))"
        Assert-Eq @(Get-ChildItem -LiteralPath $d -Filter '*.REFUSED').Count 0 'nenhum arquivo REFUSED'
    }
    Test-Case 'V5 tools' 'Resumo: plantados e recusados, cada um sozinho - um caminho, um SID, o USERNAME do runner, um e-mail, um codigo fora da lista e uma lista de codigos validos num campo de um valor so; nenhuma saida final, so o temporario REFUSED com o nome do campo e a regra, sem o valor (nem no console)' {
        $plants = @(
            , @('caminho', 'C:\Users\alice\AppData\Local\Temp\x', 'PATH_SEPARATOR')
            , @('sid', 'S-1-5-21-1-2-3-777', 'SID_PREFIX')
            , @('usuario', $env:USERNAME, 'ENVIRONMENT_NAME')
            , @('email', ('piloto' + '@' + 'exemplo.test'), 'AT_SIGN')
            , @('codigo', 'NOT_A_KNOWN_CODE', 'NOT_OF_TYPE_stopCode')
            , @('lista', @('STOPPED_AFTER_REFUSED', 'STOPPED_AFTER_PARTIAL'), 'NOT_OF_TYPE_stopCode')
        )
        foreach ($p in $plants) {
            Assert-True (([string]$p[1]).Length -gt 0) "valor plantado de $($p[0])"
            $d = Join-Path $sandbox ('v5-sum-plant-' + $p[0]); [void][IO.Directory]::CreateDirectory($d)
            $run = [guid]::NewGuid().ToString()
            $log = Join-Path $d 't1.jsonl'
            New-V5T1Log -Path $log -RunId $run -Records (Get-V5Records -RunId $run -Kind 'COMPLETE' -StoppedBy $p[1])
            $out = Join-Path $d 'summary.json'
            $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = $out }
            Assert-True ($r.Code -eq 3 -and -not [IO.File]::Exists($out)) "$($p[0]): recusado, nenhuma saida final ($($r.Text))"
            $ref = @(Get-ChildItem -LiteralPath $d -Filter 'summary.json.*.REFUSED')
            Assert-Eq $ref.Count 1 "$($p[0]): o temporario fica com REFUSED no nome"
            $rt = [IO.File]::ReadAllText($ref[0].FullName)
            Assert-True ($rt.Contains("field`trun.stoppedBy`t$($p[2])") -and @($rt -split "`r?`n" | Where-Object { $_ -like "field`t*" }).Count -eq 1) "$($p[0]): o campo e a regra ($($p[2]))"
            Assert-True ($rt.IndexOf([string]$p[1], [StringComparison]::OrdinalIgnoreCase) -lt 0 -and $r.Text.IndexOf([string]$p[1], [StringComparison]::OrdinalIgnoreCase) -lt 0) "$($p[0]): o valor nao aparece no arquivo nem no console"
        }
        # A code typed by the operator is checked the same way.
        $d = Join-Path $sandbox 'v5-sum-plant-shown'; [void][IO.Directory]::CreateDirectory($d)
        $r = Invoke-V5Tool $v5Sum @{ NoLog = $true; ShownCode = 'clean lock busy'; Out = (Join-Path $d 'summary.json') }
        Assert-True ($r.Code -eq 3 -and @(Get-ChildItem -LiteralPath $d -Filter '*.REFUSED').Count -eq 1 -and -not [IO.File]::Exists((Join-Path $d 'summary.json'))) "codigo digitado fora da lista: recusado ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Resumo: achado do scanner de privacidade no proprio resumo (agulha privada) - fica REFUSED, sem saida final, exit 4; scanner ausente recusado antes de escrever' {
        $d = Join-Path $sandbox 'v5-sum-scan'; [void][IO.Directory]::CreateDirectory($d)
        $run = [guid]::NewGuid().ToString()
        $log = Join-Path $d 't1.jsonl'
        New-V5T1Log -Path $log -RunId $run -Records (Get-V5Records -RunId $run -Kind 'COMPLETE')
        $needles = Join-Path $sandbox 'v5-needles.txt'
        [IO.File]::WriteAllText($needles, "# agulha de teste`nNOTHING_NEEDED`n")
        $out = Join-Path $d 'summary.json'
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = $out; NeedlesFile = $needles }
        Assert-True ($r.Code -eq 4 -and -not [IO.File]::Exists($out) -and $r.Text -match 'PRIVATE_IDENTIFIER') "achado no resumo: exit 4 ($($r.Text))"
        $ref = @(Get-ChildItem -LiteralPath $d -Filter 'summary.json.*.REFUSED')
        Assert-True ($ref.Count -eq 1 -and ([IO.File]::ReadAllText($ref[0].FullName)).Contains('atm-pilot-summary-2')) 'o resumo fica com o nome REFUSED (nunca apagado)'
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = (Join-Path $d 'summary2.json'); NeedlesFile = (Join-Path $sandbox 'v5-nao-existe.txt') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'NEEDLES_MISSING') "arquivo de agulhas ausente: recusado ($($r.Text))"
        $alone = Join-Path $sandbox 'v5-sem-scanner\v5-pilot'; [void][IO.Directory]::CreateDirectory($alone)
        [IO.File]::Copy($v5Sum, (Join-Path $alone 'Get-AtmPilotSummary.ps1'))
        $r = Invoke-V5Tool (Join-Path $alone 'Get-AtmPilotSummary.ps1') @{ LogFile = $log; Out = (Join-Path $d 'summary3.json') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'SCANNER_MISSING' -and @(Get-ChildItem -LiteralPath $d -Filter 'summary3.json*').Count -eq 0) "scanner ausente: recusado antes de escrever ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Resumo (V5-TOOLS-ISO): logs do isolar, do restaurar e do expurgar escritos pelo Write-AtmIsolationRecord do motor - log.kind, tipos na ordem, desfechos, contagens movidas, restauradas e expurgadas, declaredBy, verifiedByTool e automatic; o que nao se aplica ao tipo fica null; nenhum id de entrada, plan id, digest, caminho, SID ou conta; execucoes de trava fechada sem log' {
        $d = Join-Path $sandbox 'v5-sum-iso'; [void][IO.Directory]::CreateDirectory($d)
        $eid = '20261117T101500Z-5e6f7a8b'; $plan = ('c4' * 32)
        $path = 'C:\Users\alice\AppData\Local\Temp\claude\C--Users-alice-proj\' + [guid]::NewGuid().ToString()
        $kinds = @(
            , @('isolate', $script:AtmIsolateLogSchema, 'run-start,plan,confirmation,plan-check,move-intent,move-result,run-end')
            , @('restore', $script:AtmIsolateLogSchema, 'run-start,confirmation,plan-check,restore-intent,restore-result,run-end')
            , @('purge', $script:AtmPurgeLogSchema, 'run-start,declaration,confirmation,plan-check,purge-intent,purge-result,run-end')
        )
        $docs = @{}
        foreach ($k in $kinds) {
            $run = [guid]::NewGuid().ToString()
            $log = Join-Path $d "$($k[0]).jsonl"
            New-V5IsoLog -Path $log -Id $run -Schema $k[1] -Records (Get-V5IsoRecords -Kind $k[0] -RunId $run -EntryId $eid -PlanId $plan -Path $path)
            $od = Join-Path $d "out-$($k[0])"; [void][IO.Directory]::CreateDirectory($od)
            $out = Join-Path $od 'summary.json'
            $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = $out; ExitCode = '0' }
            Assert-True ($r.Code -eq 0 -and [IO.File]::Exists($out)) "$($k[0]): resumo escrito ($($r.Text))"
            $txt = [IO.File]::ReadAllText($out)
            $j = $txt | ConvertFrom-Json
            Assert-True ($j.schema -ceq 'atm-pilot-summary-2' -and $j.log.kind -ceq $k[0]) "$($k[0]): esquema e log.kind"
            Assert-Eq (@($j.log.recordTypes) -join ',') $k[2] "$($k[0]): tipos de registro, na ordem"
            Assert-True ($j.log.fullRunOrder -eq $true -and $null -eq $j.log.deletingRunOrder -and $j.log.recSeqContiguous -eq $true -and $j.log.singleRun -eq $true) "$($k[0]): execucao completa, sequencia contigua, uma execucao"
            Assert-True ((@($j.run.outcomes) -join ',') -ceq 'COMPLETE' -and $null -eq $j.run.stoppedBy -and $j.run.confirmationAccepted -eq $true -and $j.run.planCheckMatched -eq $true -and @($j.run.planCheckReasonCodes).Count -eq 0 -and $j.counts.results -eq 1 -and $j.counts.complete -eq 1 -and $j.run.consoleBy -ceq 'ENGINE_CONSOLE_CHECK') "$($k[0]): desfecho, confirmacao e verificacao do plano"
            Assert-True ($null -eq $j.counts.filesDeleted -and $null -eq $j.counts.bytesDeleted -and $null -eq $j.counts.planCheckChanged) "$($k[0]): contagens do clean ficam null"
            foreach ($x in @('alice', 'PILOTVM', 'S-1-', '\', 'C--Users', $run, $plan, $plan.Substring(0, 8), $eid, $eid.Substring($eid.Length - 8), '20261117', 'd1d1d1d1', 'f1f2', '638000000000000000', '0x00000000', '@')) { Assert-True ($txt.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0) "$($k[0]): resumo sem '$x'" }
            $docs[$k[0]] = $j
        }
        $i = $docs['isolate']
        Assert-True ((@($i.run.moved) -join ',') -eq 'True' -and (@($i.run.verified) -join ',') -eq 'True' -and $i.counts.filesMoved -eq 2 -and $i.counts.dirsMoved -eq 1 -and $i.counts.bytesMoved -eq 18 -and $null -eq $i.counts.filesRestored -and $null -eq $i.counts.filesPurged) 'isolar: movido, verificado e contagens movidas'
        Assert-True ($i.run.b1Exception -eq $true -and (@($i.run.b1ResidualRiskAccepted) -join ',') -eq 'True' -and (@($i.run.planCategories) -join ',') -ceq 'ELIGIBLE_WITH_DECLARED_RISK' -and $i.counts.uninspectableProcesses -eq 2 -and @($i.run.planCheckChangedFields).Count -eq 0 -and $null -ne $i.run.planCheckChangedFields) 'isolar: excecao B1 aceita na confirmacao; nenhum campo mudou na verificacao do plano'
        Assert-True ($null -eq $i.run.verifiedGone -and $null -eq $i.run.declaredBy -and $null -eq $i.run.verifiedByTool -and $null -eq $i.run.automatic -and $null -eq $i.run.alternative) 'isolar: campos do expurgo e do restaurar null'
        $s = $docs['restore']
        Assert-True ((@($s.run.moved) -join ',') -eq 'True' -and $s.counts.filesRestored -eq 2 -and $s.counts.dirsRestored -eq 1 -and $s.counts.bytesRestored -eq 18 -and $null -eq $s.counts.filesMoved -and $s.run.alternative -eq $false -and $s.run.reconcile -eq $false) 'restaurar: contagens restauradas, sem alternativa e sem reconciliacao'
        Assert-True ($null -eq $s.run.planCheckChangedFields -and @($s.run.b1ResidualRiskAccepted).Count -eq 0 -and $null -eq $s.run.verifiedGone -and $null -eq $s.run.automatic -and $null -eq $s.run.refusalStep) 'restaurar: o que nao se aplica fica null'
        $p = $docs['purge']
        Assert-True ($p.run.declaredBy -ceq 'OPERATOR' -and $p.run.verifiedByTool -eq $false -and $p.run.automatic -eq $false -and (@($p.run.contentDecisions) -join ',') -ceq 'RESULTS_PRESERVED' -and (@($p.run.verifiedGone) -join ',') -ceq 'GONE') 'expurgar: declaredBy OPERATOR, verifiedByTool e automatic falsos, decisao de conteudo, verificado'
        Assert-True ($p.counts.filesPurged -eq 2 -and $p.counts.dirsPurged -eq 2 -and $p.counts.bytesPurged -eq 18 -and $p.counts.uninspectableProcesses -eq 0 -and $null -eq $p.run.moved -and $null -eq $p.counts.filesMoved) 'expurgar: contagens expurgadas'
        # The gate closed: isolate and purge stop after the plan, before any log (the code and the exit code the console showed).
        foreach ($code in @('ISOLAMENTO_REAL_DESABILITADO', 'EXPURGO_REAL_DESABILITADO', 'RESTAURACAO_REAL_DESABILITADA')) {
            $od = Join-Path $d "out-$code"; [void][IO.Directory]::CreateDirectory($od)
            $r = Invoke-V5Tool $v5Sum @{ NoLog = $true; LogFile = (Join-Path $d "$code.jsonl"); ShownCode = $code; ExitCode = '3'; Out = (Join-Path $od 'summary.json') }
            Assert-True ($r.Code -eq 0) "${code}: resumo sem log ($($r.Text))"
            $j = [IO.File]::ReadAllText((Join-Path $od 'summary.json')) | ConvertFrom-Json
            Assert-True ($j.log.present -eq $false -and $null -eq $j.log.kind -and $j.log.fileAbsent -eq $true -and $j.run.shownCode -ceq $code -and $j.run.exitCode -eq 3) "${code}: sem log, sem tipo, codigo e exit do console"
        }
        # A log of the automatic purge (another schema) and a log of two schemas are refused before anything is written.
        $auto = Join-Path $d 'autopurge.jsonl'
        New-V5IsoLog -Path $auto -Id ([guid]::NewGuid().ToString()) -Schema $script:AtmAutoPurgeLogSchema -Records @(, @('run-start', [ordered]@{ operation = 'autopurge' }))
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $auto; Out = (Join-Path $d 'summary-auto.json') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'LOG_SCHEMA_UNKNOWN' -and @(Get-ChildItem -LiteralPath $d -Filter 'summary-auto*').Count -eq 0) "expurgo automatico: esquema recusado ($($r.Text))"
        $mixed = Join-Path $d 'mixed.jsonl'
        [IO.File]::WriteAllText($mixed, ([IO.File]::ReadAllText((Join-Path $d 'isolate.jsonl')) + [IO.File]::ReadAllText((Join-Path $d 'purge.jsonl'))))
        $r = Invoke-V5Tool $v5Sum @{ LogFile = $mixed; Out = (Join-Path $d 'summary-mixed.json') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'LOG_SCHEMA_MIXED' -and @(Get-ChildItem -LiteralPath $d -Filter 'summary-mixed*').Count -eq 0) "dois esquemas num log: recusado ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Resumo (V5-TOOLS-ISO): plantados e recusados, cada um sozinho - um id de entrada (deste log ou outro), um plan id, os 8 caracteres de um plan id ou de uma entrada dentro de um codigo de familia, um codigo de outro tipo de log, um codigo fora da lista, um motivo fora da lista e automatic verdadeiro; nenhuma saida final, so o REFUSED com o campo e a regra, sem o valor' {
        $eid = '20261117T101500Z-5e6f7a8b'; $plan = ('c4' * 32)
        $path = 'C:\Users\alice\AppData\Local\Temp\claude\C--Users-alice-proj\' + [guid]::NewGuid().ToString()
        $plants = @(
            , @('entrada', 'isolate', @{ 'run-end.stoppedBy' = $eid }, 'run.stoppedBy', 'ENTRY_ID')
            , @('entrada-outra', 'purge', @{ 'run-end.stoppedBy' = ('20251231T235959Z-' + '0badc0de') }, 'run.stoppedBy', 'ENTRY_ID')
            , @('plano', 'restore', @{ 'run-end.stoppedBy' = $plan }, 'run.stoppedBy', 'PLAN_ID')
            , @('plano8', 'isolate', @{ 'run-end.stoppedBy' = ('CLEAN_LOCK_ERROR_' + $plan.Substring(0, 8).ToUpperInvariant()) }, 'run.stoppedBy', 'PLAN_ID')
            , @('entrada8', 'purge', @{ 'run-end.stoppedBy' = ('CLEAN_LOCK_ERROR_' + $eid.Substring($eid.Length - 8).ToUpperInvariant()) }, 'run.stoppedBy', 'ENTRY_ID')
            , @('outro-tipo', 'isolate', @{ 'run-end.stoppedBy' = 'EXPURGO_REAL_DESABILITADO' }, 'run.stoppedBy', 'NOT_OF_TYPE_stopCode')
            , @('fora-da-lista', 'purge', @{ 'run-end.stoppedBy' = 'PURGE_DONE_ANYWAY' }, 'run.stoppedBy', 'NOT_OF_TYPE_stopCode')
            , @('motivo', 'restore', @{ 'plan-check.reasons' = @('NOT_A_REASON (1)') }, 'run.planCheckReasonCodes[0]', 'NOT_OF_TYPE_reasonCode')
            , @('automatico', 'purge', @{ 'purge-result.automatic' = $true }, 'run.automatic', 'NOT_OF_TYPE_falseOnly')
        )
        foreach ($p in $plants) {
            $d = Join-Path $sandbox ('v5-iso-plant-' + $p[0]); [void][IO.Directory]::CreateDirectory($d)
            $run = [guid]::NewGuid().ToString()
            $log = Join-Path $d 'log.jsonl'
            $schema = $(if ($p[1] -ceq 'purge') { $script:AtmPurgeLogSchema } else { $script:AtmIsolateLogSchema })
            New-V5IsoLog -Path $log -Id $run -Schema $schema -Records (Get-V5IsoRecords -Kind $p[1] -RunId $run -EntryId $eid -PlanId $plan -Path $path -Set $p[2])
            $out = Join-Path $d 'summary.json'
            $r = Invoke-V5Tool $v5Sum @{ LogFile = $log; Out = $out }
            Assert-True ($r.Code -eq 3 -and -not [IO.File]::Exists($out)) "$($p[0]): recusado, nenhuma saida final ($($r.Text))"
            $ref = @(Get-ChildItem -LiteralPath $d -Filter 'summary.json.*.REFUSED')
            Assert-Eq $ref.Count 1 "$($p[0]): o temporario fica com REFUSED no nome"
            $rt = [IO.File]::ReadAllText($ref[0].FullName)
            Assert-True ($rt.Contains("field`t$($p[3])`t$($p[4])") -and @($rt -split "`r?`n" | Where-Object { $_ -like "field`t*" }).Count -eq 1) "$($p[0]): o campo e a regra ($($p[3]) $($p[4])): $rt"
            $v = @($p[2].Values)[0]
            if ($v -is [string]) { Assert-True ($rt.IndexOf($v, [StringComparison]::OrdinalIgnoreCase) -lt 0 -and $r.Text.IndexOf($v, [StringComparison]::OrdinalIgnoreCase) -lt 0) "$($p[0]): o valor nao aparece no arquivo nem no console" }
            foreach ($x in @($eid, $eid.Substring($eid.Length - 8), $plan.Substring(0, 8))) { Assert-True ($rt.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0 -and $r.Text.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0) "$($p[0]): nenhum id no REFUSED nem no console" }
        }
    }
    Test-Case 'V5 tools' 'Compare (formato 2): raiz que nasce coberta por R5:\ esperada; sem cobertura, ou coberta so por uma pasta dela, inesperada; raiz que some continua inesperada com R5:\; -ExpectedTouched aceita so a data da pasta nomeada (exata, sem caixa); outra mudanca dela, um filho e um arquivo nomeado continuam inesperados; -ExpectedTouched sem pasta recusado' {
        $base = Join-Path $sandbox 'v5-cmp-iso'
        $r1 = Join-Path $base 'base'; $q = Join-Path $base 'AgentTempManager\Q'; $s = Join-Path $base 'snaps'
        $slug = Join-Path $r1 'claude\C--Users-alice-proj'
        foreach ($d in @((Join-Path $slug 'irma'), (Join-Path $base 'instalado'), (Join-Path $base 'checkout'), (Join-Path $base 'evid'), $s)) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $slug 'irma\f.txt'), 'f')
        $roots = @($r1, (Join-Path $base 'instalado'), (Join-Path $base 'checkout'), (Join-Path $base 'evid'), $q)
        $a = New-V5Snap $roots (Join-Path $s 'a.txt')
        $entry = '20261117T101500Z-5e6f7a8b'
        [void][IO.Directory]::CreateDirectory((Join-Path $q $entry))
        [IO.File]::WriteAllText((Join-Path $q "$entry\manifest.jsonl"), '{}')
        $b = New-V5Snap $roots (Join-Path $s 'b.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $a; After = $b; ExpectedNew = @('R5:\') }
        Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'rootsChanged.expected') -ceq '1' -and (Get-V5Count $r.Text 'new.expected') -ceq '2' -and (Get-V5Count $r.Text 'onlyExpectedChange') -ceq 'true') "raiz que nasce coberta por R5:\ - esperada ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $a; After = $b }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'rootsChanged.unexpected') -ceq '1' -and (Get-V5Count $r.Text 'new.unexpected') -ceq '2') "raiz que nasce sem cobertura: inesperada ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $a; After = $b; ExpectedNew = @("R5:$entry\") }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'rootsChanged.unexpected') -ceq '1' -and (Get-V5Count $r.Text 'new.expected') -ceq '2') "raiz que nasce coberta so por uma pasta dela: o nascimento e inesperado ($($r.Text))"
        $r = Invoke-V5Tool $v5Cmp @{ Before = $b; After = $a; ExpectedNew = @('R5:\') }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'rootsChanged.unexpected') -ceq '1') "raiz que some, com R5:\ - inesperada ($($r.Text))"
        # -ExpectedTouched: the parent of a root that left and came back changes only its last write time.
        $c = New-V5Snap $roots (Join-Path $s 'c.txt')
        [IO.Directory]::SetLastWriteTimeUtc($slug, [IO.Directory]::GetLastWriteTimeUtc($slug).AddMinutes(-7))
        $dd = New-V5Snap $roots (Join-Path $s 'd.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $dd }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'changed.unexpected') -ceq '1') "pasta com a data mudada, sem -ExpectedTouched: inesperada ($($r.Text))"
        foreach ($t in @('R1:claude\C--Users-alice-proj', 'R1:CLAUDE/c--users-alice-proj\')) {
            $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $dd; ExpectedTouched = @($t) }
            Assert-True ($r.Code -eq 0 -and (Get-V5Count $r.Text 'changed.expected') -ceq '1' -and (Get-V5Count $r.Text 'touched.expected') -ceq '1' -and (Get-V5Count $r.Text 'expectedTouchedPatterns') -ceq '1') "-ExpectedTouched '$t': so a data, esperada ($($r.Text))"
        }
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $dd; ExpectedTouched = @('R1:claude') }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'touched.expected') -ceq '0') "-ExpectedTouched no avo: exato, nao cobre a pasta de baixo ($($r.Text))"
        # Another change of the named folder (its code, in a synthetic copy of the snapshot): unexpected.
        $lines = [IO.File]::ReadAllLines($dd)
        for ($n = 0; $n -lt $lines.Length; $n++) { $f = $lines[$n].Split("`t"); if ($f[0] -ceq 'E' -and $f[1] -ceq 'R1' -and $f[7] -ceq 'claude\C--Users-alice-proj') { $f[6] = 'ACCESS_DENIED'; $lines[$n] = $f -join "`t" } }
        $e2 = Join-Path $s 'e.txt'; [IO.File]::WriteAllText($e2, (($lines -join "`r`n") + "`r`n"))
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $e2; ExpectedTouched = @('R1:claude\C--Users-alice-proj') }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'changed.unexpected') -ceq '1' -and (Get-V5Count $r.Text 'touched.expected') -ceq '0') "pasta nomeada com outra mudanca: inesperada ($($r.Text))"
        # A child of the named folder whose date changed, and a file named by -ExpectedTouched: unexpected.
        [IO.Directory]::SetLastWriteTimeUtc((Join-Path $slug 'irma'), [IO.Directory]::GetLastWriteTimeUtc((Join-Path $slug 'irma')).AddMinutes(-7))
        [IO.File]::WriteAllText((Join-Path $slug 'irma\f.txt'), 'mudou')
        $g = New-V5Snap $roots (Join-Path $s 'g.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $g; ExpectedTouched = @('R1:claude\C--Users-alice-proj', 'R1:claude\C--Users-alice-proj\irma\f.txt') }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'touched.expected') -ceq '1' -and (Get-V5Count $r.Text 'changed.unexpected') -ceq '2') "filho com a data mudada e arquivo nomeado: inesperados ($($r.Text))"
        foreach ($t in @('R1:', 'R1:\')) {
            $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $dd; ExpectedTouched = @($t) }
            Assert-True ($r.Code -eq 2 -and $r.Text -match 'EXPECTED_FORMAT') "-ExpectedTouched '$t' sem pasta: recusado ($($r.Text))"
        }
        $r = Invoke-V5Tool $v5Cmp @{ Before = $c; After = $dd; ExpectedTouched = @('R9:x') }
        Assert-True ($r.Code -eq 2 -and $r.Text -match 'EXPECTED_LABEL_UNKNOWN') "-ExpectedTouched de rotulo desconhecido: recusado ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Sequencia sintetica do roteiro do isolamento (I-4, I-6, I-7 e E-3): isolar, restaurar, isolar de novo e expurgar, por movimentos na sandbox (o expurgo leva o payload para fora das raizes); cada compare com os parametros do roteiro da onlyExpectedChange, e cada resumo, com o log do motor e esse compare, sai com o tipo certo e sem id, plan id nem caminho' {
        $base = Join-Path $sandbox 'v5-seq'
        $r1 = Join-Path $base 'AgentTempBase'; $r2 = Join-Path $base 'instalado'; $r3 = Join-Path $base 'co-iso'; $evid = Join-Path $base 'evid'; $q = Join-Path $base 'AgentTempManager\Q'
        $snaps = Join-Path $base 'snaps'; $sums = Join-Path $base 'resumos'; $away = Join-Path $base 'fora-das-raizes'
        $slugRel = 'claude\C--Users-alice-proj'; $rootRel = "$slugRel\0f0e0d0c-1111-2222-3333-444455556666"
        $raiz = Join-Path $r1 $rootRel
        foreach ($d in @((Join-Path $raiz 'tmp'), (Join-Path $r1 "$slugRel\irma"), $r2, $r3, $evid, $snaps, $sums, $away)) { [void][IO.Directory]::CreateDirectory($d) }
        [IO.File]::WriteAllText((Join-Path $raiz 'saida.txt'), 'sintetico')
        [IO.File]::WriteAllText((Join-Path $raiz 'tmp\x.txt'), 'sintetico')
        [IO.File]::WriteAllText((Join-Path $r1 "$slugRel\irma\y.txt"), 'irma')
        [IO.File]::WriteAllText((Join-Path $r2 'atm.ps1'), 'copia instalada')
        [IO.File]::WriteAllText((Join-Path $r3 'README.md'), 'checkout')
        $roots = @($r1, $r2, $r3, $evid, $q)
        $sha = ('0123456789abcdef' * 3).Substring(0, 40)
        $id1 = '20261117T101500Z-5e6f7a8b'; $id2 = '20261117T103000Z-9a0b1c2d'; $plan1 = ('c4' * 32); $plan2 = ('7e' * 32)
        $needles = @($id1, $id2, $id1.Substring($id1.Length - 8), $id2.Substring($id2.Length - 8), $plan1.Substring(0, 8), $plan2.Substring(0, 8), 'alice', 'C--Users', '\', '20261117')
        $man = {
            # The entry's manifest, by the same writer (schema atm.quarantine/1); -Seq: the records already in it.
            param([string]$Id, [object[]]$Recs, [int]$Seq)
            New-V5IsoLog -Path (Join-Path $q "$Id\manifest.jsonl") -Id $Id -Schema $script:AtmQuarantineSchema -Records $Recs -Seq $Seq -Append:($Seq -gt 0)
        }
        $step = {
            # One compare and one summary of the roteiro, with its parameters; both exit 0.
            param([string]$Name, [string]$Before, [string]$After, [hashtable]$CmpArgs, [string]$Log, [string]$Kind)
            $cmpOut = Join-Path $snaps "$Name-compare.txt"
            $ca = @{ Before = $Before; After = $After; Out = $cmpOut } + $CmpArgs
            $rc = Invoke-V5Tool $v5Cmp $ca
            Assert-True ($rc.Code -eq 0 -and (Get-V5Count $rc.Text 'onlyExpectedChange') -ceq 'true') "${Name}: compare so com o esperado, exit 0 ($($rc.Text))"
            $od = Join-Path $sums $Name; [void][IO.Directory]::CreateDirectory($od)
            $out = Join-Path $od "$Name-summary.json"
            $rs = Invoke-V5Tool $v5Sum @{ LogFile = $Log; Compare = $cmpOut; PinnedSha = $sha; ExitCode = '0'; Out = $out }
            Assert-True ($rs.Code -eq 0 -and [IO.File]::Exists($out)) "${Name}: resumo escrito, exit 0 ($($rs.Text))"
            $txt = [IO.File]::ReadAllText($out)
            foreach ($x in $needles) { Assert-True ($txt.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0) "${Name}: resumo sem '$x'" }
            $j = $txt | ConvertFrom-Json
            Assert-True ($j.log.kind -ceq $Kind -and $j.log.fullRunOrder -eq $true -and $j.compare.onlyExpectedChange -eq $true -and $j.checks.changedOutsideRoot -eq $false -and (@($j.run.outcomes) -join ',') -ceq 'COMPLETE') "${Name}: tipo $Kind, execucao completa, so a mudanca esperada"
            return $j
        }
        $s0 = New-V5Snap $roots (Join-Path $snaps 'I4-antes.txt')
        # I-4: the quarantine (born here), the entry and its manifest, then the root moved to <entry>\payload.
        $run1 = [guid]::NewGuid().ToString()
        [void][IO.Directory]::CreateDirectory((Join-Path $q $id1))
        & $man $id1 @(, @('entry', [ordered]@{ tool = $script:AtmVersion; runId = $run1; planId = $plan1; targetKind = 'SessionRoot'; originalPath = $raiz; provider = 'ClaudeCode' })) 0
        & $man $id1 @(, @('move-intent', [ordered]@{ opId = "${run1}:1"; fingerprint = 'f1f2'; files = 2; dirs = 1; bytes = 18 })) 1
        [IO.Directory]::Move($raiz, (Join-Path $q "$id1\payload"))
        & $man $id1 @(, @('move-result', [ordered]@{ opId = "${run1}:1"; outcome = 'COMPLETE'; moved = $true; verified = $true })) 2
        New-V5IsoLog -Path (Join-Path $evid 'I4-isolate.jsonl') -Id $run1 -Schema $script:AtmIsolateLogSchema -Records (Get-V5IsoRecords -Kind 'isolate' -RunId $run1 -EntryId $id1 -PlanId $plan1 -Path $raiz)
        [IO.File]::WriteAllText((Join-Path $evid 'I4-console.txt'), 'console copiado a mao')
        $s1 = New-V5Snap $roots (Join-Path $snaps 'I4-depois.txt')
        $j = & $step 'I4' $s0 $s1 @{ ExpectedRemoved = "R1:$rootRel"; ExpectedNew = @('R5:\', 'R4:\') } (Join-Path $evid 'I4-isolate.jsonl') 'isolate'
        Assert-True ($j.compare.'removed.expected' -eq 4 -and $j.compare.'rootsChanged.expected' -eq 1 -and $j.compare.expectedRemovedFound -eq $true -and $j.counts.filesMoved -eq 2) 'I-4: a raiz saiu, a quarentena nasceu'
        # I-6: the payload back to the original path; the manifest grows.
        $run2 = [guid]::NewGuid().ToString()
        & $man $id1 @(, @('restore-intent', [ordered]@{ opId = "${run2}:1"; runId = $run2; planId = $plan1; destination = $raiz; alternative = $false })) 3
        [IO.Directory]::Move((Join-Path $q "$id1\payload"), $raiz)
        & $man $id1 @(, @('restore-result', [ordered]@{ opId = "${run2}:1"; outcome = 'COMPLETE'; moved = $true; verified = $true; destination = $raiz })) 4
        New-V5IsoLog -Path (Join-Path $evid 'I6-restore.jsonl') -Id $run2 -Schema $script:AtmIsolateLogSchema -Records (Get-V5IsoRecords -Kind 'restore' -RunId $run2 -EntryId $id1 -PlanId $plan1 -Path $raiz)
        [IO.File]::WriteAllText((Join-Path $evid 'I6-console.txt'), 'console copiado a mao')
        $s2 = New-V5Snap $roots (Join-Path $snaps 'I6-depois.txt')
        $r = Invoke-V5Tool $v5Cmp @{ Before = $s0; After = $s2; ExpectedNew = @('R5:\', 'R4:\') }
        Assert-True ($r.Code -eq 1 -and (Get-V5Count $r.Text 'changed.unexpected') -ceq '1') "I-6 sem -ExpectedTouched: a data do pai e inesperada ($($r.Text))"
        $j = & $step 'I6' $s0 $s2 @{ ExpectedTouched = @("R1:$slugRel"); ExpectedNew = @('R5:\', 'R4:\') } (Join-Path $evid 'I6-restore.jsonl') 'restore'
        Assert-True ($j.compare.'touched.expected' -eq 1 -and $j.compare.'removed.unexpected' -eq 0 -and $j.compare.'rootsChanged.expected' -eq 1 -and $j.counts.filesRestored -eq 2) 'I-6: a arvore voltou identica, o pai so mudou a data'
        # I-7: a second isolation of the same root, a new entry, left in quarantine.
        $run3 = [guid]::NewGuid().ToString()
        [void][IO.Directory]::CreateDirectory((Join-Path $q $id2))
        & $man $id2 @(, @('entry', [ordered]@{ tool = $script:AtmVersion; runId = $run3; planId = $plan2; targetKind = 'SessionRoot'; originalPath = $raiz; provider = 'ClaudeCode' })) 0
        & $man $id2 @(, @('move-intent', [ordered]@{ opId = "${run3}:1"; fingerprint = 'f1f2'; files = 2; dirs = 1; bytes = 18 })) 1
        [IO.Directory]::Move($raiz, (Join-Path $q "$id2\payload"))
        & $man $id2 @(, @('move-result', [ordered]@{ opId = "${run3}:1"; outcome = 'COMPLETE'; moved = $true; verified = $true })) 2
        New-V5IsoLog -Path (Join-Path $evid 'I7-isolate.jsonl') -Id $run3 -Schema $script:AtmIsolateLogSchema -Records (Get-V5IsoRecords -Kind 'isolate' -RunId $run3 -EntryId $id2 -PlanId $plan2 -Path $raiz)
        [IO.File]::WriteAllText((Join-Path $evid 'I7-console.txt'), 'console copiado a mao')
        $s3 = New-V5Snap $roots (Join-Path $snaps 'I7-depois.txt')
        $j = & $step 'I7' $s2 $s3 @{ ExpectedRemoved = "R1:$rootRel"; ExpectedNew = @("R5:$id2\", 'R4:\') } (Join-Path $evid 'I7-isolate.jsonl') 'isolate'
        Assert-True ($j.compare.'removed.expected' -eq 4 -and $j.compare.'rootsChanged.expected' -eq 0 -and $j.compare.'unchanged.unexpected' -eq 0) 'I-7: a raiz saiu de novo, a primeira entrada ficou igual'
        # E-3: the payload leaves every root (the deleter, here a move out of the roots); the entry and its manifest stay.
        $run4 = [guid]::NewGuid().ToString()
        $s3e = New-V5Snap $roots (Join-Path $snaps 'E3-antes.txt')
        & $man $id2 @(, @('purge-intent', [ordered]@{ opId = "${run4}:1"; runId = $run4; planId = ('5a' * 32); files = 2; dirs = 1; bytes = 18; automatic = $false; declaredBy = 'OPERATOR' })) 3
        [IO.Directory]::Move((Join-Path $q "$id2\payload"), (Join-Path $away 'payload'))
        & $man $id2 @(, @('purge-result', [ordered]@{ opId = "${run4}:1"; outcome = 'COMPLETE'; filesDeleted = 2; dirsDeleted = 2; automatic = $false; verifiedGone = $true })) 4
        New-V5IsoLog -Path (Join-Path $evid 'E3-purge.jsonl') -Id $run4 -Schema $script:AtmPurgeLogSchema -Records (Get-V5IsoRecords -Kind 'purge' -RunId $run4 -EntryId $id2 -PlanId ('5a' * 32) -Path $raiz)
        [IO.File]::WriteAllText((Join-Path $evid 'E3-console.txt'), 'console copiado a mao')
        $s4 = New-V5Snap $roots (Join-Path $snaps 'E3-depois.txt')
        $j = & $step 'E3' $s3e $s4 @{ ExpectedRemoved = "R5:$id2\payload"; ExpectedNew = @("R5:$id2\manifest.jsonl", 'R4:\') } (Join-Path $evid 'E3-purge.jsonl') 'purge'
        Assert-True ($j.compare.'removed.expected' -eq 4 -and $j.compare.'changed.expected' -ge 1 -and $j.run.declaredBy -ceq 'OPERATOR' -and $j.run.verifiedByTool -eq $false -and $j.run.automatic -eq $false -and $j.counts.filesPurged -eq 2) 'E-3: o payload saiu, o manifesto cresceu, declaredBy OPERATOR'
    }
    Test-Case 'V5 tools' 'Processo novo, sem o motor carregado: snapshot, compare e resumo pela linha de comando (-File), com os codigos de saida 0, 1 e 2' {
        $shell = (Get-Process -Id $PID).Path
        $base = Join-Path $sandbox 'v5-child'; $root = Join-Path $base 'root'; [void][IO.Directory]::CreateDirectory($root)
        [IO.File]::WriteAllText((Join-Path $root 'a.txt'), 'a')
        $run = { param([string]$Tool, [string]$ArgLine) Invoke-AtmTestChild -CommandLine ("`"$shell`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$Tool`" " + $ArgLine) -TimeoutSec 180 }
        $s1 = Join-Path $base 's1.txt'; $s2 = Join-Path $base 's2.txt'
        $r = & $run $v5Snap "-Root `"$root`" -Out `"$s1`""
        Assert-Eq $r.Exit 0 "snapshot ($($r.Text))"
        [IO.File]::WriteAllText((Join-Path $root 'b.txt'), 'b')
        $r = & $run $v5Snap "-Root `"$root`" -Out `"$s2`""
        Assert-Eq $r.Exit 0 "segundo snapshot ($($r.Text))"
        $r = & $run $v5Cmp "-Before `"$s1`" -After `"$s1`""
        Assert-Eq $r.Exit 0 "compare sem mudanca ($($r.Text))"
        $r = & $run $v5Cmp "-Before `"$s1`" -After `"$s2`""
        Assert-Eq $r.Exit 1 "compare com mudanca inesperada ($($r.Text))"
        $r = & $run $v5Cmp "-Before `"$s1`" -After `"$(Join-Path $base 'nao-existe.txt')`""
        Assert-Eq $r.Exit 2 "compare recusado ($($r.Text))"
        $r = & $run $v5Sum "-NoLog -ExitCode 6 -Out `"$(Join-Path $base 'summary.json')`""
        Assert-True ($r.Exit -eq 0 -and [IO.File]::Exists((Join-Path $base 'summary.json'))) "resumo ($($r.Text))"
    }
    Test-Case 'V5 tools' 'Estatico: as tres ferramentas nao atribuem trava, nao citam seam, lock nem Invoke-AtmClean, nao chamam funcao de src\lib, nao apagam, movem nem escrevem fora do -Out (um unico arquivo novo por ferramenta, uma unica troca de nome, a do resumo), sem redirecionamento e sem rede; StrictMode, Stop e codigos de saida no cabecalho' {
        $libFns = @(Get-ChildItem -LiteralPath (Join-Path $srcDir 'lib') -Filter '*.ps1' | ForEach-Object { [regex]::Matches([IO.File]::ReadAllText($_.FullName), '(?m)^\s*function\s+([A-Za-z]+-[A-Za-z0-9]+)') | ForEach-Object { $_.Groups[1].Value } } | Sort-Object -Unique)
        Assert-True ($libFns.Count -gt 50 -and $libFns -contains 'Invoke-AtmClean' -and $libFns -contains 'Write-AtmCleanLogRecord') "funcoes do motor lidas ($($libFns.Count))"
        $forbidden = @('AtmRealDeletionEnabled', 'AtmGuiEnabled', 'AtmIsolationEnabled', 'AtmQuarantinePurgeEnabled', 'AtmDiagnoseExportEnabled', 'AtmWorktreeDiagnosticsEnabled', 'AtmHandleDiagnosticsEnabled', 'AtmRecoveryEnabled',
            'AtmCleanConsoleSource', 'DeleteTreeImpl', 'PathPresenceImpl', 'LogWriter', 'AtmRuntimeEvidenceSources', 'AtmIsolationQuarantineRoot', 'AtmCleanLockName', 'AgentTempManager.', 'AtmCleanLock',
            'Invoke-AtmClean', 'Initialize-AtmNative', 'Engine.', 'src\lib', 'Native.cs', 'Add-Type', 'Import-Module',
            'Remove-Item', 'Move-Item', 'Rename-Item', 'Copy-Item', 'Clear-Content', 'Set-Content', 'Add-Content', 'Out-File', 'New-Item', 'Set-ItemProperty', 'Set-Acl', 'Set-Date', 'Tee-Object', 'Export-',
            'File]::Delete', 'Directory]::Delete', '.Delete(', 'File]::Copy', '.CopyTo(', '.MoveTo(', 'Directory]::Move', 'File]::Replace', 'File]::WriteAll', 'File]::AppendAll', 'File]::Create(', 'File]::Open(',
            'CreateDirectory', 'SetLastWriteTime', 'SetCreationTime', 'SetLastAccessTime', 'LastWriteTime =', 'LastWriteTimeUtc =', 'SetAttributes', 'Attributes =',
            'Start-Process', 'Invoke-Expression', 'Invoke-WebRequest', 'Invoke-RestMethod', 'WebClient', 'Net.Http', 'Net.Sockets', 'Test-NetConnection', 'Start-BitsTransfer', 'Register-ScheduledTask', 'Invoke-Command')
        foreach ($tool in @($v5Snap, $v5Cmp, $v5Sum)) {
            $name = Split-Path -Leaf $tool
            $t = [IO.File]::ReadAllText($tool)
            foreach ($x in $forbidden) { Assert-True ($t.IndexOf($x, [StringComparison]::OrdinalIgnoreCase) -lt 0) "${name}: sem '$x'" }
            foreach ($fn in $libFns) { Assert-True (-not [regex]::IsMatch($t, '(?i)(?<![A-Za-z0-9-])' + [regex]::Escape($fn) + '(?![A-Za-z0-9-])')) "${name}: nao chama $fn" }
            Assert-True (-not [regex]::IsMatch($t, 'FileMode\]::(Create|OpenOrCreate|Append|Truncate)\b') -and -not $t.Contains('FileAccess]::ReadWrite')) "${name}: nenhum arquivo aberto para escrita alem do novo"
            Assert-Eq ([regex]::Matches($t, 'FileMode\]::CreateNew').Count) 1 "${name}: um unico ponto de escrita, um arquivo NOVO"
            Assert-Eq ([regex]::Matches($t, 'FileAccess\]::Write\b').Count) 1 "${name}: um unico acesso de escrita"
            Assert-Eq ([regex]::Matches($t, [regex]::Escape('[IO.File]::Move(')).Count) $(if ($name -ceq 'Get-AtmPilotSummary.ps1') { 1 } else { 0 }) "${name}: troca de nome so a do resumo (temporario REFUSED -> -Out)"
            Assert-True ($t.Contains('Set-StrictMode -Version 2.0') -and $t.Contains("`$ErrorActionPreference = 'Stop'") -and $t.Contains('.EXITCODES') -and $t.Contains('  0  ') -and $t.Contains('  2  ')) "${name}: StrictMode, Stop e codigos de saida no cabecalho"
            $tk = $null; $pe = $null
            $ast = [Management.Automation.Language.Parser]::ParseFile($tool, [ref]$tk, [ref]$pe)
            Assert-Eq @($pe).Count 0 "${name}: sem erro de sintaxe"
            Assert-Eq @($ast.FindAll({ param($n) $n -is [Management.Automation.Language.FileRedirectionAst] }, $true)).Count 0 "${name}: sem redirecionamento para arquivo"
        }
        $sumText = [IO.File]::ReadAllText($v5Sum)
        Assert-True ($sumText.Contains('[IO.File]::Move($tmp, $outFull)') -and $sumText.IndexOf('[IO.File]::Move($tmp, $outFull)') -gt $sumText.IndexOf('if ($hits.Count -gt 0)')) 'resumo: o nome final so depois do scanner'
    }
    Test-Case 'V5 tools' 'Pacote: tools\v5-pilot entra no pacote (a pasta tools e copiada e nenhuma entrada de $ciOnly e dela), com exatamente as tres ferramentas, e o scanner de privacidade passa nelas' {
        $repo = Split-Path -Parent $testsDir
        $br = [IO.File]::ReadAllText((Join-Path $repo 'tools\Build-Release.ps1'))
        Assert-True ($br.Contains("foreach (`$rel in @('src', 'install', 'docs', 'tests', 'tools'))")) 'build: a pasta tools inteira vai para o stage'
        $ci = @([regex]::Matches($br, "\`$ciOnly\s*\+?=\s*(?:@\()?'([^']+)'") | ForEach-Object { $_.Groups[1].Value })
        Assert-True ($ci.Count -ge 2 -and @($ci | Where-Object { $_ -like '*v5-pilot*' -or $_ -like '*AtmPilot*' }).Count -eq 0) "build: nenhuma ferramenta do piloto em `$ciOnly ($($ci -join ', '))"
        Assert-Eq ((@(Get-ChildItem -LiteralPath $v5Dir -Force | ForEach-Object { $_.Name }) | Sort-Object) -join ',') 'Compare-AtmPilotSnapshot.ps1,Get-AtmPilotSnapshot.ps1,Get-AtmPilotSummary.ps1' 'tools\v5-pilot: exatamente as tres ferramentas'
        $copy = Join-Path $sandbox 'v5-package\tools\v5-pilot'; [void][IO.Directory]::CreateDirectory($copy)
        foreach ($f in @(Get-ChildItem -LiteralPath $v5Dir -File)) { [IO.File]::Copy($f.FullName, (Join-Path $copy $f.Name)) }
        $hits = @(& (Join-Path $repo 'tools\Test-AtmPrivacy.ps1') -Path (Join-Path $sandbox 'v5-package') -NeedlesFile $env:ATM_PRIVATE_NEEDLES -WarningAction SilentlyContinue)
        Assert-Eq $hits.Count 0 (($hits | ForEach-Object { "$($_.File):$($_.Line) $($_.Kind)" }) -join '; ')
    }
    # --- end V5 tools ---
    Test-Case 'Configuracao' 'Regras locais opcionais; sem regra nem evidencia o projeto e "nao identificado"' {
        $cd = Join-Path $sandbox 'cfg'; [void][IO.Directory]::CreateDirectory($cd)
        Copy-Item (Join-Path $cfgDir 'projects.json') $cd
        $cfg0 = Get-AtmConfig -ConfigDir $cd
        Assert-Eq @($cfg0.projects).Count 0 'sem projects.local.json: nenhuma regra (generico)'
        $prov = (Get-AtmProviders)[0]
        $u = Resolve-AtmProject -Slug 'C--Users-x-src-beta' -ProfilePath 'C:\Users\x' -Config $cfg0 -Provider $prov
        Assert-Eq $u.Name (Get-AtmText 'project.unknown') 'nao identificado'
        Assert-True (-not $u.Identified) 'flag'
        Assert-True ((Get-AtmText 'project.unknown') -match '^Projeto n.o identificado$') 'texto padrao pt-BR'
        [IO.File]::WriteAllText((Join-Path $cd 'projects.local.json'), '{"projects":[{"name":"Alpha","pattern":"alpha-?svc"}]}')
        $cfg = Get-AtmConfig -ConfigDir $cd
        Assert-Eq (Resolve-AtmProject -Slug 'C--Users-x-src-alpha-svc' -ProfilePath 'C:\Users\x' -Config $cfg -Provider $prov).Name 'Alpha' 'regra local'
        Assert-Eq (Resolve-AtmProject -Slug 'C--Users-x' -ProfilePath 'C:\Users\x' -Config $cfg -Provider $prov).Name (Get-AtmText 'project.home') 'home'
        $ev = @{ 'c--src-gamma' = 'gamma' }
        $g = Resolve-AtmProject -Slug 'C--src-gamma' -ProfilePath 'C:\Users\x' -Config $cfg -Provider $prov -EvidenceNames $ev
        Assert-True ($g.Identified -and $g.Name -eq 'gamma' -and $g.Source -eq (Get-AtmText 'project.srcSession')) 'evidencia de sessao'
    }

    # ------------------------------------------------------------------ i18n (pt-BR / en-US)
    Test-Case 'I18n' 'Catalogo: paridade de chaves, mesmos placeholders e nenhuma chave usada sem traducao' {
        $en = $script:AtmMessages['en-US']; $pt = $script:AtmMessages['pt-BR']
        Assert-Eq @($en.Keys | Where-Object { -not $pt.ContainsKey($_) }).Count 0 'chaves so em en-US'
        Assert-Eq @($pt.Keys | Where-Object { -not $en.ContainsKey($_) }).Count 0 'chaves so em pt-BR'
        foreach ($k in $en.Keys) {
            $a = @([regex]::Matches($en[$k], '\{(\d+)') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique) -join ','
            $b = @([regex]::Matches($pt[$k], '\{(\d+)') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique) -join ','
            Assert-Eq $b $a "placeholders de '$k'"
        }
        $repo = Split-Path -Parent $testsDir
        $used = @(Get-ChildItem (Join-Path $repo 'src'), (Join-Path $repo 'install') -Recurse -Filter '*.ps1' | Select-String -Pattern "Get-AtmText\s+'([^']+)'" -AllMatches | ForEach-Object { $_.Matches } | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
        $missing = @($used | Where-Object { -not $en.ContainsKey($_) })
        Assert-Eq $missing.Count 0 ('chaves usadas sem entrada: ' + ($missing -join ','))
        foreach ($code in @('AUDITADO', 'AUDITADO_PARCIAL', 'TEMP_NAO_VERIFICAVEL', 'INACESSIVEL', 'NAO_AUDITADO_REPARSE', 'NAO_AUDITADO_UNIDADE', 'SEM_TEMP_CLAUDE')) { Assert-True $en.ContainsKey("status.$code") "status.$code" }
        foreach ($m in @('dll', 'memory')) { Assert-True $en.ContainsKey("native.$m") "native.$m" }
    }
    Test-Case 'I18n' 'Resolucao de idioma e fallback seguro (desconhecido -> en-US; chave ausente -> [chave]; formato invalido nao lanca)' {
        try {
            Set-AtmLanguage -Requested 'en-US'; Assert-Eq (Get-AtmLanguage) 'en-US' 'explicito en-US'
            Set-AtmLanguage -Requested 'pt-br'; Assert-Eq (Get-AtmLanguage) 'pt-BR' 'explicito pt (qualquer caixa)'
            Set-AtmLanguage -Requested 'pt-PT'; Assert-Eq (Get-AtmLanguage) 'pt-BR' 'pt-* -> pt-BR'
            Set-AtmLanguage -Requested 'xx-YY'; Assert-Eq (Get-AtmLanguage) 'en-US' 'desconhecido -> en-US'
            Set-AtmLanguage -Requested 'de-DE'; Assert-Eq (Get-AtmLanguage) 'en-US' 'nao suportado -> en-US'
            $old = $env:ATM_LANG; $env:ATM_LANG = 'en-US'; Set-AtmLanguage; Assert-Eq (Get-AtmLanguage) 'en-US' 'ATM_LANG'; $env:ATM_LANG = $old
            Assert-Eq (Get-AtmText 'chave.que.nao.existe') '[chave.que.nao.existe]' 'chave ausente'
            Assert-True ((Get-AtmText 'audit.total') -match '\{0\}') 'sem argumentos: modelo intacto, sem excecao'
            $script:AtmMessages['pt-BR'].Remove('preview.done'); Set-AtmLanguage -Requested 'pt-BR'
            Assert-True ((Get-AtmText 'preview.done') -match '^PREVIEW: nothing') 'chave ausente em pt-BR cai para en-US'
        } finally {
            . (Join-Path $srcDir 'lib\I18n.ps1')
            Set-AtmLanguage -Requested 'pt-BR'
        }
    }
    Test-Case 'I18n' 'en-US: auditoria, preview, plano de limpeza e TUI totalmente em ingles; codigos do motor identicos' {
        $p = New-TestProfile 'idioma'
        $r = New-TestRoot -ProfileInfo $p
        [IO.File]::SetLastWriteTimeUtc((Join-Path $r 'a.txt'), $nowFuture.AddHours(-1))
        $r2 = New-TestRoot -ProfileInfo $p
        try {
            Set-AtmLanguage -Requested 'pt-BR'
            $iPt = Inv -Profiles @($p)
            Set-AtmLanguage -Requested 'en-US'
            $iEn = Inv -Profiles @($p)
            foreach ($x in @($r, $r2)) {
                Assert-Eq (Find-Part $iEn $x).Class (Find-Part $iPt $x).Class 'classe identica'
                Assert-Eq ((Find-Part $iEn $x).Flags -join ',') ((Find-Part $iPt $x).Flags -join ',') 'flags identicas'
            }
            $gPt = Invoke-AtmPreview -Inventory $iPt; $gEn = Invoke-AtmPreview -Inventory $iEn
            Assert-Eq (@($gEn | ForEach-Object { $_.Gate.Category }) -join ',') (@($gPt | ForEach-Object { $_.Gate.Category }) -join ',') 'categorias identicas'
            $msg = { param($sb) (@(& $sb 6>&1 | ForEach-Object { [string]$_.MessageData }) -join "`n") }
            $audit = & $msg { Show-AtmAudit -Inventory $iEn }
            $prev = & $msg { Show-AtmPreview -Inventory $iEn -Rows $gEn }
            $plan = & $msg { Show-AtmCleanPlan -Verified @() -Rejected @() -Inventory $iEn }
            foreach ($s in @('GENERAL SUMMARY', 'SUMMARY BY USER / SID', 'FINAL SUMMARY', 'Read-only mode')) { Assert-True ($audit.Contains($s)) "audit en: $s" }
            foreach ($s in @('BLOCKED PATHS', 'TECHNICALLY ELIGIBLE', 'reason:', 'nothing was deleted')) { Assert-True ($prev.Contains($s)) "preview en: $s" }
            Assert-True ($plan.Contains('NOTHING HAS BEEN DELETED YET')) 'plano en'
            foreach ($pt in @('RESUMO', 'NADA FOI APAGADO', 'Partições', 'Usuário', 'motivo:', 'nenhum item')) { Assert-True (-not ($audit + $prev + $plan).Contains($pt)) "sem pt-BR no en-US: $pt" }
            $o = Invoke-HeadlessTui -Keys @((New-Key 'D1' '1'), (New-Key 'Escape'), (New-Key 'D2' '2'), (New-Key 'Escape'), (New-Key 'H' 'h'), (New-Key 'Escape'), (New-Key 'Q' 'q')) -InvArgs (Get-InvArgs -Profiles @($p))
            $all = $o.Frames -join "`n"
            foreach ($s in @('Main menu', 'Users / SIDs', 'Profiles', 'Space', 'Navigation:', 'Q quit')) { Assert-True ($all.Contains($s)) "TUI en: $s" }
            foreach ($pt in @('Menu principal', 'Usuários', 'Espaço', 'Sair')) { Assert-True (-not $all.Contains($pt)) "TUI sem pt-BR: $pt" }
        } finally { Set-AtmLanguage -Requested 'pt-BR' }
    }
    Test-Case 'I18n' 'ASCII: acentos transliterados (pt-BR) e nada fora do ASCII imprimivel' {
        Assert-Eq (ConvertTo-AtmAscii ('Usu' + [char]0x00E1 + 'rio ' + [char]0x00E7 + [char]0x00E3 + ' ' + [char]0x540D)) 'Usuario ca ?' 'transliteracao'
        $p = New-TestProfile ('Jos' + [char]0x00E9)
        $null = New-TestRoot -ProfileInfo $p
        $o = Invoke-HeadlessTui -Keys @((New-Key 'D1' '1'), (New-Key 'Escape'), (New-Key 'D2' '2'), (New-Key 'Q' 'q')) -InvArgs (Get-InvArgs -Profiles @($p)) -Ascii -W 140 -H 30
        $all = $o.Frames -join "`n"
        Assert-True ($all -match '^[\x09\x0A\x20-\x7E]*$') 'somente ASCII'
        Assert-True ($all.Contains('Usuarios / SIDs') -and $all.Contains('Jose')) 'texto pt-BR legivel sem acentos'
    }
    Test-Case 'I18n' 'CLI: -Lang en-US, ATM_LANG e idioma invalido (fallback en-US)' {
        $cmd = Join-Path $srcDir 'bin\agent-temp.cmd'
        $out = (& cmd.exe /c "`"$cmd`" version -Lang en-US" 2>&1) -join ' '
        Assert-True ($out -match 'language: en-US' -and $out -match 'real deletion: DISABLED') "en-US: $out"
        $out = (& cmd.exe /c "`"$cmd`" version -Lang pt-BR" 2>&1) -join ' '
        Assert-True ($out -match 'idioma: pt-BR' -and $out -match 'limpeza real: DESABILITADA') "pt-BR: $out"
        $out = (& cmd.exe /c "`"$cmd`" version -Lang xx-YY" 2>&1) -join ' '
        Assert-True ($out -match 'language: en-US') "invalido -> en-US: $out"
        $old = $env:ATM_LANG; $env:ATM_LANG = 'en-US'
        try { $out = (& cmd.exe /c "`"$cmd`" help" 2>&1) -join ' ' } finally { $env:ATM_LANG = $old }
        Assert-True ($out -match 'Examples:' -and $out -match 'PLAN ONLY') "ATM_LANG=en-US: help em ingles"
        $out = (& cmd.exe /c "`"$cmd`" clean -Lang en-US" 2>&1) -join ' '
        Assert-True ($out -match 'NOTHING WAS DELETED') 'clean sem allowlist em ingles'
    }

    # ------------------------------------------------------------------ portability
    Test-Case 'Portabilidade' 'Windows com apenas um usuario' {
        $p = New-TestProfile 'unico'
        $null = New-TestRoot -ProfileInfo $p
        $i = Inv -Profiles @($p)
        Assert-Eq @($i.Profiles).Count 1 'um perfil'
        Assert-Eq (Get-AtmProfileStatusLabel -Inventory $i -ProfileInfo $p) 'AUDITADO' 'rotulo'
