    Test-Case 'Portabilidade' 'Projetos: nao identificado por padrao; identificado pelo diretorio de trabalho da sessao; colisao nao identifica' {
        $p = New-TestProfile 'projetos'
        $cfgRoot = Join-Path $p.ProfilePath '.claude'
