            Assert-True ($r.Exit -eq 0 -and (Test-Path -LiteralPath $out -PathType Leaf)) "janela P6 ${lang}: processo filho saida $($r.Exit) $($r.Text)"
            $j = Get-Content -LiteralPath $out -Raw -Encoding UTF8 | ConvertFrom-Json
